CREATE OR REPLACE PROCEDURE EXT.SP_RELLENAR_TABLAS (IN i_PeriodSeq BIGINT, IN i_lista_informes VARCHAR(5000), IN i_id_proceso BIGINT, INOUT i_log_count INTEGER)
LANGUAGE SQLSCRIPT 
SQL SECURITY INVOKER 
DEFAULT SCHEMA EXT AS

/*---------------------------------------------------------------------
    | Authors: Brais Romero
    | Company: Inycom
    | Initial Version Date: 16-Mayo-2025
    |----------------------------------------------------------------------
    | Procedure Purpose: Procedimiento para informar las tablas FINAL de informes sin modificar las tablas intermedias. 
    | El procedimiento funciona desde un interfaz de salida de XDL, pasandole al DataExtract el texto ""
	|
	| Version: 	0.1		BRG 	20250716	Versión inicial.
	| 			0.2		LLS 	20250924	Eliminados como datos de entrada y añadidas como variables. Modificarlos para poder lanzar por DataExtract
	|          								Eliminado "TEST_"
	| 			0.3		LLS 	20251002	Redondear a 2 decimales VALOR_IRPF para OUT_S4_FACTURA_FINAL_REP y OUT_S5_FACTURA_FINAL_REP
	| 			0.4		LLS     20251022    Añadido el campo SALESTRANSACTIONSEQ en el insert de OUT_S4_POLIZAS_FINAL_REP
	|			0.5		DTB		20251023	Añadido el insert a OUT_PEPA_RESUMEN_FINAL_REP
	|			0.6		DTB		20251023	Añadido el insert a OUT_PEPI_RESUMEN_FINAL_REP
	|			0.7		LLS		20251024	Añadido el insert a OUT_S4_RPA_RESUMEN_FINAL_REP
	| 										Añadimos las variables v_PeriodSeq_1, v_PeriodSeq_2, v_PeriodParentSeq y su extracción para fin de trimestre
	| 										Añadimos los campos en los INSERT INTO
	|			0.8		BRG		20251024	Añadidos INSERT para informes 1.27.1-2 y 1.27.3-4
	|			0.9		LLS		20251030	Añadido el insert a OUT_S5_RPI_RESUMEN_FINAL_REP
	|			0.10	BRG		20251031	Añadido INSERT para OUT_RPP_RESUMEN_FINAL_REP y OUT_RPP_DETALLE_FINAL_REP
	|			1.0		LLS		20251031	Corrección de errores: Modificar INYC_BAL_RPI_RESUMEN por OUT_BAL_RPI_RESUMEN_REP
	|			1.1		LLS		20251110	Corrección de error: PEPI, para N_MEDIDA %906% falta el = a 2024
	| 										Añadida la parte histórica para OUT_S4_RPA_RESUMEN_FINAL_REP. Los cálculos cuatrimestrales no
	|			1.2		LLS		20251112	Eliminado i_PeriodSeq_3
	| 										Corrección de error: Cruce con OUT_JERARQUIA_REP hacer DISTINCT
	| 										Corrección de error: Añadido el campo SALESTRANSACTIONSEQ a la tabla OUT_PROD_AGENTES_FINAL_REP
	|			1.3		BRG/DBT	20251112	Revisado SOLO_DIFERENCIAS y ROUND en campos numéricos de las tablas FINAL
	|			1.4		BRG/DBT	20251113	Ahora el procedimiento es llamado por el CREAR_TABLAS y por el RELLENAR_TABLAS_MANUAL
	|			1.5		BRG		20251114	Se me habían quedado ROUND para campos numéricos en los inserts a las tablas FINAL
	|			1.6		BRG		20251114	Añado inserts de --SELECCIONAR-- para todas las tablas con Estructura de Privilegios. Pendiente REPEXT!
	|			1.7		DTB		20251117	2200-->2100 en OUT_ESTRUCTURA_COMERCIAL.POS_effectivestartdate
	|			1.8		BRG		20251118	Eliminado --SELECCIONAR-- de todas las tablas excepto Detalle Pólizas
	|			1.9		BRG		20251120	Modificado insert en S4 Pólizas final: agrupar pólizas RRTT
	|			2.0		LLS		20251124	Añadido el cruce POSITIONSEQ = POSITIONSEQ_PRIN para que sólo saque posición pincipal en los informes (en Oracle era el cruce con CSA_PAREPORTINGDIMENSION): 1.11, 1.12, 1.13, 1.14, 1.26
	|			2.1		LLS		20251124	Modificado el insert del 1.18
	| 										Añadido el cruce POSITIONSEQ = POSITIONSEQ_PRIN para que sólo saque posición pincipal en los informes: S4 Detalle Pólizas, S5 Detalle Pólizas, S4 RPA, S5 RPI
	|			2.2		BRG		20251125	Eliminado OFICINA del campo FILTRO de S4 Factura
	|			2.3		BRG		20251126	Modificado IRPF y NUM_FAC en S4 y S5 Factura
	|			2.4		DTB		20251126	Filtro TIPO_AGENTE <> 79 en S5 Percepciones Resumen (PEPI)
    |           2.6     BRG     20251127    Modificado insert en S5 Pólizas final: agrupar pólizas RRTT
	|			2.7		BRG		20251202	Agrupación por RRTT de RPP Detalle
    |           2.8		BRG		20251209	Añadida carga de OUT_LC_RPA_RESUMEN_FINAL_REP para informe S4 RPA LC
	|			2.9		BRG		20251209	Añadidas v_period_quarter y v_period_year
	|			2.10	BRG		20251212	Modificado por completo el INSERT de OUT_PROD_AGENTES_FINAL_REP, así como la tabla
	|			2.11	BRG		20251217	Añadido informe Rappel Especial (Tablas RE)
    |           2.12    BRG     20251219    Solucionado error duplicados FACTURA S4, correo Cristian
	|			2.13	BRG		20251219	Corrección SOLO_DIFERENCIAS en RE_RESUMEN
	|			2.14	BRG		20251222	Añadido INSERT de OUT_BAL_RPA_RESUMEN_FINAL_REP para informe S4 RPA BAL
	|			2.15	DTB		20251223	Añadido INSERT de OUT_LC_S5_RPI_RESUMEN_FINAL_REP para informe S5 RPI LC
	|			2.16	BRG		20251223	Corregido error en S5 Pólizas
    |           2.17    BRG     20251224    Añadidas dos columnas a OUT_PROD_AGENTES_FINAL_REP para pestaña de producción por meses
	|			2.18 	BRG		20251226	Añadida tercera columna a OUT_PROD_AGENTES_FINAL_REP e INSERT adicional para ID_TIPO_AGENTE por mes
    |           2.19    BRG     20260102    Eliminado temporalmente el filtro del S4 Pólizas de corredores
    |           2.20    BRG     20250105    Eliminado DISTINCT de INSERT en OUT_REPARTO_PAGOS_FINAL_REP
	|			2.21	BRG		20260107	Añadido Informe S4 Polizas Corredores
    |           2.22    BRG     20260107    Modificación de NIF-Nombre en informes S4 y S5 Pólizas, ahora tiene el POS_PRIN al final
	|			2.23	BRG		20260108	Incidencia informe 1.12, registros duplicados, correo de David
	|			3.0		BRG		20260115	Informes restantes: RDC DETALLE/RESUMEN + BAL
	|			3.1		BRG		20260119	Informes restantes: RPA DETALLE
	|			3.2		BRG		20260123	Informes restantes: CARTERA
	|			3.3		BRG		20260127	Informes restantes: PP + BAL
	|			3.3.1	BRG		20260127	Incidencia con RPA
	|			3.4		BRG		20260129	Informe restantes: LC RPA DETALLE, BAL RE, BAL RPI
	|			3.5		BRG		20260202	Incidencia con RPA, se veían varios TIPO_AGENTE
	|			3.6		BRG		20260202	Añadido Fecha Alta a 1.12 por Meses
	|			3.6.1	BRG		20260206	Añadido STARTDATE a OUT_RDC_RESUMEN_FINAL_REP 
	|			3.6.2	BRG		20260211	Añadida parte de --SELECCIONAR-- a RDC DETALLE y a RPA DETALLE
	|			3.6.3	BRG		20260212	Error REPEXT periodo formato
	|			3.7		BRG		20260305	Añadidas queries comentadas de 1.12 y 1.14 con origen de S4 y S5, respectivamente
	|										Añadido control a RDC Resumen y PP Resumen para no incluir meses de balance no ejecutados
	|			3.8		DTB		20260310	Cambio en el inner join para 1.11 y 1.13, ahora se usa una subtabla de la tabla OUT_JERARQUIA_REP
	|			3.9		DTB		20260324	Se deja de usar OUT_CARTERA_AGENTES_REP.VALUE para usar OUT_CARTERA_AGENTES.PRIMA
	|			3.10	BRG		20260330	Añadido bloque de PP LC
	|			3.11	BRG		20260401	Añadido INSERT de 1.12 con S4 Polizas y 1.14 con S5 Polizas
	|			3.12	BRG		20260408	Añadido INSERT de 1.16 con S5 Polizas
	|			3.13	BRG		20260414	Añadida columna COMPANIA en OUT_CARTERA_AGENTES_FINAL_REP
	|			3.14	BRG		20260415	Añadida tipología 49 a RPA RESUMEN por petición Bloque 1
	|			3.15	BRG		20260416	Corregido INSERT RPA LC DETALLE, se estaba usando tabla BAL
	|			3.16	BRG		20260416	Añadido ETERNA a CARTERA_AGENTES
	|			3.17	DTB		20260420 	Añadidas primas neta y comis. a DDEE en informe S4 Pólizas
	|			3.18	DTB		20260422 	Corregida regul. trim. en RPA Resumen cierre
	|			3.19	BRG		20260422	Agrupación de S4 Pólizas Corredores por RRTT
	|			3.20	BRG		20260423	Corregido formato del producto en agrupación RRTT, ahora se ve el producto principal aunque el detalle no lo tenga
	|										Eliminados DDEE del 1.12
	|										Corrección duplicados en S4 Corredores
	|			3.21 	DTB		20260423	Añadidos updates para OUT_S4_RPA_RESUMEN_FINAL_REP
	|			3.22 	DTB		20260424	Añadidos campo REG_TRIM a OUT_BAL_RPA_RESUMEN_FINAL_REP
	|			3.23	BRG		20260428	PRIN, PRAG y OMESCU ahora tienen los BAL de los meses anteriores
	|			3.24	BRG		20260512	Se vuelve a poner el 1.12 como antes
	|
    -----------------------------------------------------------------------
*/

BEGIN

	USING SQLSCRIPT_STRING AS LIBRARY;
	
	--	VARIABLES DE USO GENERAL
	DECLARE proc_name VARCHAR(50) := ::CURRENT_OBJECT_SCHEMA ||'.'|| ::CURRENT_OBJECT_NAME;
	DECLARE v_version VARCHAR(10) := '3.24';
	DECLARE v_num_rows INTEGER := 0;
	DECLARE v_permisos_log VARCHAR(50) := EXT.LIB_GLOBAL:GET_PERMISOS_LOG();
	DECLARE v_eot DATE := EXT.LIB_CONSTANTES:v_eot;
	DECLARE v_period_name VARCHAR(100);
	DECLARE v_period_name_format VARCHAR(100); --BRG 20260127
	DECLARE v_period_startdate DATE;
	DECLARE v_period_enddate DATE;
	DECLARE v_period_month INTEGER; --BRG 20260407
    DECLARE v_period_quarter VARCHAR(50);
    DECLARE v_period_year VARCHAR(50);
	DECLARE v_idtenant VARCHAR(50) := EXT.LIB_GLOBAL:getTenantID();--LLS 20250924
    DECLARE v_PeriodParentSeq BIGINT;--LLS 20251024
    DECLARE v_PeriodSeq_1 BIGINT;--LLS 20251024
    DECLARE v_PeriodSeq_2 BIGINT;--LLS 20251024
	
	DECLARE EXIT HANDLER FOR SQLEXCEPTION
		BEGIN
		
			ROLLBACK;
			
			CALL EXT.LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name , 'Error en procedimiento principal ' || proc_name || ' - SQL_ERROR_MESSAGE: ' || IFNULL(::SQL_ERROR_MESSAGE,'')
																									|| '. SQL_ERROR_CODE: ' || ::SQL_ERROR_CODE, i_log_count, i_id_proceso, 'error');

			v_num_rows := 0;
		
			RESIGNAL;
		
		END;
	
	BEGIN

		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Version: ' || v_version || ' - Procedure starting ...', i_log_count, i_id_proceso, 'info');
		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Parámetros de entrada -> i_PeriodSeq: ' || i_PeriodSeq, i_log_count, i_id_proceso, 'info');
		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Parámetros de entrada -> i_listado_informes: ' || i_lista_informes, i_log_count, i_id_proceso, 'info');
		
		--CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Parámetros de entrada -> i_pPlRunSeq: ' || i_pPlRunSeq || ' | i_listado_informes: ' || i_lista_informes, i_log_count, i_id_proceso, 'info');
		
		-- Obtenemos datos del Periodo--LLS 20250924
		
		SELECT PER1.NAME, PER1.STARTDATE, MONTH(PER1.STARTDATE), PER1.ENDDATE, PER2.NAME, PER3.NAME INTO v_period_name, v_period_startdate, v_period_month, v_period_enddate, v_period_quarter, v_period_year
        FROM TCMP.CS_PERIOD PER1
        INNER JOIN TCMP.CS_PERIOD PER2 ON PER1.PARENTSEQ = PER2.PERIODSEQ
            AND PER2.REMOVEDATE = :v_eot
        INNER JOIN TCMP.CS_PERIOD PER3 ON PER2.PARENTSEQ = PER3.PERIODSEQ
            AND PER3.REMOVEDATE = :v_eot
        WHERE PER1.PERIODSEQ = :i_PeriodSeq
            AND PER1.REMOVEDATE = :v_eot;
				
		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Periodo -> Period Name: ' || v_period_name, i_log_count, i_id_proceso, 'info');
		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Periodo -> Period Startdate: ' || v_period_startdate, i_log_count, i_id_proceso, 'info');
		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Periodo -> Period Enddate: ' || v_period_enddate, i_log_count, i_id_proceso, 'info');
		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Periodo -> Period Month: ' || v_period_month, i_log_count, i_id_proceso, 'info');
		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Periodo -> Period Quarter: ' || v_period_quarter, i_log_count, i_id_proceso, 'info');
		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Periodo -> Period Year: ' || v_period_year, i_log_count, i_id_proceso, 'info');
		/*
		SELECT PERIODSEQ, NAME, STARTDATE, ENDDATE INTO i_PeriodSeq, v_period_name, v_period_startdate, v_period_enddate 
		FROM EXT.LIB_GLOBAL:getPeriodRow(v_idTenant, i_pPlRunSeq);

		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Periodo -> NAME: ' || :v_period_name || ' | STARTDATE: ' || :v_period_startdate || ' | ENDDATE: ' || v_period_enddate, i_log_count, i_id_proceso, 'info');
        */

		
		-- Si estamos en fin de trimestre--LLS 20251024
		IF SUBSTR_BEFORE(:v_period_name, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
		THEN
			-- Obtenemos los datos del ParentSeq del periodo
			SELECT PARENTSEQ INTO v_PeriodParentSeq
			FROM TCMP.CS_PERIOD WHERE REMOVEDATE= :v_eot AND PERIODSEQ = :i_PeriodSeq;

			-- Obtenemos los datos del Periodo-1 y Periodo-2
			SELECT PERIODSEQ INTO v_PeriodSeq_1
			FROM TCMP.CS_PERIOD 
			WHERE REMOVEDATE= :v_eot AND PARENTSEQ = :v_PeriodParentSeq AND STARTDATE = ADD_MONTHS(:v_period_startdate,-1);
			
			SELECT PERIODSEQ INTO v_PeriodSeq_2
			FROM TCMP.CS_PERIOD 
			WHERE REMOVEDATE= :v_eot AND PARENTSEQ = :v_PeriodParentSeq AND STARTDATE = ADD_MONTHS(:v_period_startdate,-2);
			
			-- Obtenemos los datos del Periodo-3 LLS 20251110: Añadido --LLS 20251112: Eliminado
			/*SELECT PERIODSEQ INTO i_PeriodSeq_3
			FROM TCMP.CS_PERIOD 
			WHERE REMOVEDATE= :v_eot AND PARENTSEQ = :v_PeriodParentSeq AND STARTDATE = ADD_MONTHS(:v_period_startdate,-3);
			*/
		END IF;


	-------------------------------------------------------------------------------------------------------------------------------------
    -- INICIO TABLAS DE INFORMES
	------------------------------------------------------------------------------------------------------------------------------------
		---------------------------------------------------------------------------------------------------------------------------------
		-- BRG 20250522: Tabla auxiliar para el formato del periodo
		TBL_PER_FORMAT = SELECT DISTINCT
				J.PERIODO,
				SUBSTR_AFTER(J.PERIODO, ' ') || CASE 
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Enero' THEN ' 01 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Febrero' THEN ' 02 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Marzo' THEN ' 03 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Abril' THEN ' 04 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Mayo' THEN ' 05 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Junio' THEN ' 06 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Julio' THEN ' 07 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Agosto' THEN ' 08 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Octubre' THEN ' 10 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
					WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
					END || SUBSTR_BEFORE(J.PERIODO, ' ') AS PERIODO_FORMATO
			FROM EXT.OUT_JERARQUIA_REP J;
		
		SELECT PERIODO_FORMATO INTO v_period_name_format FROM :TBL_PER_FORMAT WHERE PERIODO = :v_period_name; 

		---------------------------------------------------------------------------------------------------------------------------------
		-- BRG 20250529: Tabla Estructura Comercial
		IF :i_lista_informes = 'ESTR' OR :i_lista_informes LIKE '%|ESTR|%' OR :i_lista_informes LIKE '%|ESTR' OR :i_lista_informes LIKE 'ESTR|%'
			OR :i_lista_informes = 'ALL' THEN

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado y Carga Tabla Estructura.', i_log_count, i_id_proceso, 'info');

			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Borrado ESTRUCTURA_COMERCIAL', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.ESTRUCTURA_COMERCIAL --WHERE PERIODSEQ = :i_PeriodSeq --LLS 20251124: borrado completo, sin filtro de periodo
				;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Borrado ESTRUCTURA_COMERCIAL. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Carga ESTRUCTURA_COMERCIAL', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.ESTRUCTURA_COMERCIAL (PARTICIPANTEMAIL, TAXID, PAR_EFFECTIVESTARTDATE,PAR_EFFECTIVEENDDATE,PERIODNAME,PERIODSHORTNAME,PERIODDESCRIPTION,STARTDATE,ENDDATE,NOMBRE_COMPLETO,PERIODSEQ,POSITIONSEQ, PARTICIPANTSEQ, PARTICIPANTID, USERID, PREFIX, FIRSTNAME, MIDDLENAME,LASTNAME, SUFFIX, FULLNAME, SALARY, HIREDATE, TERMINATIONDATE, BUSINESSUNITMAP, BUSINESSUNITNAME, POSITIONNAME, POSITIONDESCRIPTION, POSITIONGROUPNAME, TITLENAME, TITLEDESCRIPTION, TARGETCOMPENSATION, PLANNAME, PLANSEQ, POSITIONGENERICATTRIBUTE1, POSITIONGENERICATTRIBUTE2, POSITIONGENERICATTRIBUTE3, POSITIONGENERICATTRIBUTE4, POSITIONGENERICATTRIBUTE5, POSITIONGENERICATTRIBUTE6, POSITIONGENERICATTRIBUTE7, POSITIONGENERICATTRIBUTE8, POSITIONGENERICATTRIBUTE9, POSITIONGENERICATTRIBUTE10, POSITIONGENERICATTRIBUTE11, POSITIONGENERICATTRIBUTE12, POSITIONGENERICATTRIBUTE13, POSITIONGENERICATTRIBUTE14, POSITIONGENERICATTRIBUTE15, POSITIONGENERICATTRIBUTE16, POSITIONGENERICNUMBER1, POSITIONGENERICNUMBER2, POSITIONGENERICNUMBER3, POSITIONGENERICNUMBER4, POSITIONGENERICNUMBER5, POSITIONGENERICNUMBER6, POSITIONGENERICDATE1, POSITIONGENERICDATE2, POSITIONGENERICDATE3, POSITIONGENERICDATE4, POSITIONGENERICDATE5, POSITIONGENERICDATE6, POSITIONGENERICBOOLEAN1, POSITIONGENERICBOOLEAN2, POSITIONGENERICBOOLEAN3, POSITIONGENERICBOOLEAN4, POSITIONGENERICBOOLEAN5, POSITIONGENERICBOOLEAN6, PARTICIPANTGENERICATTRIBUTE1, PARTICIPANTGENERICATTRIBUTE2, PARTICIPANTGENERICATTRIBUTE3, PARTICIPANTGENERICATTRIBUTE4, PARTICIPANTGENERICATTRIBUTE5, PARTICIPANTGENERICATTRIBUTE6, PARTICIPANTGENERICATTRIBUTE7, PARTICIPANTGENERICATTRIBUTE8, PARTICIPANTGENERICATTRIBUTE9, PARTICIPANTGENERICATTRIBUTE10, PARTICIPANTGENERICATTRIBUTE11, PARTICIPANTGENERICATTRIBUTE12, PARTICIPANTGENERICATTRIBUTE13, PARTICIPANTGENERICATTRIBUTE14, PARTICIPANTGENERICATTRIBUTE15, PARTICIPANTGENERICATTRIBUTE16, PARTICIPANTGENERICNUMBER1, PARTICIPANTGENERICNUMBER2, PARTICIPANTGENERICNUMBER3, PARTICIPANTGENERICNUMBER4, PARTICIPANTGENERICNUMBER5, PARTICIPANTGENERICNUMBER6, PARTICIPANTGENERICDATE1, PARTICIPANTGENERICDATE2, PARTICIPANTGENERICDATE3, PARTICIPANTGENERICDATE4, PARTICIPANTGENERICDATE5, PARTICIPANTGENERICDATE6, PARTICIPANTGENERICBOOLEAN1, PARTICIPANTGENERICBOOLEAN2, PARTICIPANTGENERICBOOLEAN3, PARTICIPANTGENERICBOOLEAN4, PARTICIPANTGENERICBOOLEAN5, PARTICIPANTGENERICBOOLEAN6, TITLEGENERICATTRIBUTE1, TITLEGENERICATTRIBUTE2, TITLEGENERICATTRIBUTE3, TITLEGENERICATTRIBUTE4, TITLEGENERICNUMBER1, TITLEGENERICNUMBER2, TITLEGENERICNUMBER3, TITLEGENERICNUMBER4, TITLEGENERICDATE1, TITLEGENERICDATE2, TITLEGENERICBOOLEAN1, TITLEGENERICBOOLEAN2, MANAGERSEQ, MANAGERFULLNAME, ISPAYEE, BOUSERID, MANAGERPARTICIPANTSEQ, PA_SK, IDREGIONAL, REGIONAL, IDSUCURSAL, SUCURSAL, IDOFICINA, OFICINA, PV, CODIGO, INSPECTOR_NAME, INSPECTOR_NIF, INSPECTOR_NOMBRE_COMPLETO, INSPECTOR_TITLE, INSPECTOR_LDAP, INSPECTOR_IDTIPOAGENTE, INSPECTOR_TIPOAGENTE, INSPCAP_NAME, INSPCAP_NIF, INSPCAP_NOMBRE_COMPLETO, INSPCAP_TITLE, INSPCAP_LDAP, INSPCAP_IDTIPOAGENTE, INSPCAP_TIPOAGENTE, MEDCOUNT)
			-- LLS 20251124: Nueva versión
			WITH  pos_ids AS (
				SELECT DISTINCT RULEELEMENTOWNERSEQ
				FROM CS_POSITION pos
				WHERE pos.removeDate = :v_eot
				  AND pos.effectiveEndDate >= '2020-01-01'
			), 
			"ESTRUCTURA" AS (SELECT X.NAME as EPOS_NAME,X.RULEELEMENTOWNERSEQ as EPOSITIONSEQ,
					X.GENERICATTRIBUTE2 EPOS_GENERICATTRIBUTE2, X.GENERICATTRIBUTE3 AS EPOS_GENERICATTRIBUTE3,
					TO_INTEGER(X.GENERICNUMBER2) AS EPOS_GENERICNUMBER2, X.GENERICNUMBER3 AS EPOS_GENERICNUMBER3,
					IFNULL(RTRIM(Y.FIRSTNAME) || ' ','')  || IFNULL(RTRIM(Y.LASTNAME),'') || IFNULL(' ' || RTRIM(Y.SUFFIX), '') AS NOMBRE_COMPLETO, 
					Y.FIRSTNAME,Y.LASTNAME,Y.SUFFIX,Y.GENERICATTRIBUTE1 AS NIF, X.MANAGERSEQ as EPOS_MANAGERSEQ,
					Y.USERID as EPAR_USERID,
					Z.NAME AS ETITLE,
					X.EFFECTIVESTARTDATE as EPOS_EFFECTIVESTARTDATE, X.EFFECTIVEENDDATE as EPOS_EFFECTIVEENDDATE,
					Y.EFFECTIVESTARTDATE as EPAR_EFFECTIVESTARTDATE, Y.EFFECTIVEENDDATE as EPAR_EFFECTIVEENDDATE,
					Z.EFFECTIVESTARTDATE as ETIT_EFFECTIVESTARTDATE, Z.EFFECTIVEENDDATE as ETIT_EFFECTIVEENDDATE
				FROM 
				TCMP.CS_POSITION X 
					INNER JOIN TCMP.CS_PARTICIPANT Y ON Y.PAYEESEQ = X.PAYEESEQ and Y.REMOVEDATE = :v_eot
								AND X.EFFECTIVESTARTDATE <= Y.EFFECTIVEENDDATE and X.EFFECTIVEENDDATE >= Y.EFFECTIVESTARTDATE
					INNER JOIN TCMP.CS_PAYEE R ON Y.PAYEESEQ = R.PAYEESEQ and R.REMOVEDATE = :v_eot
								AND Y.EFFECTIVESTARTDATE = R.EFFECTIVESTARTDATE and Y.EFFECTIVEENDDATE = R.EFFECTIVEENDDATE
					INNER JOIN TCMP.CS_TITLE Z ON X.TITLESEQ = Z.RULEELEMENTOWNERSEQ AND Z.REMOVEDATE = :v_eot
								AND X.EFFECTIVESTARTDATE <= Z.EFFECTIVEENDDATE and X.EFFECTIVEENDDATE >= Z.EFFECTIVESTARTDATE
					where X.REMOVEDATE = :v_eot) 
			SELECT 
				IFNULL(PAR.PARTICIPANTEMAIL,' '), -- Correo electrónico
				PAR.TAXID , -- Tipo de IRPF
				POS.EFFECTIVESTARTDATE as POS_EFFECTIVESTARTDATE, -- Fecha Inicio Efectividad
				IFNULL(CASE WHEN POS.EFFECTIVEENDDATE = '22000101' THEN ADD_YEARS(POS.EFFECTIVEENDDATE, -100) ELSE ADD_SECONDS(POS.EFFECTIVEENDDATE, -1) END, ' ') as POS_EFFECTIVEENDDATE, -- Fecha Fin Efectividad, restado un segundo o 100 años
				null AS PERIODNAME, 
				null as PERIODSHORTNAME, 
				null AS PERIODDESCRIPTION, 
				null as STARTDATE, 
				null as ENDDATE, 
				IFNULL(RTRIM(PAR.FIRSTNAME) || ' ','')  || IFNULL(RTRIM(PAR.LASTNAME),'') || IFNULL(' ' || RTRIM(PAR.SUFFIX), '') AS NOMBRE_COMPLETO, 
				null as PERIODSEQ, 
				POS.RULEELEMENTOWNERSEQ as POSITIONSEQ, 
				par.PAYEESEQ,
				r.PAYEEID as PARTICIPANTID,
				par.USERID, -- Usuario LDAP
				par.PREFIX, -- NULL
				par.FIRSTNAME, -- Nombre
				par.MIDDLENAME, -- Email personal
				par.LASTNAME, -- Apellido 1/Razón social
				par.SUFFIX, -- Apellido 2
				null as FULLNAME,
				par.SALARY, -- Pago por IBAN
				par.HIREDATE, -- Fecha de Contrato
				par.TERMINATIONDATE, -- Fecha Fin Agente
				null as BUSINESSUNITMAP, 
				null as BUSINESSUNITNAME, 
				POS.NAME as POSITIONNAME, -- Posición
				null as DESCRIPTION, -- Descripción Posición
				null as POSITIONGROUPNAME, -- Grupo de Posición
				tit.NAME, -- Título
				null as DESCRIPTION, -- Descripción Título
				POS.TARGETCOMPENSATION, -- Objetivo Comisiones
				null as PLANNAME, -- PLAN
				null PLANSEQ, 
				IFNULL(POS.GENERICATTRIBUTE1,' ') as POSITIONGENERICATTRIBUTE1, -- Tipo Principal Agente / Clase Oficina (GA1)
				IFNULL(TO_VARCHAR(TO_INTEGER(POS.GENERICNUMBER2))  || ' - ','') || IFNULL(POS.GENERICATTRIBUTE2 ,'') as POSITIONGENERICATTRIBUTE2 , -- Tipo Agente / Tipo Oficina (GA2)
				POS.GENERICATTRIBUTE3 as POSITIONGENERICATTRIBUTE3, -- Código de Agente OCASO (GA3)
				POS.GENERICATTRIBUTE4 as POSITIONGENERICATTRIBUTE4, -- Rehabilitación (GA4)
				POS.GENERICATTRIBUTE5 as POSITIONGENERICATTRIBUTE5, -- Cuadro Inspector Ocaso (GA5)
				POS.GENERICATTRIBUTE6 as POSITIONGENERICATTRIBUTE6, -- Cuadro RRGG Ocaso (GA6)
				POS.GENERICATTRIBUTE7 as POSITIONGENERICATTRIBUTE7, -- Cuadro RRTT Ocaso (GA7)
				IFNULL(POS.GENERICATTRIBUTE8,' ') as POSITIONGENERICATTRIBUTE8, -- Compañía (GA8)
				POS.GENERICATTRIBUTE9 as POSITIONGENERICATTRIBUTE9, -- Promoción Agente (GA9)
				POS.GENERICATTRIBUTE10 as POSITIONGENERICATTRIBUTE10, -- Cuadro Inspector Eterna (GA10)
				POS.GENERICATTRIBUTE11 as POSITIONGENERICATTRIBUTE11, -- Cuadro RRGG Eterna (GA11)
				POS.GENERICATTRIBUTE12 as POSITIONGENERICATTRIBUTE12, -- Cuadro RRTT Eterna (GA12)
				POS.GENERICATTRIBUTE13 as POSITIONGENERICATTRIBUTE13, -- Año Captación (GA13)
				POS.GENERICATTRIBUTE14 as POSITIONGENERICATTRIBUTE14, -- Inspector Captador (GA14)
				POS.GENERICATTRIBUTE15 as POSITIONGENERICATTRIBUTE15, -- Número Meses Preplan (GA15)
				POS.GENERICATTRIBUTE16 as POSITIONGENERICATTRIBUTE16, -- Escalado Asistencia (GA16)
				POS.GENERICNUMBER1 as POSITIONGENERICNUMBER1, -- ID Tipo Principal Agente (GN1)
				POS.GENERICNUMBER2 as POSITIONGENERICNUMBER2, -- ID Tipo Agente (GN2)
				POS.GENERICNUMBER3 as POSITIONGENERICNUMBER3, -- ID Clase Oficina (GN3)
				POS.GENERICNUMBER4 as POSITIONGENERICNUMBER4, -- ID Tipo Oficina (GN4)
				POS.GENERICNUMBER5 as POSITIONGENERICNUMBER5, -- % Comisión Cartera (GN5)
				POS.GENERICNUMBER6 as POSITIONGENERICNUMBER6, -- Importe Comisión Cartera (GN6)
				POS.GENERICDATE1 as POSITIONGENERICDATE1, -- Fecha de Alta (GD1)
				POS.GENERICDATE2 as POSITIONGENERICDATE2, -- Fecha de Baja (GD2)
				POS.GENERICDATE3 as POSITIONGENERICDATE3, -- Fecha Inicio Consolidación P.C. (GD3)
				POS.GENERICDATE4 as POSITIONGENERICDATE4, -- Fecha Fin Consolidación P.C. (GD4)
				POS.GENERICDATE5 as POSITIONGENERICDATE5, -- Fecha Inicio Asistencia (GD5)
				POS.GENERICDATE6 as POSITIONGENERICDATE6, -- Fecha Límite Comisiones Cartera (GD6)
				POS.GENERICBOOLEAN1 as POSITIONGENERICBOOLEAN1, -- Reducción (GB1)
				POS.GENERICBOOLEAN2 as POSITIONGENERICBOOLEAN2, -- Productor Ocaso (GB2)
				POS.GENERICBOOLEAN3 as POSITIONGENERICBOOLEAN3, -- Consolida (GB3)
				POS.GENERICBOOLEAN4 as POSITIONGENERICBOOLEAN4, -- Inicio Agente Asistencia (GB4)
				POS.GENERICBOOLEAN5 as POSITIONGENERICBOOLEAN5, -- Productor Eterna (GB5)
				POS.GENERICBOOLEAN6 as POSITIONGENERICBOOLEAN6, -- Ag. Lider (GB6)
				PAR.GENERICATTRIBUTE1 as PARTICIPANTGENERICATTRIBUTE1, -- Documento (GA1)
				PAR.GENERICATTRIBUTE2 as PARTICIPANTGENERICATTRIBUTE2, -- Tipo Documento (GA2)
				PAR.GENERICATTRIBUTE3 as PARTICIPANTGENERICATTRIBUTE3, -- Tipo Persona (GA3)
				PAR.GENERICATTRIBUTE4 as PARTICIPANTGENERICATTRIBUTE4, -- Código DGS (GA4)
				PAR.GENERICATTRIBUTE5 as PARTICIPANTGENERICATTRIBUTE5, -- Compañía (GA5)
				PAR.GENERICATTRIBUTE6 as PARTICIPANTGENERICATTRIBUTE6, -- Tipo Mediador (GA6)
				PAR.GENERICATTRIBUTE7 as PARTICIPANTGENERICATTRIBUTE7, -- Localidad (GA7)
				PAR.GENERICATTRIBUTE8 as PARTICIPANTGENERICATTRIBUTE8, -- Tipo Vía (GA8)
				PAR.GENERICATTRIBUTE9 as PARTICIPANTGENERICATTRIBUTE9, -- Domicilio (GA9)
				PAR.GENERICATTRIBUTE10 as PARTICIPANTGENERICATTRIBUTE10, -- Número (GA10)
				PAR.GENERICATTRIBUTE11 as PARTICIPANTGENERICATTRIBUTE11, -- Resto Domicilio (GA11)
				PAR.GENERICATTRIBUTE12 as PARTICIPANTGENERICATTRIBUTE12, -- Sexo (GA12)
				PAR.GENERICATTRIBUTE13 as PARTICIPANTGENERICATTRIBUTE13, -- Estado Civil (GA13)
				PAR.GENERICATTRIBUTE14 as PARTICIPANTGENERICATTRIBUTE14, -- Teléfono Fijo (GA14)
				PAR.GENERICATTRIBUTE15 as PARTICIPANTGENERICATTRIBUTE15, -- Teléfono Móvil (GA15)
				PAR.GENERICATTRIBUTE16 as PARTICIPANTGENERICATTRIBUTE16, -- IBAN (GA16)
				PAR.GENERICNUMBER1 as PARTICIPANTGENERICNUMBER1, -- Código Postal (GN1)
				PAR.GENERICNUMBER2 as PARTICIPANTGENERICNUMBER2, -- Provincia (GN2)
				PAR.GENERICNUMBER3 as PARTICIPANTGENERICNUMBER3, -- Municipio (GN3)
				PAR.GENERICNUMBER4 as PARTICIPANTGENERICNUMBER4, -- ID_Empleado (GN4)
				PAR.GENERICNUMBER5 as PARTICIPANTGENERICNUMBER5, -- % IRPF (GN5)
				PAR.GENERICNUMBER6 as PARTICIPANTGENERICNUMBER6, -- Fax (GN6)
				PAR.GENERICDATE1 as PARTICIPANTGENERICDATE1, -- Fecha Nacimiento (GD1)
				PAR.GENERICDATE2 as PARTICIPANTGENERICDATE2, -- Fecha Registro DGS (GD2)
				PAR.GENERICDATE3 as PARTICIPANTGENERICDATE3, -- Fecha Envío DGS (GD3)
				PAR.GENERICDATE4 as PARTICIPANTGENERICDATE4, -- Fin CIASE 1 (GD4)
				PAR.GENERICDATE5 as PARTICIPANTGENERICDATE5, -- Fecha Efecto SuperRappel (GD5)
				PAR.GENERICDATE6 as PARTICIPANTGENERICDATE6, -- Fecha Regularización SuperRappel (GD6)
				PAR.GENERICBOOLEAN1 as PARTICIPANTGENERICBOOLEAN1, -- Autoliquida (GB1)
				PAR.GENERICBOOLEAN2 as PARTICIPANTGENERICBOOLEAN2, -- Corredor (GB2)
				PAR.GENERICBOOLEAN3 as PARTICIPANTGENERICBOOLEAN3, -- Autorización Factura (GB3)
				PAR.GENERICBOOLEAN4 as PARTICIPANTGENERICBOOLEAN4, -- SuperRappel (GB4)
				PAR.GENERICBOOLEAN5 as PARTICIPANTGENERICBOOLEAN5, -- Comisiones Anualizadas RRPP OCASO (GB5)
				PAR.GENERICBOOLEAN6 as PARTICIPANTGENERICBOOLEAN6, -- Cartera RRTT (GB6)
				TIT.GENERICATTRIBUTE1 as TITLEGENERICATTRIBUTE1, -- Tipo Principal Agente / Clase Oficina (GA1)
				TIT.GENERICATTRIBUTE2 as TITLEGENERICATTRIBUTE2, -- Tipo Agente / Tipo Oficina (GA2)
				TIT.GENERICATTRIBUTE3 as TITLEGENERICATTRIBUTE3, 
				TIT.GENERICATTRIBUTE4 as TITLEGENERICATTRIBUTE4, 
				TIT.GENERICNUMBER1 as TITLEGENERICNUMBER1, -- ID Tipo Principal  Agente (GN1)
				TIT.GENERICNUMBER2 as TITLEGENERICNUMBER2, -- ID Tipo  Agente (GN2)
				TIT.GENERICNUMBER3 as TITLEGENERICNUMBER3, -- ID Clase Oficina (GN3)
				TIT.GENERICNUMBER4 as TITLEGENERICNUMBER4, -- ID Tipo Oficina (GN4)
				TIT.GENERICDATE1 as TITLEGENERICDATE1, 
				TIT.GENERICDATE2 as TITLEGENERICDATE2, 
				TIT.GENERICBOOLEAN1 as TITLEGENERICBOOLEAN1, -- Genera Informe (GB1)
				TIT.GENERICBOOLEAN2 as TITLEGENERICBOOLEAN2, 
				POS.MANAGERSEQ, -- MANAGERSEQ
				MANAGER.NOMBRE_COMPLETO as MANAGERFULLNAME,
				null as ISPAYEE, 
				null as BOUSERID, 
				null as MANAGERPARTICIPANTSEQ, 
				null as PA_SK,
				 IFNULL( CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN REG.EPOS_NAME
						ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (4,7) THEN SUC.EPOS_NAME
							ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (3,6,8,10,11) THEN OFI.EPOS_NAME
								ELSE PTO_VENTA.EPOS_NAME END
					END END , ' ') as IDREGIONAL,
					IFNULL( CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN REG.EPOS_NAME
						ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (4,7) THEN SUC.EPOS_NAME
							ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (3,6,8,10,11) THEN OFI.EPOS_NAME
								ELSE PTO_VENTA.EPOS_NAME END
					END END || ' - ' ||
					CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN REG.LASTNAME
						ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (4,7) THEN SUC.LASTNAME
							ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (3,6,8,10,11) THEN OFI.LASTNAME
								ELSE PTO_VENTA.LASTNAME END
					END END  , ' ') AS REGIONAL, 
					IFNULL( CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN SUC.EPOS_NAME
						ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (4,7) THEN OFI.EPOS_NAME
							ELSE PTO_VENTA.EPOS_NAME END 
					END , ' ' )as IDSUCURSAL,
					IFNULL( CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN SUC.EPOS_NAME
						ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (4,7) THEN OFI.EPOS_NAME
							ELSE PTO_VENTA.EPOS_NAME END 
					END || ' - ' ||
					CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN SUC.LASTNAME
						ELSE CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (4,7) THEN OFI.LASTNAME
							ELSE PTO_VENTA.LASTNAME END 
					END , ' ' ) AS SUCURSAL,                                                                                            --titleGenericAttribute2
					IFNULL( CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN OFI.EPOS_NAME  
						ELSE PTO_VENTA.EPOS_NAME END, ' ') as IDOFICINA,
					IFNULL( CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN OFI.EPOS_NAME  
						ELSE PTO_VENTA.EPOS_NAME END || ' - ' ||
					CASE WHEN PTO_VENTA.EPOS_GENERICNUMBER3 IN (5) THEN OFI.LASTNAME  
						ELSE PTO_VENTA.LASTNAME END, ' ') AS OFICINA,
				IFNULL( LEFT(POS.GENERICATTRIBUTE3, 4), ' ') as PV, IFNULL( RIGHT(Pos.GENERICATTRIBUTE3, 4), ' ' ) as CODIGO,
				MANAGER.EPOS_GENERICATTRIBUTE3 as INSPECTOR_NAME, MANAGER.NIF as INSPECTOR_NIF, MANAGER.NOMBRE_COMPLETO as INSPECTOR_NOMBRE_COMPLETO, 
				MANAGER.ETITLE as INSPECTOR_TITLE, MANAGER.EPAR_USERID as INSPECTOR_LDAP,
				MANAGER.EPOS_GENERICNUMBER2 AS INSPECTOR_IDTIPOAGENTE,MANAGER.EPOS_GENERICATTRIBUTE2 AS INSPECTOR_TIPOAGENTE,
				INSP_CAP.EPOS_GENERICATTRIBUTE3 as INSPCAP_NAME, INSP_CAP.NIF as INSPCAP_NIF, INSP_CAP.NOMBRE_COMPLETO as INSPCAP_NOMBRE_COMPLETO, 
				INSP_CAP.ETITLE as INSPCAP_TITLE, INSP_CAP.EPAR_USERID as INSPCAP_LDAP,
				INSP_CAP.EPOS_GENERICNUMBER2 AS INSPCAP_IDTIPOAGENTE,INSP_CAP.EPOS_GENERICATTRIBUTE2 AS INSPCAP_TIPOAGENTE,
				1 as MEDCOUNT
			FROM CS_POSITION pos
			JOIN pos_ids i
				ON pos.RULEELEMENTOWNERSEQ = i.RULEELEMENTOWNERSEQ and POS.REMOVEDATE = TO_DATE('22000101','yyyymmdd')
			INNER JOIN CS_PARTICIPANT PAR -- Se hace un JOIN con CS_PARTICIPANT a ultimo dia del mes de cada periodo para extraer: PAR.PARTICIPANTEMAIL, PAR.TAXID y fechas de efectividad por si quisieran filtrar por fecha concreta
				ON  PAR.PAYEESEQ = POS.PAYEESEQ and PAR.REMOVEDATE = TO_DATE('22000101','yyyymmdd')
				AND PAR.EFFECTIVESTARTDATE<= POS.EFFECTIVESTARTDATE and  PAR.EFFECTIVEENDDATE > POS.EFFECTIVESTARTDATE

			INNER JOIN TCMP.CS_PAYEE R ON PAR.PAYEESEQ = R.PAYEESEQ and R.REMOVEDATE = TO_DATE('22000101','yyyymmdd')
				AND PAR.EFFECTIVESTARTDATE = R.EFFECTIVESTARTDATE and PAR.EFFECTIVEENDDATE = R.EFFECTIVEENDDATE	

			INNER JOIN TCMP.CS_TITLE TIT ON  POS.TITLESEQ = TIT.RULEELEMENTOWNERSEQ  AND TIT.REMOVEDATE = TO_DATE('22000101','yyyymmdd') 
				AND TIT.EFFECTIVESTARTDATE<= POS.EFFECTIVESTARTDATE and  TIT.EFFECTIVEENDDATE > POS.EFFECTIVESTARTDATE
								
			-- MANAGER
			LEFT JOIN ESTRUCTURA MANAGER ON MANAGER.EPOSITIONSEQ = POS.MANAGERSEQ --PAD.MANAGERSEQ 
											AND MANAGER.EPOS_GENERICNUMBER2 is not null 
											AND MANAGER.EPOS_GENERICATTRIBUTE3 NOT IN ('0000000000','0') 
											AND MANAGER.EPOS_MANAGERSEQ IS NOT NULL
											AND MANAGER.EPOS_EFFECTIVESTARTDATE < POS.EFFECTIVESTARTDATE and  MANAGER.EPOS_EFFECTIVEENDDATE >= POS.EFFECTIVESTARTDATE
											AND MANAGER.EPAR_EFFECTIVESTARTDATE <  POS.EFFECTIVESTARTDATE  and  MANAGER.EPAR_EFFECTIVEENDDATE >=  POS.EFFECTIVESTARTDATE  
											AND MANAGER.ETIT_EFFECTIVESTARTDATE <  POS.EFFECTIVESTARTDATE  and  MANAGER.ETIT_EFFECTIVEENDDATE >= POS.EFFECTIVESTARTDATE

			-- INSP_CAP						
			LEFT JOIN ESTRUCTURA INSP_CAP ON INSP_CAP.EPOS_NAME = POS.GENERICATTRIBUTE14  --PAD.POSITIONGENERICATTRIBUTE14
											AND INSP_CAP.EPOS_GENERICATTRIBUTE3 NOT IN ('0000000000','0') 
											AND INSP_CAP.EPOS_EFFECTIVESTARTDATE < POS.EFFECTIVESTARTDATE and  INSP_CAP.EPOS_EFFECTIVEENDDATE >= POS.EFFECTIVESTARTDATE
											AND INSP_CAP.EPAR_EFFECTIVESTARTDATE <  POS.EFFECTIVESTARTDATE  and  INSP_CAP.EPAR_EFFECTIVEENDDATE >=  POS.EFFECTIVESTARTDATE  
											AND INSP_CAP.ETIT_EFFECTIVESTARTDATE <  POS.EFFECTIVESTARTDATE  and  INSP_CAP.ETIT_EFFECTIVEENDDATE >=  POS.EFFECTIVESTARTDATE 
			-- PTO_VENTA
			LEFT JOIN ESTRUCTURA PTO_VENTA ON SUBSTR(POS.GENERICATTRIBUTE3,1,4) = PTO_VENTA.EPOS_NAME --SUBSTR(PAD.POSITIONGENERICATTRIBUTE3,1,4) = PTO_VENTA.EPOS_NAME
											AND PTO_VENTA.EPOS_GENERICNUMBER2 IS NULL 
											AND PTO_VENTA.EPOS_EFFECTIVESTARTDATE < POS.EFFECTIVESTARTDATE and  PTO_VENTA.EPOS_EFFECTIVEENDDATE >= POS.EFFECTIVESTARTDATE
											AND PTO_VENTA.EPAR_EFFECTIVESTARTDATE <  POS.EFFECTIVESTARTDATE  and  PTO_VENTA.EPAR_EFFECTIVEENDDATE >=  POS.EFFECTIVESTARTDATE  
											AND PTO_VENTA.ETIT_EFFECTIVESTARTDATE <  POS.EFFECTIVESTARTDATE  and  PTO_VENTA.ETIT_EFFECTIVEENDDATE >=  POS.EFFECTIVESTARTDATE
			-- OFI
			LEFT JOIN ESTRUCTURA OFI ON PTO_VENTA.EPOS_MANAGERSEQ = OFI.EPOSITIONSEQ
											AND OFI.EPOS_GENERICNUMBER2 IS NULL 
											AND OFI.EPOS_EFFECTIVESTARTDATE < POS.EFFECTIVESTARTDATE and  OFI.EPOS_EFFECTIVEENDDATE >= POS.EFFECTIVESTARTDATE
											AND OFI.EPAR_EFFECTIVESTARTDATE <  POS.EFFECTIVESTARTDATE  and  OFI.EPAR_EFFECTIVEENDDATE >=  POS.EFFECTIVESTARTDATE  
											AND OFI.ETIT_EFFECTIVESTARTDATE <  POS.EFFECTIVESTARTDATE  and  OFI.ETIT_EFFECTIVEENDDATE >=  POS.EFFECTIVESTARTDATE


			-- SUC
			LEFT JOIN ESTRUCTURA SUC ON OFI.EPOS_MANAGERSEQ = SUC.EPOSITIONSEQ
											AND SUC.EPOS_GENERICNUMBER2 IS NULL 
											AND SUC.EPOS_EFFECTIVESTARTDATE < POS.EFFECTIVESTARTDATE and  SUC.EPOS_EFFECTIVEENDDATE >= POS.EFFECTIVESTARTDATE
											AND SUC.EPAR_EFFECTIVESTARTDATE <  POS.EFFECTIVESTARTDATE  and  SUC.EPAR_EFFECTIVEENDDATE >=  POS.EFFECTIVESTARTDATE  
											AND SUC.ETIT_EFFECTIVESTARTDATE <  POS.EFFECTIVESTARTDATE  and  SUC.ETIT_EFFECTIVEENDDATE >=  POS.EFFECTIVESTARTDATE 		

			-- REG
			LEFT JOIN ESTRUCTURA REG ON SUC.EPOS_MANAGERSEQ = REG.EPOSITIONSEQ
											AND REG.EPOS_GENERICNUMBER2 IS NULL 
											AND REG.EPOS_EFFECTIVESTARTDATE < POS.EFFECTIVESTARTDATE and  REG.EPOS_EFFECTIVEENDDATE >= POS.EFFECTIVESTARTDATE
											AND REG.EPAR_EFFECTIVESTARTDATE <  POS.EFFECTIVESTARTDATE  and  REG.EPAR_EFFECTIVEENDDATE >=  POS.EFFECTIVESTARTDATE  
											AND REG.ETIT_EFFECTIVESTARTDATE <  POS.EFFECTIVESTARTDATE  and  REG.ETIT_EFFECTIVEENDDATE >=  POS.EFFECTIVESTARTDATE 		

			where Pos.effectiveenddate > '2020-01-01'		
			;
			
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Carga ESTRUCTURA_COMERCIAL. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio actualización de fecha en OUT_FECHAS_WEBI_REP de ESTRUCTURA_COMERCIAL', i_log_count, i_id_proceso, 'debug');
			CALL EXT.LIB_CREAR_TABLAS:UPDATE_FECHAS_WEBI(i_PeriodSeq, 'ESTRUCTURA_COMERCIAL');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin actualización de fecha en OUT_FECHAS_WEBI_REP de ESTRUCTURA_COMERCIAL', i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado y Carga Tabla Estructura.', i_log_count, i_id_proceso, 'info');

		-- Fin informe Estructura Comercial
		END IF;

		---------------------------------------------------------------------------------------------------------------------------------
		-- BRG 20250522: INFORME 1.11 PERCEPCION AGENTES
		IF :i_lista_informes = 'PEAG' OR :i_lista_informes LIKE '%|PEAG|%' OR :i_lista_informes LIKE '%|PEAG' OR :i_lista_informes LIKE 'PEAG|%' 
			OR :i_lista_informes = 'ALL' THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe 1.11 Percepción Agentes.', i_log_count, i_id_proceso, 'info');

			-- BRG 20250523: Nueva tabla OUT_PERC_AGENTES_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_PERC_AGENTES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_PERC_AGENTES_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_PERC_AGENTES_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_PERC_AGENTES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PERC_AGENTES_FINAL_REP (REGIONAL,SUCURSAL,OFICINA,COD,AGENTE,NIF,NIF_NOMBRE,CUADRO,COD_TIPO,TIPO,PERIODO,MES_PERIODO,PERCEPCION,IMPORTE,MES_PERCEPCION,IGUALES,ANYO,INCLUIR_AGENCIAS,FEC_ACTUALIZACION,POSITIONSEQ,PERIODSEQ)
				WITH CTE_JERARQUIA AS (SELECT DISTINCT
						PARTICIPANTSEQ,
						POSITIONSEQ_PRIN,
						POSITIONSEQ,
						POS_PRIN,
						PERIODSEQ,
						PERIODO,
						COD_REGIONAL,
						REGIONAL,
						COD_SUCURSAL,
						SUCURSAL,
						COD_OFICINA,
						OFICINA,
						NOMBRE,
						NIF,
						CUADRO_RRGG_OCASO,
						ID_TIPO_AGENTE,
						TIPO_AGENTE
					FROM EXT.OUT_JERARQUIA_REP
					WHERE PERIODSEQ = :i_PeriodSeq)
				SELECT DISTINCT --LLS 20251112: Añadido el distinct
					J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
					J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
					J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
					J.POS_PRIN AS COD,
					J.NOMBRE AS AGENTE,
					J.NIF,
					J.NIF || ' - ' || J.NOMBRE AS NIF_NOMBRE,
					J.CUADRO_RRGG_OCASO AS CUADRO,
					TO_INTEGER(J.ID_TIPO_AGENTE) AS COD_TIPO,
					J.TIPO_AGENTE AS TIPO,
					:v_period_name_format AS PERIODO,
					SUBSTR(:v_period_name_format, 6, 2) AS MES_PERIODO,
					PERC.PERCEPCION AS PERCEPCION,
					SUM(ROUND(PERC.IMP_PERCEPCION, 2)) AS IMPORTE,
					TO_VARCHAR(PERC.MES_PERCEPCION, '00') AS MES_PERCEPCION,
					CASE 
						WHEN SUBSTR(:v_period_name_format, 6, 2) = TO_VARCHAR(PERC.MES_PERCEPCION, '00')
							THEN 1
						ELSE 0
						END AS IGUALES,
					PERC.YEAR,
					CASE
						WHEN J.POS_PRIN LIKE '%999999'
							THEN 'SI'
						ELSE 'NO'
						END AS INCLUIR_AGENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					J.POSITIONSEQ_PRIN AS POSITIONSEQ,
					J.PERIODSEQ
				FROM CTE_JERARQUIA J
				INNER JOIN EXT.OUT_PERC_AGENTES_REP PERC ON J.PARTICIPANTSEQ = PERC.PARTICIPANTSEQ
					AND J.POSITIONSEQ_PRIN = PERC.POSITIONSEQ_PRIN
					AND J.PERIODSEQ = PERC.PERIODSEQ
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_PERC_AGENTES_REP'
				WHERE J.PERIODSEQ = :i_PeriodSeq
					AND J.POSITIONSEQ = J.POSITIONSEQ_PRIN --LLS 20251124: Añadido para quitar posiciones secundarias
				GROUP BY J.COD_REGIONAL, J.REGIONAL, J.COD_SUCURSAL, J.SUCURSAL, J.COD_OFICINA, J.OFICINA,
				J.POS_PRIN, J.NOMBRE, J.NIF, J.CUADRO_RRGG_OCASO, J.ID_TIPO_AGENTE, J.TIPO_AGENTE, 
				PERC.PERCEPCION,
				PERC.MES_PERCEPCION, PERC.YEAR, F.ULTIMA_ACTUALIZACION,
				J.POSITIONSEQ_PRIN, J.PERIODSEQ,
				CASE
					WHEN J.POS_PRIN LIKE '%999999'
						THEN 'SI'
					ELSE 'NO'
					END;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_PERC_AGENTES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe 1.11 Percepción Agentes', i_log_count, i_id_proceso, 'info');

		-- Fin informe 1.11 Percepcion Agentes
		END IF;

		-------------------------------------------------------------------------------------------------------------------------------------
		--DTB 20250526: INFORME 1.12 PRODUCCION AGENTES
		IF :i_lista_informes = 'PRAG' OR :i_lista_informes LIKE '%|PRAG|%' OR :i_lista_informes LIKE '%|PRAG' OR :i_lista_informes LIKE 'PRAG|%' 
			OR :i_lista_informes = 'ALL' THEN

			--ALM 20170420: No tenemos en cuenta si el periodo esta cerrado para este informe porque no se entrega a agentes.
			--              Por lo tanto lo recargamos siempre con la ultima informacion.    
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe 1.12 Producción Agentes', i_log_count, i_id_proceso, 'info');

			-- DTB 20250523 Creacion de la tabla OUT_PROD_AGENTES_FINAL_REP, de ella tira la Vista
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Borrado OUT_PROD_AGENTES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_PROD_AGENTES_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Borrado OUT_PROD_AGENTES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			--BRG 20260401 Antiguo INSERT
			INSERT INTO EXT.OUT_PROD_AGENTES_FINAL_REP (REGIONAL, SUCURSAL, OFICINA, COD_AGENTE, AGENTE, POSITIONNAME, NIF, NIF_NOMBRE, CUADRO, TIPO_AGENTE, FECHA_ALTA, AGENTES_ACTIVOS, MANAGER, MANAGER_NOMBRE, MANAGER_NIF, PRODUCTOS, ASEG, POL_FIS, POL_CORR, PRIMAS, ID_TIPO_AGENTE, YEAR, PERIODO, PERIODO_FORMATO, PERIODO_TABLA, IGUALES, FEC_ACTUALIZACION, POSITIONSEQ, PERIODSEQ)
				SELECT DISTINCT
					J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
					J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
					J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
					J.POS_PRIN AS COD_AGENTE,
					J.NOMBRE AS AGENTE,
					J.POS_CALLIDUS AS POSITIONNAME,
					J.NIF,
					J.NIF || ' - ' || J.NOMBRE AS NIF_NOMBRE,
					J.CUADRO_RRGG_OCASO AS CUADRO,
					TO_INTEGER(J.ID_TIPO_AGENTE) || ' - ' || J.TIPO_AGENTE AS TIPO_AGENTE,
					TO_VARCHAR(J.FEC_ALTA_POS, 'DD/MM/YYYY') AS FECHA_ALTA,
					CASE WHEN J.FEC_BAJA_POS IS NULL
						THEN 'SI'
						ELSE 'NO'
						END AS AGENTES_ACTIVOS,
					J.MANAGER_POS_PRIN AS MANAGER,
					J.MANAGER_NOMBRE,
					J.MANAGER_NIF,
					RIGHT(LEFT(PROD_AGENTES.PRODUCTID, 5), 3) AS PRODUCTOS,
					SUM(CASE WHEN PROD_AGENTES.NAME = 'DC-O-GEN-Agente-NumAsegurados'
						THEN IFNULL(ROUND(PROD_AGENTES.VALUE, 2), 0)
						ELSE 0
						END) AS ASEG,
					SUM(CASE WHEN PROD_AGENTES.NAME LIKE '%Poliza%998'
						THEN IFNULL(ROUND(PROD_AGENTES.VALUE, 2), 0)
						ELSE 0
						END) AS POL_FIS,
					SUM(CASE WHEN PROD_AGENTES.NAME LIKE '%Poliza%998'
						THEN IFNULL(ROUND(PROD_AGENTES.C_GN4, 2), 0)
						ELSE 0
						END) AS POL_CORR,
					SUM(CASE WHEN (PROD_AGENTES.NAME LIKE '%Prima%' 
							OR PROD_AGENTES.NAME LIKE '%998-Re%')
						THEN IFNULL(ROUND(PROD_AGENTES.VALUE, 2), 0)
						ELSE 0
						END) AS PRIMAS,
                    --BRG 20251226 Añadido para Producción por Meses
                    0 AS ID_TIPO_AGENTE,
				
					PROD_AGENTES.YEAR,
					J.PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
                    --BRG 20251224 Añadido para Producción por Meses
                    TO_VARCHAR(PROD_AGENTES.STARTDATE, 'YYYY-MM') AS PERIODO_TABLA,
					CASE WHEN PROD_AGENTES.PERIODO = J.PERIODO
						THEN 'SI'
						ELSE 'NO'
						END AS IGUALES,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					J.POSITIONSEQ_PRIN AS POSITIONSEQ,
					J.PERIODSEQ
				FROM EXT.OUT_JERARQUIA_REP J
				INNER JOIN EXT.OUT_PROD_AGENTES_REP PROD_AGENTES ON J.PARTICIPANTSEQ = PROD_AGENTES.PARTICIPANTSEQ
					AND J.POSITIONSEQ_PRIN = PROD_AGENTES.POSITIONSEQ_PRIN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_PROD_AGENTES_REP'
				WHERE J.PERIODSEQ = :i_PeriodSeq
					AND (J.MANAGER_POS_PRIN = J.MANAGER_POSITIONNAME OR J.MANAGER_POS_PRIN IS NULL)
					AND PROD_AGENTES.YEAR = :v_period_year
					AND PROD_AGENTES.STARTDATE <= :v_period_startdate
				GROUP BY J.COD_REGIONAL, J.REGIONAL, J.COD_SUCURSAL, J.SUCURSAL, J.COD_OFICINA, J.OFICINA,
					J.POS_PRIN, J.NOMBRE, J.POS_CALLIDUS, J.NIF, J.CUADRO_RRGG_OCASO, J.ID_TIPO_AGENTE, J.TIPO_AGENTE, J.FEC_BAJA_POS,
					J.MANAGER_POS_PRIN, J.MANAGER_NOMBRE, J.MANAGER_NIF, RIGHT(LEFT(PROD_AGENTES.PRODUCTID, 5), 3),
					PROD_AGENTES.YEAR, J.PERIODO, PROD_AGENTES.PERIODO, PROD_AGENTES.STARTDATE,
                    F.ULTIMA_ACTUALIZACION, J.POSITIONSEQ_PRIN, J.PERIODSEQ, J.FEC_ALTA_POS;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Carga OUT_PROD_AGENTES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			

			--BRG 20260305 Query usando la información de la tabla S4_POLIZAS
			/*CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Carga OUT_PROD_AGENTES_FINAL_REP. Valores S4 Polizas.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PROD_AGENTES_FINAL_REP (REGIONAL, SUCURSAL, OFICINA, COD_AGENTE, AGENTE, POSITIONNAME, NIF, NIF_NOMBRE, CUADRO, TIPO_AGENTE, FECHA_ALTA, AGENTES_ACTIVOS, MANAGER, MANAGER_NOMBRE, MANAGER_NIF, PRODUCTOS, ASEG, POL_FIS, POL_CORR, PRIMAS, ID_TIPO_AGENTE, YEAR, PERIODO, PERIODO_FORMATO, PERIODO_TABLA, IGUALES, FEC_ACTUALIZACION, POSITIONSEQ, PERIODSEQ)
				WITH CTE_JERARQUIA AS (SELECT DISTINCT
							PARTICIPANTSEQ,
							POSITIONSEQ_PRIN,
							POSITIONSEQ,
							POS_PRIN,
							POS_CALLIDUS,
							PERIODSEQ,
							PERIODO,
							COD_REGIONAL,
							REGIONAL,
							COD_SUCURSAL,
							SUCURSAL,
							COD_OFICINA,
							OFICINA,
							NOMBRE,
							NIF,
							CUADRO_RRGG_OCASO,
							ID_TIPO_AGENTE,
							TIPO_AGENTE,
							FEC_ALTA_POS,
							FEC_BAJA_POS,
							MANAGER_POS_PRIN,
							MANAGER_POSITIONNAME,
							MANAGER_NOMBRE,
							MANAGER_NIF
						FROM EXT.OUT_JERARQUIA_REP
						WHERE PERIODSEQ = :i_PeriodSeq)
				SELECT DISTINCT
					J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
					J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
					J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
					J.POS_PRIN AS COD_AGENTE,
					J.NOMBRE AS AGENTE,
					J.POS_CALLIDUS AS POSITIONNAME,
					J.NIF,
					J.NIF || ' - ' || J.NOMBRE AS NIF_NOMBRE,
					J.CUADRO_RRGG_OCASO AS CUADRO,
					TO_INTEGER(J.ID_TIPO_AGENTE) || ' - ' || J.TIPO_AGENTE AS TIPO_AGENTE,
					TO_VARCHAR(J.FEC_ALTA_POS, 'DD/MM/YYYY') AS FECHA_ALTA,
					CASE WHEN J.FEC_BAJA_POS IS NULL
						THEN 'SI'
						ELSE 'NO'
						END AS AGENTES_ACTIVOS,
					J.MANAGER_POS_PRIN AS MANAGER,
					J.MANAGER_NOMBRE,
					J.MANAGER_NIF,

					RIGHT(LEFT(S4.PRODUCTID, 5), 3) AS PRODUCTOS,
					SUM(S4.ASEGURADOS) AS ASEG,
					SUM(S4.POLIZ_NP) AS POL_FIS,
					SUM(CASE
					WHEN S4.NAME LIKE '%Recuperadas' AND (LEFT(RIGHT(S4.PRODUCTID,5),3) <> '501'
							OR S4.ID_TIPO_AGENTE = 39)
							THEN 0
					ELSE S4.POLIZ_CORR
					END) AS POL_CORR,
					SUM(CASE
						WHEN (S4.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' 
						OR S4.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' 
						OR S4.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' 
						OR S4.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' 
						OR S4.NAME LIKE 'DC-O-COM%-GestionCobro' 
						OR S4.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' 
						OR S4.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' 
						OR S4.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' 
						OR S4.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' 
						OR S4.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' 
						OR S4.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' 
						OR S4.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' 
						OR S4.NAME LIKE 'DC-O-COM%-Cartera-Importe' 
						OR S4.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' 
						OR S4.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' 
						OR S4.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' 
						OR S4.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
						OR S4.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos' 
						OR S4.NAME LIKE 'DC-O-COM-AgentesZona-Porcentaje' 
						OR S4.NAME LIKE 'DC-O-SER%' 
						OR S4.NAME LIKE 'CARTERA_LP')
					THEN S4.PRIMA_COMIS
					ELSE 0
					END) AS PRIMAS,
					0 AS ID_TIPO_AGENTE,
					:v_period_year AS YEAR,
					:v_period_name AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					TO_VARCHAR((SELECT MAX(STARTDATE) FROM CS_PERIOD WHERE PERIODSEQ = S4.PERIODSEQ AND REMOVEDATE = '2200-01-01'), 'YYYY-MM') AS PERIODO_TABLA,
					CASE WHEN S4.PERIODO = J.PERIODO
							THEN 'SI'
							ELSE 'NO'
							END AS IGUALES,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					J.POSITIONSEQ_PRIN AS POSITIONSEQ,
					:i_PeriodSeq AS PERIODSEQ
				FROM CTE_JERARQUIA J
				INNER JOIN EXT.OUT_S4_POLIZAS_REP S4 ON RIGHT(S4.PERIODO, 4) = :v_period_year
					-- BRG 20260428 Sólo el mes actual
					AND (SELECT MAX(STARTDATE) FROM CS_PERIOD WHERE PERIODSEQ = S4.PERIODSEQ AND REMOVEDATE = '2200-01-01') = :v_period_startdate
					AND (J.MANAGER_POS_PRIN = J.MANAGER_POSITIONNAME OR J.MANAGER_POS_PRIN IS NULL)
					AND S4.PARTICIPANTSEQ = J.PARTICIPANTSEQ
					AND S4.POSITIONSEQ_PRIN = J.POSITIONSEQ
				INNER JOIN EXT.CONF_AGENTES_REP AG ON J.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
					AND AG.COD_INFORME = 112
					AND AG.F_INICIO <= :v_period_startdate AND AG.F_FIN > :v_period_startdate
					--BRG 20260423 Revisando meses anteriores a la corrección he visto que los DDEE NO se mostraban en el 1.12
					AND AG.ID_TIPO_AGENTE <> 12
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_S4_POLIZAS_REP'
				WHERE J.PERIODSEQ = :i_PeriodSeq
				GROUP BY J.COD_REGIONAL, J.REGIONAL, J.COD_SUCURSAL, J.SUCURSAL, J.COD_OFICINA, J.OFICINA,
						J.POS_PRIN, J.NOMBRE, J.POS_CALLIDUS, J.NIF, J.CUADRO_RRGG_OCASO, J.ID_TIPO_AGENTE, J.TIPO_AGENTE,
						J.FEC_ALTA_POS, J.FEC_BAJA_POS, J.MANAGER_POS_PRIN, J.MANAGER_NOMBRE, J.MANAGER_NIF,
						RIGHT(LEFT(S4.PRODUCTID, 5), 3), S4.PERIODO, J.PERIODO, S4.PERIODSEQ, J.PERIODSEQ, J.POSITIONSEQ_PRIN,
						F.ULTIMA_ACTUALIZACION
				
				UNION ALL
				
				SELECT DISTINCT
					J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
					J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
					J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
					J.POS_PRIN AS COD_AGENTE,
					J.NOMBRE AS AGENTE,
					J.POS_CALLIDUS AS POSITIONNAME,
					J.NIF,
					J.NIF || ' - ' || J.NOMBRE AS NIF_NOMBRE,
					J.CUADRO_RRGG_OCASO AS CUADRO,
					TO_INTEGER(J.ID_TIPO_AGENTE) || ' - ' || J.TIPO_AGENTE AS TIPO_AGENTE,
					TO_VARCHAR(J.FEC_ALTA_POS, 'DD/MM/YYYY') AS FECHA_ALTA,
					CASE WHEN J.FEC_BAJA_POS IS NULL
						THEN 'SI'
						ELSE 'NO'
						END AS AGENTES_ACTIVOS,
					J.MANAGER_POS_PRIN AS MANAGER,
					J.MANAGER_NOMBRE,
					J.MANAGER_NIF,

					RIGHT(LEFT(S4.PRODUCTID, 5), 3) AS PRODUCTOS,
					SUM(S4.ASEGURADOS) AS ASEG,
					SUM(S4.POLIZ_NP) AS POL_FIS,
					SUM(CASE
					WHEN S4.NAME LIKE '%Recuperadas' AND (LEFT(RIGHT(S4.PRODUCTID,5),3) <> '501'
							OR S4.ID_TIPO_AGENTE = 39)
							THEN 0
					ELSE S4.POLIZ_CORR
					END) AS POL_CORR,
					SUM(CASE
						WHEN (S4.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' 
						OR S4.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' 
						OR S4.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' 
						OR S4.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' 
						OR S4.NAME LIKE 'DC-O-COM%-GestionCobro' 
						OR S4.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' 
						OR S4.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' 
						OR S4.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' 
						OR S4.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' 
						OR S4.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' 
						OR S4.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' 
						OR S4.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' 
						OR S4.NAME LIKE 'DC-O-COM%-Cartera-Importe' 
						OR S4.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' 
						OR S4.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' 
						OR S4.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' 
						OR S4.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
						OR S4.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos' 
						OR S4.NAME LIKE 'DC-O-COM-AgentesZona-Porcentaje' 
						OR S4.NAME LIKE 'DC-O-SER%' 
						OR S4.NAME LIKE 'CARTERA_LP')
					THEN S4.PRIMA_COMIS
					ELSE 0
					END) AS PRIMAS,
					0 AS ID_TIPO_AGENTE,
					:v_period_year AS YEAR,
					:v_period_name AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					TO_VARCHAR((SELECT MAX(STARTDATE) FROM CS_PERIOD WHERE PERIODSEQ = S4.PERIODSEQ AND REMOVEDATE = '2200-01-01'), 'YYYY-MM') AS PERIODO_TABLA,
					CASE WHEN S4.PERIODO = J.PERIODO
							THEN 'SI'
							ELSE 'NO'
							END AS IGUALES,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					J.POSITIONSEQ_PRIN AS POSITIONSEQ,
					:i_PeriodSeq AS PERIODSEQ
				FROM CTE_JERARQUIA J
				INNER JOIN EXT.OUT_BAL_S4_POLIZAS_REP S4 ON RIGHT(S4.PERIODO, 4) = :v_period_year
					-- BRG 20260428 Meses anteriores al actual
					AND (SELECT MAX(STARTDATE) FROM CS_PERIOD WHERE PERIODSEQ = S4.PERIODSEQ AND REMOVEDATE = '2200-01-01') < :v_period_startdate
					AND (J.MANAGER_POS_PRIN = J.MANAGER_POSITIONNAME OR J.MANAGER_POS_PRIN IS NULL)
					AND S4.PARTICIPANTSEQ = J.PARTICIPANTSEQ
					AND S4.POSITIONSEQ_PRIN = J.POSITIONSEQ
				INNER JOIN EXT.CONF_AGENTES_REP AG ON J.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
					AND AG.COD_INFORME = 112
					AND AG.F_INICIO <= :v_period_startdate AND AG.F_FIN > :v_period_startdate
					--BRG 20260423 Revisando meses anteriores a la corrección he visto que los DDEE NO se mostraban en el 1.12
					AND AG.ID_TIPO_AGENTE <> 12
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_S4_POLIZAS_REP'
				WHERE J.PERIODSEQ = :i_PeriodSeq
				GROUP BY J.COD_REGIONAL, J.REGIONAL, J.COD_SUCURSAL, J.SUCURSAL, J.COD_OFICINA, J.OFICINA,
						J.POS_PRIN, J.NOMBRE, J.POS_CALLIDUS, J.NIF, J.CUADRO_RRGG_OCASO, J.ID_TIPO_AGENTE, J.TIPO_AGENTE,
						J.FEC_ALTA_POS, J.FEC_BAJA_POS, J.MANAGER_POS_PRIN, J.MANAGER_NOMBRE, J.MANAGER_NIF,
						RIGHT(LEFT(S4.PRODUCTID, 5), 3), S4.PERIODO, J.PERIODO, S4.PERIODSEQ, J.PERIODSEQ, J.POSITIONSEQ_PRIN,
						F.ULTIMA_ACTUALIZACION
				;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Carga OUT_PROD_AGENTES_FINAL_REP. Valores S4 Polizas. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			*/

			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Carga OUT_PROD_AGENTES_FINAL_REP. ID Tipo Agente', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PROD_AGENTES_FINAL_REP (REGIONAL, SUCURSAL, OFICINA, COD_AGENTE, AGENTE, POSITIONNAME, NIF, NIF_NOMBRE, CUADRO, TIPO_AGENTE, FECHA_ALTA, AGENTES_ACTIVOS, MANAGER, MANAGER_NOMBRE, MANAGER_NIF, PRODUCTOS, ASEG, POL_FIS, POL_CORR, PRIMAS, ID_TIPO_AGENTE, YEAR, PERIODO, PERIODO_FORMATO, PERIODO_TABLA, IGUALES, FEC_ACTUALIZACION, POSITIONSEQ, PERIODSEQ)
                WITH date_range AS (
                    SELECT v_period_year || '-01' AS periodo_tabla FROM DUMMY UNION ALL
                    SELECT v_period_year || '-02' FROM DUMMY UNION ALL
                    SELECT v_period_year || '-03' FROM DUMMY UNION ALL
                    SELECT v_period_year || '-04' FROM DUMMY UNION ALL
                    SELECT v_period_year || '-05' FROM DUMMY UNION ALL
                    SELECT v_period_year || '-06' FROM DUMMY UNION ALL
                    SELECT v_period_year || '-07' FROM DUMMY UNION ALL
                    SELECT v_period_year || '-08' FROM DUMMY UNION ALL
                    SELECT v_period_year || '-09' FROM DUMMY UNION ALL
                    SELECT v_period_year || '-10' FROM DUMMY UNION ALL
                    SELECT v_period_year || '-11' FROM DUMMY UNION ALL
                    SELECT v_period_year || '-12' FROM DUMMY
                )
                SELECT DISTINCT
                    PRAG.REGIONAL,
                    PRAG.SUCURSAL,
                    PRAG.OFICINA,
                    PRAG.COD_AGENTE,
                    PRAG.AGENTE,
                    PRAG.POSITIONNAME,
                    PRAG.NIF,
                    PRAG.NIF_NOMBRE,
                    PRAG.CUADRO,
                    PRAG.TIPO_AGENTE,
					PRAG.FECHA_ALTA,
                    PRAG.AGENTES_ACTIVOS,
                    PRAG.MANAGER,
                    PRAG.MANAGER_NOMBRE,
                    PRAG.MANAGER_NIF,
                    NULL AS PRODUCTOS,
                    0 AS ASEG,
                    0 AS POL_FIS,
                    0 AS POL_CORR,
                    0 AS PRIMAS,
                    TO_INTEGER(J.ID_TIPO_AGENTE),
                    PRAG.YEAR,
                    PRAG.PERIODO,
                    PRAG.PERIODO_FORMATO,
                    DR.PERIODO_TABLA,
                    NULL AS IGUALES,
                    PRAG.FEC_ACTUALIZACION,
                    PRAG.POSITIONSEQ,
                    PRAG.PERIODSEQ
                FROM EXT.OUT_PROD_AGENTES_FINAL_REP PRAG
                CROSS JOIN DATE_RANGE DR 
                INNER JOIN EXT.OUT_JERARQUIA_REP J ON J.POSITIONSEQ = PRAG.POSITIONSEQ
                    AND J.STARTDATE = TO_DATE(DR.PERIODO_TABLA)
                WHERE TO_DATE(DR.PERIODO_TABLA) <= :v_period_startdate
                    AND PRAG.PERIODSEQ = :i_PeriodSeq;
            v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Carga OUT_PROD_AGENTES_FINAL_REP. ID Tipo Agente. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe 1.12 Producción Agentes', i_log_count, i_id_proceso, 'info');
		
		-- Fin informe 1.12 Producción agentes
		END IF;
		
		--------------------------------------------------------------------------------------------------------------
		-- DTB 20250522: INFORME 1.13 PERCEPCIONES INSPECTORES
		IF :i_lista_informes = 'PEIN' OR :i_lista_informes LIKE '%|PEIN|%' OR :i_lista_informes LIKE '%|PEIN' OR :i_lista_informes LIKE 'PEIN|%' 
			OR :i_lista_informes = 'ALL' THEN

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe 1.13 Percepción Inspectores', i_log_count, i_id_proceso, 'info');

			-- DTB 20250523 Creacion de la tabla OUT_PERC_INSPECTORES_FINAL_REP, de ella tira la Vista
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Borrado OUT_PERC_INSPECTORES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_PERC_INSPECTORES_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Borrado OUT_PERC_INSPECTORES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Carga OUT_PERC_INSPECTORES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PERC_INSPECTORES_FINAL_REP (REGIONAL,SUCURSAL,OFICINA,COD,AGENTE,NIF,NIF_NOMBRE,CUADRO,COD_TIPO,TIPO,PERIODO,MES_PERIODO,PERCEPCION,IMPORTE,MES_PERCEPCION,IGUALES,ANYO,INCLUIR_AGENCIAS,FEC_ACTUALIZACION,POSITIONSEQ,PERIODSEQ)
				WITH CTE_JERARQUIA AS (SELECT DISTINCT
						PARTICIPANTSEQ,
						POSITIONSEQ_PRIN,
						POSITIONSEQ,
						POS_PRIN,
						PERIODSEQ,
						PERIODO,
						COD_REGIONAL,
						REGIONAL,
						COD_SUCURSAL,
						SUCURSAL,
						COD_OFICINA,
						OFICINA,
						NOMBRE,
						NIF,
						CUADRO_INSP_OCASO,
						ID_TIPO_AGENTE,
						TIPO_AGENTE
					FROM EXT.OUT_JERARQUIA_REP
					WHERE PERIODSEQ = :i_PeriodSeq)
				SELECT DISTINCT --LLS 20251112: Añadido el distinct
					J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
					J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
					J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
					J.POS_PRIN AS COD,
					J.NOMBRE AS AGENTE,
					J.NIF,
					J.NIF || ' - ' || J.NOMBRE AS NIF_NOMBRE,
					J.CUADRO_INSP_OCASO AS CUADRO,
					TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) AS COD_TIPO,
					J.TIPO_AGENTE AS TIPO,
					:v_period_name_format AS PERIODO,
					SUBSTR(:v_period_name_format, 6, 2) AS MES_PERIODO,
					PERC.PERCEPCION AS PERCEPCION,
					SUM(ROUND(PERC.IMP_PERCEPCION, 2)) AS IMPORTE,
					TO_VARCHAR(PERC.MES_PERCEPCION, '00') AS MES_PERCEPCION,
					CASE 
						WHEN SUBSTR(:v_period_name_format, 6, 2) = MES_PERCEPCION
							THEN 1
						ELSE 0
						END AS IGUALES,
					PERC.YEAR AS ANYO,
					CASE
						WHEN J.POS_PRIN LIKE '%999999'
							THEN 'SI'
						ELSE 'NO'
						END AS INCLUIR_AGENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					J.POSITIONSEQ_PRIN AS POSITIONSEQ,
					J.PERIODSEQ
				FROM EXT.OUT_PERC_INSPECTORES_REP PERC
				INNER JOIN CTE_JERARQUIA J ON J.POSITIONSEQ_PRIN = PERC.POSITIONSEQ_PRIN
					AND J.PARTICIPANTSEQ = PERC.PARTICIPANTSEQ
					AND J.PERIODSEQ = PERC.PERIODSEQ
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_PERC_INSPECTORES_REP'
				WHERE J.PERIODSEQ = :i_PeriodSeq
					AND J.POSITIONSEQ = J.POSITIONSEQ_PRIN --LLS 20251124: Añadido para quitar posiciones secundarias
				GROUP BY J.COD_REGIONAL, J.REGIONAL, J.COD_SUCURSAL, J.SUCURSAL, J.COD_OFICINA, J.OFICINA,
					J.POS_PRIN, J.NOMBRE, J.NIF, J.CUADRO_INSP_OCASO, J.ID_TIPO_AGENTE, J.TIPO_AGENTE, PERC.PERCEPCION,
                    PERC.MES_PERCEPCION, PERC.YEAR, F.ULTIMA_ACTUALIZACION,
                    J.POSITIONSEQ_PRIN, J.PERIODSEQ,
                    CASE
						WHEN J.POS_PRIN LIKE '%999999'
							THEN 'SI'
						ELSE 'NO'
						END;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Carga OUT_PERC_INSPECTORES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe 1.13 Percepción Inspectores', i_log_count, i_id_proceso, 'info');

		-- Fin informe 1.13 Percepciones Inspectores
		END IF;
		
		-------------------------------------------------------------------------------------------------------------------------------------
		--DTB 20250526: INFORME 1.14 PRODUCCION INSPECTORES
		IF :i_lista_informes = 'PRIN' OR :i_lista_informes LIKE '%|PRIN|%' OR :i_lista_informes LIKE '%|PRIN' OR :i_lista_informes LIKE 'PRIN|%' 
			OR i_lista_informes = 'ALL' THEN

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe 1.14 Producción Inspectores', i_log_count, i_id_proceso, 'info');

			-- DTB 20250523 Creacion de la tabla Final, de ella tira la Vista
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Borrado OUT_PROD_INSPECTORES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_PROD_INSPECTORES_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Borrado OUT_PROD_INSPECTORES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			--BRG 20250401 Antiguo INSERT
			/*INSERT INTO EXT.OUT_PROD_INSPECTORES_FINAL_REP (REGIONAL,SUCURSAL,OFICINA,COD,AGENTE,NIF,NIF_NOMBRE,CUADRO,TIPO_AGENTE,INSPECTOR_ACTIVO,PRODUCTOS,POL_FIS,POL_CORR,PRIMA,PRIMA_CORR,YEAR,PERIODO,PERIODO_FORMATO,IGUALES,FEC_ACTUALIZACION,POSITIONSEQ,PERIODSEQ)
				SELECT DISTINCT --LLS 20251112: Añadido el distinct
					J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
					J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
					J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
					J.POS_PRIN AS COD_AGENTE,
					J.NOMBRE AS AGENTE,
					J.NIF,
					J.NIF || ' - ' || J.NOMBRE AS NIF_NOMBRE,
					J.CUADRO_INSP_OCASO AS CUADRO,
					TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) || ' - ' || J.TIPO_AGENTE AS TIPO_AGENTE,
					CASE 
						WHEN J.FEC_BAJA_POS IS NULL
							THEN 'SI'
						ELSE 'NO'
						END AS INSPECTOR_ACTIVO,
					RIGHT(LEFT(PROD.PRODUCTID, 5), 3) AS PRODUCTOS,
					SUM(CASE
						WHEN PROD.NAME LIKE '%Poliza%998' 
							THEN IFNULL(ROUND(PROD.VALUE, 2), 0)
						ELSE 0
						END) AS POL_FIS,
					SUM(CASE
						WHEN PROD.NAME LIKE '%Poliza%998%'
							THEN IFNULL(ROUND(PROD.POLIZ_CORR, 2), 0)
						ELSE 0
						END) AS POL_CORR,
					SUM(CASE
						WHEN PROD.NAME LIKE '%Prima%'
							THEN IFNULL(ROUND(PROD.C_GN5, 2), 0)
						ELSE 0
						END) AS PRIMA,
					SUM(CASE
						WHEN PROD.NAME LIKE '%Prima%'
							THEN IFNULL(ROUND(PROD.VALUE, 2), 0)
						ELSE 0
						END) AS PRIMA_CORR,
					PROD.YEAR,
					J.PERIODO,
					:v_period_name_format,
					CASE 
						WHEN PROD.PERIODO = J.PERIODO
							THEN 1
						ELSE 0
						END AS IGUALES,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					J.POSITIONSEQ_PRIN AS POSITIONSEQ,
					J.PERIODSEQ
				FROM EXT.OUT_PROD_INSPECTORES_REP PROD
				INNER JOIN EXT.OUT_JERARQUIA_REP J
					ON J.PARTICIPANTSEQ = PROD.PARTICIPANTSEQ
					AND J.POSITIONSEQ_PRIN = PROD.POSITIONSEQ_PRIN
					AND PROD.YEAR = RIGHT(J.PERIODO, 4)
					AND MONTH(PROD.STARTDATE) <= MONTH(J.STARTDATE)
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_PROD_INSPECTORES_REP'
				WHERE J.PERIODSEQ = :i_PeriodSeq
					AND J.POSITIONSEQ = J.POSITIONSEQ_PRIN --LLS 20251124: Añadido para quitar posiciones secundarias
				GROUP BY J.COD_REGIONAL, J.REGIONAL, J.COD_SUCURSAL, J.SUCURSAL, J.COD_OFICINA, J.OFICINA,
					J.POS_PRIN, J.NOMBRE, J.NIF, J.CUADRO_INSP_OCASO, J.ID_TIPO_AGENTE,  J.TIPO_AGENTE, J.FEC_BAJA_POS,
					RIGHT(LEFT(PROD.PRODUCTID, 5), 3),
                    PROD.YEAR, J.PERIODO, PROD.PERIODO, F.ULTIMA_ACTUALIZACION,
                    J.POSITIONSEQ_PRIN, J.PERIODSEQ;
			*/

			--BRG 20260304 Query usando la información de la tabla S5_POLIZAS
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Inicio Carga OUT_PROD_INSPECTORES_FINAL_REP. Valores S5 Polizas.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PROD_INSPECTORES_FINAL_REP (REGIONAL,SUCURSAL,OFICINA,COD,AGENTE,NIF,NIF_NOMBRE,CUADRO,TIPO_AGENTE,INSPECTOR_ACTIVO,PRODUCTOS,POL_FIS,POL_CORR,PRIMA,PRIMA_CORR,YEAR,PERIODO,PERIODO_FORMATO,IGUALES,FEC_ACTUALIZACION,POSITIONSEQ,PERIODSEQ)
				WITH CTE_JERARQUIA AS (SELECT DISTINCT
						PARTICIPANTSEQ,
						POSITIONSEQ_PRIN,
						POSITIONSEQ,
						POS_PRIN,
						PERIODSEQ,
						PERIODO,
						COD_REGIONAL,
						REGIONAL,
						COD_SUCURSAL,
						SUCURSAL,
						COD_OFICINA,
						OFICINA,
						NOMBRE,
						NIF,
						CUADRO_INSP_OCASO,
						ID_TIPO_AGENTE,
						TIPO_AGENTE,
						FEC_BAJA_POS
					FROM EXT.OUT_JERARQUIA_REP
					WHERE PERIODSEQ = :i_PeriodSeq)
				SELECT DISTINCT 
					J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
					J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
					J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
					J.POS_PRIN AS COD_AGENTE,
					J.NOMBRE AS AGENTE,
					J.NIF,
					J.NIF || ' - ' || J.NOMBRE AS NIF_NOMBRE,
					J.CUADRO_INSP_OCASO AS CUADRO,
					TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) || ' - ' || J.TIPO_AGENTE AS TIPO_AGENTE,
					CASE 
						WHEN J.FEC_BAJA_POS IS NULL
						THEN 'SI'
					ELSE 'NO'
					END AS INSPECTOR_ACTIVO,

					RIGHT(LEFT(S5.PRODUCTID, 5), 3) AS PRODUCTOS,
					SUM(S5.POLIZ_NP) AS POLIZA_FISICA,
					SUM(S5.POLIZ_CORR) AS POLIZA_CORREGIDA,
					SUM(S5.PRIMA_NETA) AS PRIMA_NETA,
					SUM(IFNULL(S5.VALUE, 0)) AS PRIMA_CORREGIDA,

					:v_period_year AS YEAR,
					:v_period_name AS PERIODO_FILTRO,
					:v_period_name_format AS PERIODO_FORMATO,
					CASE WHEN S5.PERIODO = :v_period_name
						THEN 1
						ELSE 0
						END AS IGUALES,
					
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					J.POSITIONSEQ_PRIN AS POSITIONSEQ,
					:i_PeriodSeq AS PERIODSEQ
				FROM EXT.OUT_JERARQUIA_REP J
				INNER JOIN EXT.OUT_S5_POLIZAS_REP S5 ON RIGHT(S5.PERIODO, 4) = :v_period_year
					-- BRG 20260428 Sólo el mes actual
					AND (SELECT STARTDATE FROM CS_PERIOD WHERE PERIODSEQ = S5.PERIODSEQ AND REMOVEDATE = '2200-01-01') = :v_period_startdate
					AND J.PARTICIPANTSEQ = S5.PARTICIPANTSEQ
					AND J.POSITIONSEQ_PRIN = S5.POSITIONSEQ_PRIN
				INNER JOIN EXT.CONF_AGENTES_REP AG ON J.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
					AND AG.COD_INFORME = 114
					AND AG.F_INICIO <= :v_period_startdate AND AG.F_FIN > :v_period_startdate
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
					AND F.TABLA = 'OUT_S5_POLIZAS_REP'
				WHERE J.PERIODSEQ = :i_PeriodSeq
					AND J.POSITIONSEQ = J.POSITIONSEQ_PRIN
				GROUP BY S5.PERIODO, S5.PERIODSEQ,
					J.COD_REGIONAL, J.REGIONAL, J.COD_SUCURSAL, J.SUCURSAL, J.COD_OFICINA, J.OFICINA, 
					J.POS_PRIN, J.NOMBRE, J.NIF, J.CUADRO_INSP_OCASO, J.ID_TIPO_AGENTE, J.TIPO_AGENTE, J.FEC_BAJA_POS,
					RIGHT(LEFT(S5.PRODUCTID, 5), 3), F.ULTIMA_ACTUALIZACION, J.POSITIONSEQ_PRIN
				
				UNION ALL
				
				SELECT DISTINCT 
					J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
					J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
					J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
					J.POS_PRIN AS COD_AGENTE,
					J.NOMBRE AS AGENTE,
					J.NIF,
					J.NIF || ' - ' || J.NOMBRE AS NIF_NOMBRE,
					J.CUADRO_INSP_OCASO AS CUADRO,
					TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) || ' - ' || J.TIPO_AGENTE AS TIPO_AGENTE,
					CASE 
						WHEN J.FEC_BAJA_POS IS NULL
						THEN 'SI'
					ELSE 'NO'
					END AS INSPECTOR_ACTIVO,

					RIGHT(LEFT(S5.PRODUCTID, 5), 3) AS PRODUCTOS,
					SUM(S5.POLIZ_NP) AS POLIZA_FISICA,
					SUM(S5.POLIZ_CORR) AS POLIZA_CORREGIDA,
					SUM(S5.PRIMA_NETA) AS PRIMA_NETA,
					SUM(IFNULL(S5.VALUE, 0)) AS PRIMA_CORREGIDA,

					:v_period_year AS YEAR,
					:v_period_name AS PERIODO_FILTRO,
					:v_period_name_format AS PERIODO_FORMATO,
					CASE WHEN S5.PERIODO = :v_period_name
						THEN 1
						ELSE 0
						END AS IGUALES,
					
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					J.POSITIONSEQ_PRIN AS POSITIONSEQ,
					:i_PeriodSeq AS PERIODSEQ
				FROM EXT.OUT_JERARQUIA_REP J
				INNER JOIN EXT.OUT_BAL_S5_POLIZAS_REP S5 ON RIGHT(S5.PERIODO, 4) = :v_period_year
					-- BRG 20260428 Meses anteriores al actual
					AND (SELECT STARTDATE FROM CS_PERIOD WHERE PERIODSEQ = S5.PERIODSEQ AND REMOVEDATE = '2200-01-01') < :v_period_startdate
					AND J.PARTICIPANTSEQ = S5.PARTICIPANTSEQ
					AND J.POSITIONSEQ_PRIN = S5.POSITIONSEQ_PRIN
				INNER JOIN EXT.CONF_AGENTES_REP AG ON J.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
					AND AG.COD_INFORME = 114
					AND AG.F_INICIO <= :v_period_startdate AND AG.F_FIN > :v_period_startdate
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
					AND F.TABLA = 'OUT_S5_POLIZAS_REP'
				WHERE J.PERIODSEQ = :i_PeriodSeq
					AND J.POSITIONSEQ = J.POSITIONSEQ_PRIN
				GROUP BY S5.PERIODO, S5.PERIODSEQ,
					J.COD_REGIONAL, J.REGIONAL, J.COD_SUCURSAL, J.SUCURSAL, J.COD_OFICINA, J.OFICINA, 
					J.POS_PRIN, J.NOMBRE, J.NIF, J.CUADRO_INSP_OCASO, J.ID_TIPO_AGENTE, J.TIPO_AGENTE, J.FEC_BAJA_POS,
					RIGHT(LEFT(S5.PRODUCTID, 5), 3), F.ULTIMA_ACTUALIZACION, J.POSITIONSEQ_PRIN;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG(v_permisos_log, proc_name, 'Fin Carga OUT_PROD_INSPECTORES_FINAL_REP. Valores S5 Polizas. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe 1.14 Producción Inspectores', i_log_count, i_id_proceso, 'info');

		-- Fin informe 1.14 Produccion Inspectores
		END IF;

		---------------------------------------------------------------------------------------------------------------------------------------
		-- BRG 20250526: TABLAS PARA INFORME 1.16 AGENTES ACTIVOS (OMESCU)
		IF :i_lista_informes = 'OMESCU' OR :i_lista_informes LIKE '%|OMESCU|%' OR :i_lista_informes LIKE '%|OMESCU' OR :i_lista_informes LIKE 'OMESCU|%' 
			OR :i_lista_informes = 'ALL' THEN

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe 1.16 Agentes Activos (OMESCU)', i_log_count, i_id_proceso, 'info');

			-- BRG 20250526: Nueva tabla OUT_INSP_ACTIVOS_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_INSP_ACTIVOS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_INSP_ACTIVOS_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_INSP_ACTIVOS_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			--BRG 20260409 Antiguo INSER
			/*INSERT INTO EXT.OUT_INSP_ACTIVOS_FINAL_REP (POSITIONSEQ,REGIONAL,SUCURSAL,OFICINA,COD_AGENTE,INSPECTOR,NIF,NIF_NOMBRE,CUADRO,TIPO_AGENTE,OBJ_POL,OBJ_PR,TOTAL_POL,TOTAL_POL_CORR,TOTAL_PRIMA_NETA,TOTAL_PRIMA_CORR,FECHA_ALTA,FECHA_ALTA_CAT,FEC_EFECTO,OBJ_POL_MES,OBJ_PR_MES,PORC_CUM_POL,PORC_CUM_PR,MES_PERIODO,PERIODO,PERIODSEQ,ANYO,FEC_ACTUALIZACION)
				-- BRG Tablas auxiliares para calcular la fecha de efecto y los objetivos
				WITH
					-- BRG Valores del mes del periodo, fecha alta categoría y año, necesarios más tarde
					TABLA_FECHA AS (
						SELECT DISTINCT
							EXTRACT(MONTH FROM (SELECT MAX(STARTDATE) FROM CS_PERIOD WHERE PERIODSEQ = :i_PeriodSeq AND REMOVEDATE = :v_eot)) AS MES_PERIODO,
							LAST_DAY(ADD_MONTHS(IFNULL(ADD_DAYS(FEC_ALTA_CAT,-1), ADD_DAYS(FEC_ALTA_POS,-1)), 1)) AS FEC_EF_ALTA_CAT,
							RIGHT(PERIODO, 4) AS ANYO,
							POSITIONSEQ_PRIN,
							PERIODO
						FROM EXT.OUT_INSP_ACTIVOS_REP
					),
					-- BRG Cálculo de la FEC_EFECTO
					EFECTO AS (
						SELECT
							CASE
								WHEN FEC_EF_ALTA_CAT < TO_DATE(CONCAT('01/01/', ANYO), 'DD/MM/YYYY')
									THEN '01-' || ANYO
								ELSE
									TO_VARCHAR(MONTH(FEC_EF_ALTA_CAT), '00') || '-' || YEAR(FEC_EF_ALTA_CAT)
								END AS FEC_EFECTO,
							POSITIONSEQ_PRIN,
							PERIODO
						FROM TABLA_FECHA
					),
					-- BRG Cogemos para cada FEC_EFECTO el valor de la FEC_EFECTO del mes anterior (para ver si hubo cambios)
					AUX_EFECTO1 AS (
						SELECT
							LAG(EF.FEC_EFECTO) OVER (
								PARTITION BY 
									INSP.POSITIONSEQ_PRIN, 
									TF.ANYO
								ORDER BY TF.MES_PERIODO
							) AS PREV_FEC_EFECTO,
							TF.ANYO,
							TF.MES_PERIODO,
							EF.FEC_EFECTO,
							INSP.POSITIONSEQ_PRIN,
							INSP.PERIODO
						FROM EXT.OUT_INSP_ACTIVOS_REP INSP
						INNER JOIN TABLA_FECHA TF ON TF.PERIODO = INSP.PERIODO
							AND TF.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN
						INNER JOIN EFECTO EF ON EF.PERIODO = INSP.PERIODO
							AND EF.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN 
					),
					-- BRG Si la FEC_EFECTO ha cambiado, marcamos esa fila como un 1
					AUX_EFECTO2 AS (
						SELECT
							SUM(
								CASE
									WHEN FEC_EFECTO <> COALESCE(PREV_FEC_EFECTO, FEC_EFECTO)
										THEN 1
									ELSE 0 END
							) OVER (
								PARTITION BY
									POSITIONSEQ_PRIN,
									ANYO
								ORDER BY MES_PERIODO
							) AS ID,
							POSITIONSEQ_PRIN,
							PERIODO
						FROM AUX_EFECTO1
					),
					-- BRG Tabla con todos los cálculos complejos de objetivos, y totales
					OBJETIVOS AS (
						SELECT
							CASE
								WHEN INSP.ID_TIPO_AGENTE = 60
									THEN 235
								WHEN INSP.ID_TIPO_AGENTE IN (58,61,62,65)
									THEN 385
								ELSE TO_INTEGER(INSP.OBJ_POL)
								END AS OBJ_POL,
							CASE
								WHEN INSP.ID_TIPO_AGENTE = 60
									THEN 66000
								WHEN INSP.ID_TIPO_AGENTE IN (58,61,62,65)
									THEN 112000
								ELSE TO_INTEGER(INSP.OBJ_PRIMA)
								END AS OBJ_PR,
							-- La partición incluye el campo ID, para que se deje de sumar cuando FEC_EFECTO cambia
							SUM(INSP.NUM_POL) OVER (
								PARTITION BY
									INSP.POSITIONSEQ_PRIN,
									TF.ANYO,
									AUX_EF.ID
									ORDER BY TF.MES_PERIODO
									ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
							) AS TOTAL_POL,
							SUM(INSP.NUM_POL_CORR) OVER (
								PARTITION BY
									INSP.POSITIONSEQ_PRIN,
									TF.ANYO,
									AUX_EF.ID
									ORDER BY TF.MES_PERIODO
									ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
							) AS TOTAL_POL_CORR,
							SUM(INSP.NUM_PRIMA_NETA) OVER (
								PARTITION BY
									INSP.POSITIONSEQ_PRIN,
									TF.ANYO,
									AUX_EF.ID
									ORDER BY TF.MES_PERIODO
									ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
							) AS TOTAL_PRIMA_NETA,
							SUM(INSP.NUM_PRIMA_CORR) OVER (
								PARTITION BY
									INSP.POSITIONSEQ_PRIN,
									TF.ANYO,
									AUX_EF.ID
									ORDER BY TF.MES_PERIODO
									ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
							) AS TOTAL_PRIMA_CORR,
							TF.MES_PERIODO,
							TF.ANYO,
							INSP.PERIODO,
							INSP.POSITIONSEQ_PRIN
						FROM EXT.OUT_INSP_ACTIVOS_REP INSP
						INNER JOIN TABLA_FECHA TF ON TF.PERIODO = INSP.PERIODO
							AND TF.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN
						INNER JOIN EFECTO EF ON EF.PERIODO = INSP.PERIODO
							AND EF.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN
						INNER JOIN AUX_EFECTO2 AUX_EF ON AUX_EF.PERIODO = INSP.PERIODO
							AND AUX_EF.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN
					)
				SELECT
					INSP.POSITIONSEQ_PRIN AS POSITIONSEQ,
					COD_REGIONAL || ' - ' || REGIONAL AS REGIONAL,
					COD_SUCURSAL || ' - ' || SUCURSAL AS SUCURSAL,
					COD_OFICINA || ' - ' || OFICINA AS OFICINA,
					POS_PRIN AS COD_AGENTE,
					NOMBRE AS INSPECTOR,
					NIF AS NIF,
					NIF || ' - ' || NOMBRE AS NIF_NOMBRE,
					CUADRO_INSP AS CUADRO,
					TO_INTEGER(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGENTE,
					ROUND(OBJ.OBJ_POL, 2) AS OBJ_POL,
					ROUND(OBJ.OBJ_PR, 2) AS OBJ_PR,
					ROUND(OBJ.TOTAL_POL, 2) AS TOTAL_POL,
					ROUND(OBJ.TOTAL_POL_CORR, 2) AS TOTAL_POL_CORR,
					ROUND(OBJ.TOTAL_PRIMA_NETA, 2) AS TOTAL_PRIMA_NETA,
					ROUND(OBJ.TOTAL_PRIMA_CORR, 2) AS TOTAL_PRIMA_CORR,
					TO_VARCHAR(FEC_ALTA_POS, 'DD/MM/YYYY') AS FECHA_ALTA,
					TO_VARCHAR(FEC_ALTA_CAT, 'DD/MM/YYYY') AS FECHA_ALTA_CAT,
					EF.FEC_EFECTO,
					ROUND(OBJ.OBJ_POL/12 * (TF.MES_PERIODO - TO_INTEGER(LEFT(EF.FEC_EFECTO, 2)) + 1), 2) AS OBJ_POL_MES,	
					ROUND(OBJ.OBJ_PR/12 * (TF.MES_PERIODO - TO_INTEGER(LEFT(EF.FEC_EFECTO, 2)) + 1), 2) AS OBJ_PR_MES,
					CASE
						WHEN OBJ.OBJ_POL/12 * (TF.MES_PERIODO - TO_INTEGER(LEFT(EF.FEC_EFECTO, 2)) + 1) <= 0
							THEN 0
						ELSE ROUND(OBJ.TOTAL_POL_CORR/(OBJ.OBJ_POL/12 * (TF.MES_PERIODO - TO_INTEGER(LEFT(EF.FEC_EFECTO, 2)) + 1))*100, 2)
						END AS PORC_CUM_POL,
					CASE
						WHEN OBJ.OBJ_PR/12 * (TF.MES_PERIODO - TO_INTEGER(LEFT(EF.FEC_EFECTO, 2)) + 1) <= 0
							THEN 0
						ELSE ROUND(OBJ.TOTAL_PRIMA_CORR/(OBJ.OBJ_PR/12 * (TF.MES_PERIODO - TO_INTEGER(LEFT(EF.FEC_EFECTO, 2)) + 1))*100, 2)
						END AS PORC_CUM_PR,
					TF.MES_PERIODO,
					SUBSTR_AFTER(INSP.PERIODO, ' ') || ' ' || RIGHT(CONCAT('0', TF.MES_PERIODO), 2) || ' ' || SUBSTR_BEFORE(INSP.PERIODO, ' ') AS PERIODO,
					INSP.PERIODSEQ,
					TF.ANYO,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY')
				FROM EXT.OUT_INSP_ACTIVOS_REP INSP
				INNER JOIN TABLA_FECHA TF ON TF.PERIODO = INSP.PERIODO
					AND TF.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN
				INNER JOIN EFECTO EF ON EF.PERIODO = INSP.PERIODO
					AND EF.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN
				INNER JOIN OBJETIVOS OBJ ON OBJ.PERIODO = INSP.PERIODO
					AND OBJ.POSITIONSEQ_PRIN = INSP.POSITIONSEQ_PRIN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = INSP.PERIODO
					AND F.TABLA = 'OUT_INSP_ACTIVOS_REP'
				WHERE INSP.PERIODSEQ = :i_PeriodSeq
				--	AND INSP.POSITIONSEQ = INSP.POSITIONSEQ_PRIN --LLS 20251124: Añadido para quitar posiciones secundarias
					;
			*/
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_INSP_ACTIVOS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_INSP_ACTIVOS_FINAL_REP (POSITIONSEQ,REGIONAL,SUCURSAL,OFICINA,COD_AGENTE,INSPECTOR,NIF,NIF_NOMBRE,CUADRO,TIPO_AGENTE,OBJ_POL,OBJ_PR,TOTAL_POL,TOTAL_POL_CORR,TOTAL_PRIMA_NETA,TOTAL_PRIMA_CORR,FECHA_ALTA,FECHA_ALTA_CAT,FEC_EFECTO,OBJ_POL_MES,OBJ_PR_MES,PORC_CUM_POL,PORC_CUM_PR,MES_PERIODO,PERIODO,PERIODSEQ,ANYO,FEC_ACTUALIZACION)
				WITH CTE_JERARQUIA AS (
					SELECT DISTINCT
						PARTICIPANTSEQ,
						POSITIONSEQ_PRIN,
						POSITIONSEQ,
						POS_PRIN,
						PERIODSEQ,
						PERIODO,
						J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
						J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
						J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
						NOMBRE,
						NIF,
						CUADRO_INSP_OCASO AS CUADRO,
						ID_TIPO_AGENTE,
						TIPO_AGENTE,
						FEC_ALTA_POS,
						--BRG 20260407 Copiado del CREAR_TABLAS
						--ALM 20170512: Nos quedamos con la fecha final de la version anterior al ultimo cambio de cuadro 
						--              o, si es nula, con la fecha inicial de la primera version en la que tiene tipologia de agente con grupo/inspector/responsable  
						(SELECT IFNULL(MAX(POS_ANT.EFFECTIVEENDDATE),MIN(POS_ACT.EFFECTIVESTARTDATE)) 
							FROM TCMP.CS_POSITION POS_ACT
							--ALM 20170510: Tenemos que tener en cuenta cualquier cambio de tipologia no solo el paso de agente a inspector
							LEFT JOIN TCMP.CS_POSITION POS_ANT ON POS_ACT.PAYEESEQ = POS_ANT.PAYEESEQ
								--ALM 20170519: Tenemos en cuenta todas las versiones anteriores porque puede que venga de una tipologia que no sea inspector
								AND POS_ACT.EFFECTIVESTARTDATE >= POS_ANT.EFFECTIVEENDDATE
								AND (REPLACE(REPLACE(REPLACE(POS_ACT.GENERICATTRIBUTE5, 'A', 'P'), 'D', 'P'), 'N', 'P') <> REPLACE(REPLACE(REPLACE(POS_ANT.GENERICATTRIBUTE5, 'A', 'P'), 'D', 'P'), 'N', 'P') OR POS_ANT.GENERICATTRIBUTE5 IS NULL)
								AND POS_ANT.REMOVEDATE = '2200-01-01'
							WHERE POS_ACT.REMOVEDATE = '2200-01-01'
								--ALM 20170320: Se tiene que tener en cuenta la fecha de la version de cuando ha sido TTL SIN PLAN.
								--ALM 20170512: Filtramos las versiones de las posiciones con tipologia de agente con grupo/inspector/responsable
								AND POS_ACT.GENERICNUMBER2 >= 50
								AND POS_ACT.EFFECTIVESTARTDATE <= :v_period_startdate
								AND POS_ACT.PAYEESEQ = J.PARTICIPANTSEQ
						) AS FEC_ALTA_CAT,
						CASE 
							WHEN TO_INTEGER(J.ID_TIPO_AGENTE) IN (61, 62)
								THEN 385
							ELSE 0
							END AS OBJ_POL,
						CASE
							WHEN TO_INTEGER(J.ID_TIPO_AGENTE) IN (61, 62)
								THEN 112000
							ELSE 0
							END AS OBJ_PR
					FROM EXT.OUT_JERARQUIA_REP J
					WHERE PERIODSEQ = :i_PeriodSeq
				),
				J_EFECTO AS (
					SELECT 
						*,
						--BRG 20260408 Si el alta de la categoría ha sido este año
						CASE WHEN YEAR(J.FEC_ALTA_CAT) = :v_period_year
							--BRG 20260408 Cogemos el mismo mes si el alta es a día 1, mes siguiente en otros casos
							THEN (CASE WHEN EXTRACT(DAY FROM J.FEC_ALTA_CAT) = 1
								THEN TO_VARCHAR(J.FEC_ALTA_CAT, 'MM-YYYY')
								ELSE TO_VARCHAR(ADD_MONTHS(J.FEC_ALTA_CAT, 1), 'MM-YYYY')
								END)
							--BRG 20260408 Si ha sido otro año, cogemos enero del año actual
							ELSE ('01-' || :v_period_year) END AS FEC_EFECTO
					FROM CTE_JERARQUIA J
				),
				J_FINAL AS (
					SELECT
						J.PARTICIPANTSEQ,
						J.POSITIONSEQ_PRIN,
						J.POSITIONSEQ,
						J.POS_PRIN,
						J.PERIODSEQ,
						J.REGIONAL,
						J.SUCURSAL,
						J.OFICINA,
						J.NOMBRE,
						J.NIF,
						J.CUADRO,
						J.ID_TIPO_AGENTE,
						J.TIPO_AGENTE,
						J.FEC_ALTA_POS,
						J.FEC_ALTA_CAT,
						J.OBJ_POL,
						J.OBJ_PR,
						J.FEC_EFECTO,
						TO_INTEGER(LEFT(J.FEC_EFECTO, 2)) AS MES_EFECTO,
						
						SUM(S5.POLIZ_NP) AS TOTAL_POL,
						SUM(S5.POLIZ_CORR) AS TOTAL_POL_CORR,
						SUM(S5.PRIMA_NETA) AS TOTAL_PRIMA_NETA,
						SUM(IFNULL(S5.VALUE, 0)) AS TOTAL_PRIMA_CORR
					FROM J_EFECTO J
					INNER JOIN EXT.OUT_BAL_S5_POLIZAS_REP S5 ON RIGHT(S5.PERIODO, 4) = :v_period_year
						AND (SELECT STARTDATE FROM CS_PERIOD WHERE PERIODSEQ = S5.PERIODSEQ AND REMOVEDATE = '2200-01-01') <= :v_period_startdate
						AND J.PARTICIPANTSEQ = S5.PARTICIPANTSEQ
						AND J.POSITIONSEQ_PRIN = S5.POSITIONSEQ_PRIN
					INNER JOIN EXT.CONF_AGENTES_REP AG ON J.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
						AND AG.COD_INFORME = 116
						AND AG.F_INICIO <= :v_period_startdate AND AG.F_FIN > :v_period_startdate
					GROUP BY J.PARTICIPANTSEQ, J.POSITIONSEQ_PRIN, J.POSITIONSEQ, J.PERIODSEQ, J.POS_PRIN, 
						J.REGIONAL, J.SUCURSAL, J.OFICINA, J.NOMBRE, J.NIF, J.CUADRO, J.ID_TIPO_AGENTE, J.TIPO_AGENTE,
						J.FEC_ALTA_POS, J.FEC_ALTA_CAT, J.OBJ_POL, J.OBJ_PR, J.FEC_EFECTO
				)
				SELECT DISTINCT 
					J.POSITIONSEQ_PRIN AS POSITIONSEQ,
					J.REGIONAL,
					J.SUCURSAL,
					J.OFICINA,
					J.POS_PRIN AS COD_AGENTE,
					J.NOMBRE AS INSPECTOR,
					J.NIF,
					J.NIF || ' - ' || J.NOMBRE AS NIF_NOMBRE,
					J.CUADRO,
					TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) || ' - ' || J.TIPO_AGENTE AS TIPO_AGENTE,
					
					J.OBJ_POL,
					J.OBJ_PR,
					
					J.TOTAL_POL,
					J.TOTAL_POL_CORR,
					J.TOTAL_PRIMA_NETA,
					J.TOTAL_PRIMA_CORR,
					
					TO_VARCHAR(J.FEC_ALTA_POS, 'DD/MM/YYYY') AS FEC_ALTA_POS,
					TO_VARCHAR(J.FEC_ALTA_CAT, 'DD/MM/YYYY') AS FEC_ALTA_CAT,
					J.FEC_EFECTO,

					ROUND(J.OBJ_POL/12 * (:v_period_month - J.MES_EFECTO + 1), 2) AS OBJ_POL_MES,
					ROUND(J.OBJ_PR/12 * (:v_period_month - J.MES_EFECTO + 1), 2) AS OBJ_PR_MES,
					
					CASE
						WHEN J.OBJ_POL/12 * (:v_period_month - J.MES_EFECTO + 1) <= 0
							THEN 0
						ELSE ROUND(J.TOTAL_POL_CORR/(J.OBJ_POL/12 * (:v_period_month - J.MES_EFECTO + 1))*100, 2)
						END AS PORC_CUM_POL,
					CASE
						WHEN J.OBJ_PR/12 * (:v_period_month - J.MES_EFECTO + 1) <= 0
							THEN 0
						ELSE ROUND(J.TOTAL_PRIMA_CORR/(J.OBJ_PR/12 * (:v_period_month - J.MES_EFECTO + 1))*100, 2)
						END AS PORC_CUM_PR,
					
					:v_period_month AS MES_PERIODO,
					:v_period_name_format AS PERIODO,
					:i_PeriodSeq AS PERIODSEQ,
					:v_period_year AS ANYO,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION
				FROM J_FINAL J
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
					AND F.TABLA = 'OUT_S5_POLIZAS_REP'
				ORDER BY J.REGIONAL, J.SUCURSAL, J.OFICINA, J.POS_PRIN;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_INSP_ACTIVOS_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe 1.16 Agentes Activos (OMESCU)', i_log_count, i_id_proceso, 'info');

		-- Fin informe 1.16 Agentes Activos (OMESCU)
		END IF;
		
		---------------------------------------------------------------------------------------------------------------------------------------
		-- BRG 20250526: TABLAS PARA INFORME 1.26 Rappel Producción Agentes
		IF :i_lista_informes = 'RPA' OR :i_lista_informes LIKE '%|RPA|%' OR :i_lista_informes LIKE '%|RPA' OR :i_lista_informes LIKE 'RPA|%' 
			OR :i_lista_informes = 'ALL' THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe 1.26 Rappel Producción Agentes', i_log_count, i_id_proceso, 'info');

			-- BRG 20250526: Nueva tabla OUT_RPA_RESUMEN_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RPA_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RPA_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RPA_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RPA_RESUMEN_FINAL_REP (CIA,PERIODO,REGIONAL,SUCURSAL,OFICINA,COD_AGENTE,AGENTE,NIF,CUADRO_RRGG,CUADRO_RRTT,COD_TIPO_AGENTE,TIPO_AGENTE,ESCALADO_ASISTENCIA,INFORME,ULT_ACT,POL_FIS_HOGAR,POL_FIS_RRTT,POL_FIS_RRPP,ASEG,PRIMA,POL_CORREG,POL_FISIC,RAPPEL,NUM_ASISTENCIAS,IMP_MENSUAL_XL,IMP_MENSUAL_XXL,REGUL_TRIMESTRAL,CUMPLE_MINIMO,IMPORTE_COMISION_ASISTENCIAS,MINIMO_ASISTENCIA,IMPORTE_ESCALADO_RAPPEL,RAPPEL_FINAL,TOTAL_ASEGURADOS_TRIMESTRE,TOTAL_POL_RRTT_TRIMESTRE,TOTAL_POL_HOGAR_TRIMESTRE,TOTAL_POL_OCASO_ORO_TRIMESTRE,TOTAL_POL_RRPP_TRIMESTRE,TOTAL_PRIMAS_TRIMESTRE,TOTAL_POL_CORREGIDAS_TRIMESTRE,CUMPLE_OBJETIVOS_REG_TRIMESTRAL,ESCALADO_RAPPEL_REGUL,TOTAL_RAPPEL_ABONADO,IMPORTE_REGUL_A_PAGAR,GESTIONES_CERRADAS,OBJETIVO_GESTIONES,PORC_CONSEGUIDO,IMPORTE_PAGO,POSITIONSEQ,PERIODSEQ)
				WITH TABLA_RPA AS (
					SELECT DISTINCT
						POS_PRIN AS POS_PRIN,
						POSITIONNAME AS POSITIONNAME,
						V_MEDIDA AS V_MEDIDA,
						N_MEDIDA AS N_MEDIDA,
						PERIODO AS PERIODO,
						PARTICIPANTSEQ AS PARTICIPANTSEQ,
						POSITIONSEQ_PRIN AS POSITIONSEQ_PRIN,
						PERIODSEQ AS PERIODSEQ
					FROM EXT.OUT_RPA_RESUMEN_REP T
					WHERE
					1=1
					AND NOT EXISTS (SELECT B.PERIODSEQ FROM TCMP.CS_BALANCE B WHERE B.PERIODSEQ = T.PERIODSEQ) -- SOLO PERIODOS SIN BALANCE
					
					UNION ALL

					SELECT DISTINCT
						POS_PRIN AS POS_PRIN,
						POSITIONNAME AS POSITIONNAME,
						V_MEDIDA AS V_MEDIDA,
						N_MEDIDA AS N_MEDIDA,
						PERIODO AS PERIODO,
						PARTICIPANTSEQ AS PARTICIPANTSEQ,
						POSITIONSEQ_PRIN AS POSITIONSEQ_PRIN,
						PERIODSEQ AS PERIODSEQ
					FROM EXT.OUT_LC_RPA_RESUMEN_REP T
					WHERE
					1=1
					
					UNION ALL

					SELECT DISTINCT
						POS_PRIN AS POS_PRIN,
						POSITIONNAME AS POSITIONNAME,
						V_MEDIDA AS V_MEDIDA,
						N_MEDIDA AS N_MEDIDA,
						PERIODO AS PERIODO,
						PARTICIPANTSEQ AS PARTICIPANTSEQ,
						POSITIONSEQ_PRIN AS POSITIONSEQ_PRIN,
						PERIODSEQ AS PERIODSEQ
					FROM EXT.OUT_BAL_RPA_RESUMEN_REP T
					WHERE
					1=1
					),
				TABLA_ASI AS (
					SELECT DISTINCT
						POS_PRIN AS POS_PRIN,
						POSITIONNAME AS POSITIONNAME,
						V_MEDIDA AS V_MEDIDA,
						N_MEDIDA AS N_MEDIDA,
						GN1_MEDIDA AS GN1_MEDIDA,
						PERIODO AS PERIODO,
						PARTICIPANTSEQ AS PARTICIPANTSEQ,
						POSITIONSEQ_PRIN AS POSITIONSEQ_PRIN,
						PERIODSEQ AS PERIODSEQ
					FROM EXT.OUT_ASI_RESUMEN_REP T
					WHERE
					1=1
					AND NOT EXISTS (SELECT B.PERIODSEQ FROM TCMP.CS_BALANCE B WHERE B.PERIODSEQ = T.PERIODSEQ) -- SOLO PERIODOS SIN BALANCE

					UNION ALL

					SELECT DISTINCT
						POS_PRIN AS POS_PRIN,
						POSITIONNAME AS POSITIONNAME,
						V_MEDIDA AS V_MEDIDA,
						N_MEDIDA AS N_MEDIDA,
						GN1_MEDIDA AS GN1_MEDIDA,
						PERIODO AS PERIODO,
						PARTICIPANTSEQ AS PARTICIPANTSEQ,
						POSITIONSEQ_PRIN AS POSITIONSEQ_PRIN,
						PERIODSEQ AS PERIODSEQ
					FROM EXT.OUT_LC_ASI_RESUMEN_REP T
					WHERE
					1=1
					AND NOT EXISTS (SELECT B.PERIODSEQ FROM TCMP.CS_BALANCE B WHERE B.PERIODSEQ = T.PERIODSEQ) -- SOLO PERIODOS SIN BALANCE

					UNION ALL

					SELECT DISTINCT
						POS_PRIN AS POS_PRIN,
						POSITIONNAME AS POSITIONNAME,
						V_MEDIDA AS V_MEDIDA,
						N_MEDIDA AS N_MEDIDA,
						GN1_MEDIDA AS GN1_MEDIDA,
						PERIODO AS PERIODO,
						PARTICIPANTSEQ AS PARTICIPANTSEQ,
						POSITIONSEQ_PRIN AS POSITIONSEQ_PRIN,
						PERIODSEQ AS PERIODSEQ
					FROM EXT.OUT_BAL_ASI_RESUMEN_REP T
					WHERE
					1=1
					--AND EXISTS (SELECT B.PERIODSEQ FROM TCMP.CS_BALANCE B WHERE B.PERIODSEQ = T.PERIODSEQ) -- SOLO PERIODOS CON BALANCE
					),
				TABLA_CUMPLE_MINIMO AS (
					SELECT DISTINCT --LLS 20251112: Añadido el distinct
						'01' AS INFORME,
						TO_VARCHAR(J.PERIODO) AS PERIODO,
						J.NIF AS NIF,
						TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) AS ID_TIPO_AGENTE,
						CASE WHEN((
						--N2N3:
						SUM(
						CASE WHEN ID_TIPO_AGENTE IN ('31','39','40','32','44','45')
							AND N_MEDIDA = 'SM-O-RPP-Agente-Cumple-Objetivos'
							THEN V_MEDIDA
							ELSE 0 END)+
						--GENERAL:
						SUM(
						CASE WHEN ID_TIPO_AGENTE IN ('19')
							AND N_MEDIDA = 'SM-O-RPP-AgenteGeneral-Cumple-Objetivos'
							THEN V_MEDIDA
							ELSE 0 END)+
						--RESTO:
						SUM(
						CASE WHEN ID_TIPO_AGENTE NOT IN ('31','39','40','32','44','45','19')
							AND N_MEDIDA = 'SM-O-RPP-Agente-Cumple-Llave'
							THEN V_MEDIDA
							ELSE 0 END)+
						--N1:
						(CASE WHEN(ID_TIPO_AGENTE IN ('16') 
							AND SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Categoria-MesesTotal'
									THEN V_MEDIDA
									ELSE 0 END) <= 3
							AND SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes'
									THEN V_MEDIDA
									ELSE 0 END) >= 1
							AND SUM(CASE
									WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes'
									THEN V_MEDIDA
									ELSE 0
									END) >= 2)
							THEN 1
							ELSE 0 END)) >=1)
						THEN 'SI'
						ELSE 'NO'
						END AS CUMPLE_MINIMO,
						CASE WHEN
							SUM(CASE
									WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes'
									THEN V_MEDIDA
									ELSE 0
									END) = 1
							THEN 'SI'
							ELSE 'NO'
						END AS OBJ_REGUL_TRIMESTRAL
					FROM TABLA_RPA AS RESUMEN
					INNER JOIN EXT.OUT_JERARQUIA_REP J ON J.PARTICIPANTSEQ = RESUMEN.PARTICIPANTSEQ
							AND J.POSITIONSEQ_PRIN =RESUMEN.POSITIONSEQ_PRIN
							AND J.PERIODSEQ =RESUMEN.PERIODSEQ
							-- AND (RESUMEN.V_MEDIDA <> 0 OR RESUMEN.N_MEDIDA LIKE '%Bolsa%')
					WHERE
						1=1
						AND (RESUMEN.N_MEDIDA LIKE '%-Rappel-%' OR
							RESUMEN.N_MEDIDA IN ('SM-O-RPP-Agente-Cumple-Objetivos', 'SM-O-RPP-AgenteGeneral-Cumple-Objetivos', 'SM-O-RPP-Agente-Cumple-Llave', 'SM-O-GEN-Categoria-MesesTotal', 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes','SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes'))
						AND J.POSITIONSEQ = J.POSITIONSEQ_PRIN --LLS 20251124: Añadido para quitar posiciones secundarias
					GROUP BY
					J.PERIODO,
					J.NIF,
					J.ID_TIPO_AGENTE
					),
				TABLA_CUMPLE_MINIMO_ASIS AS (
						SELECT DISTINCT --LLS 20251112: Añadido el distinct
							'02' AS INFORME,
							TO_VARCHAR(J.PERIODO) AS PERIODO,
							TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) AS ID_TIPO_AGENTE,
							J.NIF AS NIF,
							CASE 
								WHEN
								SUM(CASE 
									WHEN N_MEDIDA = 'SM-O-ARA-NumeroPolizasCorregidas-998-Total-ConResto'
									THEN V_MEDIDA
									ELSE 0
								END)>=1
								THEN 'SI'
								ELSE 'NO'
						END AS CUMPLE_MINIMO,
						NULL AS OBJ_REGUL_TRIMESTRAL

						FROM TABLA_ASI AS RESUMEN
						INNER JOIN EXT.OUT_JERARQUIA_REP J ON J.PARTICIPANTSEQ = RESUMEN.PARTICIPANTSEQ
								AND J.POSITIONSEQ_PRIN =RESUMEN.POSITIONSEQ_PRIN
								AND J.PERIODSEQ =RESUMEN.PERIODSEQ
								AND J.POSITIONSEQ = J.POSITIONSEQ_PRIN --LLS 20251124: Añadido para quitar posiciones secundarias
						WHERE
						1=1
						AND RESUMEN.N_MEDIDA IN ('SM-O-ARA-NumeroPolizasCorregidas-998-Total-ConResto')
						GROUP BY
						J.PERIODO,
						J.NIF,
						J.ID_TIPO_AGENTE
					),
				TABLA_MINIMOS AS (
						SELECT 
							INFORME,
							PERIODO,
							NIF,
							CUMPLE_MINIMO,
							OBJ_REGUL_TRIMESTRAL
						FROM TABLA_CUMPLE_MINIMO
						UNION ALL 
						SELECT 
							INFORME,
							PERIODO,
							NIF,
							CUMPLE_MINIMO,
							OBJ_REGUL_TRIMESTRAL
						FROM TABLA_CUMPLE_MINIMO_ASIS
					),
				ULT_ACT_1 AS (
						SELECT
						PERIODO,
						TABLA,
						MAX(ULTIMA_ACTUALIZACION) OVER (PARTITION BY PERIODO) AS ULT_ACT
						FROM EXT.OUT_FECHAS_WEBI_REP
						WHERE TABLA IN ('OUT_RPA_RESUMEN_REP', 'OUT_BAL_RPA_RESUMEN_REP', 'OUT_LC_RPA_RESUMEN_REP')
					),
				ULT_ACT_2 AS (
						SELECT
						PERIODO,
						TABLA,
						MAX(ULTIMA_ACTUALIZACION) OVER (PARTITION BY PERIODO) AS ULT_ACT
						FROM EXT.OUT_FECHAS_WEBI_REP
						WHERE TABLA IN ('OUT_ASI_RESUMEN_REP', 'OUT_BAL_ASI_RESUMEN_REP', 'OUT_LC_ASI_RESUMEN_REP')
					)
				--AQUI TERMINA LA DEFINICION DE TABLAS TEMPORALES
				SELECT DISTINCT
					'01' AS CIA,
					TRIM(CASE
						WHEN R.PERIODO LIKE 'Enero%' THEN RIGHT(R.PERIODO, 5) || ' 01 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Febrero%' THEN RIGHT(R.PERIODO, 5) || ' 02 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Marzo%' THEN RIGHT(R.PERIODO, 5) || ' 03 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Abril%' THEN RIGHT(R.PERIODO, 5) || ' 04 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Mayo%' THEN RIGHT(R.PERIODO, 5) || ' 05 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Junio%' THEN RIGHT(R.PERIODO, 5) || ' 06 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Julio%' THEN RIGHT(R.PERIODO, 5) || ' 07 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Agosto%' THEN RIGHT(R.PERIODO, 5) || ' 08 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Septiembre%' THEN RIGHT(R.PERIODO, 5) || ' 09 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Octubre%' THEN RIGHT(R.PERIODO, 5) || ' 10 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Noviembre%' THEN RIGHT(R.PERIODO, 5) || ' 11 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
						WHEN R.PERIODO LIKE 'Diciembre%' THEN RIGHT(R.PERIODO, 5) || ' 12 ' || LEFT(R.PERIODO,LENGTH(R.PERIODO)-5)
					END) AS PERIODO,
					R.REGIONAL AS REGIONAL,
					R.SUCURSAL AS SUCURSAL,
					R.OFICINA AS OFICINA,
					R.POS_PRIN AS COD_AGENTE,
					R.NOMBRE AS AGENTE,
					R.NIF,
					R.CUADRO_RRGG,
					R.CUADRO_RRTT,
					R.ID_TIPO_AGENTE AS COD_TIPO_AGENTE,
					R.TIPO_AGENTE,
					R.ESCALADO_ASISTENCIA AS ESCALADO_ASISTENCIA,
					R.INFORME,
					TO_VARCHAR((R.ULT_ACT), 'DD/MM/YYYY') AS ULT_ACT,
					IFNULL(ROUND(R.POL_FIS_HOGAR, 2),0) AS POL_FIS_HOGAR, -- INFORME1
					IFNULL(ROUND(R.POL_FIS_RRTT, 2),0) AS POL_FIS_RRTT, -- INFORME1
					IFNULL(ROUND(R.POL_FIS_RRPP, 2),0) AS POL_FIS_RRPP, -- INFORME1
					IFNULL(ROUND(R.ASEG, 2),0) AS ASEG, -- INFORME1
					IFNULL(ROUND(R.PRIMA, 2),0) AS PRIMA , -- INFORME1,2
					IFNULL(ROUND(R.POL_CORREG, 2),0) AS POL_CORREG, -- INFORME1
					IFNULL(ROUND(R.POL_FISIC, 2),0) AS POL_FISIC, -- INFORME1,2
					IFNULL(ROUND(R.RAPPEL, 2),0) AS RAPPEL, -- INFORME1
					IFNULL(ROUND(R.NUM_ASISTENCIAS, 2),0) AS NUM_ASISTENCIAS, --INFORME2
					IFNULL(ROUND(R.IMP_MENSUAL_XL, 2),0) AS IMP_MENSUAL_XL, -- INFORME1,2
					IFNULL(ROUND(R.IMP_MENSUAL_XXL, 2),0) AS IMP_MENSUAL_XXL, -- INFORME1,2
					IFNULL(ROUND(R.REGUL_TRIMESTRAL, 2),0) AS REGUL_TRIMESTRAL, -- INFORME1,2
					IFNULL(CM.CUMPLE_MINIMO,'NO'), -- INFORME1,2
					IFNULL(ROUND(R.IMPORTE_COMISION_ASISTENCIAS, 2),0) AS IMPORTE_COMISION_ASISTENCIAS, -- INFORME2
					IFNULL(ROUND(R.MINIMO_ASISTENCIA, 2),0) AS MINIMO_ASISTENCIA, -- INFORME2
					IFNULL(ROUND(R.IMPORTE_ESCALADO_RAPPEL, 2),0) AS IMPORTE_ESCALADO_RAPPEL, -- INFORME2
					IFNULL(ROUND(R.RAPPEL_FINAL, 2),0) AS RAPPEL_FINAL, -- INFORME2
					IFNULL(ROUND(R.TOTAL_ASEGURADOS_TRIMESTRE, 2),0) AS TOTAL_ASEGURADOS_TRIMESTRE, -- INFORME3
					IFNULL(ROUND(R.TOTAL_POL_RRTT_TRIMESTRE, 2),0) AS TOTAL_POL_RRTT_TRIMESTRE, -- INFORME3
					IFNULL(ROUND(R.TOTAL_POL_HOGAR_TRIMESTRE, 2),0) AS TOTAL_POL_HOGAR_TRIMESTRE, -- INFORME3
					IFNULL(ROUND(R.TOTAL_POL_OCASO_ORO_TRIMESTRE, 2),0) AS TOTAL_POL_OCASO_ORO_TRIMESTRE, -- INFORME3
					IFNULL(ROUND(R.TOTAL_POL_RRPP_TRIMESTRE, 2),0) AS TOTAL_POL_RRPP_TRIMESTRE, -- INFORME3
					IFNULL(ROUND(R.TOTAL_PRIMAS_TRIMESTRE, 2),0) AS TOTAL_PRIMAS_TRIMESTRE, -- INFORME3
					IFNULL(ROUND(R.TOTAL_POL_CORREGIDAS_TRIMESTRE, 2),0) AS TOTAL_POL_CORREGIDAS_TRIMESTRE, -- INFORME3
					IFNULL(CM.OBJ_REGUL_TRIMESTRAL,'NO') AS CUMPLE_OBJETIVOS_REG_TRIMESTRAL, --INFORME 3
					IFNULL(ROUND(R.ESCALADO_RAPPEL_REGUL, 2),0) AS ESCALADO_RAPPEL_REGUL, -- INFORME3
					IFNULL(ROUND(R.TOTAL_RAPPEL_ABONADO, 2),0) AS TOTAL_RAPPEL_ABONADO, -- INFORME3
					IFNULL(ROUND(R.IMPORTE_REGUL_A_PAGAR, 2),0) AS IMPORTE_REGUL_A_PAGAR, -- INFORME3
					IFNULL(ROUND(R.GESTIONES_CERRADAS, 2),0) AS GESTIONES_CERRADAS, -- INFORME4
					'20' AS OBJETIVO_GESTIONES, -- INFORME4
					IFNULL(ROUND(100 * R.porc_CONSEGUIDO, 2),0) AS PORC_CONSEGUIDO, -- INFORME4
					IFNULL(ROUND(R.IMPORTE_PAGO, 2),0) AS IMPORTE_PAGO, -- INFORME4
					R.POSITIONSEQ AS POSITIONSEQ,
					R.PERIODSEQ AS PERIODSEQ
				FROM(
					SELECT DISTINCT
						-- CAMPOS COMUNES A TODOS LOS INFORMES --
						'01' AS INFORME,
						F.ULT_ACT AS ULT_ACT,
						TO_VARCHAR(RESUMEN.PERIODO) AS PERIODO,           
						J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
						J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
						J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
						J.POS_PRIN AS POS_PRIN,
						J.NOMBRE AS NOMBRE,
						J.NIF AS NIF,
						J.CUADRO_RRGG_OCASO AS CUADRO_RRGG,
						J.CUADRO_RRTT_OCASO AS CUADRO_RRTT,
						TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) AS ID_TIPO_AGENTE,
						TO_VARCHAR(J.TIPO_AGENTE) AS TIPO_AGENTE,
						--------------------------------------------------          
						NULL AS ESCALADO_ASISTENCIA, --INFORME2
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' THEN V_MEDIDA END AS POL_FIS_HOGAR, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' THEN V_MEDIDA END AS POL_FIS_RRTT, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' THEN V_MEDIDA END AS POL_FIS_RRPP, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN V_MEDIDA END AS ASEG, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN V_MEDIDA END AS PRIMA, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes' THEN V_MEDIDA END AS POL_CORREG, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-998-TotalMes' THEN V_MEDIDA END AS POL_FISIC, -- INFORME1,2
						CASE WHEN N_MEDIDA LIKE '%-Rappel-%' THEN V_MEDIDA END AS RAPPEL, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' THEN V_MEDIDA END AS IMP_MENSUAL_XL, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' THEN V_MEDIDA END AS IMP_MENSUAL_XXL, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-ImporteNeto-RegTrim' THEN V_MEDIDA END AS REGUL_TRIMESTRAL, -- INFORME1,2
						NULL AS IMPORTE_COMISION_ASISTENCIAS, -- INFORME2
						NULL AS MINIMO_ASISTENCIA, -- INFORME2
						NULL AS IMPORTE_ESCALADO_RAPPEL, -- INFORME2
						NULL AS RAPPEL_FINAL, -- INFORME2
						NULL AS NUM_ASISTENCIAS, --INFORME2
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalTrim' THEN V_MEDIDA END AS TOTAL_ASEGURADOS_TRIMESTRE, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalTrim' THEN V_MEDIDA END AS TOTAL_POL_RRTT_TRIMESTRE, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalTrim' THEN V_MEDIDA END AS TOTAL_POL_HOGAR_TRIMESTRE, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-007-TotalTrim' THEN V_MEDIDA END AS TOTAL_POL_OCASO_ORO_TRIMESTRE, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalTrim' THEN V_MEDIDA END AS TOTAL_POL_RRPP_TRIMESTRE, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalTrim' THEN V_MEDIDA END AS TOTAL_PRIMAS_TRIMESTRE, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizasCorregidas-998-TotalTrim' THEN V_MEDIDA END AS TOTAL_POL_CORREGIDAS_TRIMESTRE, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-Importe-RegTrim' THEN V_MEDIDA END AS ESCALADO_RAPPEL_REGUL, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-TotalPagoRappel-RegTrim' THEN V_MEDIDA END AS TOTAL_RAPPEL_ABONADO, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-ImporteNeto-RegTrim' THEN V_MEDIDA END AS IMPORTE_REGUL_A_PAGAR, -- INFORME3
						CASE WHEN N_MEDIDA = 'SM-O-COM-GestionExplotacion' THEN V_MEDIDA END AS GESTIONES_CERRADAS, -- INFORME4
						'20' AS OBJETIVO_GESTIONES, -- INFORME4
						CASE WHEN N_MEDIDA = 'SM-O-COM-GestionExplotacion-PorcentajeConsecucion' THEN V_MEDIDA END AS porc_CONSEGUIDO, -- INFORME4
						CASE WHEN N_MEDIDA = 'SM-O-COM-GestionExplotacion-ImportePago' THEN V_MEDIDA END AS IMPORTE_PAGO, -- INFORME4
						J.POSITIONSEQ_PRIN AS POSITIONSEQ,
						J.PERIODSEQ AS PERIODSEQ
					FROM TABLA_RPA AS RESUMEN
					INNER JOIN EXT.OUT_JERARQUIA_REP J ON J.PARTICIPANTSEQ = RESUMEN.PARTICIPANTSEQ
						AND J.POSITIONSEQ_PRIN = RESUMEN.POSITIONSEQ_PRIN
						AND J.PERIODSEQ = RESUMEN.PERIODSEQ
					LEFT JOIN ULT_ACT_1 F
						ON F.PERIODO = RESUMEN.PERIODO
					WHERE
						1=1
						AND (RESUMEN.N_MEDIDA LIKE '%-Rappel-%' OR
							RESUMEN.N_MEDIDA IN ('SM-O-GEN-Agente-NumeroPolizas-002-TotalMes', 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes','SM-O-GEN-Agente-NumeroPolizas-906-TotalMes', 'SM-O-GEN-Agente-NumAsegurados-TotalMes', 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes', 'SM-O-GEN-Agente-Prima-998-TotalMes','SM-O-GEN-Agente-NumeroPolizas-998-TotalMes','SM-O-RPP-Agente-Rappel-Pago-MensualXL','SM-O-RPP-Agente-Rappel-Pago-MensualXXL','SM-O-RPP-Agente-ImporteNeto-RegTrim','SM-O-GEN-Agente-NumAsegurados-TotalTrim','SM-O-GEN-Agente-NumeroPolizas-001-TotalTrim','SM-O-GEN-Agente-NumeroPolizas-002-TotalTrim','SM-O-GEN-Agente-NumeroPolizas-007-TotalTrim','SM-O-GEN-Agente-NumeroPolizas-906-TotalTrim','SM-O-GEN-Agente-Prima-998-TotalTrim','SM-O-GEN-Agente-NumeroPolizasCorregidas-998-TotalTrim','SM-O-RPP-Agente-Importe-RegTrim','SM-O-RPP-Agente-TotalPagoRappel-RegTrim','SM-O-RPP-Agente-ImporteNeto-RegTrim','SM-O-COM-GestionExplotacion','SM-O-COM-GestionExplotacion-PorcentajeConsecucion','SM-O-COM-GestionExplotacion-ImportePago'))
						AND J.POSITIONSEQ = J.POSITIONSEQ_PRIN --LLS 20251124: Añadido para quitar posiciones secundarias
					
					UNION ALL

					SELECT DISTINCT
						-- CAMPOS COMUNES A TODOS LOS INFORMES --
						'02' AS INFORME,
						F.ULT_ACT AS ULT_ACT,
						TO_VARCHAR(RESUMEN.PERIODO) AS PERIODO,           
						J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
						J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
						J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
						J.POS_PRIN AS POS_PRIN,
						J.NOMBRE AS NOMBRE,
						J.NIF AS NIF,
						J.CUADRO_RRGG_OCASO AS CUADRO_RRGG,
						J.CUADRO_RRTT_OCASO AS CUADRO_RRTT,
						TO_VARCHAR(TO_INTEGER(J.ID_TIPO_AGENTE)) AS ID_TIPO_AGENTE,
						TO_VARCHAR(J.TIPO_AGENTE) AS TIPO_AGENTE,
						--------------------------------------------------          
						J.ESCALADO AS ESCALADO_ASISTENCIA, --INFORME2
						NULL AS POL_FIS_HOGAR, -- INFORME1
						NULL AS POL_FIS_RRTT, -- INFORME1
						NULL AS POL_FIS_RRPP, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN V_MEDIDA END AS ASEG, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN V_MEDIDA END AS PRIMA, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-ARA-NumeroPolizasCorregidas-998-Total-ConResto' THEN V_MEDIDA END AS POL_CORREG, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-998-TotalMes' THEN V_MEDIDA END AS POL_FISIC, -- INFORME1,2
						NULL AS RAPPEL, -- INFORME1
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' THEN V_MEDIDA END AS IMP_MENSUAL_XL, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' THEN V_MEDIDA END AS IMP_MENSUAL_XXL, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-ARA-ImportePagoTrim-Final' THEN V_MEDIDA END AS REGUL_TRIMESTRAL, -- INFORME1,2
						CASE WHEN N_MEDIDA = 'SM-O-COM-Asistencia-Importe' THEN V_MEDIDA END AS IMPORTE_COMISION_ASISTENCIAS, -- INFORME2
						CASE WHEN N_MEDIDA = 'SM-O-ARA-TotalPagoSubvencion' THEN V_MEDIDA END AS MINIMO_ASISTENCIA, -- INFORME2
						CASE WHEN N_MEDIDA = 'SM-O-ARA-ImportePago' THEN V_MEDIDA END AS IMPORTE_ESCALADO_RAPPEL, -- INFORME2
						CASE WHEN N_MEDIDA = 'SM-O-ARA-ImporteFinal' THEN V_MEDIDA END AS RAPPEL_FINAL, -- INFORME2
						CASE WHEN N_MEDIDA = 'PM-O-COM-NumeroAsistencias' THEN V_MEDIDA END AS NUM_ASISTENCIAS, -- INFORME2
						NULL AS TOTAL_ASEGURADOS_TRIMESTRE, -- INFORME3
						NULL AS TOTAL_POL_RRTT_TRIMESTRE, -- INFORME3
						NULL AS TOTAL_POL_HOGAR_TRIMESTRE, -- INFORME3
						NULL AS TOTAL_POL_OCASO_ORO_TRIMESTRE, -- INFORME3
						NULL AS TOTAL_POL_RRPP_TRIMESTRE, -- INFORME3
						NULL AS TOTAL_PRIMAS_TRIMESTRE, -- INFORME3
						NULL AS TOTAL_POL_CORREGIDAS_TRIMESTRE, -- INFORME3
						NULL AS ESCALADO_RAPPEL_REGUL, -- INFORME3
						NULL AS TOTAL_RAPPEL_ABONADO, -- INFORME3
						NULL AS IMPORTE_REGUL_A_PAGAR, -- INFORME3
						NULL AS GESTIONES_CERRADAS, -- INFORME4
						NULL AS OBJETIVO_GESTIONES, -- INFORME4
						NULL AS porc_CONSEGUIDO, -- INFORME4
						NULL AS IMPORTE_PAGO, -- INFORME4
						J.POSITIONSEQ_PRIN AS POSITIONSEQ,
						J.PERIODSEQ AS PERIODSEQ
					FROM TABLA_ASI AS RESUMEN
					INNER JOIN EXT.OUT_JERARQUIA_REP J ON J.PARTICIPANTSEQ = RESUMEN.PARTICIPANTSEQ
						AND J.POSITIONSEQ_PRIN = RESUMEN.POSITIONSEQ_PRIN
						AND J.PERIODSEQ =RESUMEN.PERIODSEQ
						-- AND (RESUMEN.V_MEDIDA <> 0 OR RESUMEN.N_MEDIDA LIKE '%Bolsa%')
					LEFT JOIN ULT_ACT_2 F
						ON F.PERIODO = RESUMEN.PERIODO
					WHERE
						1=1
						AND	RESUMEN.N_MEDIDA IN ('SM-O-GEN-Agente-NumAsegurados-TotalMes', 'SM-O-GEN-Agente-Prima-998-TotalMes', 'SM-O-ARA-NumeroPolizasCorregidas-998-Total-ConResto', 'SM-O-GEN-Agente-NumeroPolizas-998-TotalMes', 'SM-O-RPP-Agente-Rappel-Pago-MensualXL', 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL', 'SM-O-ARA-ImportePagoTrim-Final', 'SM-O-COM-Asistencia-Importe', 'SM-O-ARA-TotalPagoSubvencion', 'SM-O-ARA-ImportePago', 'SM-O-ARA-ImporteFinal', 'PM-O-COM-NumeroAsistencias')
						AND J.POSITIONSEQ = J.POSITIONSEQ_PRIN --LLS 20251124: Añadido para quitar posiciones secundarias
						
				) R
				INNER JOIN TABLA_MINIMOS CM ON CM.INFORME = R.INFORME
					AND CM.NIF = R.NIF
					AND CM.PERIODO = R.PERIODO
				WHERE R.PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPA_RESUMEN_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe 1.26 Rappel Producción Agentes', i_log_count, i_id_proceso, 'info');

		-- Fin informe 1.26 Rappel Producción Agentes
		END IF;
		
		---------------------------------------------------------------------------------------------------------------------------------------
		--DTB 20250527: TABLAS PARA INFORME S4 Detalle Pólizas
		IF :i_lista_informes = 'S4' OR :i_lista_informes LIKE '%|S4|%' OR :i_lista_informes LIKE '%|S4' OR :i_lista_informes LIKE 'S4|%' 
			OR i_lista_informes = 'S4_E' OR i_lista_informes LIKE '%|S4_E|%' OR i_lista_informes LIKE '%|S4_E' OR i_lista_informes LIKE 'S4_E|%' 
			OR :i_lista_informes = 'ALL' THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S4 Detalle Pólizas', i_log_count, i_id_proceso, 'info');

			-- BRG 20250527: Nueva tabla OUT_S4_POLIZAS_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_POLIZAS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S4_POLIZAS_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_POLIZAS_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			
            --BRG 20251120 Variable tabla auxiliar para agrupar RRTT
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio creación TBL_S4_POL_FINAL.', i_log_count, i_id_proceso, 'debug');
			TBL_S4_POL_FINAL = 
				SELECT EMPRESA, 
					INFORME_EA, 
					PERIODSEQ, 
					POSITIONSEQ_PRIN AS POSITIONSEQ, 
					PARTICIPANTSEQ, 
					COD_REGIONAL || ' - ' || REGIONAL AS CAMPO_REGIONAL, 
					COD_SUCURSAL || ' - ' || SUCURSAL AS CAMPO_SUCURSAL, 
					CASE WHEN EMPRESA = 'OCASO' THEN COD_PTO_VENTA || ' - '|| PTO_VENTA 
						WHEN EMPRESA = 'ETERNA' THEN COD_OFICINA || ' - '|| OFICINA 
						END AS CAMPO_OFICINA, 
					RIGHT(POS_PRIN,4) || ' - '|| IFNULL(CUADRO_RRGG,' ') || ' - '|| IFNULL(CUADRO_RRTT,' ') || ' - '|| NOMBRE AS CAMPO_AGENTE, 
					TO_DECIMAL(ID_TIPO_AGENTE,25,0) || ' - '|| TIPO_AGENTE AS CAMPO_TIPO_AGENTE, 
					RIGHT(PRODUCTID,5) || ' - '|| PRODUCTO AS CAMPO_PRODUCTO, 
					POS_PRIN,
					POSITIONNAME,
					POLIZA,
					TO_VARCHAR(FEC_CARGO,'MM-YYYY') AS FECHA_CARGO,
					ROUND(PRIMA_NETA_CALC, 2) AS PRIMA_NETA_CALC,
					ROUND(PRIMA_COMISIONABLE, 2) AS PRIMA_COMISIONABLE,
					ROUND(PRODUCCION, 2) AS PRODUCCION,
					ROUND(CONSERVACION, 2) AS CONSERVACION,
					ROUND(PREMIO, 2) AS PREMIO,
					ROUND(FORMACION, 2) AS FORMACION,
					ROUND(POLIZA_CORREGIDA, 2) AS POLIZA_CORREGIDA,
					ROUND(POLIZ_NP, 2) AS POLIZ_NP,
					TIPO_RECIBO,
					NIF,
					:v_period_name_format AS PERIODO, 
					TO_VARCHAR(FEC_VTO_REC,'MM-YYYY') AS FECHA_VENCIMIENTO , 
					IFNULL(SUPERRAPEL, 0) AS SUPERRAPEL_TEXT, 
					ROUND(ASEGURADOS, 2) AS ASEGURADOS, 
					SOLO_DIFERENCIAS, 
					FEC_ACTUALIZACION, 
					TO_VARCHAR(FEC_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION_FORMATO, 
					NIF || ' - ' || NOMBRE || ' - ' || POS_PRIN AS NIF_NOMBRE,
					SALESTRANSACTIONSEQ, --LLS 20251022 añadido
                    --BRG 20251120 campo para agrupar en RRTT por Producto Principal 2X0ZZ
					MIN(RIGHT(PRODUCTID,5) || ' - ' || PRODUCTO) OVER (PARTITION BY PERIODO, EMPRESA, INFORME_EA, POLIZA, TIPO_RECIBO, FEC_CARGO, FEC_VTO_REC, NIF, NOMBRE, POS_PRIN) as PROD_PRIN,
                    --BRG 20251120 campo auxiliar para evitar diferenciar por SALESTRANSACTIONSEQ en la agrupación de RRTT
					MIN(SALESTRANSACTIONSEQ) OVER (PARTITION BY PERIODO, EMPRESA, INFORME_EA, POLIZA, TIPO_RECIBO, FEC_CARGO, FEC_VTO_REC, NIF, NOMBRE, POS_PRIN) AS SALESTRANSACTIONSEQ_PRIN
				FROM 
				( --DETALLE POLIZAS OCASO
					SELECT DISTINCT 'OCASO' AS EMPRESA,
						'CIERRE' AS INFORME_EA, 
						S4_POL.PERIODSEQ, 
						S4_POL.PERIODO, --PERIOD NAME
						S4_POL.POSITIONSEQ_PRIN,
						S4_POL.PARTICIPANTSEQ,
						S4_POL.SALESTRANSACTIONSEQ, --LLS 20251022 añadido
						S4_POL.COD_PTO_VENTA, --TITLEGENERICATTRIBUTE1
						S4_POL.PTO_VENTA, --TITLEGENERICATTRIBUTE2
						S4_POL.COD_OFICINA, --TITLEGENERICATTRIBUTE3
						S4_POL.OFICINA, --TITLEGENERICATTRIBUTE4
						S4_POL.COD_SUCURSAL, --TITLEGENERICATTRIBUTE5
						S4_POL.SUCURSAL, --TITLEGENERICATTRIBUTE6
						S4_POL.COD_REGIONAL, --TITLEGENERICATTRIBUTE7
						S4_POL.REGIONAL, --TITLEGENERICATTRIBUTE8
						S4_POL.NOMBRE, --GENERICATTRIBUTE2
						S4_POL.CUADRO_RRGG, --GENERICATTRIBUTE3
						S4_POL.CUADRO_RRTT, --GENERICATTRIBUTE4
						S4_POL.PRODUCTID, --GENERICATTRIBUTE6
						S4_POL.POS_PRIN, --GENERICATTRIBUTE7
						S4_POL.PRODUCTO, --GENERICATTRIBUTE8 
						S4_POL.POSITIONNAME, --GENERICATTRIBUTE9
						S4_POL.POLIZA, --GENERICATTRIBUTE10
						S4_POL.FEC_CARGO, --GENERICDATE1
						CASE --PRIMA NETA
							WHEN (S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos' 
								OR S4_POL.NAME LIKE 'DC-O-COM-AgentesZona-Porcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-SER%' 
								OR S4_POL.NAME LIKE 'CARTERA_LP')
							THEN S4_POL.PRIMA_NETA
							ELSE 0
							END AS PRIMA_NETA_CALC,
						CASE --PRIMA COMISIONABLE
							WHEN (S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos' 
								OR S4_POL.NAME LIKE 'DC-O-COM-AgentesZona-Porcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-SER%' 
								OR S4_POL.NAME LIKE 'CARTERA_LP')
							THEN S4_POL.PRIMA_COMIS
							ELSE 0
							END AS PRIMA_COMISIONABLE,
						CASE --PRODUCCION
							WHEN (S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-SECI' 
								OR S4_POL.SALESTRANSACTIONSEQ='101')
							THEN S4_POL.VALUE
							ELSE 0
							END AS PRODUCCION,
						CASE --CONSERVACION
							WHEN (S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' 
								OR S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas'
								OR S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe%'
								OR S4_POL.NAME LIKE 'DC-O-COM%-AgentesZona-Porcentaje' 
								OR S4_POL.NAME LIKE 'DC-O-SER%' 
								OR S4_POL.SALESTRANSACTIONSEQ IN ('102','106','107','109','113','123','124','125','126','127','150','153')
								OR S4_POL.NAME LIKE 'CARTERA_LP' 
								OR S4_POL.NAME LIKE 'D-O-%GestionExplotacio%')
							THEN S4_POL.VALUE
							ELSE 0
							END AS CONSERVACION,
						CASE --PREMIO
							WHEN (S4_POL.NAME LIKE 'DC-O-COM-INC-Agente-Campania')
							THEN S4_POL.VALUE
							ELSE 0
							END AS PREMIO,
						CASE --FORMACION
							WHEN (S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos')
							THEN S4_POL.VALUE
							ELSE 0
							END AS FORMACION,
						CASE --POLIZA_CORREGIDA
							WHEN (S4_POL.NAME LIKE '%Recuperadas' 
									AND (LEFT(RIGHT(S4_POL.PRODUCTID,5),3) NOT IN ('501')
										OR S4_POL.ID_TIPO_AGENTE = 39)
									)
							THEN 0
							ELSE S4_POL.POLIZ_CORR
							END AS POLIZA_CORREGIDA,
						S4_POL.POLIZ_NP, --GENERICNUMBER4
						CASE WHEN S4_POL.NAME LIKE '%Recuperadas' THEN 'Recuperación'
							WHEN S4_POL.NAME LIKE 'DC-O-SER-COM' THEN 'CA 13 Comisión'
							WHEN S4_POL.NAME LIKE 'DC-O-SER-SUBV' THEN 'CA 13 Gratificación'
							WHEN S4_POL.NAME LIKE 'DC-O-COM-AgenteZona-Porcentaje' THEN 'R.Cartera A.Z'
							ELSE S4_POL.EVENTO		
							END AS TIPO_RECIBO, 
						S4_POL.NIF, --GENERICATTRIBUTE12
						S4_POL.FEC_VTO_REC, --GENERICDATE2
						S4_POL.ID_TIPO_AGENTE, --GENERICNUMBER6
						S4_POL.TIPO_AGENTE, --GENERICATTRIBUTE16
						S4_POL.SUPERRAPEL, --GENERICBOOLEAN1
						S4_POL.ASEGURADOS, --PARTICIPANTGENERICNUMBER1
						NULL AS SOLO_DIFERENCIAS,
						CASE WHEN F.ULTIMA_ACTUALIZACION > PER.ENDDATE
							THEN LAST_DAY(PER.STARTDATE)
							ELSE F.ULTIMA_ACTUALIZACION
							END FEC_ACTUALIZACION
					FROM EXT.OUT_S4_POLIZAS_REP S4_POL
					INNER JOIN TCMP.CSA_PERIODDIMENSION PER ON PER.PERIODSEQ = S4_POL.PERIODSEQ
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = S4_POL.PERIODO
						AND F.TABLA = 'OUT_S4_POLIZAS_REP'
					WHERE S4_POL.PERIODSEQ = :i_PeriodSeq
						AND S4_POL.ID_TIPO_AGENTE NOT IN (5,6)
						AND S4_POL.POS_PRIN = S4_POL.POSITIONNAME --20251124 LLS: Añadido para quitar posiciones secundarias
					
					UNION ALL
					
					--BALANCE POLIZAS OCASO
					SELECT DISTINCT 'OCASO' AS EMPRESA,
						'BALANCE' AS INFORME_EA, 
						BAL_S4_POL.PERIODSEQ, 
						BAL_S4_POL.PERIODO, --PERIOD NAME
						BAL_S4_POL.POSITIONSEQ_PRIN,
						BAL_S4_POL.PARTICIPANTSEQ,
						BAL_S4_POL.SALESTRANSACTIONSEQ, --LLS 20251022 añadido
						BAL_S4_POL.COD_PTO_VENTA, --TITLEGENERICATTRIBUTE1
						BAL_S4_POL.PTO_VENTA, --TITLEGENERICATTRIBUTE2
						BAL_S4_POL.COD_OFICINA, --TITLEGENERICATTRIBUTE3
						BAL_S4_POL.OFICINA, --TITLEGENERICATTRIBUTE4
						BAL_S4_POL.COD_SUCURSAL, --TITLEGENERICATTRIBUTE5
						BAL_S4_POL.SUCURSAL, --TITLEGENERICATTRIBUTE6
						BAL_S4_POL.COD_REGIONAL, --TITLEGENERICATTRIBUTE7
						BAL_S4_POL.REGIONAL, --TITLEGENERICATTRIBUTE8
						BAL_S4_POL.NOMBRE, --GENERICATTRIBUTE2
						BAL_S4_POL.CUADRO_RRGG, --GENERICATTRIBUTE3
						BAL_S4_POL.CUADRO_RRTT, --GENERICATTRIBUTE4
						BAL_S4_POL.PRODUCTID, --GENERICATTRIBUTE6
						BAL_S4_POL.POS_PRIN, --GENERICATTRIBUTE7
						BAL_S4_POL.PRODUCTO, --GENERICATTRIBUTE8 
						BAL_S4_POL.POSITIONNAME, --GENERICATTRIBUTE9
						BAL_S4_POL.POLIZA, --GENERICATTRIBUTE10
						BAL_S4_POL.FEC_CARGO, --GENERICDATE1
						CASE --PRIMA NETA
							WHEN (BAL_S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' 
								OR BAL_S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
