								OR LC_S4_E_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' 
								OR LC_S4_E_POL.NAME LIKE 'DC-E-SER%' 
								OR LC_S4_E_POL.SALESTRANSACTIONSEQ IN ('102','109','123','124','125','126','150','153')
								OR LC_S4_E_POL.NAME LIKE 'CARTERA_LP') --DTB 20260420 añadido este caso
							THEN LC_S4_E_POL.VALUE
							ELSE 0
							END AS CONSERVACION,
						CASE --PREMIO
							WHEN (LC_S4_E_POL.NAME = '')
							THEN LC_S4_E_POL.VALUE
							ELSE 0
							END AS PREMIO,
						CASE --FORMACION
							WHEN (LC_S4_E_POL.NAME LIKE 'DC-E-COM%-NuevaProduccion-Candidatos')
							THEN LC_S4_E_POL.VALUE
							ELSE 0
							END AS FORMACION,
						CASE --POLIZA_CORREGIDA
							WHEN (LC_S4_E_POL.POLIZ_CORR IS NULL)
							THEN 0
							ELSE LC_S4_E_POL.POLIZ_CORR
							END AS POLIZA_CORREGIDA,
						LC_S4_E_POL.POLIZ_NP, --GENERICNUMBER4
						CASE WHEN LC_S4_E_POL.NAME LIKE '%Recuperadas' THEN 'Recuperación'
							WHEN LC_S4_E_POL.NAME LIKE 'DC-E-SER-COM' THEN 'CA 13 Comisión'
							WHEN LC_S4_E_POL.NAME LIKE 'DC-E-SER-SUBV' THEN 'CA 13 Gratificación'
							ELSE LC_S4_E_POL.EVENTO		
							END AS TIPO_RECIBO, 
						LC_S4_E_POL.NIF, --GENERICATTRIBUTE12
						LC_S4_E_POL.FEC_VTO_REC, --GENERICDATE2
						LC_S4_E_POL.ID_TIPO_AGENTE, --GENERICNUMBER6
						LC_S4_E_POL.TIPO_AGENTE, --GENERICATTRIBUTE16
						LC_S4_E_POL.SUPERRAPEL, --GENERICBOOLEAN1
						LC_S4_E_POL.ASEGURADOS, --PARTICIPANTGENERICNUMBER1
						CASE WHEN ((PAY.POSTPIPELINERUNSEQ IS NULL OR PAY.POSTPIPELINERUNDATE >= PER.ENDDATE) AND PAY.PERIODSEQ = PER.PERIODSEQ)
							THEN 'SI' ELSE NULL END SOLO_DIFERENCIAS, 
						F.ULTIMA_ACTUALIZACION FEC_ACTUALIZACION --LLS 20250508
					FROM EXT.OUT_LC_S4_E_POLIZAS_REP LC_S4_E_POL
					INNER JOIN EXT.OUT_JERARQUIA_REP J ON LC_S4_E_POL.PERIODSEQ = J.PERIODSEQ
						AND LC_S4_E_POL.PARTICIPANTSEQ = J.PARTICIPANTSEQ
						AND LC_S4_E_POL.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
					INNER JOIN TCMP.CSA_PERIODDIMENSION PER ON PER.PERIODSEQ = LC_S4_E_POL.PERIODSEQ
					LEFT JOIN TCMP.CS_PAYMENT PAY ON PAY.PERIODSEQ = LC_S4_E_POL.PERIODSEQ
						AND PAY.PAYEESEQ = LC_S4_E_POL.PARTICIPANTSEQ
						AND PAY.POSITIONSEQ = LC_S4_E_POL.POSITIONSEQ_PRIN
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = LC_S4_E_POL.PERIODO
						AND F.TABLA = 'OUT_LC_S4_E_POLIZAS_REP'
					WHERE LC_S4_E_POL.PERIODSEQ = :i_PeriodSeq
						AND LC_S4_E_POL.POS_PRIN = LC_S4_E_POL.POSITIONNAME --20251124 LLS: Añadido para quitar posiciones secundarias
				)
				WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := RECORD_COUNT(:TBL_S4_POL_FINAL);
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'TBL_S4_POL_FINAL creada. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			--BRG 20251120 Dividimos el INSERT en la final en 2 partes, RRTT agrupado y el resto de ramos sin agrupar
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S4_POLIZAS_FINAL_REP RRTT agrupado.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S4_POLIZAS_FINAL_REP (EMPRESA,INFORME_EA,PERIODSEQ,POSITIONSEQ,PARTICIPANTSEQ,CAMPO_REGIONAL,CAMPO_SUCURSAL,CAMPO_OFICINA,CAMPO_AGENTE,CAMPO_TIPO_AGENTE,CAMPO_PRODUCTO,POS_PRIN,POSITIONNAME,POLIZA,FECHA_CARGO,PRIMA_NETA_CALC,PRIMA_COMISIONABLE,PRODUCCION,CONSERVACION,PREMIO,FORMACION,POLIZA_CORREGIDA,POLIZ_NP,TIPO_RECIBO,NIF,PERIODO,FECHA_VENCIMIENTO,SUPERRAPEL_TEXT,ASEGURADOS,SOLO_DIFERENCIAS,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO,NIF_NOMBRE,SALESTRANSACTIONSEQ)
				SELECT 
					EMPRESA, INFORME_EA, PERIODSEQ, POSITIONSEQ, PARTICIPANTSEQ, 
					CAMPO_REGIONAL, CAMPO_SUCURSAL, CAMPO_OFICINA, CAMPO_AGENTE, CAMPO_TIPO_AGENTE,
					--BRG 20260423 Transformamos para que los productos se vean bien cuando falta el principal
					LEFT(PROD_PRIN, 2) || '0' || RIGHT(PROD_PRIN, LENGTH(PROD_PRIN)-3) AS PROD_PRIN, --BRG 20251120 En vez de CAMPO_PRODUCTO
					POS_PRIN, POSITIONNAME, 
					POLIZA, FECHA_CARGO, SUM(PRIMA_NETA_CALC), SUM(PRIMA_COMISIONABLE), SUM(PRODUCCION), SUM(CONSERVACION), SUM(PREMIO), SUM(FORMACION), SUM(POLIZA_CORREGIDA), SUM(POLIZ_NP), TIPO_RECIBO,
					NIF,
					PERIODO, FECHA_VENCIMIENTO, SUPERRAPEL_TEXT, SUM(ASEGURADOS), SOLO_DIFERENCIAS, FEC_ACTUALIZACION, FEC_ACTUALIZACION_FORMATO, NIF_NOMBRE, 
					SALESTRANSACTIONSEQ_PRIN --BRG 20251120 En vez de SALESTRANSACTIONSEQ
				FROM :TBL_S4_POL_FINAL
				WHERE CAMPO_PRODUCTO LIKE '2%'
				GROUP BY EMPRESA, INFORME_EA, PERIODSEQ, POSITIONSEQ, PARTICIPANTSEQ,
					CAMPO_REGIONAL, CAMPO_SUCURSAL, CAMPO_OFICINA, CAMPO_AGENTE, CAMPO_TIPO_AGENTE,
					PROD_PRIN, --BRG 20251120 En vez de CAMPO_PRODUCTO
					POS_PRIN, POSITIONNAME, 
					POLIZA, FECHA_CARGO, TIPO_RECIBO,
					NIF,
					PERIODO, FECHA_VENCIMIENTO, SUPERRAPEL_TEXT, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, FEC_ACTUALIZACION_FORMATO, NIF_NOMBRE, 
					SALESTRANSACTIONSEQ_PRIN; --BRG 20251120 En vez de SALESTRANSACTIONSEQ
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S4_POLIZAS_FINAL_REP RRTT agrupado. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S4_POLIZAS_FINAL_REP Resto Ramos.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S4_POLIZAS_FINAL_REP (EMPRESA,INFORME_EA,PERIODSEQ,POSITIONSEQ,PARTICIPANTSEQ,CAMPO_REGIONAL,CAMPO_SUCURSAL,CAMPO_OFICINA,CAMPO_AGENTE,CAMPO_TIPO_AGENTE,CAMPO_PRODUCTO,POS_PRIN,POSITIONNAME,POLIZA,FECHA_CARGO,PRIMA_NETA_CALC,PRIMA_COMISIONABLE,PRODUCCION,CONSERVACION,PREMIO,FORMACION,POLIZA_CORREGIDA,POLIZ_NP,TIPO_RECIBO,NIF,PERIODO,FECHA_VENCIMIENTO,SUPERRAPEL_TEXT,ASEGURADOS,SOLO_DIFERENCIAS,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO,NIF_NOMBRE,SALESTRANSACTIONSEQ)
				SELECT 
					EMPRESA, INFORME_EA, PERIODSEQ, POSITIONSEQ, PARTICIPANTSEQ, 
					CAMPO_REGIONAL, CAMPO_SUCURSAL, CAMPO_OFICINA, CAMPO_AGENTE, CAMPO_TIPO_AGENTE,
					CAMPO_PRODUCTO,
					POS_PRIN, POSITIONNAME, 
					POLIZA, FECHA_CARGO, PRIMA_NETA_CALC, PRIMA_COMISIONABLE, PRODUCCION, CONSERVACION, PREMIO, FORMACION, POLIZA_CORREGIDA, POLIZ_NP, TIPO_RECIBO,
					NIF,
					PERIODO, FECHA_VENCIMIENTO, SUPERRAPEL_TEXT, ASEGURADOS, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, FEC_ACTUALIZACION_FORMATO, NIF_NOMBRE, 
					SALESTRANSACTIONSEQ
				FROM :TBL_S4_POL_FINAL
				WHERE CAMPO_PRODUCTO NOT LIKE '2%';
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S4_POLIZAS_FINAL_REP Resto Ramos. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Insert de --SELECCIONAR-- en OUT_S4_POLIZAS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S4_POLIZAS_FINAL_REP (EMPRESA,INFORME_EA,PERIODSEQ,POSITIONSEQ,PARTICIPANTSEQ,CAMPO_REGIONAL,CAMPO_SUCURSAL,CAMPO_OFICINA,CAMPO_AGENTE,CAMPO_TIPO_AGENTE,CAMPO_PRODUCTO,POS_PRIN,POSITIONNAME,POLIZA,FECHA_CARGO,PRIMA_NETA_CALC,PRIMA_COMISIONABLE,PRODUCCION,CONSERVACION,PREMIO,FORMACION,POLIZA_CORREGIDA,POLIZ_NP,TIPO_RECIBO,NIF,PERIODO,FECHA_VENCIMIENTO,SUPERRAPEL_TEXT,ASEGURADOS,SOLO_DIFERENCIAS,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO,NIF_NOMBRE,SALESTRANSACTIONSEQ)
				SELECT DISTINCT
					EMPRESA,
					INFORME_EA,
					PERIODSEQ,
					-1, --POSITIONSEQ
					NULL, --PARTICIPANTSEQ
					' ', --REG
					' ', --SUC
					' ', --OFI
					' ', --AG
					' ', --TIPO_AG
					' ', --PROD
					' ', --POS_PRIN
					' ', --POSNAME
					' ', --POLIZ
					' ', --FEC_CAR
					NULL, --PRIMA_NETA
					NULL, --PRIMA_COMIS
					NULL, --PROD
					NULL, --CONSERV
					NULL, --PREMIO
					NULL, --FORMAC
					NULL, --POLIZ_CORR
					NULL, --POLIZ_NP
					' ', --TIPO_REC
					' ', --NIF
					PERIODO,
					' ', --FEC_VENC
					NULL, --SUPERRAPPEL
					NULL, --ASEG
					SOLO_DIFERENCIAS, --SOLO_DIF
					FEC_ACTUALIZACION,
					FEC_ACTUALIZACION_FORMATO,
					'--SELECCIONAR--', --NIF_NOMBRE
					NULL --SALESTRANSACTIONSEQ--LLS 20251022 añadido
				FROM EXT.OUT_S4_POLIZAS_FINAL_REP
				WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Insert de --SELECCIONAR-- en OUT_S4_POLIZAS_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe S4 Detalle Pólizas', i_log_count, i_id_proceso, 'info');


            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S4 Detalle Pólizas Corredores', i_log_count, i_id_proceso, 'info');

            -- BRG 20250527: Nueva tabla OUT_S4_POLIZAS_CORR_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_POLIZAS_CORR_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S4_POLIZAS_CORR_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_POLIZAS_CORR_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			
			-- BRG 20260422 Variable tabla auxiliar para agrupar RRTT
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Creación TBL_S4_POL_CORR_FINAL', i_log_count, i_id_proceso, 'debug');
            TBL_S4_POL_CORR_FINAL =
				SELECT TIPO_INFORME, 
					REGIONAL,
					SUCURSAL,
					OFICINA,
					AGENTE,
					NIF,
					NIF_NOMBRE,
					TIPO_AGENTE,
					PRODUCTO, 
					GEST,
					COD_AGENTE,
					POLIZA,
					COD_RECIBO,
					FEC_CARGO,
					FEC_VTO_REC,
					PRIMA_NETA,
					PRIMA_COMISIONABLE,
					PRODUCCION,
					CONSERVACION,
					NUEVA_PRODUCCION,
					TIPO_RECIBO,
					AUTOLIQUIDACION,
					SOLO_DIFERENCIAS,
					FEC_ACTUALIZACION,
					PERIODO,
					PERIODO_FORMATO,
					PERIODSEQ,
					POSITIONSEQ,
					--BRG 20251120 campo para agrupar en RRTT por Producto Principal 2X0ZZ
					MIN(PRODUCTO) OVER (PARTITION BY PERIODO, TIPO_INFORME, POLIZA, COD_RECIBO, TIPO_RECIBO, FEC_CARGO, FEC_VTO_REC, NIF, AGENTE) AS PROD_PRIN
				FROM (
					--BRG 20260423 Añadimos DISTINCT por incidencia de duplicados
					SELECT DISTINCT 
						'CIERRE' AS TIPO_INFORME,
						S4_POL.COD_REGIONAL || ' - ' || S4_POL.REGIONAL AS REGIONAL,
						S4_POL.COD_SUCURSAL || ' - ' || S4_POL.SUCURSAL AS SUCURSAL,
						S4_POL.COD_PTO_VENTA || ' - ' || S4_POL.PTO_VENTA AS OFICINA,
						RIGHT(S4_POL.POS_PRIN, 4) || IFNULL(' - ' || S4_POL.CUADRO_RRGG, '') || IFNULL(' - ' || S4_POL.CUADRO_RRTT, '') || ' - ' || S4_POL.NOMBRE AS AGENTE,
						S4_POL.NIF,
						S4_POL.NIF || ' - ' || S4_POL.NOMBRE || ' - ' || S4_POL.POS_PRIN AS NIF_NOMBRE,
						TO_INTEGER(S4_POL.ID_TIPO_AGENTE) || ' - ' || S4_POL.TIPO_AGENTE AS TIPO_AGENTE,
						RIGHT(S4_POL.PRODUCTID, 5) || ' - ' || S4_POL.PRODUCTO AS PRODUCTO,
						LEFT(S4_POL.POSITIONNAME, 4) AS GEST,
						RIGHT(S4_POL.POSITIONNAME, 6) AS COD_AGENTE,
						S4_POL.POLIZA,
						S4_POL.COD_RECIBO,
						TO_VARCHAR(S4_POL.FEC_CARGO, 'MM-YYYY') AS FEC_CARGO,
						TO_VARCHAR(S4_POL.FEC_VTO_REC, 'MM-YYYY') AS FEC_VTO_REC,
						CASE WHEN (
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos' OR
							S4_POL.NAME LIKE 'DC-O-SER%' OR
							S4_POL.NAME LIKE 'CARTERA_LP')
							THEN S4_POL.PRIMA_NETA 
							ELSE 0 END AS PRIMA_NETA,
						CASE WHEN (
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos' OR
							S4_POL.NAME LIKE 'DC-O-SER%' OR
							S4_POL.NAME LIKE 'CARTERA_LP')
							THEN S4_POL.PRIMA_COMIS
							ELSE 0 END AS PRIMA_COMISIONABLE,
						CASE WHEN (
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-SECI' OR
							S4_POL.SALESTRANSACTIONSEQ = '101') 
							THEN S4_POL.VALUE 
							ELSE 0 END AS PRODUCCION,
						CASE WHEN (
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' OR
							S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe%' OR
							S4_POL.NAME LIKE 'DC-O-SER%' OR
							S4_POL.SALESTRANSACTIONSEQ IN ('102', '106', '107' , '109' , '123' , '124', '125', '126', '127', '150', '153') OR
							S4_POL.NAME LIKE 'CARTERA_LP' OR
							S4_POL.NAME LIKE 'D-O-%GestionExplotacio%')	
							THEN S4_POL.VALUE 
							ELSE 0 END AS CONSERVACION,
						S4_POL.POLIZ_NP AS NUEVA_PRODUCCION,
						CASE WHEN S4_POL.NAME LIKE '%Recuperadas' THEN 'Recuperación'
							WHEN S4_POL.NAME LIKE 'DC-O-SER-COM' THEN 'CA 13 Comisión'
							WHEN S4_POL.NAME LIKE 'DC-O-SER-SUBV' THEN 'CA 13 Gratificación'
							ELSE S4_POL.EVENTO END AS TIPO_RECIBO,
						CASE WHEN S4_POL.NAME LIKE '%-AUT-%' THEN 'SI'
							ELSE 'NO' END AS AUTOLIQUIDACION,
						NULL AS SOLO_DIFERENCIAS,
						
						TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
						S4_POL.PERIODO,
						:v_period_name_format AS PERIODO_FORMATO,
						S4_POL.PERIODSEQ,
						S4_POL.POSITIONSEQ_PRIN AS POSITIONSEQ,
						S4_POL.SALESTRANSACTIONSEQ --BRG 20260423 Añadido para reforzar el DISTINCT
					FROM EXT.OUT_S4_POLIZAS_REP S4_POL
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = S4_POL.PERIODO
						AND F.TABLA = 'OUT_S4_POLIZAS_REP'
					WHERE S4_POL.PERIODSEQ = :i_PeriodSeq
						AND S4_POL.ID_TIPO_AGENTE IN (5,6)
					
					UNION ALL
					
					--BRG 20260423 Añadimos DISTINCT por incidencia de duplicados
					SELECT DISTINCT
						'BALANCE' AS TIPO_INFORME,
						S4_POL.COD_REGIONAL || ' - ' || S4_POL.REGIONAL AS REGIONAL,
						S4_POL.COD_SUCURSAL || ' - ' || S4_POL.SUCURSAL AS SUCURSAL,
						S4_POL.COD_PTO_VENTA || ' - ' || S4_POL.PTO_VENTA AS OFICINA,
						RIGHT(S4_POL.POS_PRIN, 4) || IFNULL(' - ' || S4_POL.CUADRO_RRGG, '') || IFNULL(' - ' || S4_POL.CUADRO_RRTT, '') || ' - ' || S4_POL.NOMBRE AS AGENTE,
						S4_POL.NIF,
						S4_POL.NIF || ' - ' || S4_POL.NOMBRE || ' - ' || S4_POL.POS_PRIN AS NIF_NOMBRE,
						TO_INTEGER(S4_POL.ID_TIPO_AGENTE) || ' - ' || S4_POL.TIPO_AGENTE AS TIPO_AGENTE,
						RIGHT(S4_POL.PRODUCTID, 5) || ' - ' || S4_POL.PRODUCTO AS PRODUCTO,
						LEFT(S4_POL.POSITIONNAME, 4) AS GEST,
						RIGHT(S4_POL.POSITIONNAME, 6) AS COD_AGENTE,
						S4_POL.POLIZA,
						S4_POL.COD_RECIBO,
						TO_VARCHAR(S4_POL.FEC_CARGO, 'MM-YYYY') AS FEC_CARGO,
						TO_VARCHAR(S4_POL.FEC_VTO_REC, 'MM-YYYY') AS FEC_VTO_REC,
						CASE WHEN (
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos' OR
							S4_POL.NAME LIKE 'DC-O-SER%' OR
							S4_POL.NAME LIKE 'CARTERA_LP')
							THEN S4_POL.PRIMA_NETA 
							ELSE 0 END AS PRIMA_NETA,
						CASE WHEN (
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos' OR
							S4_POL.NAME LIKE 'DC-O-SER%' OR
							S4_POL.NAME LIKE 'CARTERA_LP')
							THEN S4_POL.PRIMA_COMIS
							ELSE 0 END AS PRIMA_COMISIONABLE,
						CASE WHEN (
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-SECI' OR
							S4_POL.SALESTRANSACTIONSEQ = '101') 
							THEN S4_POL.VALUE 
							ELSE 0 END AS PRODUCCION,
						CASE WHEN (
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' OR
							S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe%' OR
							S4_POL.NAME LIKE 'DC-O-SER%' OR
							S4_POL.SALESTRANSACTIONSEQ IN ('102', '106', '107' , '109' , '123' , '124', '125', '126', '127', '150', '153') OR
							S4_POL.NAME LIKE 'CARTERA_LP' OR
							S4_POL.NAME LIKE 'D-O-%GestionExplotacio%')	
							THEN S4_POL.VALUE 
							ELSE 0 END AS CONSERVACION,
						S4_POL.POLIZ_NP AS NUEVA_PRODUCCION,
						CASE WHEN S4_POL.NAME LIKE '%Recuperadas' THEN 'Recuperación'
							WHEN S4_POL.NAME LIKE 'DC-O-SER-COM' THEN 'CA 13 Comisión'
							WHEN S4_POL.NAME LIKE 'DC-O-SER-SUBV' THEN 'CA 13 Gratificación'
							ELSE S4_POL.EVENTO END AS TIPO_RECIBO,
						CASE WHEN S4_POL.NAME LIKE '%-AUT-%' THEN 'SI'
							ELSE 'NO' END AS AUTOLIQUIDACION,
						CASE WHEN B.BALANCESEQ IS NOT NULL THEN 'SI'
							ELSE NULL END AS SOLO_DIFERENCIAS,
						
						TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
						S4_POL.PERIODO,
						:v_period_name_format,
						S4_POL.PERIODSEQ,
						S4_POL.POSITIONSEQ_PRIN AS POSITIONSEQ,
						S4_POL.SALESTRANSACTIONSEQ --BRG 20260423 Añadido para reforzar el DISTINCT
					FROM EXT.OUT_BAL_S4_POLIZAS_REP S4_POL
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = S4_POL.PERIODO
						AND F.TABLA = 'OUT_BAL_S4_POLIZAS_REP'
					LEFT JOIN TCMP.CS_BALANCE B ON B.PERIODSEQ = S4_POL.PERIODSEQ
						AND B.PAYEESEQ = S4_POL.PARTICIPANTSEQ
						AND B.POSITIONSEQ = S4_POL.POSITIONSEQ_PRIN
					WHERE S4_POL.PERIODSEQ = :i_PeriodSeq
						AND S4_POL.ID_TIPO_AGENTE IN (5,6)
					
					UNION ALL
					
					--BRG 20260423 Añadimos DISTINCT por incidencia de duplicados
					SELECT DISTINCT
						'LC' AS TIPO_INFORME,
						S4_POL.COD_REGIONAL || ' - ' || S4_POL.REGIONAL AS REGIONAL,
						S4_POL.COD_SUCURSAL || ' - ' || S4_POL.SUCURSAL AS SUCURSAL,
						S4_POL.COD_PTO_VENTA || ' - ' || S4_POL.PTO_VENTA AS OFICINA,
						RIGHT(S4_POL.POS_PRIN, 4) || IFNULL(' - ' || S4_POL.CUADRO_RRGG, '') || IFNULL(' - ' || S4_POL.CUADRO_RRTT, '') || ' - ' || S4_POL.NOMBRE AS AGENTE,
						S4_POL.NIF,
						S4_POL.NIF || ' - ' || S4_POL.NOMBRE || ' - ' || S4_POL.POS_PRIN AS NIF_NOMBRE,
						TO_INTEGER(S4_POL.ID_TIPO_AGENTE) || ' - ' || S4_POL.TIPO_AGENTE AS TIPO_AGENTE,
						RIGHT(S4_POL.PRODUCTID, 5) || ' - ' || S4_POL.PRODUCTO AS PRODUCTO,
						LEFT(S4_POL.POSITIONNAME, 4) AS GEST,
						RIGHT(S4_POL.POSITIONNAME, 6) AS COD_AGENTE,
						S4_POL.POLIZA,
						S4_POL.COD_RECIBO,
						TO_VARCHAR(S4_POL.FEC_CARGO, 'MM-YYYY') AS FEC_CARGO,
						TO_VARCHAR(S4_POL.FEC_VTO_REC, 'MM-YYYY') AS FEC_VTO_REC,
						CASE WHEN (
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos' OR
							S4_POL.NAME LIKE 'DC-O-SER%' OR
							S4_POL.NAME LIKE 'CARTERA_LP')
							THEN S4_POL.PRIMA_NETA 
							ELSE 0 END AS PRIMA_NETA,
						CASE WHEN (
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Candidatos' OR
							S4_POL.NAME LIKE 'DC-O-SER%' OR
							S4_POL.NAME LIKE 'CARTERA_LP')
							THEN S4_POL.PRIMA_COMIS
							ELSE 0 END AS PRIMA_COMISIONABLE,
						CASE WHEN (
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-NuevaProduccion-SECI' OR
							S4_POL.SALESTRANSACTIONSEQ = '101') 
							THEN S4_POL.VALUE 
							ELSE 0 END AS PRODUCCION,
						CASE WHEN (
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Cartera-Importe' OR
							S4_POL.NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' OR
							S4_POL.NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe%' OR
							S4_POL.NAME LIKE 'DC-O-SER%' OR
							S4_POL.SALESTRANSACTIONSEQ IN ('102', '106', '107' , '109' , '123' , '124', '125', '126', '127', '150', '153') OR
							S4_POL.NAME LIKE 'CARTERA_LP' OR
							S4_POL.NAME LIKE 'D-O-%GestionExplotacio%')	
							THEN S4_POL.VALUE 
							ELSE 0 END AS CONSERVACION,
						S4_POL.POLIZ_NP AS NUEVA_PRODUCCION,
						CASE WHEN S4_POL.NAME LIKE '%Recuperadas' THEN 'Recuperación'
							WHEN S4_POL.NAME LIKE 'DC-O-SER-COM' THEN 'CA 13 Comisión'
							WHEN S4_POL.NAME LIKE 'DC-O-SER-SUBV' THEN 'CA 13 Gratificación'
							ELSE S4_POL.EVENTO END AS TIPO_RECIBO,
						CASE WHEN S4_POL.NAME LIKE '%-AUT-%' THEN 'SI'
							ELSE 'NO' END AS AUTOLIQUIDACION,
						CASE WHEN (P.POSTPIPELINERUNSEQ IS NULL OR P.POSTPIPELINERUNDATE > :v_period_enddate) THEN 'SI'
							ELSE NULL END AS SOLO_DIFERENCIAS,
			
						TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
						S4_POL.PERIODO,
						:v_period_name_format,
						S4_POL.PERIODSEQ,
						S4_POL.POSITIONSEQ_PRIN AS POSITIONSEQ,
						S4_POL.SALESTRANSACTIONSEQ --BRG 20260423 Añadido para reforzar el DISTINCT
					FROM EXT.OUT_LC_S4_POLIZAS_REP S4_POL
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = S4_POL.PERIODO
						AND F.TABLA = 'OUT_LC_S4_POLIZAS_REP'
					LEFT JOIN TCMP.CS_PAYMENT P ON P.PERIODSEQ = S4_POL.PERIODSEQ
						AND P.PAYEESEQ = S4_POL.PARTICIPANTSEQ
						AND P.POSITIONSEQ = S4_POL.POSITIONSEQ_PRIN
					WHERE S4_POL.PERIODSEQ = :i_PeriodSeq
						AND S4_POL.ID_TIPO_AGENTE IN (5,6)
				);
            v_num_rows := ::ROWCOUNT;
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Creación TBL_S4_POL_CORR_FINAL. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			--BRG 20260421 Dividimos el INSERT en la final en 2 partes, RRTT agrupado y el resto de ramos sin agrupar
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S4_POLIZAS_CORR_FINAL_REP RRTT agrupado.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S4_POLIZAS_CORR_FINAL_REP (TIPO_INFORME, REGIONAL, SUCURSAL, OFICINA, AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, PRODUCTO, GEST, COD_AGENTE, POLIZA, COD_RECIBO, FEC_CARGO, FEC_VTO_REC, PRIMA_NETA, PRIMA_COMISIONABLE, PRODUCCION, CONSERVACION, NUEVA_PRODUCCION, TIPO_RECIBO, AUTOLIQUIDACION, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, PERIODO, PERIODO_FORMATO, PERIODSEQ, POSITIONSEQ)
				SELECT
					TIPO_INFORME, REGIONAL, SUCURSAL, OFICINA,
					AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE,
					--BRG 20260423 Transformamos para que los productos se vean bien cuando falta el principal
					LEFT(PROD_PRIN, 2) || '0' || RIGHT(PROD_PRIN, LENGTH(PROD_PRIN)-3) AS PRODUCTO, --BRG 20260421 En vez de PRODUCTO
					GEST, COD_AGENTE, 
					POLIZA, COD_RECIBO, FEC_CARGO, FEC_VTO_REC, SUM(PRIMA_NETA), SUM(PRIMA_COMISIONABLE), SUM(PRODUCCION), SUM(CONSERVACION), SUM(NUEVA_PRODUCCION), TIPO_RECIBO,
					AUTOLIQUIDACION, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, PERIODO, PERIODO_FORMATO, PERIODSEQ, POSITIONSEQ
				FROM :TBL_S4_POL_CORR_FINAL
				WHERE PRODUCTO LIKE '2%'
				GROUP BY TIPO_INFORME, REGIONAL, SUCURSAL, OFICINA,
					AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE,
					PROD_PRIN, --BRG 20260421 En vez de PRODUCTO
					GEST, COD_AGENTE,
					POLIZA, COD_RECIBO, FEC_CARGO, FEC_VTO_REC, TIPO_RECIBO,
					AUTOLIQUIDACION, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, PERIODO, PERIODO_FORMATO, PERIODSEQ, POSITIONSEQ;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S4_POLIZAS_CORR_FINAL_REP RRTT agrupado. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S4_POLIZAS_CORR_FINAL_REP Resto Ramos.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S4_POLIZAS_CORR_FINAL_REP (TIPO_INFORME, REGIONAL, SUCURSAL, OFICINA, AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, PRODUCTO, GEST, COD_AGENTE, POLIZA, COD_RECIBO, FEC_CARGO, FEC_VTO_REC, PRIMA_NETA, PRIMA_COMISIONABLE, PRODUCCION, CONSERVACION, NUEVA_PRODUCCION, TIPO_RECIBO, AUTOLIQUIDACION, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, PERIODO, PERIODO_FORMATO, PERIODSEQ, POSITIONSEQ)
				SELECT
					TIPO_INFORME, REGIONAL, SUCURSAL, OFICINA,
					AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE,
					PRODUCTO,
					GEST, COD_AGENTE,
					POLIZA, COD_RECIBO, FEC_CARGO, FEC_VTO_REC, PRIMA_NETA, PRIMA_COMISIONABLE, PRODUCCION, CONSERVACION, NUEVA_PRODUCCION, TIPO_RECIBO,
					AUTOLIQUIDACION, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, PERIODO, PERIODO_FORMATO, PERIODSEQ, POSITIONSEQ
				FROM :TBL_S4_POL_CORR_FINAL
				WHERE PRODUCTO NOT LIKE '2%';
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S4_POLIZAS_CORR_FINAL_REP Resto Ramos. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Insert de --SELECCIONAR-- en OUT_S4_POLIZAS_CORR_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
            INSERT INTO EXT.OUT_S4_POLIZAS_CORR_FINAL_REP (TIPO_INFORME, REGIONAL, SUCURSAL, OFICINA, AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, PRODUCTO, GEST, COD_AGENTE, POLIZA, COD_RECIBO, FEC_CARGO, FEC_VTO_REC, PRIMA_NETA, PRIMA_COMISIONABLE, PRODUCCION, CONSERVACION, NUEVA_PRODUCCION, TIPO_RECIBO, AUTOLIQUIDACION, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, PERIODO, PERIODO_FORMATO, PERIODSEQ, POSITIONSEQ)
                SELECT DISTINCT
                    TIPO_INFORME,
                    ' ' AS REGIONAL,
                    ' ' AS SUCURSAL,
                    ' ' AS OFICINA,
                    ' ' AS AGENTE,
                    ' ' AS NIF,
                    '--SELECCIONAR--' AS NIF_NOMBRE,
                    ' ' AS TIPO_AGENTE,
                    ' ' AS PRODUCTO,
                    ' ' AS GEST,
                    ' ' AS COD_AGENTE,
                    ' ' AS POLIZA,
                    ' ' AS COD_RECIBO,
                    ' ' AS FEC_CARGO,
                    ' ' AS FEC_VTO_REC,
                    NULL AS PRIMA_NETA,
                    NULL AS PRIMA_COMISIONABLE,
                    NULL AS PRODUCCION,
                    NULL AS CONSERVACION,
                    NULL AS NUEVA_PRODUCCION,
                    ' ' AS TIPO_RECIBO,
                    ' ' AS AUTOLIQUIDACION,
                    SOLO_DIFERENCIAS,
                    FEC_ACTUALIZACION,
                    PERIODO,
                    PERIODO_FORMATO,
                    PERIODSEQ,
                    -1 AS POSITIONSEQ
                FROM EXT.OUT_S4_POLIZAS_CORR_FINAL_REP
				WHERE PERIODSEQ = :i_PeriodSeq;
            v_num_rows := ::ROWCOUNT;
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Insert de --SELECCIONAR-- en OUT_S4_POLIZAS_CORR_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe S4 Detalle Pólizas Corredores', i_log_count, i_id_proceso, 'info');

		-- Fin informe S4 Detalle Pólizas
		END IF;
		
		---------------------------------------------------------------------------------------------------------------------------------------
		-- BRG 20250527: TABLAS PARA INFORME S5 Detalle Pólizas (sólo se migra Ocaso)
		IF :i_lista_informes = 'S5' OR :i_lista_informes LIKE '%|S5|%' OR :i_lista_informes LIKE '%|S5' OR :i_lista_informes LIKE 'S5|%' 
			OR i_lista_informes = 'ALL' THEN

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S5 Detalle Pólizas', i_log_count, i_id_proceso, 'info');

			-- BRG 20250526: Nueva tabla OUT_S5_POLIZAS_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S5_POLIZAS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S5_POLIZAS_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S5_POLIZAS_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			-- BRG 20251127	Variable tabla auxiliar para agrupar RRTT
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio creación TBL_S5_POL_FINAL.', i_log_count, i_id_proceso, 'debug');
			TBL_S5_POL_FINAL =
				SELECT DISTINCT
					EMPRESA,
					INFORME_EA,
					:v_period_name_format AS PERIODO,
					SALESTRANSACTIONSEQ,
					REGIONAL,
					SUCURSAL,
					OFICINA,
					AGENTE,
					NIF,
					NIF_NOMBRE,
					TIPO_AGENTE,
					PRODUCTO,
					TIPO_RECIBO,
					POLIZA,
					ROUND(POLIZ_NP, 2) AS POLIZ_NP,
					IFNULL(AGENTE_TABLA, ' ') AS AGENTE_TABLA,
					IFNULL(TO_VARCHAR(TO_INTEGER(TIPO_AGENTE_TABLA)), ' ') AS TIPO_AGENTE_TABLA,
					TO_VARCHAR(FEC_CARGO, 'MM-YYYY') AS FEC_CARGO,
					--TO_VARCHAR(FEC_VTO_RECIBO, 'DD/MM/YYYY'),
					TO_VARCHAR(FEC_VTO_RECIBO, 'MM-YYYY') AS FEC_VTO_RECIBO,
					ROUND(POL_FIS, 2) AS POL_FIS,
					ROUND(PRIMA_NETA, 2) AS PRIMA_NETA,
					ROUND(COEF_CORR_POLIZA, 2) AS COEF_CORR_POLIZA,
					IFNULL(ROUND(COEF_CORR_PRIMA*100, 2), 0) AS COEF_CORR_PRIMA,
					ROUND(CORR_TIPO_AGEN, 2) AS CORR_TIPO_AGEN,
					ROUND(CORR_CAPTACION, 2) AS CORR_CAPTACION,
					ROUND(PRIMA_CORREGIDA, 2) AS PRIMA_CORREGIDA,
					IFNULL(ROUND(PORC_DIFE*100, 2), 0) AS PORC_DIFE,
					IFNULL(ROUND(IMPORTE_DIF, 2), 0) AS IMPORTE_DIF,
					IFNULL(ROUND(POLIZA_CORREGIDA, 2), 0) AS POLIZA_CORREGIDA,
					ROUND(ASEG, 2) AS ASEG,
					SUPERRAPPEL,
					FEC_ACTUALIZACION,
					DIFERENCIAS,
					PERIODSEQ,
					POSITIONSEQ_PRIN AS POSITIONSEQ,
					--BRG 20251127 campo para agrupar en RRTT por Producto Principal 2X0ZZ
					MIN(PRODUCTO) OVER (PARTITION BY PERIODO, EMPRESA, INFORME_EA, POLIZA, TIPO_RECIBO, FEC_CARGO, AGENTE_TABLA, TIPO_AGENTE_TABLA, FEC_VTO_RECIBO, NIF_NOMBRE) AS PROD_PRIN,
					--BRG 20251120 campo auxiliar para evitar diferenciar por SALESTRANSACTIONSEQ en la agrupación de RRTT
					MIN(SALESTRANSACTIONSEQ) OVER (PARTITION BY PERIODO, EMPRESA, INFORME_EA, POLIZA, TIPO_RECIBO, FEC_CARGO, AGENTE_TABLA, TIPO_AGENTE_TABLA, FEC_VTO_RECIBO, NIF_NOMBRE) AS SALESTRANSACTIONSEQ_PRIN
				FROM
				(
					SELECT
						EMPRESA, INFORME_EA,
						PERIODO, SALESTRANSACTIONSEQ, REGIONAL, SUCURSAL, OFICINA, AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, PRODUCTO, TIPO_RECIBO, POLIZA, POLIZ_NP, AGENTE_TABLA, TIPO_AGENTE_TABLA,
						FEC_CARGO, FEC_VTO_RECIBO, MAX(POL_FIS) AS POL_FIS, PRIMA_NETA, COEF_CORR_POLIZA, COEF_CORR_PRIMA, CORR_TIPO_AGEN, CORR_CAPTACION,
						PRIMA_CORREGIDA, MAX(PORC_DIFE) AS PORC_DIFE, IMPORTE_DIF, POLIZA_CORREGIDA, ASEG, SUPERRAPPEL, FEC_ACTUALIZACION, DIFERENCIAS,
						PERIODSEQ, POSITIONSEQ_PRIN
					FROM (
						-- S5_POLIZAS OCASO
						SELECT DISTINCT --LLS 20251112: Añadido el distinct
							'OCASO' AS EMPRESA,
							'CIERRE' AS INFORME_EA,
							J.PERIODO AS PERIODO,
							S5_POLIZAS.SALESTRANSACTIONSEQ,
							J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
							J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
							J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
							IFNULL(' ' || S5_POLIZAS.CUADRO_INSP,'')
								|| ' - ' || S5_POLIZAS.NOMBRE AS AGENTE,
							S5_POLIZAS.NIF AS NIF,
							S5_POLIZAS.NIF || ' - ' || S5_POLIZAS.NOMBRE || ' - ' || S5_POLIZAS.POS_PRIN AS NIF_NOMBRE,
							S5_POLIZAS.TIPO_AGENTE AS TIPO_AGENTE,
							RIGHT(S5_POLIZAS.PRODUCTID,5) || ' - ' || S5_POLIZAS.PRODUCTO AS PRODUCTO,
							S5_POLIZAS.EVENTO AS TIPO_RECIBO,
							S5_POLIZAS.POLIZA AS POLIZA,
							S5_POLIZAS.POLIZ_NP AS POLIZ_NP,
							S5_POLIZAS.POSITIONNAME_AG || '-' || S5_POLIZAS.CUADRO_RRGG_AG AS AGENTE_TABLA,
							S5_POLIZAS.ID_TIPO_AGENTE_AG AS TIPO_AGENTE_TABLA,
							S5_POLIZAS.FEC_CARGO AS FEC_CARGO,
							S5_POLIZAS.FEC_VTO_REC AS FEC_VTO_RECIBO,
							S5_POLIZAS.POLIZ_NP AS POL_FIS,
							S5_POLIZAS.PRIMA_NETA AS PRIMA_NETA,
							IFNULL(S5_POLIZAS.POLIZ_CORR_AG, 0) AS COEF_CORR_POLIZA,
							S5_POLIZAS.COEF_CORR AS COEF_CORR_PRIMA,
							CASE 
								WHEN J.STARTDATE < TO_DATE('20230101')
									THEN NULL
								ELSE IFNULL(S5_POLIZAS.CORR_TIPO_AGENTE, 0)
								END AS CORR_TIPO_AGEN,
							CASE
								WHEN J.STARTDATE < TO_DATE('20230101')
									THEN NULL
								ELSE IFNULL(1 - S5_POLIZAS.CORR_CAPTACION, 0) 
								END AS CORR_CAPTACION,
							IFNULL(S5_POLIZAS.VALUE, 0) AS PRIMA_CORREGIDA,
							S5_POLIZAS.PORC_DIFERENCIAL AS PORC_DIFE,
							S5_POLIZAS.IMP_DIFERENCIAL AS IMPORTE_DIF,
							S5_POLIZAS.POLIZ_CORR AS POLIZA_CORREGIDA,
							IFNULL(TO_INTEGER(S5_POLIZAS.ASEGURADOS), 0) AS ASEG,
							CASE
								WHEN J.SUPERRAPEL = 1
									THEN 'SI'
								ELSE 'NO'
							END AS SUPERRAPPEL,
							TO_VARCHAR(CASE WHEN F.ULTIMA_ACTUALIZACION > LAST_DAY(J.STARTDATE)
								THEN LAST_DAY(J.STARTDATE)
								ELSE F.ULTIMA_ACTUALIZACION
								END,'DD/MM/YYYY') AS FEC_ACTUALIZACION,
							NULL AS DIFERENCIAS,
							S5_POLIZAS.PERIODSEQ,
							S5_POLIZAS.POSITIONSEQ_PRIN
						FROM EXT.OUT_S5_POLIZAS_REP S5_POLIZAS
						INNER JOIN EXT.OUT_JERARQUIA_REP J ON S5_POLIZAS.PERIODSEQ = J.PERIODSEQ
							AND S5_POLIZAS.PARTICIPANTSEQ = J.PARTICIPANTSEQ
							AND S5_POLIZAS.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
						LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
							AND F.TABLA = 'OUT_S5_POLIZAS_REP'
						WHERE
							S5_POLIZAS.NAME NOT LIKE 'DD-O-COLC-Inspector-Pago-00%'
							AND S5_POLIZAS.ID_TIPO_AGENTE <> 79
							AND S5_POLIZAS.POS_PRIN = S5_POLIZAS.POSITIONNAME --20251124 LLS: Añadido para quitar posiciones secundarias

						UNION ALL

						-- BALANCES - S5 POLIZAS OCASO
						SELECT DISTINCT --LLS 20251112: Añadido el distinct
							'OCASO' AS EMPRESA,
							'BALANCES' AS INFORME_EA,
							J.PERIODO,
							S5_POLIZAS.SALESTRANSACTIONSEQ,
							J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
							J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
							J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
							IFNULL(' ' || S5_POLIZAS.CUADRO_INSP,'')
								|| ' - ' || S5_POLIZAS.NOMBRE AS AGENTE,
							S5_POLIZAS.NIF AS NIF,
							S5_POLIZAS.NIF || ' - ' || S5_POLIZAS.NOMBRE || ' - ' || S5_POLIZAS.POS_PRIN AS NIF_NOMBRE,
							S5_POLIZAS.TIPO_AGENTE AS TIPO_AGENTE,
							RIGHT(S5_POLIZAS.PRODUCTID,5) || ' - ' || S5_POLIZAS.PRODUCTO AS PRODUCTO,
							S5_POLIZAS.EVENTO AS TIPO_RECIBO,
							S5_POLIZAS.POLIZA AS POLIZA,
							S5_POLIZAS.POLIZ_NP AS POLIZ_NP,
							S5_POLIZAS.POSITIONNAME_AG || '-' || S5_POLIZAS.CUADRO_RRGG_AG AS AGENTE_TABLA,
							S5_POLIZAS.ID_TIPO_AGENTE_AG AS TIPO_AGENTE_TABLA,
							S5_POLIZAS.FEC_CARGO AS FEC_CARGO,
							S5_POLIZAS.FEC_VTO_REC AS FEC_VTO_RECIBO,
							S5_POLIZAS.POLIZ_NP AS POL_FIS,
							S5_POLIZAS.PRIMA_NETA AS PRIMA_NETA,
							IFNULL(S5_POLIZAS.POLIZ_CORR_AG, 0) AS COEF_CORR_POLIZA,
							S5_POLIZAS.COEF_CORR AS COEF_CORR_PRIMA,
							CASE 
								WHEN J.STARTDATE < TO_DATE('20200101')
									THEN NULL
								ELSE IFNULL(S5_POLIZAS.CORR_TIPO_AGENTE, 0)
								END AS CORR_TIPO_AGEN,
							CASE
								WHEN J.STARTDATE < TO_DATE('20200101')
									THEN NULL
								ELSE IFNULL(1 - S5_POLIZAS.CORR_CAPTACION, 0) 
								END AS CORR_CAPTACION,
							IFNULL(S5_POLIZAS.VALUE, 0) AS PRIMA_CORREGIDA,
							S5_POLIZAS.PORC_DIFERENCIAL AS PORC_DIFE,
							S5_POLIZAS.IMP_DIFERENCIAL AS IMPORTE_DIF,
							S5_POLIZAS.POLIZ_CORR AS POLIZA_CORREGIDA,
							IFNULL(TO_INTEGER(S5_POLIZAS.ASEGURADOS), 0) AS ASEG,
							CASE
								WHEN J.SUPERRAPEL = 1
									THEN 'SI'
								ELSE 'NO'
							END AS SUPERRAPPEL,
							TO_VARCHAR(F.ULTIMA_ACTUALIZACION,'DD/MM/YYYY') AS FEC_ACTUALIZACION,
							CASE
								WHEN B.BALANCESEQ IS NOT NULL
									THEN 'SI'
								ELSE NULL
							END AS DIFERENCIAS,
							S5_POLIZAS.PERIODSEQ,
							S5_POLIZAS.POSITIONSEQ_PRIN
						FROM EXT.OUT_BAL_S5_POLIZAS_REP S5_POLIZAS
						INNER JOIN EXT.OUT_JERARQUIA_REP J ON S5_POLIZAS.PERIODSEQ = J.PERIODSEQ
							AND S5_POLIZAS.PARTICIPANTSEQ = J.PARTICIPANTSEQ
							AND S5_POLIZAS.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
						LEFT JOIN TCMP.CS_BALANCE B ON B.PERIODSEQ = S5_POLIZAS.PERIODSEQ
							AND B.PAYEESEQ = S5_POLIZAS.PARTICIPANTSEQ
							AND B.POSITIONSEQ = S5_POLIZAS.POSITIONSEQ_PRIN
						LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
							AND F.TABLA = 'OUT_BAL_S5_POLIZAS_REP'
						WHERE
							S5_POLIZAS.NAME NOT LIKE 'DD-O-COLC-Inspector-Pago-00%'
							AND S5_POLIZAS.ID_TIPO_AGENTE <> 79
							AND S5_POLIZAS.POS_PRIN = S5_POLIZAS.POSITIONNAME --20251124 LLS: Añadido para quitar posiciones secundarias

						UNION ALL

						-- LC - S5 POLIZAS OCASO
						SELECT DISTINCT --LLS 20251112: Añadido el distinct
							'OCASO' AS EMPRESA,
							'LIQUIDACIÓN COMPLEMENTARIA' AS INFORME_EA,
							J.PERIODO,
							S5_POLIZAS.SALESTRANSACTIONSEQ,
							J.COD_REGIONAL || ' - ' || J.REGIONAL AS REGIONAL,
							J.COD_SUCURSAL || ' - ' || J.SUCURSAL AS SUCURSAL,
							J.COD_OFICINA || ' - ' || J.OFICINA AS OFICINA,
							IFNULL(' ' || S5_POLIZAS.CUADRO_INSP,'')
								|| ' - ' || S5_POLIZAS.NOMBRE AS AGENTE,
							S5_POLIZAS.NIF AS NIF,
							S5_POLIZAS.NIF || ' - ' || S5_POLIZAS.NOMBRE || ' - ' || S5_POLIZAS.POS_PRIN AS NIF_NOMBRE,
							S5_POLIZAS.TIPO_AGENTE AS TIPO_AGENTE,
							RIGHT(S5_POLIZAS.PRODUCTID,5) || ' - ' || S5_POLIZAS.PRODUCTO AS PRODUCTO,
							S5_POLIZAS.EVENTO AS TIPO_RECIBO,
							S5_POLIZAS.POLIZA AS POLIZA,
							S5_POLIZAS.POLIZ_NP AS POLIZ_NP,
							S5_POLIZAS.POSITIONNAME_AG || '-' || S5_POLIZAS.CUADRO_RRGG_AG AS AGENTE_TABLA,
							S5_POLIZAS.ID_TIPO_AGENTE_AG AS TIPO_AGENTE_TABLA,
							S5_POLIZAS.FEC_CARGO AS FEC_CARGO,
							S5_POLIZAS.FEC_VTO_REC AS FEC_VTO_RECIBO,
							S5_POLIZAS.POLIZ_NP AS POL_FIS,
							S5_POLIZAS.PRIMA_NETA AS PRIMA_NETA,
							IFNULL(S5_POLIZAS.POLIZ_CORR_AG, 0) AS COEF_CORR_POLIZA,
							S5_POLIZAS.COEF_CORR AS COEF_CORR_PRIMA,
							CASE 
								WHEN J.STARTDATE < TO_DATE('20200101')
									THEN NULL
								ELSE IFNULL(S5_POLIZAS.CORR_TIPO_AGENTE, 0)
								END AS CORR_TIPO_AGEN,
							CASE
								WHEN J.STARTDATE < TO_DATE('20200101')
									THEN NULL
								ELSE IFNULL(1 - S5_POLIZAS.CORR_CAPTACION, 0) 
								END AS CORR_CAPTACION,
							IFNULL(S5_POLIZAS.VALUE, 0) AS PRIMA_CORREGIDA,
							S5_POLIZAS.PORC_DIFERENCIAL AS PORC_DIFE,
							S5_POLIZAS.IMP_DIFERENCIAL AS IMPORTE_DIF,
							S5_POLIZAS.POLIZ_CORR AS POLIZA_CORREGIDA,
							IFNULL(TO_INTEGER(S5_POLIZAS.ASEGURADOS), 0) AS ASEG,
							CASE
								WHEN J.SUPERRAPEL = 1
									THEN 'SI'
								ELSE 'NO'
							END AS SUPERRAPPEL,
							TO_VARCHAR(CASE WHEN F.ULTIMA_ACTUALIZACION > LAST_DAY(J.STARTDATE)
								THEN LAST_DAY(J.STARTDATE)
								ELSE F.ULTIMA_ACTUALIZACION
								END,'DD/MM/YYYY') AS FEC_ACTUALIZACION,
							CASE
								WHEN (PAY.POSTPIPELINERUNDATE IS NULL OR PAY.POSTPIPELINERUNDATE > LAST_DAY(J.STARTDATE)) 
								AND PAY.PERIODSEQ = S5_POLIZAS.PERIODSEQ
									THEN 'SI'
								ELSE NULL
							END AS DIFERENCIAS,
							S5_POLIZAS.PERIODSEQ,
							S5_POLIZAS.POSITIONSEQ_PRIN
						FROM EXT.OUT_LC_S5_POLIZAS_REP S5_POLIZAS
						INNER JOIN EXT.OUT_JERARQUIA_REP J ON S5_POLIZAS.PERIODSEQ = J.PERIODSEQ
							AND S5_POLIZAS.PARTICIPANTSEQ = J.PARTICIPANTSEQ
							AND S5_POLIZAS.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
						LEFT JOIN TCMP.CS_PAYMENT PAY ON PAY.PERIODSEQ = S5_POLIZAS.PERIODSEQ
							AND PAY.PAYEESEQ = S5_POLIZAS.PARTICIPANTSEQ
							AND PAY.POSITIONSEQ = S5_POLIZAS.POSITIONSEQ_PRIN
						LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
							AND F.TABLA = 'OUT_LC_S5_POLIZAS_REP'
						WHERE
							S5_POLIZAS.NAME NOT LIKE 'DD-O-COLC-Inspector-Pago-00%'
							AND S5_POLIZAS.ID_TIPO_AGENTE <> 79
							AND S5_POLIZAS.POS_PRIN = S5_POLIZAS.POSITIONNAME --20251124 LLS: Añadido para quitar posiciones secundarias
					)
					GROUP BY
						EMPRESA, INFORME_EA, 
						PERIODO, SALESTRANSACTIONSEQ, REGIONAL, SUCURSAL, OFICINA, AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, PRODUCTO, TIPO_RECIBO, POLIZA, POLIZ_NP,
						AGENTE_TABLA, TIPO_AGENTE_TABLA, FEC_CARGO, FEC_VTO_RECIBO, PRIMA_NETA, COEF_CORR_POLIZA, COEF_CORR_PRIMA, CORR_TIPO_AGEN, 
						CORR_CAPTACION, PRIMA_CORREGIDA, IMPORTE_DIF, POLIZA_CORREGIDA, ASEG, SUPERRAPPEL, FEC_ACTUALIZACION, DIFERENCIAS,
						PERIODSEQ, POSITIONSEQ_PRIN
				)
				WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := RECORD_COUNT(:TBL_S5_POL_FINAL);
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'TBL_S5_POL_FINAL. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			-- BRG 20251127 Dividimos el INSERT en la final en 2 partes, RRTT agrupado y el resto de ramos sin agrupar
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S5_POLIZAS_FINAL_REP RRTT agrupado.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S5_POLIZAS_FINAL_REP (EMPRESA,INFORME_EA,PERIODO,SALESTRANSACTIONSEQ,REGIONAL,SUCURSAL,OFICINA,AGENTE,NIF,NIF_NOMBRE,TIPO_AGENTE,PRODUCTO,TIPO_RECIBO,POLIZA,POLIZ_NP,AGENTE_TABLA,TIPO_AGENTE_TABLA,FEC_CARGO,FEC_VTO_RECIBO,POL_FIS,PRIMA_NETA,COEF_CORR_POLIZA,COEF_CORR_PRIMA,CORR_TIPO_AGEN,CORR_CAPTACION,PRIMA_CORREGIDA,PORC_DIFE,IMPORTE_DIF,POLIZA_CORREGIDA,ASEG,SUPERRAPPEL,FEC_ACTUALIZACION,DIFERENCIAS,PERIODSEQ,POSITIONSEQ)
				SELECT
					EMPRESA, INFORME_EA, PERIODO,
                    SALESTRANSACTIONSEQ_PRIN, --BRG 20251127 En vez de SALESTRANSACTIONSEQ
                    REGIONAL, SUCURSAL, OFICINA, AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE,
					--BRG 20260423 Transformamos para que los productos se vean bien cuando falta el principal
                    LEFT(PROD_PRIN, 2) || '0' || RIGHT(PROD_PRIN, LENGTH(PROD_PRIN)-3) AS PROD_PRIN, --BRG 20251127 En vez de PRODUCTO
                    TIPO_RECIBO, POLIZA,
                    SUM(POLIZ_NP),
                    AGENTE_TABLA, TIPO_AGENTE_TABLA, FEC_CARGO, FEC_VTO_RECIBO,
                    SUM(POL_FIS), SUM(PRIMA_NETA), MAX(COEF_CORR_POLIZA), MAX(COEF_CORR_PRIMA), MAX(CORR_TIPO_AGEN), 
                    MAX(CORR_CAPTACION), SUM(PRIMA_CORREGIDA), MAX(PORC_DIFE), SUM(IMPORTE_DIF), SUM(POLIZA_CORREGIDA), SUM(ASEG),
                    SUPERRAPPEL, FEC_ACTUALIZACION, DIFERENCIAS, PERIODSEQ, POSITIONSEQ
				FROM :TBL_S5_POL_FINAL
				WHERE PRODUCTO LIKE '2%'
				GROUP BY
					EMPRESA, INFORME_EA, PERIODO,
                    SALESTRANSACTIONSEQ_PRIN, --BRG 20251127 En vez de SALESTRANSACTIONSEQ
                    REGIONAL, SUCURSAL, OFICINA, AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE,
                    PROD_PRIN, --BRG 20251127 En vez de PRODUCTO
                    TIPO_RECIBO, POLIZA,
                    AGENTE_TABLA, TIPO_AGENTE_TABLA, FEC_CARGO, FEC_VTO_RECIBO,
                    SUPERRAPPEL, FEC_ACTUALIZACION, DIFERENCIAS, PERIODSEQ, POSITIONSEQ;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S5_POLIZAS_FINAL_REP RRTT agrupado. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

            -- BRG 20251127 Segundo insert
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S5_POLIZAS_FINAL_REP Resto Ramos.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S5_POLIZAS_FINAL_REP (EMPRESA,INFORME_EA,PERIODO,SALESTRANSACTIONSEQ,REGIONAL,SUCURSAL,OFICINA,AGENTE,NIF,NIF_NOMBRE,TIPO_AGENTE,PRODUCTO,TIPO_RECIBO,POLIZA,POLIZ_NP,AGENTE_TABLA,TIPO_AGENTE_TABLA,FEC_CARGO,FEC_VTO_RECIBO,POL_FIS,PRIMA_NETA,COEF_CORR_POLIZA,COEF_CORR_PRIMA,CORR_TIPO_AGEN,CORR_CAPTACION,PRIMA_CORREGIDA,PORC_DIFE,IMPORTE_DIF,POLIZA_CORREGIDA,ASEG,SUPERRAPPEL,FEC_ACTUALIZACION,DIFERENCIAS,PERIODSEQ,POSITIONSEQ)
				SELECT
					EMPRESA, INFORME_EA, PERIODO,
                    SALESTRANSACTIONSEQ,
                    REGIONAL, SUCURSAL, OFICINA, AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE,
                    PRODUCTO,
                    TIPO_RECIBO, POLIZA,
                    POLIZ_NP,
                    AGENTE_TABLA, TIPO_AGENTE_TABLA, FEC_CARGO, FEC_VTO_RECIBO,
                    POL_FIS, PRIMA_NETA, COEF_CORR_POLIZA, COEF_CORR_PRIMA, CORR_TIPO_AGEN, 
                    CORR_CAPTACION, PRIMA_CORREGIDA, PORC_DIFE, IMPORTE_DIF, POLIZA_CORREGIDA, ASEG,
                    SUPERRAPPEL, FEC_ACTUALIZACION, DIFERENCIAS, PERIODSEQ, POSITIONSEQ
				FROM :TBL_S5_POL_FINAL
				WHERE PRODUCTO NOT LIKE '2%';
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S5_POLIZAS_FINAL_REP Resto Ramos. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Insert de --SELECCIONAR-- en OUT_S5_POLIZAS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S5_POLIZAS_FINAL_REP (EMPRESA,INFORME_EA,PERIODO,SALESTRANSACTIONSEQ,REGIONAL,SUCURSAL,OFICINA,AGENTE,NIF,NIF_NOMBRE,TIPO_AGENTE,PRODUCTO,TIPO_RECIBO,POLIZA,POLIZ_NP,AGENTE_TABLA,TIPO_AGENTE_TABLA,FEC_CARGO,FEC_VTO_RECIBO,POL_FIS,PRIMA_NETA,COEF_CORR_POLIZA,COEF_CORR_PRIMA,CORR_TIPO_AGEN,CORR_CAPTACION,PRIMA_CORREGIDA,PORC_DIFE,IMPORTE_DIF,POLIZA_CORREGIDA,ASEG,SUPERRAPPEL,FEC_ACTUALIZACION,DIFERENCIAS,PERIODSEQ,POSITIONSEQ)
				SELECT DISTINCT
					EMPRESA,
					INFORME_EA,
					PERIODO,
					NULL, -- SALESTRANSACTIONSEQ
					' ', -- REGIONAL
					' ', -- SUCURSAL
					' ', -- OFICINA
					' ', -- AGENTE
					' ', -- NIF
					'--SELECCIONAR--', -- NIF_NOMBRE
					' ', -- TIPO_AGENTE
					' ', -- PRODUCTO
					' ', -- TIPO_RECIBO
					' ', -- POLIZA
					NULL, -- POLIZ_NP
					' ', -- AGENTE_TABLA
					' ', -- TIPO_AGENTE_TABLA
					' ', -- FEC_CARGO
					' ', -- FEC_VTO_RECIBO
					NULL, -- POL_FIS
					NULL, -- PRIMA_NETA
					NULL, -- COEF_CORR_POLIZA
					NULL, -- COEF_CORR_PRIMA
					NULL, -- CORR_TIPO_AGEN
					NULL, -- CORR_CAPTACION
					NULL, -- PRIMA_CORREGIDA
					NULL, -- PORC_DIFE
					NULL, -- IMPORTE_DIF
					NULL, -- POLIZA_CORREGIDA
					NULL, -- ASEG
					' ', -- SUPERRAPPEL
					FEC_ACTUALIZACION,
					DIFERENCIAS, -- DIFERENCIAS VARCHAR(2),
					PERIODSEQ,
					-1 -- POSITIONSEQ
				FROM EXT.OUT_S5_POLIZAS_FINAL_REP
				WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Insert de --SELECCIONAR-- en OUT_S5_POLIZAS_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe S5 Detalle Pólizas', i_log_count, i_id_proceso, 'info');

		-- Fin informe S5 Detalle Pólizas
		END IF;
		
		---------------------------------------------------------------------------------------------------------------------------------------
		-- BRG 20250528: TABLAS PARA INFORMES S4 y S5 Factura
		IF :i_lista_informes = 'FAC_S4' OR :i_lista_informes LIKE '%|FAC_S4|%' OR :i_lista_informes LIKE '%|FAC_S4' OR :i_lista_informes LIKE 'FAC_S4|%' 
            OR :i_lista_informes = 'FAC_S5' OR :i_lista_informes LIKE '%|FAC_S5|%' OR :i_lista_informes LIKE '%|FAC_S5' OR :i_lista_informes LIKE 'FAC_S5|%'
            OR :i_lista_informes = 'FAC_S4_E' OR :i_lista_informes LIKE '%|FAC_S4_E|%' OR :i_lista_informes LIKE '%|FAC_S4_E' OR :i_lista_informes LIKE 'FAC_S4_E|%'
            OR :i_lista_informes = 'ALL' THEN
            
		
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informes S4 Factura', i_log_count, i_id_proceso, 'info');
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informes S5 Factura', i_log_count, i_id_proceso, 'info');

			-- BRG 20250527: Nueva tabla OUT_S4_FACTURA_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_FACTURA_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S4_FACTURA_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_FACTURA_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S4_FACTURA_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S4_FACTURA_FINAL_REP (COMPANYA,COMPANIA,TIPO_PAGO,PERIODSEQ,PERIODO,ANYO,MES_NUM,MES,TIPO_INFORME,SECUENCIAL,POSITIONSEQ_PRIN,POSITIONSEQ,PARTICIPANTSEQ,COD_REGIONAL,POS_PRIN,COMISION,IMPORTE,COD_OFICINA,OFICINA,OFICINA_CONCAT,NOMBRE,CUADRO_RRGG,CUADRO_RRTT,AGENTE,DOMICILIO,MUNICIPIO,CP,IRPF_NUM,IRPF,NIF,N_FACTURA,IMP_TOTAL,IMP_CORRECCION,VALOR_IRPF,NETO,NETO_A_PERCIBIR,ULTIMA_ACTUALIZACION,ULTIMA_ACTUALIZACION_YM,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO,FECHA_EMISION,FILTRO)
				SELECT DISTINCT --BRG 20251219 Añadido 
                    COMPANYA, 
					COMPANIA, 
					TIPO_PAGO, 
					PERIODSEQ, 
					:v_period_name_format AS PERIODO, 
					ANYO, 
					MES_NUM, 
					MES, 
					TIPO_INFORME, 
					SECUENCIAL, 
					POSITIONSEQ_PRIN, 
					POSITIONSEQ_PRIN AS POSITIONSEQ, 
					PARTICIPANTSEQ, 
					COD_REGIONAL, 
					POS_PRIN, 
					COMISION, 
					ROUND(IMPORTE, 2) IMPORTE, 
					COD_OFICINA, 
					OFICINA, 
					OFICINA_CONCAT, 
					NOMBRE, 
					CUADRO_RRGG, 
					CUADRO_RRTT, 
					AGENTE, 
					CASE WHEN COMPANYA = 'OCASO' AND NUMERO IS NOT NULL AND RESTO_DOMICILIO IS NOT NULL
							THEN DOMICILIO||', '||NUMERO||', '||RESTO_DOMICILIO 
						WHEN COMPANYA = 'OCASO' AND NUMERO IS NOT NULL AND RESTO_DOMICILIO IS NULL
							THEN DOMICILIO||', '||NUMERO
						WHEN COMPANYA = 'OCASO' AND NUMERO IS NULL AND RESTO_DOMICILIO IS NOT NULL
							THEN DOMICILIO||', '||RESTO_DOMICILIO 
						ELSE DOMICILIO END 
						AS DOMICILIO, 
					MUNICIPIO, 
					CP, 
					IRPF_NUM, 
					CASE 
                        WHEN IRPF = '0%'
                            THEN ' '
                        ELSE IRPF 
                        END AS IRPF,
					NIF, 
					N_FACTURA, 
					ROUND(IMP_TOTAL, 2) IMP_TOTAL, 
					ROUND(IMP_CORRECCION, 2) IMP_CORRECCION, 
					ROUND(VALOR_IRPF, 2) VALOR_IRPF, 
					ROUND(NETO, 2) NETO, 
					ROUND(NETO_A_PERCIBIR, 2) NETO_A_PERCIBIR, 
					ULTIMA_ACTUALIZACION, 
					ULTIMA_ACTUALIZACION_YM, 
					TO_DATE(FEC_ACTUALIZACION) FEC_ACTUALIZACION, 
					TO_VARCHAR(FEC_ACTUALIZACION, 'DD/MM/YYYY') FEC_ACTUALIZACION_FORMATO, 
					CASE WHEN DAYOFMONTH(FEC_ACTUALIZACION) < 10
							THEN '0'|| DAYOFMONTH(FEC_ACTUALIZACION)
								ELSE TO_VARCHAR(DAYOFMONTH(FEC_ACTUALIZACION))
							END 
						|| ' DE '
						|| CASE WHEN MONTH(FEC_ACTUALIZACION) = 1 THEN 'ENERO'
								WHEN MONTH(FEC_ACTUALIZACION) = 2 THEN 'FEBRERO'
								WHEN MONTH(FEC_ACTUALIZACION) = 3 THEN 'MARZO'
								WHEN MONTH(FEC_ACTUALIZACION) = 4 THEN 'ABRIL'
								WHEN MONTH(FEC_ACTUALIZACION) = 5 THEN 'MAYO'
								WHEN MONTH(FEC_ACTUALIZACION) = 6 THEN 'JUNIO'
								WHEN MONTH(FEC_ACTUALIZACION) = 7 THEN 'JULIO'
								WHEN MONTH(FEC_ACTUALIZACION) = 8 THEN 'AGOSTO'
								WHEN MONTH(FEC_ACTUALIZACION) = 9 THEN 'SEPTIEMBRE'
								WHEN MONTH(FEC_ACTUALIZACION) = 10 THEN 'OCTUBRE'
								WHEN MONTH(FEC_ACTUALIZACION) = 11 THEN 'NOVIEMBRE'
								WHEN MONTH(FEC_ACTUALIZACION) = 12 THEN 'DICIEMBRE'
								END
						|| ' DE '
						|| YEAR(FEC_ACTUALIZACION)
						FECHA_EMISION,
					NIF || ' - ' || NOMBRE FILTRO
					
				FROM 
				(	--OCASO CIERRE
					SELECT DISTINCT 'OCASO' COMPANYA, 
						S4_FAC.COMPANIA, 
						'CIERRE' TIPO_PAGO, 
						S4_FAC.PERIODSEQ, 
						S4_FAC.PERIODO, 
						J.YEAR ANYO , 
						EXTRACT(MONTH FROM J.STARTDATE) MES_NUM, 
						UPPER(LEFT(S4_FAC.PERIODO, LENGTH(S4_FAC.PERIODO)-5)) MES, 
						S4_FAC.TIPO_INFORME, 
						S4_FAC.SECUENCIAL, 
						S4_FAC.POSITIONSEQ_PRIN, 
						S4_FAC.PARTICIPANTSEQ, 
						J.COD_REGIONAL, 
						S4_FAC.POS_PRIN, 
						S4_FAC.COMISION, 
						S4_FAC.IMPORTE, 
						S4_FAC.COD_OFICINA, 
						S4_FAC.OFICINA, 
						S4_FAC.COD_OFICINA || ' - ' || S4_FAC.OFICINA OFICINA_CONCAT, 
						S4_FAC.NOMBRE, 
						S4_FAC.CUADRO_RRGG, 
						S4_FAC.CUADRO_RRTT, 
						RIGHT(S4_FAC.POS_PRIN, 4) || ' - ' || IFNULL(S4_FAC.CUADRO_RRGG,'') || ' - ' || IFNULL(S4_FAC.CUADRO_RRTT, '') || ' - ' || S4_FAC.NOMBRE AGENTE, 
						S4_FAC.DOMICILIO, 
						S4_FAC.NUMERO, 
						S4_FAC.RESTO_DOMICILIO, 
						S4_FAC.MUNICIPIO, 
						S4_FAC.CP, 
						S4_FAC.IRPF IRPF_NUM, 
						TO_VARCHAR(TO_DECIMAL(ROUND(S4_FAC.IRPF*100,0),25,0))||'%' IRPF, 
						S4_FAC.NIF, 
						RIGHT(S4_FAC.COMPANIA, 1) 
							|| RIGHT(S4_FAC.TIPO_INFORME, 1)
							|| RIGHT(J.YEAR,2) 
							|| LPAD(MONTH(J.STARTDATE), 2, '0')
							|| IFNULL(RIGHT(S4_FAC.COD_OFICINA,3), '')
							|| RIGHT(S4_FAC.POS_PRIN,4) 
							|| '/'
							|| LPAD(S4_FAC.SECUENCIAL, 2, '0')
							N_FACTURA, 
						CASE WHEN S4_FAC.COMISION = 'Corrección' OR S4_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE S4_FAC.IMPORTE
							END IMP_TOTAL,
						CASE WHEN S4_FAC.COMISION = 'Corrección' OR S4_FAC.COMISION = 'Correccion' 
								THEN S4_FAC.IMPORTE
								ELSE 0
							END IMP_CORRECCION,
						CASE WHEN S4_FAC.COMISION = 'Corrección' OR S4_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE ROUND(S4_FAC.IMPORTE * S4_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END VALOR_IRPF,
						CASE WHEN S4_FAC.COMISION = 'Corrección' OR S4_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE S4_FAC.IMPORTE - ROUND(S4_FAC.IMPORTE * S4_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO,
						CASE WHEN S4_FAC.COMISION = 'Corrección' OR S4_FAC.COMISION = 'Correccion' 
								THEN S4_FAC.IMPORTE
								ELSE S4_FAC.IMPORTE - ROUND(S4_FAC.IMPORTE * S4_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO_A_PERCIBIR,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S4_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN F1.ULTIMA_ACTUALIZACION
							ELSE F2.ULTIMA_ACTUALIZACION
							END ULTIMA_ACTUALIZACION,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S4_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN YEAR(F1.ULTIMA_ACTUALIZACION)*100+MONTH(F1.ULTIMA_ACTUALIZACION)
							ELSE YEAR(F2.ULTIMA_ACTUALIZACION)*100+MONTH(F2.ULTIMA_ACTUALIZACION)
							END ULTIMA_ACTUALIZACION_YM,
						CASE WHEN (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S4_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) > ADD_MONTHS(J.STARTDATE, 1) 
								THEN LAST_DAY(J.STARTDATE)
								ELSE (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S4_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) 
							END FEC_ACTUALIZACION
					FROM EXT.OUT_JERARQUIA_REP J
					INNER JOIN EXT.OUT_S4_FACTURA_REP S4_FAC ON S4_FAC.PERIODSEQ = J.PERIODSEQ
						AND S4_FAC.PARTICIPANTSEQ = J.PARTICIPANTSEQ
						AND S4_FAC.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F1 ON F1.PERIODO = S4_FAC.PERIODO
						AND F1.TABLA = 'OUT_S4_FACTURA_REP'
                    --BRG 20251219 Añadido MAX para sacar la FECHA_FACTURA
					LEFT JOIN (SELECT DISTINCT PERIODSEQ, MAX(TO_DATE(PAG_FECHA_FACTURA,'YYYYMMDD')) ULTIMA_ACTUALIZACION
							FROM EXT.FINAL_EXTRACTPAGOS_FILE
							WHERE PAG_REFERENCIA_ORIGEN LIKE '14%'
                            GROUP BY PERIODSEQ) F2
						ON F2.PERIODSEQ = S4_FAC.PERIODSEQ
                    WHERE S4_FAC.PERIODSEQ = :i_PeriodSeq
					
					UNION ALL
					
					--OCASO LC
					SELECT DISTINCT 'OCASO' COMPANYA, 
						LC_S4_FAC.COMPANIA, 
						'LC' TIPO_PAGO, 
						LC_S4_FAC.PERIODSEQ, 
						LC_S4_FAC.PERIODO, 
						J.YEAR ANYO , 
						EXTRACT(MONTH FROM J.STARTDATE) MES_NUM, 
						UPPER(LEFT(LC_S4_FAC.PERIODO, LENGTH(LC_S4_FAC.PERIODO)-5)) MES, 
						LC_S4_FAC.TIPO_INFORME, 
						LC_S4_FAC.SECUENCIAL, 
						LC_S4_FAC.POSITIONSEQ_PRIN, 
						LC_S4_FAC.PARTICIPANTSEQ, 
						J.COD_REGIONAL, 
						LC_S4_FAC.POS_PRIN, 
						LC_S4_FAC.COMISION, 
						LC_S4_FAC.IMPORTE, 
						LC_S4_FAC.COD_OFICINA, 
						LC_S4_FAC.OFICINA, 
						LC_S4_FAC.COD_OFICINA || ' - ' || LC_S4_FAC.OFICINA OFICINA_CONCAT, 
						LC_S4_FAC.NOMBRE, 
						LC_S4_FAC.CUADRO_RRGG, 
						LC_S4_FAC.CUADRO_RRTT, 
						RIGHT(LC_S4_FAC.POS_PRIN, 4) || ' - ' || IFNULL(LC_S4_FAC.CUADRO_RRGG,'') || ' - ' || IFNULL(LC_S4_FAC.CUADRO_RRTT, '') || ' - ' || LC_S4_FAC.NOMBRE AGENTE, 
						LC_S4_FAC.DOMICILIO, 
						LC_S4_FAC.NUMERO, 
						LC_S4_FAC.RESTO_DOMICILIO, 
						LC_S4_FAC.MUNICIPIO, 
						LC_S4_FAC.CP, 
						LC_S4_FAC.IRPF IRPF_NUM, 
						TO_VARCHAR(TO_DECIMAL(ROUND(LC_S4_FAC.IRPF*100,0),25,0))||'%' IRPF, 
						LC_S4_FAC.NIF, 
						RIGHT(LC_S4_FAC.COMPANIA, 1) 
							|| '7'
							|| RIGHT(J.YEAR,2) 
							|| LPAD(MONTH(J.STARTDATE), 2, '0')
							|| IFNULL(RIGHT(LC_S4_FAC.COD_OFICINA,3), '')
							|| RIGHT(LC_S4_FAC.POS_PRIN,4) 
							|| '/'
							|| LPAD(LC_S4_FAC.SECUENCIAL, 2, '0')
							N_FACTURA,
						CASE WHEN LC_S4_FAC.COMISION = 'Corrección' OR LC_S4_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE LC_S4_FAC.IMPORTE
							END IMP_TOTAL,
						CASE WHEN LC_S4_FAC.COMISION = 'Corrección' OR LC_S4_FAC.COMISION = 'Correccion' 
								THEN LC_S4_FAC.IMPORTE
								ELSE 0
							END IMP_CORRECCION,
						CASE WHEN LC_S4_FAC.COMISION = 'Corrección' OR LC_S4_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE ROUND(LC_S4_FAC.IMPORTE * LC_S4_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END VALOR_IRPF,
						CASE WHEN LC_S4_FAC.COMISION = 'Corrección' OR LC_S4_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE LC_S4_FAC.IMPORTE - ROUND(LC_S4_FAC.IMPORTE * LC_S4_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO,
						CASE WHEN LC_S4_FAC.COMISION = 'Corrección' OR LC_S4_FAC.COMISION = 'Correccion' 
								THEN LC_S4_FAC.IMPORTE
								ELSE LC_S4_FAC.IMPORTE - ROUND(LC_S4_FAC.IMPORTE * LC_S4_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO_A_PERCIBIR,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = LC_S4_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN F1.ULTIMA_ACTUALIZACION
							ELSE F2.ULTIMA_ACTUALIZACION
							END ULTIMA_ACTUALIZACION,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = LC_S4_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN YEAR(F1.ULTIMA_ACTUALIZACION)*100+MONTH(F1.ULTIMA_ACTUALIZACION)
							ELSE YEAR(F2.ULTIMA_ACTUALIZACION)*100+MONTH(F2.ULTIMA_ACTUALIZACION)
							END ULTIMA_ACTUALIZACION_YM,
						CASE WHEN (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = LC_S4_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) > ADD_MONTHS(J.STARTDATE, 1) 
								THEN LAST_DAY(J.STARTDATE)
								ELSE (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = LC_S4_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) 
							END FEC_ACTUALIZACION
					FROM EXT.OUT_JERARQUIA_REP J
					INNER JOIN EXT.OUT_LC_S4_FACTURA_REP LC_S4_FAC ON LC_S4_FAC.PERIODSEQ = J.PERIODSEQ
						AND LC_S4_FAC.PARTICIPANTSEQ = J.PARTICIPANTSEQ
						AND LC_S4_FAC.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F1 ON F1.PERIODO = LC_S4_FAC.PERIODO
						AND F1.TABLA = 'OUT_LC_S4_FACTURA_REP'
                    --BRG 20251219 Añadido MAX para sacar la FECHA_FACTURA
					LEFT JOIN (SELECT DISTINCT PERIODSEQ, MAX(TO_DATE(PAG_FECHA_FACTURA,'YYYYMMDD')) ULTIMA_ACTUALIZACION
							FROM EXT.FINAL_EXTRACTPAGOS_FILE
							WHERE PAG_REFERENCIA_ORIGEN LIKE '17%'
                            GROUP BY PERIODSEQ) F2
						ON F2.PERIODSEQ = LC_S4_FAC.PERIODSEQ
                    WHERE LC_S4_FAC.PERIODSEQ = :i_PeriodSeq
					
					UNION ALL
					
					--ETERNA CIERRE
					SELECT DISTINCT 'ETERNA' COMPANYA, 
						S4_E_FAC.COMPANIA, 
						'CIERRE' TIPO_PAGO, 
						S4_E_FAC.PERIODSEQ, 
						S4_E_FAC.PERIODO, 
						J.YEAR ANYO , 
						EXTRACT(MONTH FROM J.STARTDATE) MES_NUM, 
						UPPER(LEFT(S4_E_FAC.PERIODO, LENGTH(S4_E_FAC.PERIODO)-5)) MES, 
						S4_E_FAC.TIPO_INFORME, 
						S4_E_FAC.SECUENCIAL, 
						S4_E_FAC.POSITIONSEQ_PRIN, 
						S4_E_FAC.PARTICIPANTSEQ, 
						J.COD_REGIONAL, 
						S4_E_FAC.POS_PRIN, 
						S4_E_FAC.COMISION, 
						S4_E_FAC.IMPORTE, 
						S4_E_FAC.COD_OFICINA, 
						S4_E_FAC.OFICINA, 
						S4_E_FAC.COD_OFICINA || ' - ' || S4_E_FAC.OFICINA OFICINA_CONCAT, 
						S4_E_FAC.NOMBRE, 
						S4_E_FAC.CUADRO_RRGG, 
						S4_E_FAC.CUADRO_RRTT, 
						RIGHT(S4_E_FAC.POS_PRIN, 4) || ' - ' || IFNULL(S4_E_FAC.CUADRO_RRGG,'') || ' - ' || IFNULL(S4_E_FAC.CUADRO_RRTT, '') || ' - ' || S4_E_FAC.NOMBRE AGENTE, 
						S4_E_FAC.DOMICILIO, 
						NULL AS NUMERO, 
						NULL AS RESTO_DOMICILIO, 
						S4_E_FAC.MUNICIPIO, 
						S4_E_FAC.CP, 
						S4_E_FAC.IRPF IRPF_NUM, 
						TO_VARCHAR(TO_DECIMAL(ROUND(S4_E_FAC.IRPF*100,0),25,0))||'%' IRPF, 
						S4_E_FAC.NIF, 
						S4_E_FAC.COMPANIA
							|| RIGHT(S4_E_FAC.TIPO_INFORME, 1) 
							|| RIGHT(J.YEAR,2) 
							|| LPAD(MONTH(J.STARTDATE), 2, '0')
							|| IFNULL(RIGHT(S4_E_FAC.COD_OFICINA,3), '')
							|| RIGHT(S4_E_FAC.POS_PRIN,4) 
							|| '/'
							|| LPAD(S4_E_FAC.SECUENCIAL, 2, '0')
							N_FACTURA,
						CASE WHEN S4_E_FAC.COMISION = 'Corrección' OR S4_E_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE S4_E_FAC.IMPORTE
							END IMP_TOTAL,
						CASE WHEN S4_E_FAC.COMISION = 'Corrección' OR S4_E_FAC.COMISION = 'Correccion' 
								THEN S4_E_FAC.IMPORTE
								ELSE 0
							END IMP_CORRECCION,
						CASE WHEN S4_E_FAC.COMISION = 'Corrección' OR S4_E_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE ROUND(S4_E_FAC.IMPORTE * S4_E_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END VALOR_IRPF,
						CASE WHEN S4_E_FAC.COMISION = 'Corrección' OR S4_E_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE S4_E_FAC.IMPORTE - ROUND(S4_E_FAC.IMPORTE * S4_E_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO,
						CASE WHEN S4_E_FAC.COMISION = 'Corrección' OR S4_E_FAC.COMISION = 'Correccion' 
								THEN S4_E_FAC.IMPORTE
								ELSE S4_E_FAC.IMPORTE - ROUND(S4_E_FAC.IMPORTE * S4_E_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO_A_PERCIBIR,
						cASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S4_E_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN F1.ULTIMA_ACTUALIZACION
							ELSE F2.ULTIMA_ACTUALIZACION
							END ULTIMA_ACTUALIZACION,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S4_E_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN YEAR(F1.ULTIMA_ACTUALIZACION)*100+MONTH(F1.ULTIMA_ACTUALIZACION)
							ELSE YEAR(F2.ULTIMA_ACTUALIZACION)*100+MONTH(F2.ULTIMA_ACTUALIZACION)
							END ULTIMA_ACTUALIZACION_YM,
						CASE WHEN (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S4_E_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) > ADD_MONTHS(J.STARTDATE, 1) 
								THEN LAST_DAY(J.STARTDATE)
								ELSE (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S4_E_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) 
							END FEC_ACTUALIZACION
					FROM EXT.OUT_JERARQUIA_REP J
					INNER JOIN EXT.OUT_S4_E_FACTURA_REP S4_E_FAC ON S4_E_FAC.PERIODSEQ = J.PERIODSEQ
						AND S4_E_FAC.PARTICIPANTSEQ = J.PARTICIPANTSEQ
						AND S4_E_FAC.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F1 ON F1.PERIODO = S4_E_FAC.PERIODO
						AND F1.TABLA = 'OUT_S4_E_FACTURA_REP'
                    --BRG 20251219 Añadido MAX para sacar la FECHA_FACTURA
					LEFT JOIN (SELECT DISTINCT PERIODSEQ, MAX(TO_DATE(PAG_FECHA_FACTURA,'YYYYMMDD')) ULTIMA_ACTUALIZACION
							FROM EXT.FINAL_EXTRACTPAGOS_FILE
							WHERE PAG_REFERENCIA_ORIGEN LIKE '34%'
                            GROUP BY PERIODSEQ) F2
						ON F2.PERIODSEQ = S4_E_FAC.PERIODSEQ
                    WHERE S4_E_FAC.PERIODSEQ = :i_PeriodSeq
					
					UNION ALL
					
					--ETERNA LC
					SELECT DISTINCT 'ETERNA' COMPANYA, 
						LC_S4_E_FAC.COMPANIA, 
						'LC' TIPO_PAGO, 
						LC_S4_E_FAC.PERIODSEQ, 
						LC_S4_E_FAC.PERIODO, 
						J.YEAR ANYO, 
						EXTRACT(MONTH FROM J.STARTDATE) MES_NUM, 
						UPPER(LEFT(LC_S4_E_FAC.PERIODO, LENGTH(LC_S4_E_FAC.PERIODO)-5)) MES, 
						LC_S4_E_FAC.TIPO_INFORME, 
						LC_S4_E_FAC.SECUENCIAL, 
						LC_S4_E_FAC.POSITIONSEQ_PRIN, 
						LC_S4_E_FAC.PARTICIPANTSEQ, 
						J.COD_REGIONAL, 
						LC_S4_E_FAC.POS_PRIN, 
						LC_S4_E_FAC.COMISION, 
						LC_S4_E_FAC.IMPORTE, 
						LC_S4_E_FAC.COD_OFICINA, 
						LC_S4_E_FAC.OFICINA, 
						LC_S4_E_FAC.COD_OFICINA || ' - ' || LC_S4_E_FAC.OFICINA OFICINA_CONCAT, 
						LC_S4_E_FAC.NOMBRE, 
						LC_S4_E_FAC.CUADRO_RRGG, 
						LC_S4_E_FAC.CUADRO_RRTT, 
						RIGHT(LC_S4_E_FAC.POS_PRIN, 4) || ' - ' || IFNULL(LC_S4_E_FAC.CUADRO_RRGG,'') || ' - ' || IFNULL(LC_S4_E_FAC.CUADRO_RRTT, '') || ' - ' || LC_S4_E_FAC.NOMBRE AGENTE, 
						LC_S4_E_FAC.DOMICILIO, 
						NULL AS NUMERO, 
						NULL AS RESTO_DOMICILIO, 
						LC_S4_E_FAC.MUNICIPIO, 
						LC_S4_E_FAC.CP, 
						LC_S4_E_FAC.IRPF IRPF_NUM, 
						TO_VARCHAR(TO_DECIMAL(ROUND(LC_S4_E_FAC.IRPF*100,0),25,0))||'%' IRPF, 
						LC_S4_E_FAC.NIF, 
						LC_S4_E_FAC.COMPANIA
                            || CASE WHEN RIGHT(LC_S4_E_FAC.TIPO_INFORME, 1)='4'
                                    THEN '7'
                                    ELSE '8'
                                END
                            || RIGHT(J.YEAR,2) 
                            || LPAD(MONTH(J.STARTDATE), 2, '0')
                            || IFNULL(RIGHT(LC_S4_E_FAC.COD_OFICINA,3), '') 
                            || RIGHT(LC_S4_E_FAC.POS_PRIN,4) 
                            || '/'
                            || LPAD(LC_S4_E_FAC.SECUENCIAL, 2, '0')
							N_FACTURA,
						CASE WHEN LC_S4_E_FAC.COMISION = 'Corrección' OR LC_S4_E_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE LC_S4_E_FAC.IMPORTE
							END IMP_TOTAL,
						CASE WHEN LC_S4_E_FAC.COMISION = 'Corrección' OR LC_S4_E_FAC.COMISION = 'Correccion' 
								THEN LC_S4_E_FAC.IMPORTE
								ELSE 0
							END IMP_CORRECCION,
						CASE WHEN LC_S4_E_FAC.COMISION = 'Corrección' OR LC_S4_E_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE ROUND(LC_S4_E_FAC.IMPORTE * LC_S4_E_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END VALOR_IRPF,
						CASE WHEN LC_S4_E_FAC.COMISION = 'Corrección' OR LC_S4_E_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE LC_S4_E_FAC.IMPORTE - ROUND(LC_S4_E_FAC.IMPORTE * LC_S4_E_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO,
						CASE WHEN LC_S4_E_FAC.COMISION = 'Corrección' OR LC_S4_E_FAC.COMISION = 'Correccion' 
								THEN LC_S4_E_FAC.IMPORTE
								ELSE LC_S4_E_FAC.IMPORTE - ROUND(LC_S4_E_FAC.IMPORTE * LC_S4_E_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO_A_PERCIBIR,
						F1.ULTIMA_ACTUALIZACION,
						YEAR(F1.ULTIMA_ACTUALIZACION)*100+MONTH(F1.ULTIMA_ACTUALIZACION) ULTIMA_ACTUALIZACION_YM,
						CASE WHEN F1.ULTIMA_ACTUALIZACION > ADD_MONTHS(J.STARTDATE, 1) 
								THEN LAST_DAY(J.STARTDATE)
								ELSE F1.ULTIMA_ACTUALIZACION
							END FEC_ACTUALIZACION
					FROM EXT.OUT_JERARQUIA_REP J
					INNER JOIN EXT.OUT_LC_S4_E_FACTURA_REP LC_S4_E_FAC ON LC_S4_E_FAC.PERIODSEQ = J.PERIODSEQ
						AND LC_S4_E_FAC.PARTICIPANTSEQ = J.PARTICIPANTSEQ
						AND LC_S4_E_FAC.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F1 ON F1.PERIODO = LC_S4_E_FAC.PERIODO
						AND F1.TABLA = 'OUT_LC_S4_E_FACTURA_REP'
                    WHERE LC_S4_E_FAC.PERIODSEQ = :i_PeriodSeq
				)
				WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S4_FACTURA_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			-- BRG 20250527: Nueva tabla OUT_S5_FACTURA_FINAL_REP para que la vista tire directamente de ella
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S5_FACTURA_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S5_FACTURA_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S5_FACTURA_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S5_FACTURA_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S5_FACTURA_FINAL_REP (COMPANYA,COMPANIA,TIPO_PAGO,PERIODSEQ,PERIODO,ANYO,MES_NUM,MES,TIPO_INFORME,SECUENCIAL,POSITIONSEQ_PRIN,POSITIONSEQ,PARTICIPANTSEQ,COD_REGIONAL,POS_PRIN,COMISION,IMPORTE,COD_OFICINA,OFICINA,OFICINA_CONCAT,NOMBRE,CUADRO_INSP,INSPECTOR,DOMICILIO,MUNICIPIO,CP,IRPF_NUM,IRPF,NIF,N_FACTURA,IMP_TOTAL,IMP_CORRECCION,VALOR_IRPF,NETO,NETO_A_PERCIBIR,ULTIMA_ACTUALIZACION,ULTIMA_ACTUALIZACION_YM,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO,FECHA_EMISION,FILTRO)
				SELECT COMPANYA, 
					COMPANIA, 
					TIPO_PAGO, 
					PERIODSEQ, 
					:v_period_name_format AS PERIODO, 
					ANYO, 
					MES_NUM, 
					MES, 
					TIPO_INFORME, 
					SECUENCIAL, 
					POSITIONSEQ_PRIN, 
					POSITIONSEQ_PRIN AS POSITIONSEQ, 
					PARTICIPANTSEQ, 
					COD_REGIONAL, 
					POS_PRIN, 
					COMISION, 
					ROUND(IMPORTE, 2) IMPORTE, 
					COD_OFICINA, 
					OFICINA, 
					OFICINA_CONCAT, 
					NOMBRE, 
					CUADRO_INSP, 
					INSPECTOR, 
					CASE WHEN COMPANYA = 'OCASO' AND NUMERO IS NOT NULL AND RESTO_DOMICILIO IS NOT NULL
							THEN DOMICILIO||', '||NUMERO||', '||RESTO_DOMICILIO 
						WHEN COMPANYA = 'OCASO' AND NUMERO IS NOT NULL AND RESTO_DOMICILIO IS NULL
							THEN DOMICILIO||', '||NUMERO
						WHEN COMPANYA = 'OCASO' AND NUMERO IS NULL AND RESTO_DOMICILIO IS NOT NULL
							THEN DOMICILIO||', '||RESTO_DOMICILIO 
						ELSE DOMICILIO END 
						AS DOMICILIO, 
					MUNICIPIO, 
					CP, 
					IRPF_NUM, 
					CASE 
                        WHEN IRPF = '0%'
                            THEN ' '
                        ELSE IRPF
                        END AS IRPF, 
					NIF, 
					N_FACTURA, 
					ROUND(IMP_TOTAL, 2) IMP_TOTAL, 
					ROUND(IMP_CORRECCION, 2) IMP_CORRECCION, 
					ROUND(VALOR_IRPF, 2) VALOR_IRPF, 
					ROUND(NETO, 2) NETO, 
					ROUND(NETO_A_PERCIBIR, 2) NETO_A_PERCIBIR, 
					ULTIMA_ACTUALIZACION, 
					ULTIMA_ACTUALIZACION_YM, 
					TO_DATE(FEC_ACTUALIZACION) FEC_ACTUALIZACION, 
					TO_VARCHAR(FEC_ACTUALIZACION, 'DD/MM/YYYY') FEC_ACTUALIZACION_FORMATO, 
					CASE WHEN DAYOFMONTH(FEC_ACTUALIZACION) < 10
							THEN '0'|| DAYOFMONTH(FEC_ACTUALIZACION)
								ELSE TO_VARCHAR(DAYOFMONTH(FEC_ACTUALIZACION))
							END 
						|| ' DE '
						|| CASE WHEN MONTH(FEC_ACTUALIZACION) = 1 THEN 'ENERO'
								WHEN MONTH(FEC_ACTUALIZACION) = 2 THEN 'FEBRERO'
								WHEN MONTH(FEC_ACTUALIZACION) = 3 THEN 'MARZO'
								WHEN MONTH(FEC_ACTUALIZACION) = 4 THEN 'ABRIL'
								WHEN MONTH(FEC_ACTUALIZACION) = 5 THEN 'MAYO'
								WHEN MONTH(FEC_ACTUALIZACION) = 6 THEN 'JUNIO'
								WHEN MONTH(FEC_ACTUALIZACION) = 7 THEN 'JULIO'
								WHEN MONTH(FEC_ACTUALIZACION) = 8 THEN 'AGOSTO'
								WHEN MONTH(FEC_ACTUALIZACION) = 9 THEN 'SEPTIEMBRE'
								WHEN MONTH(FEC_ACTUALIZACION) = 10 THEN 'OCTUBRE'
								WHEN MONTH(FEC_ACTUALIZACION) = 11 THEN 'NOVIEMBRE'
								WHEN MONTH(FEC_ACTUALIZACION) = 12 THEN 'DICIEMBRE'
								END
						|| ' DE '
						|| YEAR(FEC_ACTUALIZACION)
					FECHA_EMISION,
					NIF || ' - ' || NOMBRE FILTRO
				FROM 
				(	--OCASO CIERRE
					SELECT DISTINCT 'OCASO' COMPANYA, 
						S5_FAC.COMPANIA, 
						'CIERRE' TIPO_PAGO, 
						S5_FAC.PERIODSEQ, 
						S5_FAC.PERIODO, 
						J.YEAR ANYO , 
						EXTRACT(MONTH FROM J.STARTDATE) MES_NUM, 
						UPPER(LEFT(S5_FAC.PERIODO, LENGTH(S5_FAC.PERIODO)-5)) MES, 
						S5_FAC.TIPO_INFORME, 
						S5_FAC.SECUENCIAL, 
						S5_FAC.POSITIONSEQ_PRIN, 
						S5_FAC.PARTICIPANTSEQ, 
						J.COD_REGIONAL, 
						S5_FAC.POS_PRIN, 
						S5_FAC.COMISION, 
						S5_FAC.IMPORTE, 
						S5_FAC.COD_OFICINA, 
						S5_FAC.OFICINA, 
						S5_FAC.COD_OFICINA || ' - ' || S5_FAC.OFICINA OFICINA_CONCAT, 
						S5_FAC.NOMBRE, 
						S5_FAC.CUADRO_INSP, 
						RIGHT(S5_FAC.POS_PRIN, 4) || ' - ' || IFNULL(S5_FAC.CUADRO_INSP,'') || ' - ' || S5_FAC.NOMBRE INSPECTOR, 
						S5_FAC.DOMICILIO, 
						S5_FAC.NUMERO, 
						S5_FAC.RESTO_DOMICILIO, 
						S5_FAC.MUNICIPIO, 
						S5_FAC.CP, 
						S5_FAC.IRPF IRPF_NUM, 
						TO_VARCHAR(TO_DECIMAL(ROUND(S5_FAC.IRPF*100,0),25,0))||'%' IRPF, 
						S5_FAC.NIF, 
						S5_FAC.COMPANIA
                            || RIGHT(S5_FAC.TIPO_INFORME, 1) 
                            || RIGHT(J.YEAR,2) 
                            || LPAD(MONTH(J.STARTDATE), 2, '0')
                            || IFNULL(RIGHT(S5_FAC.COD_OFICINA,3), '') 
                            || RIGHT(S5_FAC.POS_PRIN,4) 
                            || '/'
                            || LPAD(S5_FAC.SECUENCIAL, 2, '0')
							AS N_FACTURA,
						CASE WHEN S5_FAC.COMISION = 'Corrección' OR S5_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE S5_FAC.IMPORTE
							END IMP_TOTAL,
						CASE WHEN S5_FAC.COMISION = 'Corrección' OR S5_FAC.COMISION = 'Correccion' 
								THEN S5_FAC.IMPORTE
								ELSE 0
							END IMP_CORRECCION,
						CASE WHEN S5_FAC.COMISION = 'Corrección' OR S5_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE ROUND(S5_FAC.IMPORTE * S5_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END VALOR_IRPF,
						CASE WHEN S5_FAC.COMISION = 'Corrección' OR S5_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE S5_FAC.IMPORTE - ROUND(S5_FAC.IMPORTE * S5_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO,
						CASE WHEN S5_FAC.COMISION = 'Corrección' OR S5_FAC.COMISION = 'Correccion' 
								THEN S5_FAC.IMPORTE
								ELSE S5_FAC.IMPORTE - ROUND(S5_FAC.IMPORTE * S5_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO_A_PERCIBIR,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN F1.ULTIMA_ACTUALIZACION
							ELSE F2.ULTIMA_ACTUALIZACION
							END ULTIMA_ACTUALIZACION,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN YEAR(F1.ULTIMA_ACTUALIZACION)*100+MONTH(F1.ULTIMA_ACTUALIZACION)
							ELSE YEAR(F2.ULTIMA_ACTUALIZACION)*100+MONTH(F2.ULTIMA_ACTUALIZACION)
							END ULTIMA_ACTUALIZACION_YM,
						CASE WHEN (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) > ADD_MONTHS(J.STARTDATE, 1) 
								THEN LAST_DAY(J.STARTDATE)
								ELSE (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) 
							END FEC_ACTUALIZACION
					FROM EXT.OUT_JERARQUIA_REP J
					INNER JOIN EXT.OUT_S5_FACTURA_REP S5_FAC ON S5_FAC.PERIODSEQ = J.PERIODSEQ
						AND S5_FAC.PARTICIPANTSEQ = J.PARTICIPANTSEQ
						AND S5_FAC.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F1 ON F1.PERIODO = S5_FAC.PERIODO
						AND F1.TABLA = 'OUT_S5_FACTURA_REP'	
                    --BRG 20251219 Añadido MAX para sacar la FECHA_FACTURA
					LEFT JOIN (SELECT DISTINCT PERIODSEQ, MAX(TO_DATE(PAG_FECHA_FACTURA,'YYYYMMDD')) ULTIMA_ACTUALIZACION
							FROM EXT.FINAL_EXTRACTPAGOS_FILE
							WHERE PAG_REFERENCIA_ORIGEN LIKE '15%'
                            GROUP BY PERIODSEQ) F2
						ON F2.PERIODSEQ = S5_FAC.PERIODSEQ
                    WHERE S5_FAC.PERIODSEQ = :i_PeriodSeq
					
					UNION ALL
					
					--OCASO LC
					SELECT DISTINCT 'OCASO' COMPANYA, 
						LC_S5_FAC.COMPANIA, 
						'LC' TIPO_PAGO, 
						LC_S5_FAC.PERIODSEQ, 
						LC_S5_FAC.PERIODO, 
						J.YEAR ANYO, 
						EXTRACT(MONTH FROM J.STARTDATE) MES_NUM, 
						UPPER(LEFT(LC_S5_FAC.PERIODO, LENGTH(LC_S5_FAC.PERIODO)-5)) MES, 
						LC_S5_FAC.TIPO_INFORME, 
						LC_S5_FAC.SECUENCIAL, 
						LC_S5_FAC.POSITIONSEQ_PRIN, 
						LC_S5_FAC.PARTICIPANTSEQ, 
						J.COD_REGIONAL, 
						LC_S5_FAC.POS_PRIN, 
						LC_S5_FAC.COMISION, 
						LC_S5_FAC.IMPORTE, 
						LC_S5_FAC.COD_OFICINA, 
						LC_S5_FAC.OFICINA, 
						LC_S5_FAC.COD_OFICINA || ' - ' || LC_S5_FAC.OFICINA OFICINA_CONCAT, 
						LC_S5_FAC.NOMBRE, 
						LC_S5_FAC.CUADRO_INSP, 
						RIGHT(LC_S5_FAC.POS_PRIN, 4) || ' - ' || IFNULL(LC_S5_FAC.CUADRO_INSP,'') || ' - ' || LC_S5_FAC.NOMBRE INSPECTOR, 
						LC_S5_FAC.DOMICILIO, 
						LC_S5_FAC.NUMERO, 
						LC_S5_FAC.RESTO_DOMICILIO, 
						LC_S5_FAC.MUNICIPIO, 
						LC_S5_FAC.CP, 
						LC_S5_FAC.IRPF IRPF_NUM, 
						TO_VARCHAR(TO_DECIMAL(ROUND(LC_S5_FAC.IRPF*100,0),25,0))||'%' IRPF, 
						LC_S5_FAC.NIF, 
						LC_S5_FAC.COMPANIA
                            || CASE WHEN RIGHT(LC_S5_FAC.TIPO_INFORME, 1) = '4'
                                    THEN '7'
                                    ELSE '8' 
                                END
                            || RIGHT(J.YEAR,2) 
                            || LPAD(MONTH(J.STARTDATE), 2, '0')
                            || RIGHT(LC_S5_FAC.COD_OFICINA,3) 
                            || RIGHT(LC_S5_FAC.POS_PRIN,4) 
                            || '/'
                            || LPAD(LC_S5_FAC.SECUENCIAL, 2, '0')
							AS N_FACTURA,
						CASE WHEN LC_S5_FAC.COMISION = 'Corrección' OR LC_S5_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE LC_S5_FAC.IMPORTE
							END IMP_TOTAL,
						CASE WHEN LC_S5_FAC.COMISION = 'Corrección' OR LC_S5_FAC.COMISION = 'Correccion' 
								THEN LC_S5_FAC.IMPORTE
								ELSE 0
							END IMP_CORRECCION,
						CASE WHEN LC_S5_FAC.COMISION = 'Corrección' OR LC_S5_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE ROUND(LC_S5_FAC.IMPORTE * LC_S5_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END VALOR_IRPF,
						CASE WHEN LC_S5_FAC.COMISION = 'Corrección' OR LC_S5_FAC.COMISION = 'Correccion' 
								THEN 0
								ELSE LC_S5_FAC.IMPORTE - ROUND(LC_S5_FAC.IMPORTE * LC_S5_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO,
						CASE WHEN LC_S5_FAC.COMISION = 'Corrección' OR LC_S5_FAC.COMISION = 'Correccion' 
								THEN LC_S5_FAC.IMPORTE
								ELSE LC_S5_FAC.IMPORTE - ROUND(LC_S5_FAC.IMPORTE * LC_S5_FAC.IRPF, 2)--- LLS 20251002 Incluir ROUND
							END NETO_A_PERCIBIR,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = LC_S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN F1.ULTIMA_ACTUALIZACION
							ELSE F2.ULTIMA_ACTUALIZACION
							END ULTIMA_ACTUALIZACION,
						CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = LC_S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
							THEN YEAR(F1.ULTIMA_ACTUALIZACION)*100+MONTH(F1.ULTIMA_ACTUALIZACION)
							ELSE YEAR(F2.ULTIMA_ACTUALIZACION)*100+MONTH(F2.ULTIMA_ACTUALIZACION)
							END ULTIMA_ACTUALIZACION_YM,
						CASE WHEN (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = LC_S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) > ADD_MONTHS(J.STARTDATE, 1) 
								THEN LAST_DAY(J.STARTDATE)
								ELSE (CASE WHEN (SELECT PER.STARTDATE FROM TCMP.CSA_PERIODDIMENSION PER WHERE PER.NAME = LC_S5_FAC.PERIODO) < TO_DATE('20220401','YYYYMMDD')
										THEN F1.ULTIMA_ACTUALIZACION
										ELSE F2.ULTIMA_ACTUALIZACION
										END) 
							END FEC_ACTUALIZACION	
					FROM EXT.OUT_JERARQUIA_REP J
					INNER JOIN EXT.OUT_LC_S5_FACTURA_REP LC_S5_FAC ON LC_S5_FAC.PERIODSEQ = J.PERIODSEQ
						AND LC_S5_FAC.PARTICIPANTSEQ = J.PARTICIPANTSEQ
						AND LC_S5_FAC.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F1 ON F1.PERIODO = LC_S5_FAC.PERIODO
						AND F1.TABLA = 'OUT_LC_S5_FACTURA_REP'
                    --BRG 20251219 Añadido MAX para sacar la FECHA_FACTURA
					LEFT JOIN (SELECT DISTINCT PERIODSEQ, MAX(TO_DATE(PAG_FECHA_FACTURA,'YYYYMMDD')) ULTIMA_ACTUALIZACION
							FROM EXT.FINAL_EXTRACTPAGOS_FILE
							WHERE PAG_REFERENCIA_ORIGEN LIKE '18%'
                            GROUP BY PERIODSEQ) F2
						ON F2.PERIODSEQ = LC_S5_FAC.PERIODSEQ
                    WHERE LC_S5_FAC.PERIODSEQ = :i_PeriodSeq
				)
				WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S5_FACTURA_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informes S4 Factura', i_log_count, i_id_proceso, 'info');
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informes S5 Factura', i_log_count, i_id_proceso, 'info');
            
        -- Fin informes S4 y S5 Factura
		END IF;

		---------------------------------------------------------------------------------------------
		--Inicio informe S4 PERCEPCIONES RESUMEN
		IF :i_lista_informes = 'PEPA' OR :i_lista_informes LIKE '%|PEPA|%' OR :i_lista_informes LIKE '%|PEPA' OR :i_lista_informes LIKE 'PEPA|%' OR :i_lista_informes = 'ALL' THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S4 PERCEPCIONES RESUMEN', i_log_count, i_id_proceso, 'info');
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_PEPA_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_PEPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_PEPA_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_PEPA_RESUMEN_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PEPA_RESUMEN_FINAL_REP (POS_PRIN,COMISION,IMPORTE,ID_TIPO_AGENTE,TIPO_AGENTE,COD_REGIONAL,REGIONAL,COD_SUCURSAL,SUCURSAL,COD_OFICINA,OFICINA,NOMBRE,POS_CALLIDUS,PROMOCION,SUPERRAPEL,IMPORTE_ACUMULADO,N_MEDIDA,FILAS_TABLA,POL_FIS_MES,POL_CORR_MES,PRIMAS_MES,POL_FIS_ANUAL,POL_CORR_ANUAL,PRIMAS_ANUAL,IMPORTE_MENSUAL,IMPORTE_ANUAL,V_MEDIDA,NIF,PERIODO,PERIODO_FORMATO,CUADRO_RRGG,CUADRO_RRTT,EARNINGCODEID,TIPO_CIERRE,COMPANIA,FECHA_ULT_ACT,POSITIONSEQ,PERIODSEQ,SOLO_DIFERENCIAS)
				SELECT DISTINCT --LLS 20251112: Añadido el distinct
					OUT_PEPA_RESUMEN_REP.POS_PRIN AS POS_PRIN,
					OUT_PEPA_RESUMEN_REP.COMISION AS COMISION,
					ROUND(OUT_PEPA_RESUMEN_REP.IMPORTE) AS IMPORTE,
					TO_INT(OUT_PEPA_RESUMEN_REP.ID_TIPO_AGENTE) AS ID_TIPO_AGENTE,
					TO_INT(OUT_PEPA_RESUMEN_REP.ID_TIPO_AGENTE) || '-' || OUT_PEPA_RESUMEN_REP.TIPO_AGENTE AS TIPO_AGENTE,
					OUT_PEPA_RESUMEN_REP.COD_REGIONAL AS COD_REGIONAL, 
					OUT_PEPA_RESUMEN_REP.COD_REGIONAL || '-' || OUT_PEPA_RESUMEN_REP.REGIONAL AS REGIONAL,
					OUT_PEPA_RESUMEN_REP.COD_SUCURSAL AS COD_SUCURSAL,
					OUT_PEPA_RESUMEN_REP.COD_SUCURSAL || '-' || OUT_PEPA_RESUMEN_REP.SUCURSAL AS SUCURSAL,
					OUT_PEPA_RESUMEN_REP.COD_OFICINA AS COD_OFICINA,
					OUT_PEPA_RESUMEN_REP.COD_OFICINA || '-' ||OUT_PEPA_RESUMEN_REP.OFICINA AS OFICINA,
					OUT_PEPA_RESUMEN_REP.NOMBRE AS NOMBRE,
					J.POS_CALLIDUS AS POS_CALLIDUS,
					OUT_PEPA_RESUMEN_REP.PROMOCION AS PROMOCION,
					OUT_PEPA_RESUMEN_REP.SUPERRAPEL AS SUPERRAPEL,
					ROUND(OUT_PEPA_RESUMEN_REP.IMPORTE_ACUMULADO, 2) AS IMPORTE_ACUMULADO,
					OUT_PEPA_RESUMEN_REP.N_MEDIDA AS N_MEDIDA,
					CASE
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%998%' THEN 'TOTAL PRODUCTOS'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%997%' THEN 'PROD PRIORITARIOS'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%906%' THEN 'RRPP'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%001%' THEN 'RRTT'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%002%' THEN 'HOGAR'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%003%' THEN 'VIDA-RIESGO'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%004%' THEN 'VIDA-AHORRO'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%005%' THEN 'ACCIDENTES'
						WHEN OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%Asegurados%' THEN 'ASEGURADOS'
					END AS FILAS_TABLA, --REVISAR QUE NO HAYA CASOS SOLAPADOS (ASEGURADOS%005 POR EJEMPLO)
					CASE WHEN (OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizas-%-TotalMes' OR OUT_PEPA_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes') THEN ROUND(OUT_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_FIS_MES,
					CASE WHEN (OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizasCorregidas-%-TotalMes') THEN ROUND(OUT_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_CORR_MES,
					CASE WHEN (OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-Prima-%-TotalMes') THEN ROUND(OUT_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_MES,
					CASE WHEN (OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizas-%-TotalAnual' OR OUT_PEPA_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalAnual') THEN ROUND(OUT_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_FIS_ANUAL,
					CASE WHEN (OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizasCorregidas-%-TotalAnual') THEN ROUND(OUT_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_CORR_ANUAL,
					CASE WHEN (OUT_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-Prima-%-TotalAnual') THEN ROUND(OUT_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_ANUAL,
					CASE WHEN SUBSTR(:v_period_name_format,6,2) = LPAD(TO_INTEGER(OUT_PEPA_RESUMEN_REP.IMPORTE_ACUMULADO),2,'0') THEN IFNULL(ROUND(OUT_PEPA_RESUMEN_REP.IMPORTE, 2),0) ELSE 0 END AS IMPORTE_MENSUAL,
					CASE WHEN (OUT_PEPA_RESUMEN_REP.N_MEDIDA = 'Balance' AND SUBSTR(:v_period_name_format,6,2) <> '01') THEN 0 ELSE IFNULL(ROUND(OUT_PEPA_RESUMEN_REP.IMPORTE, 2),0) END AS IMPORTE_ANUAL,
				 	ROUND(OUT_PEPA_RESUMEN_REP.V_MEDIDA, 2) AS V_MEDIDA,
					OUT_PEPA_RESUMEN_REP.NIF AS NIF,
					OUT_PEPA_RESUMEN_REP.PERIODO AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					OUT_PEPA_RESUMEN_REP.CUADRO_RRGG AS CUADRO_RRGG,
					OUT_PEPA_RESUMEN_REP.CUADRO_RRTT AS CUADRO_RRTT,
					OUT_PEPA_RESUMEN_REP.EARNINGCODEID AS EARNINGCODEID,
					'CIERRE' AS TIPO_CIERRE,
					'OCASO' AS COMPANIA,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					OUT_PEPA_RESUMEN_REP.POSITIONSEQ_PRIN,
					OUT_PEPA_RESUMEN_REP.PERIODSEQ AS PERIODSEQ,
					NULL AS SOLO_DIFERENCIAS

				FROM EXT.OUT_PEPA_RESUMEN_REP
				INNER JOIN EXT.OUT_JERARQUIA_REP J ON J.PERIODSEQ = OUT_PEPA_RESUMEN_REP.PERIODSEQ
				    AND OUT_PEPA_RESUMEN_REP.PARTICIPANTSEQ = J.PARTICIPANTSEQ
					AND OUT_PEPA_RESUMEN_REP.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
									AND F.TABLA = 'OUT_PEPA_RESUMEN_REP'
				WHERE 1=1
				AND J.PERIODSEQ = :i_PeriodSeq
				;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_PEPA_RESUMEN_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_PEPA_RESUMEN_FINAL_REP. BAL', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PEPA_RESUMEN_FINAL_REP (POS_PRIN,COMISION,IMPORTE,ID_TIPO_AGENTE,TIPO_AGENTE,COD_REGIONAL,REGIONAL,COD_SUCURSAL,SUCURSAL,COD_OFICINA,OFICINA,NOMBRE,POS_CALLIDUS,PROMOCION,SUPERRAPEL,IMPORTE_ACUMULADO,N_MEDIDA,FILAS_TABLA,POL_FIS_MES,POL_CORR_MES,PRIMAS_MES,POL_FIS_ANUAL,POL_CORR_ANUAL,PRIMAS_ANUAL,IMPORTE_MENSUAL,IMPORTE_ANUAL,V_MEDIDA,NIF,PERIODO,PERIODO_FORMATO,CUADRO_RRGG,CUADRO_RRTT,EARNINGCODEID,TIPO_CIERRE,COMPANIA,FECHA_ULT_ACT,POSITIONSEQ,PERIODSEQ,SOLO_DIFERENCIAS)
				SELECT DISTINCT --LLS 20251112: Añadido el distinct
					OUT_BAL_PEPA_RESUMEN_REP.POS_PRIN AS POS_PRIN,
					OUT_BAL_PEPA_RESUMEN_REP.COMISION AS COMISION,
					ROUND(OUT_BAL_PEPA_RESUMEN_REP.IMPORTE, 2) AS IMPORTE,
					TO_INT(OUT_BAL_PEPA_RESUMEN_REP.ID_TIPO_AGENTE) AS ID_TIPO_AGENTE,
					TO_INT(OUT_BAL_PEPA_RESUMEN_REP.ID_TIPO_AGENTE) || '-' || OUT_BAL_PEPA_RESUMEN_REP.TIPO_AGENTE AS TIPO_AGENTE,
					OUT_BAL_PEPA_RESUMEN_REP.COD_REGIONAL AS COD_REGIONAL, 
					OUT_BAL_PEPA_RESUMEN_REP.COD_REGIONAL || '-' || OUT_BAL_PEPA_RESUMEN_REP.REGIONAL AS REGIONAL,
					OUT_BAL_PEPA_RESUMEN_REP.COD_SUCURSAL AS COD_SUCURSAL,
					OUT_BAL_PEPA_RESUMEN_REP.COD_SUCURSAL || '-' || OUT_BAL_PEPA_RESUMEN_REP.SUCURSAL AS SUCURSAL,
					OUT_BAL_PEPA_RESUMEN_REP.COD_OFICINA AS COD_OFICINA,
					OUT_BAL_PEPA_RESUMEN_REP.COD_OFICINA || '-' ||OUT_BAL_PEPA_RESUMEN_REP.OFICINA AS OFICINA,
					OUT_BAL_PEPA_RESUMEN_REP.NOMBRE AS NOMBRE,
					J.POS_CALLIDUS AS POS_CALLIDUS,
					OUT_BAL_PEPA_RESUMEN_REP.PROMOCION AS PROMOCION,
					OUT_BAL_PEPA_RESUMEN_REP.SUPERRAPEL AS SUPERRAPEL,
					ROUND(OUT_BAL_PEPA_RESUMEN_REP.IMPORTE_ACUMULADO, 2) AS IMPORTE_ACUMULADO,
					OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA AS N_MEDIDA,
					CASE
						WHEN OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%998%' THEN 'TOTAL PRODUCTOS'
						WHEN OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%997%' THEN 'PROD PRIORITARIOS'
						WHEN OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%906%' THEN 'RRPP'
						WHEN OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%001%' THEN 'RRTT'
						WHEN OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%002%' THEN 'HOGAR'
						WHEN OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%003%' THEN 'VIDA-RIESGO'
						WHEN OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%004%' THEN 'VIDA-AHORRO'
						WHEN OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%005%' THEN 'ACCIDENTES'
						WHEN OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%Asegurados%' THEN 'ASEGURADOS'
					END AS FILAS_TABLA, --REVISAR QUE NO HAYA CASOS SOLAPADOS (ASEGURADOS%005 POR EJEMPLO)
					CASE WHEN (OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizas-%-TotalMes' OR OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes') THEN ROUND(OUT_BAL_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_FIS_MES,
					CASE WHEN (OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizasCorregidas-%-TotalMes') THEN ROUND(OUT_BAL_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_CORR_MES,
					CASE WHEN (OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-Prima-%-TotalMes') THEN ROUND(OUT_BAL_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_MES,
					CASE WHEN (OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizas-%-TotalAnual' OR OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalAnual') THEN ROUND(OUT_BAL_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_FIS_ANUAL,
					CASE WHEN (OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizasCorregidas-%-TotalAnual') THEN ROUND(OUT_BAL_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_CORR_ANUAL,
					CASE WHEN (OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-Prima-%-TotalAnual') THEN ROUND(OUT_BAL_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_ANUAL,
					CASE WHEN SUBSTR(:v_period_name_format,6,2) = LPAD(TO_INTEGER(OUT_BAL_PEPA_RESUMEN_REP.IMPORTE_ACUMULADO),2,'0') THEN IFNULL(ROUND(OUT_BAL_PEPA_RESUMEN_REP.IMPORTE, 2),0) ELSE 0 END AS IMPORTE_MENSUAL,
					CASE WHEN (OUT_BAL_PEPA_RESUMEN_REP.N_MEDIDA = 'Balance' AND SUBSTR(:v_period_name_format,6,2) <> '01') THEN 0 ELSE IFNULL(ROUND(OUT_BAL_PEPA_RESUMEN_REP.IMPORTE, 2),0) END AS IMPORTE_ANUAL,
				 	ROUND(OUT_BAL_PEPA_RESUMEN_REP.V_MEDIDA, 2) AS V_MEDIDA,
					OUT_BAL_PEPA_RESUMEN_REP.NIF AS NIF,
					OUT_BAL_PEPA_RESUMEN_REP.PERIODO AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					OUT_BAL_PEPA_RESUMEN_REP.CUADRO_RRGG AS CUADRO_RRGG,
					OUT_BAL_PEPA_RESUMEN_REP.CUADRO_RRTT AS CUADRO_RRTT,
					OUT_BAL_PEPA_RESUMEN_REP.EARNINGCODEID AS EARNINGCODEID,
					'BAL' AS TIPO_CIERRE,
					'OCASO' AS COMPANIA,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					OUT_BAL_PEPA_RESUMEN_REP.POSITIONSEQ_PRIN,
					OUT_BAL_PEPA_RESUMEN_REP.PERIODSEQ AS PERIODSEQ,
					CASE WHEN B.BALANCESEQ IS NOT NULL THEN 'SI' ELSE NULL END AS SOLO_DIFERENCIAS

				FROM EXT.OUT_BAL_PEPA_RESUMEN_REP
				INNER JOIN EXT.OUT_JERARQUIA_REP J ON J.PERIODSEQ = OUT_BAL_PEPA_RESUMEN_REP.PERIODSEQ
				    AND OUT_BAL_PEPA_RESUMEN_REP.PARTICIPANTSEQ = J.PARTICIPANTSEQ
					AND OUT_BAL_PEPA_RESUMEN_REP.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
									AND F.TABLA = 'OUT_BAL_PEPA_RESUMEN_REP'
				LEFT JOIN (SELECT X.PERIODSEQ,X.PAYEESEQ,X.POSITIONSEQ,MAX(X.BALANCESEQ) AS BALANCESEQ FROM TCMP.CS_BALANCE X
					WHERE X.TENANTID = :v_idtenant GROUP BY X.PERIODSEQ,X.PAYEESEQ,X.POSITIONSEQ) B ON B.PERIODSEQ = OUT_BAL_PEPA_RESUMEN_REP.PERIODSEQ
    				AND B.PAYEESEQ = OUT_BAL_PEPA_RESUMEN_REP.PARTICIPANTSEQ
    				AND B.POSITIONSEQ = OUT_BAL_PEPA_RESUMEN_REP.POSITIONSEQ_PRIN
				WHERE 1=1
				AND J.PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_PEPA_RESUMEN_FINAL_REP. BAL. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_PEPA_RESUMEN_FINAL_REP. LC', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PEPA_RESUMEN_FINAL_REP (POS_PRIN,COMISION,IMPORTE,ID_TIPO_AGENTE,TIPO_AGENTE,COD_REGIONAL,REGIONAL,COD_SUCURSAL,SUCURSAL,COD_OFICINA,OFICINA,NOMBRE,POS_CALLIDUS,PROMOCION,SUPERRAPEL,IMPORTE_ACUMULADO,N_MEDIDA,FILAS_TABLA,POL_FIS_MES,POL_CORR_MES,PRIMAS_MES,POL_FIS_ANUAL,POL_CORR_ANUAL,PRIMAS_ANUAL,IMPORTE_MENSUAL,IMPORTE_ANUAL,V_MEDIDA,NIF,PERIODO,PERIODO_FORMATO,CUADRO_RRGG,CUADRO_RRTT,EARNINGCODEID,TIPO_CIERRE,COMPANIA,FECHA_ULT_ACT,POSITIONSEQ,PERIODSEQ,SOLO_DIFERENCIAS)
				SELECT DISTINCT --LLS 20251112: Añadido el distinct
					OUT_LC_PEPA_RESUMEN_REP.POS_PRIN AS POS_PRIN,
					OUT_LC_PEPA_RESUMEN_REP.COMISION AS COMISION,
					ROUND(OUT_LC_PEPA_RESUMEN_REP.IMPORTE, 2) AS IMPORTE,
					TO_INT(OUT_LC_PEPA_RESUMEN_REP.ID_TIPO_AGENTE) AS ID_TIPO_AGENTE,
					TO_INT(OUT_LC_PEPA_RESUMEN_REP.ID_TIPO_AGENTE) || '-' || OUT_LC_PEPA_RESUMEN_REP.TIPO_AGENTE AS TIPO_AGENTE,
					OUT_LC_PEPA_RESUMEN_REP.COD_REGIONAL AS COD_REGIONAL, 
					OUT_LC_PEPA_RESUMEN_REP.COD_REGIONAL || '-' || OUT_LC_PEPA_RESUMEN_REP.REGIONAL AS REGIONAL,
					OUT_LC_PEPA_RESUMEN_REP.COD_SUCURSAL AS COD_SUCURSAL,
					OUT_LC_PEPA_RESUMEN_REP.COD_SUCURSAL || '-' || OUT_LC_PEPA_RESUMEN_REP.SUCURSAL AS SUCURSAL,
					OUT_LC_PEPA_RESUMEN_REP.COD_OFICINA AS COD_OFICINA,
					OUT_LC_PEPA_RESUMEN_REP.COD_OFICINA || '-' ||OUT_LC_PEPA_RESUMEN_REP.OFICINA AS OFICINA,
					OUT_LC_PEPA_RESUMEN_REP.NOMBRE AS NOMBRE,
					J.POS_CALLIDUS AS POS_CALLIDUS,
					OUT_LC_PEPA_RESUMEN_REP.PROMOCION AS PROMOCION,
					OUT_LC_PEPA_RESUMEN_REP.SUPERRAPEL AS SUPERRAPEL,
					ROUND(OUT_LC_PEPA_RESUMEN_REP.IMPORTE_ACUMULADO, 2) AS IMPORTE_ACUMULADO,
					OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA AS N_MEDIDA,
					CASE
						WHEN OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%998%' THEN 'TOTAL PRODUCTOS'
						WHEN OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%997%' THEN 'PROD PRIORITARIOS'
						WHEN OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%906%' THEN 'RRPP'
						WHEN OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%001%' THEN 'RRTT'
						WHEN OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%002%' THEN 'HOGAR'
						WHEN OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%003%' THEN 'VIDA-RIESGO'
						WHEN OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%004%' THEN 'VIDA-AHORRO'
						WHEN OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%005%' THEN 'ACCIDENTES'
						WHEN OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE '%Asegurados%' THEN 'ASEGURADOS'
					END AS FILAS_TABLA, --REVISAR QUE NO HAYA CASOS SOLAPADOS (ASEGURADOS%005 POR EJEMPLO)
					CASE WHEN (OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizas-%-TotalMes' OR OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes') THEN ROUND(OUT_LC_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_FIS_MES,
					CASE WHEN (OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizasCorregidas-%-TotalMes') THEN ROUND(OUT_LC_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_CORR_MES,
					CASE WHEN (OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-Prima-%-TotalMes') THEN ROUND(OUT_LC_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_MES,
					CASE WHEN (OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizas-%-TotalAnual' OR OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalAnual') THEN ROUND(OUT_LC_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_FIS_ANUAL,
					CASE WHEN (OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-NumeroPolizasCorregidas-%-TotalAnual') THEN ROUND(OUT_LC_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_CORR_ANUAL,
					CASE WHEN (OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Agente-Prima-%-TotalAnual') THEN ROUND(OUT_LC_PEPA_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_ANUAL,
					CASE WHEN SUBSTR(:v_period_name_format,6,2) = LPAD(TO_INTEGER(OUT_LC_PEPA_RESUMEN_REP.IMPORTE_ACUMULADO),2,'0') THEN IFNULL(ROUND(OUT_LC_PEPA_RESUMEN_REP.IMPORTE, 2),0) ELSE 0 END AS IMPORTE_MENSUAL,
					CASE WHEN (OUT_LC_PEPA_RESUMEN_REP.N_MEDIDA = 'Balance' AND SUBSTR(:v_period_name_format,6,2) <> '01') THEN 0 ELSE IFNULL(ROUND(OUT_LC_PEPA_RESUMEN_REP.IMPORTE, 2),0) END AS IMPORTE_ANUAL,
				 	ROUND(OUT_LC_PEPA_RESUMEN_REP.V_MEDIDA, 2) AS V_MEDIDA,
					OUT_LC_PEPA_RESUMEN_REP.NIF AS NIF,
					OUT_LC_PEPA_RESUMEN_REP.PERIODO AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					OUT_LC_PEPA_RESUMEN_REP.CUADRO_RRGG AS CUADRO_RRGG,
					OUT_LC_PEPA_RESUMEN_REP.CUADRO_RRTT AS CUADRO_RRTT,
					OUT_LC_PEPA_RESUMEN_REP.EARNINGCODEID AS EARNINGCODEID,
					'LC' AS TIPO_CIERRE,
					'OCASO' AS COMPANIA,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					OUT_LC_PEPA_RESUMEN_REP.POSITIONSEQ_PRIN,
					OUT_LC_PEPA_RESUMEN_REP.PERIODSEQ AS PERIODSEQ,
					CASE WHEN (B.POSTPIPELINERUNDATE IS NULL OR B.POSTPIPELINERUNDATE > LAST_DAY(J.STARTDATE) )THEN 'SI' ELSE NULL END AS SOLO_DIFERENCIAS

				FROM EXT.OUT_LC_PEPA_RESUMEN_REP
				INNER JOIN EXT.OUT_JERARQUIA_REP J ON J.PERIODSEQ = OUT_LC_PEPA_RESUMEN_REP.PERIODSEQ
				    AND OUT_LC_PEPA_RESUMEN_REP.PARTICIPANTSEQ = J.PARTICIPANTSEQ
					AND OUT_LC_PEPA_RESUMEN_REP.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
									AND F.TABLA = 'OUT_LC_PEPA_RESUMEN_REP'
				LEFT JOIN (SELECT X.PAYEESEQ,X.POSITIONSEQ,MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE FROM TCMP.CS_PAYMENT X
           			WHERE X.TENANTID = :v_idtenant AND X.PERIODSEQ = :i_PeriodSeq
           			GROUP BY X.PAYEESEQ, X.POSITIONSEQ) B
				ON B.PAYEESEQ = OUT_LC_PEPA_RESUMEN_REP.PARTICIPANTSEQ
    			AND B.POSITIONSEQ = OUT_LC_PEPA_RESUMEN_REP.POSITIONSEQ_PRIN
				WHERE 1=1
				AND J.PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_PEPA_RESUMEN_FINAL_REP. LC. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Creación Informe Percepciones S4 Resumen', i_log_count, i_id_proceso, 'info');
		
		--FIN informe S4 PERCEPCIONES RESUMEN
		END IF;
		
		---------------------------------------------------------------------------------------------------------------------------------------
		--Inicio informe S5 PERCEPCIONES RESUMEN
		IF :i_lista_informes = 'PEPI' OR :i_lista_informes LIKE '%|PEPI|%' OR :i_lista_informes LIKE '%|PEPI' OR :i_lista_informes LIKE 'PEPI|%' OR :i_lista_informes = 'ALL' THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S5 PERCEPCIONES RESUMEN', i_log_count, i_id_proceso, 'info');
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_PEPI_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_PEPI_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_PEPI_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_PEPI_RESUMEN_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PEPI_RESUMEN_FINAL_REP (POS_PRIN,COMISION,IMPORTE,ID_TIPO_AGENTE,TIPO_AGENTE,COD_REGIONAL,REGIONAL,COD_SUCURSAL,SUCURSAL,COD_OFICINA,OFICINA,NOMBRE,POS_CALLIDUS,IMPORTE_ACUMULADO,N_MEDIDA,FILAS_TABLA,POL_FIS_MES,POL_CORR_MES,PRIMAS_MES,PRIMAS_CORR_MES,POL_FIS_ANUAL,POL_CORR_ANUAL,PRIMAS_ANUAL,PRIMAS_CORR_ANUAL,IMPORTE_MENSUAL,IMPORTE_ANUAL,V_MEDIDA,NIF,PERIODO,PERIODO_FORMATO,CUADRO_INSP,EARNINGCODEID,TIPO_CIERRE,COMPANIA,FECHA_ULT_ACT,POSITIONSEQ,PERIODSEQ,SOLO_DIFERENCIAS)
				WITH CTE_JER AS (SELECT
									PERIODSEQ,
									PARTICIPANTSEQ,
									POSITIONSEQ_PRIN,
									POSITIONSEQ,
									POS_CALLIDUS,
									STARTDATE,
									PERIODO
								FROM EXT.OUT_JERARQUIA_REP
								WHERE POSITIONSEQ = POSITIONSEQ_PRIN							
									)
				SELECT DISTINCT --LLS 20251112: Añadido el distinct
					OUT_PEPI_RESUMEN_REP.POS_PRIN AS POS_PRIN,
					OUT_PEPI_RESUMEN_REP.COMISION AS COMISION,
					ROUND(OUT_PEPI_RESUMEN_REP.IMPORTE, 2) AS IMPORTE,
					TO_INT(OUT_PEPI_RESUMEN_REP.ID_TIPO_AGENTE) AS ID_TIPO_AGENTE,
					TO_INT(OUT_PEPI_RESUMEN_REP.ID_TIPO_AGENTE) || '-' || OUT_PEPI_RESUMEN_REP.TIPO_AGENTE AS TIPO_AGENTE,
					OUT_PEPI_RESUMEN_REP.COD_REGIONAL AS COD_REGIONAL, 
					OUT_PEPI_RESUMEN_REP.COD_REGIONAL || '-' || OUT_PEPI_RESUMEN_REP.REGIONAL AS REGIONAL,
					OUT_PEPI_RESUMEN_REP.COD_SUCURSAL AS COD_SUCURSAL,
					OUT_PEPI_RESUMEN_REP.COD_SUCURSAL || '-' || OUT_PEPI_RESUMEN_REP.SUCURSAL AS SUCURSAL,
					OUT_PEPI_RESUMEN_REP.COD_OFICINA AS COD_OFICINA,
					OUT_PEPI_RESUMEN_REP.COD_OFICINA || '-' ||OUT_PEPI_RESUMEN_REP.OFICINA AS OFICINA,
					OUT_PEPI_RESUMEN_REP.NOMBRE AS NOMBRE,
					J.POS_CALLIDUS AS POS_CALLIDUS,
					ROUND(OUT_PEPI_RESUMEN_REP.IMPORTE_ACUMULADO, 2) AS IMPORTE_ACUMULADO,
					OUT_PEPI_RESUMEN_REP.N_MEDIDA AS N_MEDIDA,
					CASE
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%998%' THEN 'TOTAL PRODUCTOS'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%997%' THEN 'TOTAL PRIORITARIOS'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND RIGHT(OUT_PEPI_RESUMEN_REP.PERIODO,4) < 2020 THEN 'RRPP excl. PU/CC'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND RIGHT(OUT_PEPI_RESUMEN_REP.PERIODO,4) < 2024 THEN 'RRPP excluir Superplan'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND RIGHT(OUT_PEPI_RESUMEN_REP.PERIODO,4) >= 2024 THEN 'RRPP' --LLS 20251110 Añadido el =
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%001%' THEN 'RRTT'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%002%' THEN 'HOGAR'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%003%' THEN 'VIDA-RIESGO'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%004%' THEN 'VIDA-AHORRO'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%005%' THEN 'ACCIDENTES'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%006%' THEN 'RESTO PRODUCTOS'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%007%' THEN 'OCASO ORO'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%008%' THEN 'COMUNIDADES'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%009%' THEN 'PYME EXPRESS'
						WHEN OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%Asegurados%' THEN 'ASEGURADOS'
					END AS FILAS_TABLA, --REVISAR QUE NO HAYA CASOS SOLAPADOS (ASEGURADOS%005 POR EJEMPLO)
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizas-%-TotalMes' OR OUT_PEPI_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalMes') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_FIS_MES,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-%-TotalMes') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_CORR_MES,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-Prima-%-TotalMes') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_MES,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-PrimaCorregida-%-TotalMes') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_CORR_MES,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizas-%-TotalAnual' OR OUT_PEPI_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalAnual') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_FIS_ANUAL,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-%-TotalAnual') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_CORR_ANUAL,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-Prima-%-TotalAnual') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_ANUAL,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-PrimaCorregida-%-TotalAnual') THEN ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_CORR_ANUAL,
					CASE WHEN SUBSTR(:v_period_name_format,6,2) = LPAD(TO_INTEGER(OUT_PEPI_RESUMEN_REP.IMPORTE_ACUMULADO),2,'0') THEN IFNULL(ROUND(OUT_PEPI_RESUMEN_REP.IMPORTE, 2),0) ELSE 0 END AS IMPORTE_MENSUAL,
					CASE WHEN (OUT_PEPI_RESUMEN_REP.N_MEDIDA = 'Balance' AND SUBSTR(:v_period_name_format,6,2) <> '01') THEN 0 ELSE IFNULL(ROUND(OUT_PEPI_RESUMEN_REP.IMPORTE, 2),0) END AS IMPORTE_ANUAL,
				 	ROUND(OUT_PEPI_RESUMEN_REP.V_MEDIDA, 2) AS V_MEDIDA,
					OUT_PEPI_RESUMEN_REP.NIF AS NIF,
					OUT_PEPI_RESUMEN_REP.PERIODO AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					OUT_PEPI_RESUMEN_REP.CUADRO_INSP AS CUADRO_INSP,
					OUT_PEPI_RESUMEN_REP.EARNINGCODEID AS EARNINGCODEID,
					'CIERRE' AS TIPO_CIERRE,
					'OCASO' AS COMPANIA,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					OUT_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN AS POSITIONSEQ,
					OUT_PEPI_RESUMEN_REP.PERIODSEQ,
					NULL AS SOLO_DIFERENCIAS

				FROM EXT.OUT_PEPI_RESUMEN_REP
				INNER JOIN CTE_JER J ON J.PERIODSEQ = OUT_PEPI_RESUMEN_REP.PERIODSEQ
				    AND OUT_PEPI_RESUMEN_REP.PARTICIPANTSEQ = J.PARTICIPANTSEQ
					AND OUT_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_PEPI_RESUMEN_REP'
				WHERE 1=1
					AND J.PERIODSEQ = :i_PeriodSeq
					AND TO_INT(OUT_PEPI_RESUMEN_REP.ID_TIPO_AGENTE) <> 79 -- DTB 20251126 Los 79-INSPECTOR OFICINA no se muestran
					;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_PEPI_RESUMEN_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_PEPI_RESUMEN_FINAL_REP. BAL', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PEPI_RESUMEN_FINAL_REP (POS_PRIN,COMISION,IMPORTE,ID_TIPO_AGENTE,TIPO_AGENTE,COD_REGIONAL,REGIONAL,COD_SUCURSAL,SUCURSAL,COD_OFICINA,OFICINA,NOMBRE,POS_CALLIDUS,IMPORTE_ACUMULADO,N_MEDIDA,FILAS_TABLA,POL_FIS_MES,POL_CORR_MES,PRIMAS_MES,PRIMAS_CORR_MES,POL_FIS_ANUAL,POL_CORR_ANUAL,PRIMAS_ANUAL,PRIMAS_CORR_ANUAL,IMPORTE_MENSUAL,IMPORTE_ANUAL,V_MEDIDA,NIF,PERIODO,PERIODO_FORMATO,CUADRO_INSP,EARNINGCODEID,TIPO_CIERRE,COMPANIA,FECHA_ULT_ACT,POSITIONSEQ,PERIODSEQ,SOLO_DIFERENCIAS)
				WITH CTE_JER AS (SELECT
									PERIODSEQ,
									PARTICIPANTSEQ,
									POSITIONSEQ_PRIN,
									POSITIONSEQ,
									POS_CALLIDUS,
									PERIODO,
									STARTDATE
								FROM EXT.OUT_JERARQUIA_REP
								WHERE POSITIONSEQ = POSITIONSEQ_PRIN							
									)
				SELECT DISTINCT --LLS 20251112: Añadido el distinct
					OUT_BAL_PEPI_RESUMEN_REP.POS_PRIN AS POS_PRIN,
					OUT_BAL_PEPI_RESUMEN_REP.COMISION AS COMISION,
					ROUND(OUT_BAL_PEPI_RESUMEN_REP.IMPORTE, 2) AS IMPORTE,
					TO_INT(OUT_BAL_PEPI_RESUMEN_REP.ID_TIPO_AGENTE) AS ID_TIPO_AGENTE,
					TO_INT(OUT_BAL_PEPI_RESUMEN_REP.ID_TIPO_AGENTE) || '-' || OUT_BAL_PEPI_RESUMEN_REP.TIPO_AGENTE AS TIPO_AGENTE,
					OUT_BAL_PEPI_RESUMEN_REP.COD_REGIONAL AS COD_REGIONAL, 
					OUT_BAL_PEPI_RESUMEN_REP.COD_REGIONAL || '-' || OUT_BAL_PEPI_RESUMEN_REP.REGIONAL AS REGIONAL,
					OUT_BAL_PEPI_RESUMEN_REP.COD_SUCURSAL AS COD_SUCURSAL,
					OUT_BAL_PEPI_RESUMEN_REP.COD_SUCURSAL || '-' || OUT_BAL_PEPI_RESUMEN_REP.SUCURSAL AS SUCURSAL,
					OUT_BAL_PEPI_RESUMEN_REP.COD_OFICINA AS COD_OFICINA,
					OUT_BAL_PEPI_RESUMEN_REP.COD_OFICINA || '-' ||OUT_BAL_PEPI_RESUMEN_REP.OFICINA AS OFICINA,
					OUT_BAL_PEPI_RESUMEN_REP.NOMBRE AS NOMBRE,
					J.POS_CALLIDUS AS POS_CALLIDUS,
					ROUND(OUT_BAL_PEPI_RESUMEN_REP.IMPORTE_ACUMULADO, 2) AS IMPORTE_ACUMULADO,
					OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA AS N_MEDIDA,
					CASE
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%998%' THEN 'TOTAL PRODUCTOS'
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%997%' THEN 'TOTAL PRIORITARIOS'
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND RIGHT(OUT_BAL_PEPI_RESUMEN_REP.PERIODO,4) < 2020 THEN 'RRPP excl. PU/CC'
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND 2019 < RIGHT(OUT_BAL_PEPI_RESUMEN_REP.PERIODO,4) AND RIGHT(OUT_BAL_PEPI_RESUMEN_REP.PERIODO,4) < 2024 THEN 'RRPP excluir Superplan'
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND 2024 < RIGHT(OUT_BAL_PEPI_RESUMEN_REP.PERIODO,4) THEN 'RRPP'
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%001%' THEN 'RRTT'
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%002%' THEN 'HOGAR'
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%003%' THEN 'VIDA-RIESGO'
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%004%' THEN 'VIDA-AHORRO'
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%005%' THEN 'ACCIDENTES'
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%006%' THEN 'RESTO PRODUCTOS'
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%007%' THEN 'OCASO ORO'
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%008%' THEN 'COMUNIDADES'
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%009%' THEN 'PYME EXPRESS'
						WHEN OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%Asegurados%' THEN 'ASEGURADOS'
					END AS FILAS_TABLA, --REVISAR QUE NO HAYA CASOS SOLAPADOS (ASEGURADOS%005 POR EJEMPLO)
					CASE WHEN (OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizas-%-TotalMes' OR OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalMes') THEN ROUND(OUT_BAL_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_FIS_MES,
					CASE WHEN (OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-%-TotalMes') THEN ROUND(OUT_BAL_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_CORR_MES,
					CASE WHEN (OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-Prima-%-TotalMes') THEN ROUND(OUT_BAL_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_MES,
					CASE WHEN (OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-PrimaCorregida-%-TotalMes') THEN ROUND(OUT_BAL_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_CORR_MES,
					CASE WHEN (OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizas-%-TotalAnual' OR OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalAnual') THEN ROUND(OUT_BAL_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_FIS_ANUAL,
					CASE WHEN (OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-%-TotalAnual') THEN ROUND(OUT_BAL_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_CORR_ANUAL,
					CASE WHEN (OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-Prima-%-TotalAnual') THEN ROUND(OUT_BAL_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_ANUAL,
					CASE WHEN (OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-PrimaCorregida-%-TotalAnual') THEN ROUND(OUT_BAL_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_CORR_ANUAL,
					CASE WHEN SUBSTR(:v_period_name_format,6,2) = LPAD(TO_INTEGER(OUT_BAL_PEPI_RESUMEN_REP.IMPORTE_ACUMULADO),2,'0') THEN IFNULL(ROUND(OUT_BAL_PEPI_RESUMEN_REP.IMPORTE, 2),0) ELSE 0 END AS IMPORTE_MENSUAL,
					CASE WHEN (OUT_BAL_PEPI_RESUMEN_REP.N_MEDIDA = 'Balance' AND SUBSTR(:v_period_name_format,6,2) <> '01') THEN 0 ELSE IFNULL(ROUND(OUT_BAL_PEPI_RESUMEN_REP.IMPORTE, 2),0) END AS IMPORTE_ANUAL,
				 	ROUND(OUT_BAL_PEPI_RESUMEN_REP.V_MEDIDA, 2) AS V_MEDIDA,
					OUT_BAL_PEPI_RESUMEN_REP.NIF AS NIF,
					OUT_BAL_PEPI_RESUMEN_REP.PERIODO AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					OUT_BAL_PEPI_RESUMEN_REP.CUADRO_INSP AS CUADRO_INSP,
					OUT_BAL_PEPI_RESUMEN_REP.EARNINGCODEID AS EARNINGCODEID,
					'BAL' AS TIPO_CIERRE,
					'OCASO' AS COMPANIA,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					OUT_BAL_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN AS POSITIONSEQ,
					OUT_BAL_PEPI_RESUMEN_REP.PERIODSEQ,
					CASE WHEN B.BALANCESEQ IS NOT NULL THEN 'SI' ELSE NULL END AS SOLO_DIFERENCIAS

				FROM EXT.OUT_BAL_PEPI_RESUMEN_REP
				INNER JOIN CTE_JER J ON J.PERIODSEQ = OUT_BAL_PEPI_RESUMEN_REP.PERIODSEQ
				    AND OUT_BAL_PEPI_RESUMEN_REP.PARTICIPANTSEQ = J.PARTICIPANTSEQ
					AND OUT_BAL_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_BAL_PEPI_RESUMEN_REP'
				LEFT JOIN (SELECT X.PERIODSEQ,X.PAYEESEQ,X.POSITIONSEQ,MAX(X.BALANCESEQ) AS BALANCESEQ FROM TCMP.CS_BALANCE X
					WHERE X.TENANTID = :v_idtenant GROUP BY X.PERIODSEQ,X.PAYEESEQ,X.POSITIONSEQ) B ON B.PERIODSEQ = OUT_BAL_PEPI_RESUMEN_REP.PERIODSEQ
    				AND B.PAYEESEQ = OUT_BAL_PEPI_RESUMEN_REP.PARTICIPANTSEQ
    				AND B.POSITIONSEQ = OUT_BAL_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN
				WHERE 1=1
					AND J.PERIODSEQ = :i_PeriodSeq
					AND TO_INT(OUT_BAL_PEPI_RESUMEN_REP.ID_TIPO_AGENTE) <> 79 -- DTB 20251126 Los 79-INSPECTOR OFICINA no se muestran
					;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_PEPI_RESUMEN_FINAL_REP. BAL. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_PEPI_RESUMEN_FINAL_REP. LC', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_PEPI_RESUMEN_FINAL_REP (POS_PRIN,COMISION,IMPORTE,ID_TIPO_AGENTE,TIPO_AGENTE,COD_REGIONAL,REGIONAL,COD_SUCURSAL,SUCURSAL,COD_OFICINA,OFICINA,NOMBRE,POS_CALLIDUS,IMPORTE_ACUMULADO,N_MEDIDA,FILAS_TABLA,POL_FIS_MES,POL_CORR_MES,PRIMAS_MES,PRIMAS_CORR_MES,POL_FIS_ANUAL,POL_CORR_ANUAL,PRIMAS_ANUAL,PRIMAS_CORR_ANUAL,IMPORTE_MENSUAL,IMPORTE_ANUAL,V_MEDIDA,NIF,PERIODO,PERIODO_FORMATO,CUADRO_INSP,EARNINGCODEID,TIPO_CIERRE,COMPANIA,FECHA_ULT_ACT,POSITIONSEQ,PERIODSEQ,SOLO_DIFERENCIAS)
				--DTB 20251124 Añadida CTE y filtro POSITIONSEQ_PRIN = POSITIONSEQ
				WITH CTE_JER AS (SELECT
									PERIODSEQ,
									PARTICIPANTSEQ,
									POSITIONSEQ_PRIN,
									POSITIONSEQ,
									POS_CALLIDUS,
									PERIODO,
									STARTDATE
								FROM EXT.OUT_JERARQUIA_REP
								WHERE POSITIONSEQ = POSITIONSEQ_PRIN							
									)
				SELECT DISTINCT --LLS 20251112: Añadido el distinct
					OUT_LC_PEPI_RESUMEN_REP.POS_PRIN AS POS_PRIN,
					OUT_LC_PEPI_RESUMEN_REP.COMISION AS COMISION,
					ROUND(OUT_LC_PEPI_RESUMEN_REP.IMPORTE, 2) AS IMPORTE,
					TO_INT(OUT_LC_PEPI_RESUMEN_REP.ID_TIPO_AGENTE) AS ID_TIPO_AGENTE,
					TO_INT(OUT_LC_PEPI_RESUMEN_REP.ID_TIPO_AGENTE) || '-' || OUT_LC_PEPI_RESUMEN_REP.TIPO_AGENTE AS TIPO_AGENTE,
					OUT_LC_PEPI_RESUMEN_REP.COD_REGIONAL AS COD_REGIONAL, 
					OUT_LC_PEPI_RESUMEN_REP.COD_REGIONAL || '-' || OUT_LC_PEPI_RESUMEN_REP.REGIONAL AS REGIONAL,
					OUT_LC_PEPI_RESUMEN_REP.COD_SUCURSAL AS COD_SUCURSAL,
					OUT_LC_PEPI_RESUMEN_REP.COD_SUCURSAL || '-' || OUT_LC_PEPI_RESUMEN_REP.SUCURSAL AS SUCURSAL,
					OUT_LC_PEPI_RESUMEN_REP.COD_OFICINA AS COD_OFICINA,
					OUT_LC_PEPI_RESUMEN_REP.COD_OFICINA || '-' ||OUT_LC_PEPI_RESUMEN_REP.OFICINA AS OFICINA,
					OUT_LC_PEPI_RESUMEN_REP.NOMBRE AS NOMBRE,
					J.POS_CALLIDUS AS POS_CALLIDUS,
					ROUND(OUT_LC_PEPI_RESUMEN_REP.IMPORTE_ACUMULADO, 2) AS IMPORTE_ACUMULADO,
					OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA AS N_MEDIDA,
					CASE
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%998%' THEN 'TOTAL PRODUCTOS'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%997%' THEN 'TOTAL PRIORITARIOS'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND RIGHT(OUT_LC_PEPI_RESUMEN_REP.PERIODO,4) < 2020 THEN 'RRPP excl. PU/CC'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND 2019 < RIGHT(OUT_LC_PEPI_RESUMEN_REP.PERIODO,4) AND RIGHT(OUT_LC_PEPI_RESUMEN_REP.PERIODO,4) < 2024 THEN 'RRPP excluir Superplan'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%906%' AND 2024 < RIGHT(OUT_LC_PEPI_RESUMEN_REP.PERIODO,4) THEN 'RRPP'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%001%' THEN 'RRTT'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%002%' THEN 'HOGAR'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%003%' THEN 'VIDA-RIESGO'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%004%' THEN 'VIDA-AHORRO'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%005%' THEN 'ACCIDENTES'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%006%' THEN 'RESTO PRODUCTOS'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%007%' THEN 'OCASO ORO'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%008%' THEN 'COMUNIDADES'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%009%' THEN 'PYME EXPRESS'
						WHEN OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE '%Asegurados%' THEN 'ASEGURADOS'
					END AS FILAS_TABLA, --REVISAR QUE NO HAYA CASOS SOLAPADOS (ASEGURADOS%005 POR EJEMPLO)
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizas-%-TotalMes' OR OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalMes') THEN ROUND(OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_FIS_MES,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-%-TotalMes') THEN ROUND(OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_CORR_MES,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-Prima-%-TotalMes') THEN ROUND(OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_MES,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-PrimaCorregida-%-TotalMes') THEN ROUND(OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_CORR_MES,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizas-%-TotalAnual' OR OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalAnual') THEN ROUND(OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_FIS_ANUAL,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-%-TotalAnual') THEN ROUND(OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS POL_CORR_ANUAL,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-Prima-%-TotalAnual') THEN ROUND(OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_ANUAL,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA LIKE 'SM-O-GEN-Inspector-PrimaCorregida-%-TotalAnual') THEN ROUND(OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA, 2) ELSE 0 END AS PRIMAS_CORR_ANUAL,
					CASE WHEN SUBSTR(:v_period_name_format,6,2) = LPAD(TO_INTEGER(OUT_LC_PEPI_RESUMEN_REP.IMPORTE_ACUMULADO),2,'0') THEN IFNULL(ROUND(OUT_LC_PEPI_RESUMEN_REP.IMPORTE, 2),0) ELSE 0 END AS IMPORTE_MENSUAL,
					CASE WHEN (OUT_LC_PEPI_RESUMEN_REP.N_MEDIDA = 'Balance' AND SUBSTR(:v_period_name_format,6,2) <> '01') THEN 0 ELSE IFNULL(ROUND(OUT_LC_PEPI_RESUMEN_REP.IMPORTE, 2),0) END AS IMPORTE_ANUAL,
				 	ROUND(OUT_LC_PEPI_RESUMEN_REP.V_MEDIDA, 2) AS V_MEDIDA,
					OUT_LC_PEPI_RESUMEN_REP.NIF AS NIF,
					OUT_LC_PEPI_RESUMEN_REP.PERIODO AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					OUT_LC_PEPI_RESUMEN_REP.CUADRO_INSP AS CUADRO_INSP,
					OUT_LC_PEPI_RESUMEN_REP.EARNINGCODEID AS EARNINGCODEID,
					'LC' AS TIPO_CIERRE,
					'OCASO' AS COMPANIA,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					OUT_LC_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN AS POSITIONSEQ,
					OUT_LC_PEPI_RESUMEN_REP.PERIODSEQ,
					CASE WHEN (B.POSTPIPELINERUNDATE IS NULL OR B.POSTPIPELINERUNDATE > LAST_DAY(J.STARTDATE) )THEN 'SI' ELSE NULL END AS SOLO_DIFERENCIAS

				FROM EXT.OUT_LC_PEPI_RESUMEN_REP
				INNER JOIN CTE_JER J ON J.PERIODSEQ = OUT_LC_PEPI_RESUMEN_REP.PERIODSEQ
				    AND OUT_LC_PEPI_RESUMEN_REP.PARTICIPANTSEQ = J.PARTICIPANTSEQ
					AND OUT_LC_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = J.PERIODO
					AND F.TABLA = 'OUT_LC_PEPI_RESUMEN_REP'
				LEFT JOIN (SELECT X.PAYEESEQ,X.POSITIONSEQ,MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE FROM TCMP.CS_PAYMENT X
           			WHERE X.TENANTID = :v_idtenant AND X.PERIODSEQ = :i_PeriodSeq
           			GROUP BY X.PAYEESEQ, X.POSITIONSEQ) B
				ON B.PAYEESEQ = OUT_LC_PEPI_RESUMEN_REP.PARTICIPANTSEQ
    			AND B.POSITIONSEQ = OUT_LC_PEPI_RESUMEN_REP.POSITIONSEQ_PRIN
				WHERE 1=1
					AND J.PERIODSEQ = :i_PeriodSeq
					AND TO_INT(OUT_LC_PEPI_RESUMEN_REP.ID_TIPO_AGENTE) <> 79 -- DTB 20251126 Los 79-INSPECTOR OFICINA no se muestran
					;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_PEPI_RESUMEN_FINAL_REP. LC. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Creación Informe Percepciones S5 Resumen', i_log_count, i_id_proceso, 'info');
		
		--FIN informe S5 PERCEPCIONES RESUMEN
		END IF;
		
		---------------------------------------------------------------------------------------------------------------------------------------
		--Inicio informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN/DETALLE (RPA) -- todos los meses
		IF (:i_lista_informes = 'RPA' OR :i_lista_informes LIKE '%|RPA|%' OR :i_lista_informes LIKE '%|RPA' OR :i_lista_informes LIKE 'RPA|%' OR :i_lista_informes = 'ALL' )
			--AND SUBSTR_BEFORE(:v_period_name, ' ') NOT IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') --LLS 20251110: comentado
		    THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S4 RPA RESUMEN (Mensual)', i_log_count, i_id_proceso, 'info'); --LLS 20251112: añadido texto mensual

			--CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'No es fin de trimestre.', i_log_count, i_id_proceso, 'debug');--LLS 20251112: comentado
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_RPA_RESUMEN_FINAL_REP (Mensual)', i_log_count, i_id_proceso, 'debug'); --LLS 20251112: añadido texto mensual
			DELETE FROM EXT.OUT_S4_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_RPA_RESUMEN_FINAL_REP (Mensual). Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); --LLS 20251112: añadido texto mensual

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S4_RPA_RESUMEN_FINAL_REP (Mensual). CIERRE', i_log_count, i_id_proceso, 'debug'); --LLS 20251112: añadido texto mensual
			INSERT INTO EXT.OUT_S4_RPA_RESUMEN_FINAL_REP (COMPANYA,TIPO_PAGO,ORIGEN,PERIODSEQ,STARTDATE,PERIODO_ORIGINAL,PERIODO_CAMPO,PERIODO,QUARTER,POSITIONSEQ,N_MEDIDA,COMISION_RESUMEN,COMISION_OBJ,COMISION_PAGO,COMISION_REG,V_MEDIDA,CUMPLE_OBJ,POS_PRIN,NOMBRE,POS_CALLIDUS,AGENTE,POSITIONNAME,M_GN1,TIPO_AGENTE,ID_TIPO_AGENTE,NIF,NIF_NOMBRE,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO)
				SELECT DISTINCT 'OCASO' COMPANYA
					, TIPO_PAGO
					, ORIGEN
					, RPA.PERIODSEQ
					, STARTDATE 
					, PERIODO_ORIGINAL
					, RPA.PERIODO PERIODO_CAMPO
					, SUBSTR_AFTER(RPA.PERIODO, ' ') ||
										CASE WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Enero' THEN ' 01 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Febrero' THEN ' 02 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Marzo' THEN ' 03 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Abril' THEN ' 04 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Mayo' THEN ' 05 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Junio' THEN ' 06 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Julio' THEN ' 07 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Agosto' THEN ' 08 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Octubre' THEN ' 10 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
											WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
											END
										|| SUBSTR_BEFORE(RPA.PERIODO, ' ') PERIODO
					, QUARTER
					, POSITIONSEQ
					, N_MEDIDA
					, CASE	--tabla Tabla_Resumen_Total
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes' THEN 'Pólizas Corregidas'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN 'Prima Rappel'
							--tabla Tabla_Resumen_Productos
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-SinResto' THEN 'Periodo Actual'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-SinResto' THEN 'Periodo Actual'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Otros-Productos' THEN 'Periodo Actual'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-01503-AgNO20-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-Campania-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-Resto' THEN 'Contabilizadas para el Próximo Periodo'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-Resto' THEN 'Contabilizadas para el Próximo Periodo'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes-Resto' THEN 'Contabilizadas para el Próximo Periodo'
							ELSE NULL
						END COMISION_RESUMEN
					, CASE	--tabla Tabla_Objetivos
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN 'Aseg. RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' AND M_GN1 = 1 THEN 'RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' AND M_GN1 = 1 THEN 'Hogar'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-003-TotalMes' AND M_GN1 = 1 THEN 'Vida Riesgo'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-004-TotalMes' AND M_GN1 = 1 THEN 'Vida Ahorro'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-005-SINCC-TotalMes' AND M_GN1 = 1 THEN 'Accidentes Sin CC'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' AND M_GN1 = 1 THEN 'RRPP'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-997-TotalMes' AND M_GN1 = 1 THEN 'Productos Prioritarios'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' AND M_GN1 = 1 THEN 'Prima Total Productos'
							ELSE NULL
						END COMISION_OBJ
					, CASE	--tabla Tabla_Pago_Mensual
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-Mensual' THEN 'Importe Rappel'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' THEN 'Importe Rappel'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-SuperRappel-Pago-Mensual' AND YEAR <= 2022 THEN 'Importe Superrappel' --LLS 20251110: Añadida la condición de año
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' AND YEAR <= 2022 THEN 'Importe Superrappel' --LLS 20251110: Añadida la condición de año
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' THEN 'Importe Rappel XL/XXL'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' THEN 'Importe Rappel XL/XXL'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Pago-Fijo-Mensual' AND V_MEDIDA <> 0 THEN 'Incentivo Especial'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Pago-Fijo-Mensual' AND V_MEDIDA <> 0 THEN 'Incentivo Especial'
							ELSE NULL
						END COMISION_PAGO
					, CASE	--tabla Tabla_Trim_por_mes
						WHEN ((RPA.PERIODO LIKE 'Mar%' OR RPA.PERIODO LIKE 'Jun%' OR RPA.PERIODO LIKE 'Sep%' OR RPA.PERIODO LIKE 'Dic%')
							AND ((ID_TIPO_AGENTE IN (28, 32, 37, 38, 39, 40, 43, 44, 45, 49) AND YEAR < 2026) OR (ID_TIPO_AGENTE IN (28, 37, 38, 39, 40, 44, 45) AND YEAR >= 2026))) --DTB 20260422 No hay reg trim para ID 32, 43, 49
						THEN CASE
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN 'Aseg. RRTT'
							WHEN (YEAR < 2022 AND N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes') 
									OR (YEAR >= 2022 AND N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizasCorregidas-998-TotalMes' ) THEN 'Pólizas T.R.' --LLS 20251110: Corregido
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' THEN 'Pólizas RRTT'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' THEN 'Pólizas RRPP'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' THEN 'Pólizas Hogar'
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-007-TotalMes' AND YEAR >= 2022 THEN 'Pólizas Ocaso Oro' --LLS 20251110: Añadida la condición de año
							WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN 'Primas T.R.'
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251110: Añadida línea histórico
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251110: Añadida línea histórico
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251110: Añadida línea histórico
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251110: Añadida línea histórico
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251110: Añadida la condición de año
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251110: Añadida la condición de año
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251110: Añadida la condición de año
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251110: Añadida la condición de año
							--dato Cumple Objetivos Reg. Trim.
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-CumpleObjetivos-RegulTrimestral' AND YEAR >= 2022 THEN 'Cumple Objetivos Reg. Trim.' --LLS 20251110: Añadida la condición de año
							--tabla 
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-Importe-RegTrim' AND YEAR >= 2022 THEN 'Escalado Reg. Trim.' --LLS 20251110: Añadida la condición de año
							WHEN N_MEDIDA = 'SM-O-RPP-Agente-ImporteNeto-RegTrim' AND YEAR >= 2022 THEN 'Total Abono Reg. Trim.' --LLS 20251110: Añadida la condición de año

							ELSE NULL END
						ELSE NULL
						END COMISION_REG
					, ROUND(V_MEDIDA, 2) V_MEDIDA
					, CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-CumpleObjetivos-RegulTrimestral' AND V_MEDIDA = 1 THEN 'SI' ELSE 'NO' END CUMPLE_OBJ
					, POS_PRIN
					, NOMBRE
					, POS_CALLIDUS
					, RIGHT(POS_PRIN,4) ||' - '|| POS_CALLIDUS ||' - ' || NOMBRE AGENTE
					, POSITIONNAME
					, ROUND(M_GN1, 2) M_GN1
					, LAST_VALUE(TO_INTEGER(ID_TIPO_AGENTE) ||' - '|| TIPO_AGENTE) OVER (PARTITION BY POS_PRIN, RPA.PERIODO ORDER BY STARTDATE ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS TIPO_AGENTE
					, ID_TIPO_AGENTE
					, NIF
					, NIF || ' - ' || NOMBRE AS NIF_NOMBRE
					, FEC_ACTUALIZACION
					, TO_VARCHAR(FEC_ACTUALIZACION, 'DD/MM/YYYY') FEC_ACTUALIZACION_FORMATO

				FROM (	SELECT DISTINCT 'CIERRE' TIPO_PAGO
							,  'Cierre' ORIGEN
							, INYC_RPA_RESUMEN.PERIODSEQ
							, INYC_RPA_RESUMEN.STARTDATE 
							, INYC_RPA_RESUMEN.PERIODO PERIODO_ORIGINAL
							, INYC_RPA_RESUMEN.PERIODO
							, INYC_RPA_RESUMEN.YEAR --LLS 20251110: Incluido
							, INYC_RPA_RESUMEN.QUARTER
							, INYC_RPA_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ
							, INYC_RPA_RESUMEN.N_MEDIDA
							, INYC_RPA_RESUMEN.V_MEDIDA
							, INYC_RPA_RESUMEN.POS_PRIN
							, IFNULL(RTRIM(INYC_RPA_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.LASTNAME), '') NOMBRE
							, J.POS_CALLIDUS
							, INYC_RPA_RESUMEN.POSITIONNAME
							, INYC_RPA_RESUMEN.M_GN1
							, INYC_RPA_RESUMEN.ID_TIPO_AGENTE
							, INYC_RPA_RESUMEN.TIPO_AGENTE
							, INYC_RPA_RESUMEN.NIF
							, CASE WHEN F.ULTIMA_ACTUALIZACION > ADD_MONTHS(INYC_RPA_RESUMEN.STARTDATE, 1) 
								THEN LAST_DAY(INYC_RPA_RESUMEN.STARTDATE)
								ELSE F.ULTIMA_ACTUALIZACION
								END FEC_ACTUALIZACION
						
						FROM EXT.OUT_RPA_RESUMEN_REP INYC_RPA_RESUMEN
						
						INNER JOIN EXT.OUT_JERARQUIA_REP J
							ON INYC_RPA_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPA_RESUMEN.PERIODSEQ = J.PERIODSEQ
						
						LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F 
							ON F.PERIODO = INYC_RPA_RESUMEN.PERIODO
								AND F.TABLA = 'OUT_RPA_RESUMEN_REP'
						
						WHERE 1 = 1
							AND INYC_RPA_RESUMEN.N_MEDIDA NOT LIKE 'SM-O-RPP-Agente-Pago-Mes%Cuat'
							AND INYC_RPA_RESUMEN.PERIODSEQ = :i_PeriodSeq
							AND J.POSITIONSEQ = J.POSITIONSEQ_PRIN --LLS 20251124: Añadido para quitar posiciones secundarias

						) RPA;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S4_RPA_RESUMEN_FINAL_REP (Mensual). Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); --LLS 20251112: añadido texto mensual
			--CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Creación Informe Rappel Producción Agentes -S4- resumen', i_log_count, i_id_proceso, 'info'); --LLS 20251112: comentado

			--FIN informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN (RPA)
			--END IF; --LLS 20251110: comentado

			------------------------------------------------------------------------------------------------------------------------
			--Inicio informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN (RPA) -- si fin de trimestre y año >=2022
			IF --(:i_lista_informes = 'RPA' OR :i_lista_informes LIKE '%|RPA|%' OR :i_lista_informes LIKE '%|RPA' OR :i_lista_informes LIKE 'RPA|%' OR :i_lista_informes = 'ALL' )
				--AND --LLS 20251110: comentado
				SUBSTR_BEFORE(:v_period_name, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
				AND SUBSTR_AFTER(:v_period_name, ' ') >= 2022 --LLS 20251110: Añadido
			THEN
				
				--CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info'); --LLS 20251112: comentado
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S4 RPA RESUMEN (Trimestre)', i_log_count, i_id_proceso, 'info'); --LLS 20251112: añadido texto Trimestre

				--CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Sí es fin de trimestre.', i_log_count, i_id_proceso, 'debug'); --LLS 20251112: comentado
				
				--Borrado del periodo en los datos de cierre --LLS 20251112: comentado
				--CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. PeriodSeq ' || i_PeriodSeq, i_log_count, i_id_proceso, 'debug');
				--DELETE FROM EXT.OUT_S4_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq AND ORIGEN = 'Cierre';
				--v_num_rows := ::ROWCOUNT;
				--CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
				
				--Borrado del periodo-1 en los datos de balance
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. PeriodSeq-1 ' || v_PeriodSeq_1, i_log_count, i_id_proceso, 'debug');
				DELETE FROM EXT.OUT_S4_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :v_PeriodSeq_1 AND ORIGEN = 'Balance';
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. Filas borradas PeriodSeq-1: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); --LLS 20251112: añadido PeriodSeq-1
				
				--Borrado del periodo-2 en los datos de balance
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. PeriodSeq-2 ' || v_PeriodSeq_2, i_log_count, i_id_proceso, 'debug');
				DELETE FROM EXT.OUT_S4_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :v_PeriodSeq_2 AND ORIGEN = 'Balance';
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S4_RPA_RESUMEN_FINAL_REP. Filas borradas PeriodSeq-2: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); --LLS 20251112: añadido PeriodSeq-1

				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S4_RPA_RESUMEN_FINAL_REP (Trimestre). CIERRE', i_log_count, i_id_proceso, 'debug');--LLS 20251112: añadido texto Trimestre
				INSERT INTO EXT.OUT_S4_RPA_RESUMEN_FINAL_REP (COMPANYA,TIPO_PAGO,ORIGEN,PERIODSEQ,STARTDATE,PERIODO_ORIGINAL,PERIODO_CAMPO,PERIODO,QUARTER,POSITIONSEQ,N_MEDIDA,COMISION_RESUMEN,COMISION_OBJ,COMISION_PAGO,COMISION_REG,V_MEDIDA,CUMPLE_OBJ,POS_PRIN,NOMBRE,POS_CALLIDUS,AGENTE,POSITIONNAME,M_GN1,TIPO_AGENTE,ID_TIPO_AGENTE,NIF,NIF_NOMBRE,FEC_ACTUALIZACION,FEC_ACTUALIZACION_FORMATO)
					SELECT DISTINCT 'OCASO' COMPANYA
						, TIPO_PAGO
						, ORIGEN
						, RPA.PERIODSEQ
						, STARTDATE 
						, PERIODO_ORIGINAL
						, RPA.PERIODO PERIODO_CAMPO
						, SUBSTR_AFTER(RPA.PERIODO, ' ') ||
											CASE WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Enero' THEN ' 01 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Febrero' THEN ' 02 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Marzo' THEN ' 03 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Abril' THEN ' 04 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Mayo' THEN ' 05 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Junio' THEN ' 06 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Julio' THEN ' 07 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Agosto' THEN ' 08 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Octubre' THEN ' 10 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
												WHEN SUBSTR_BEFORE(RPA.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
												END
											|| SUBSTR_BEFORE(RPA.PERIODO, ' ') PERIODO
						, QUARTER
						, POSITIONSEQ
						, N_MEDIDA
						, CASE	--tabla Tabla_Resumen_Total
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes' THEN 'Pólizas Corregidas'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN 'Prima Rappel'
								--tabla Tabla_Resumen_Productos
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-SinResto' THEN 'Periodo Actual'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-SinResto' THEN 'Periodo Actual'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Otros-Productos' THEN 'Periodo Actual'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-01503-AgNO20-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-Campania-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Resto-Mes-Anterior' THEN 'Contabilizadas en el Periodo Anterior'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-Resto' THEN 'Contabilizadas para el Próximo Periodo'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-Resto' THEN 'Contabilizadas para el Próximo Periodo'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes-Resto' THEN 'Contabilizadas para el Próximo Periodo'
								ELSE NULL
							END COMISION_RESUMEN
						, CASE	--tabla Tabla_Objetivos
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN 'Aseg. RRTT'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' AND M_GN1 = 1 THEN 'RRTT'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' AND M_GN1 = 1 THEN 'Hogar'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-003-TotalMes' AND M_GN1 = 1 THEN 'Vida Riesgo'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-004-TotalMes' AND M_GN1 = 1 THEN 'Vida Ahorro'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-005-SINCC-TotalMes' AND M_GN1 = 1 THEN 'Accidentes Sin CC'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' AND M_GN1 = 1 THEN 'RRPP'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-997-TotalMes' AND M_GN1 = 1 THEN 'Productos Prioritarios'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' AND M_GN1 = 1 THEN 'Prima Total Productos'
								ELSE NULL
							END COMISION_OBJ
						, CASE	--tabla Tabla_Pago_Mensual
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-Mensual' THEN 'Importe Rappel'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' THEN 'Importe Rappel'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-SuperRappel-Pago-Mensual' AND YEAR <= 2022 THEN 'Importe Superrappel' --LLS 20251110: Añadida la condición de año
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' AND YEAR <= 2022 THEN 'Importe Superrappel' --LLS 20251110: Añadida la condición de año
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' THEN 'Importe Rappel XL/XXL'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' THEN 'Importe Rappel XL/XXL'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Pago-Fijo-Mensual' AND V_MEDIDA <> 0 THEN 'Incentivo Especial'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Pago-Fijo-Mensual' AND V_MEDIDA <> 0 THEN 'Incentivo Especial'
								ELSE NULL
							END COMISION_PAGO
						, CASE	--tabla Tabla_Trim_por_mes
							WHEN ((RPA.PERIODO LIKE 'Mar%' OR RPA.PERIODO LIKE 'Jun%' OR RPA.PERIODO LIKE 'Sep%' OR RPA.PERIODO LIKE 'Dic%')
								AND ((ID_TIPO_AGENTE IN (28, 32, 37, 38, 39, 40, 43, 44, 45, 49) AND YEAR < 2026) OR (ID_TIPO_AGENTE IN (28, 37, 38, 39, 40, 44, 45) AND YEAR >= 2026))) --DTB 20260422 No hay reg trim para ID 32, 43, 49
							THEN CASE
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN 'Aseg. RRTT'
								WHEN (YEAR < 2022 AND N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes') 
										OR (YEAR >= 2022 AND N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizasCorregidas-998-TotalMes' ) THEN 'Pólizas T.R.' --LLS 20251110: Corregido
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' THEN 'Pólizas RRTT'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' THEN 'Pólizas RRPP'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' THEN 'Pólizas Hogar'
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-007-TotalMes' AND YEAR >= 2022 THEN 'Pólizas Ocaso Oro' --LLS 20251110: Añadida la condición de año
								WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN 'Primas T.R.'
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251110: Añadida línea histórico
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251110: Añadida línea histórico
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251110: Añadida línea histórico
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' AND YEAR < 2022 THEN 'Pago Mensual' --LLS 20251110: Añadida línea histórico
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251110: Añadida la condición de año
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251110: Añadida la condición de año
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXXL' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251110: Añadida la condición de año
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Rappel-Pago-MensualXL' AND YEAR >= 2022 THEN 'Rappel Abonado Trimestre' --LLS 20251110: Añadida la condición de año
								--dato Cumple Objetivos Reg. Trim.
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-CumpleObjetivos-RegulTrimestral' AND YEAR >= 2022 THEN 'Cumple Objetivos Reg. Trim.' --LLS 20251110: Añadida la condición de año
								--tabla 
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-Importe-RegTrim' AND YEAR >= 2022 THEN 'Escalado Reg. Trim.' --LLS 20251110: Añadida la condición de año
								WHEN N_MEDIDA = 'SM-O-RPP-Agente-ImporteNeto-RegTrim' AND YEAR >= 2022 THEN 'Total Abono Reg. Trim.' --LLS 20251110: Añadida la condición de año

								ELSE NULL END
							ELSE NULL
							END COMISION_REG
						, ROUND(V_MEDIDA, 2) V_MEDIDA
						, CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-CumpleObjetivos-RegulTrimestral' AND V_MEDIDA = 1 THEN 'SI' ELSE 'NO' END CUMPLE_OBJ
						, POS_PRIN
						, NOMBRE
						, POS_CALLIDUS
						, RIGHT(POS_PRIN,4) ||' - '|| POS_CALLIDUS ||' - ' || NOMBRE AGENTE
						, POSITIONNAME
						, ROUND(M_GN1, 2) M_GN1
						, LAST_VALUE(TO_INTEGER(ID_TIPO_AGENTE) ||' - '|| TIPO_AGENTE) OVER (PARTITION BY POS_PRIN, RPA.PERIODO ORDER BY STARTDATE ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS TIPO_AGENTE
						, ID_TIPO_AGENTE
						, NIF
						, NIF || ' - ' || NOMBRE AS NIF_NOMBRE
						, FEC_ACTUALIZACION
						, TO_VARCHAR(FEC_ACTUALIZACION, 'DD/MM/YYYY') FEC_ACTUALIZACION_FORMATO

					FROM (SELECT DISTINCT  'CIERRE' TIPO_PAGO
								,  'Balance' ORIGEN
								, INYC_RPA_RESUMEN.PERIODSEQ
								, INYC_RPA_RESUMEN.STARTDATE 
								, INYC_RPA_RESUMEN.PERIODO PERIODO_ORIGINAL
								, CASE WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Enero' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Febrero'
										THEN 'Marzo ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
									WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Abril' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Mayo'
										THEN 'Junio ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
									WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Julio' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Agosto'
										THEN 'Septiembre ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
									WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Octubre' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Noviembre'
										THEN 'Diciembre ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
									END PERIODO
								, INYC_RPA_RESUMEN.YEAR --LLS 20251110: Incluido
								, INYC_RPA_RESUMEN.QUARTER
								, INYC_RPA_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ
								, INYC_RPA_RESUMEN.N_MEDIDA
								, INYC_RPA_RESUMEN.V_MEDIDA
								, INYC_RPA_RESUMEN.POS_PRIN
								, IFNULL(RTRIM(INYC_RPA_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.LASTNAME), '') NOMBRE
								, J.POS_CALLIDUS
								, INYC_RPA_RESUMEN.POSITIONNAME
								, INYC_RPA_RESUMEN.M_GN1
								, INYC_RPA_RESUMEN.ID_TIPO_AGENTE
								, INYC_RPA_RESUMEN.TIPO_AGENTE
								, INYC_RPA_RESUMEN.NIF
								, NULL FEC_ACTUALIZACION
							FROM EXT.OUT_BAL_RPA_RESUMEN_REP INYC_RPA_RESUMEN
							INNER JOIN EXT.OUT_JERARQUIA_REP J
								ON INYC_RPA_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
									AND INYC_RPA_RESUMEN.PERIODSEQ = J.PERIODSEQ
							WHERE 1 = 1
								AND INYC_RPA_RESUMEN.N_MEDIDA NOT LIKE 'SM-O-RPP-Agente-Pago-Mes%Cuat'
								AND INYC_RPA_RESUMEN.ID_TIPO_AGENTE IN (28,32,37,38,39,40,42,43,44,45,49)
								AND SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') NOT IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
								AND INYC_RPA_RESUMEN.PERIODSEQ = :v_PeriodSeq_1
								AND J.POSITIONSEQ = J.POSITIONSEQ_PRIN --LLS 20251124: Añadido para quitar posiciones secundarias

							UNION ALL

							SELECT DISTINCT  'CIERRE' TIPO_PAGO
								,  'Balance' ORIGEN
								, INYC_RPA_RESUMEN.PERIODSEQ
								, INYC_RPA_RESUMEN.STARTDATE 
								, INYC_RPA_RESUMEN.PERIODO PERIODO_ORIGINAL
								, CASE WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Enero' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Febrero'
										THEN 'Marzo ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
									WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Abril' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Mayo'
										THEN 'Junio ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
									WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Julio' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Agosto'
										THEN 'Septiembre ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
									WHEN SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Octubre' OR SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') = 'Noviembre'
										THEN 'Diciembre ' || SUBSTR_AFTER(INYC_RPA_RESUMEN.PERIODO, ' ')
									END PERIODO
								, INYC_RPA_RESUMEN.YEAR --LLS 20251110: Incluido
								, INYC_RPA_RESUMEN.QUARTER
								, INYC_RPA_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ
								, INYC_RPA_RESUMEN.N_MEDIDA
								, INYC_RPA_RESUMEN.V_MEDIDA
								, INYC_RPA_RESUMEN.POS_PRIN
								, IFNULL(RTRIM(INYC_RPA_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPA_RESUMEN.LASTNAME), '') NOMBRE
								, J.POS_CALLIDUS
								, INYC_RPA_RESUMEN.POSITIONNAME
								, INYC_RPA_RESUMEN.M_GN1
								, INYC_RPA_RESUMEN.ID_TIPO_AGENTE
								, INYC_RPA_RESUMEN.TIPO_AGENTE
								, INYC_RPA_RESUMEN.NIF
								, NULL FEC_ACTUALIZACION
							FROM EXT.OUT_BAL_RPA_RESUMEN_REP INYC_RPA_RESUMEN
							INNER JOIN EXT.OUT_JERARQUIA_REP J
								ON INYC_RPA_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
									AND INYC_RPA_RESUMEN.PERIODSEQ = J.PERIODSEQ
							WHERE 1 = 1
								AND INYC_RPA_RESUMEN.N_MEDIDA NOT LIKE 'SM-O-RPP-Agente-Pago-Mes%Cuat'
								AND INYC_RPA_RESUMEN.ID_TIPO_AGENTE IN (28,32,37,38,39,40,42,43,44,45,49)
								AND SUBSTR_BEFORE(INYC_RPA_RESUMEN.PERIODO, ' ') NOT IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
								AND INYC_RPA_RESUMEN.PERIODSEQ = :v_PeriodSeq_2
								AND J.POSITIONSEQ = J.POSITIONSEQ_PRIN --LLS 20251124: Añadido para quitar posiciones secundarias

							) RPA
							--DTB 20260422 Solo se muestran datos si existe en el periodo actual
							WHERE RPA.POS_CALLIDUS IN (SELECT DISTINCT POS_CALLIDUS FROM EXT.OUT_S4_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq); 
				
				v_num_rows := ::ROWCOUNT;
				
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S4_RPA_RESUMEN_FINAL_REP (Trimestre). Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');--LLS 20251112: añadido texto Trimestre
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Creación Informe Rappel Producción Agentes -S4- resumen', i_log_count, i_id_proceso, 'info');
			--FIN informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN (RPA)
			
			--DTB 20260423 Nuevo update
			UPDATE EXT.OUT_S4_RPA_RESUMEN_FINAL_REP t
				SET (TIPO_AGENTE, ID_TIPO_AGENTE)
					= (SELECT
						MAX(CASE WHEN s.PERIODO_CAMPO = s.PERIODO_ORIGINAL THEN s.TIPO_AGENTE ELSE NULL END),
						MAX(CASE WHEN s.PERIODO_CAMPO = s.PERIODO_ORIGINAL THEN s.ID_TIPO_AGENTE ELSE NULL END)
					FROM EXT.OUT_S4_RPA_RESUMEN_FINAL_REP s
					WHERE s.POS_CALLIDUS = t.POS_CALLIDUS
					AND s.PERIODO = t.PERIODO
					GROUP BY s.POS_CALLIDUS, s.PERIODO)
				WHERE t.PERIODO = :v_period_name_format;

			UPDATE EXT.OUT_S4_RPA_RESUMEN_FINAL_REP
				SET COMISION_REG =
					CASE
						WHEN (ID_TIPO_AGENTE IN (28, 32, 37, 38, 39, 40, 43, 44, 45, 49) AND LEFT(PERIODO, 4) < 2026)
							OR (ID_TIPO_AGENTE IN (28, 37, 38, 39, 40, 44, 45) AND LEFT(PERIODO, 4) >= 2026) --DTB 20260423 No hay reg trim para ID 32, 43, 49
						THEN COMISION_REG
						ELSE NULL
					END
				WHERE PERIODO = :v_period_name_format;
			
			-- DTB 20260423 Fin del cambio

			END IF;

            --BRG BAL
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S4 BAL RPA RESUMEN', i_log_count, i_id_proceso, 'info');

            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_BAL_RPA_RESUMEN_FINAL_REP', i_log_count, i_id_proceso, 'debug'); 
			DELETE FROM EXT.OUT_BAL_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_BAL_RPA_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); 

            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_BAL_RPA_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug'); 
			INSERT INTO EXT.OUT_BAL_RPA_RESUMEN_FINAL_REP (PERIODO_FILTRO, PERIODO_FORMATO, PERIODO_TABLA, POS_PRIN, NOMBRE, NIF, NIF_NOMBRE, TIPO_AGENTE, POL_CORR, PRIMA_RAPPEL, PROD_PERIODO_ACTUAL, PROD_PERIODO_ANTERIOR, PROD_PERIODO_PROXIMO, ASEG_RRTT, RRTT, HOGAR, VIDA_RIESGO, VIDA_AHORRO, ACCIDENTES_SIN_CC, RRPP, PRODUCTOS_PRIORITARIOS, IMPORTE_RAPPEL, IMPORTE_SUPERRAPPEL, IMPORTE_RAPPEL_XL, INCENTIVO_ESPECIAL, POLIZAS_TR, OCASO_ORO, CUMPLE_OBJ, RAPPEL_ABONADO_TRIMESTRE, ESCALADO_REG_TRIM, TOTAL_ABONO_REG_TRIM, IGUALES, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, POSITIONSEQ, PERIODSEQ, REG_TRIM)
                WITH QUERY_ORACLE AS (
                    SELECT DISTINCT
                        BAL_RPA_RESUMEN.PERIODO, --Period Name
                        BAL_RPA_RESUMEN.N_MEDIDA, --GENERICATTRIBUTE12
                        BAL_RPA_RESUMEN.V_MEDIDA, --GENERICNUMBER5
                        BAL_RPA_RESUMEN.POS_PRIN, --GENERICATTRIBUTE1
                        BAL_RPA_RESUMEN.LASTNAME, --GENERICATTRIBUTE2
                        BAL_RPA_RESUMEN.FIRSTNAME, --GENERICATTRIBUTE3
                        BAL_RPA_RESUMEN.MIDDLENAME, --GENERICATTRIBUTE4
                        BAL_RPA_RESUMEN.POSITIONNAME, --GENERICATTRIBUTE5
                        BAL_RPA_RESUMEN.M_GN1, --GENERICNUMBER1
                        BAL_RPA_RESUMEN.ID_TIPO_AGENTE, --GENERICNUMBER2
                        BAL_RPA_RESUMEN.TIPO_AGENTE, --GENERICATTRIBUTE6
                        BAL_RPA_RESUMEN.QUARTER, --Quarter
                        BAL_RPA_RESUMEN.STARTDATE, --GENERICDATE1
                        BAL_RPA_RESUMEN.NIF, --GENERICATTRIBUTE8
                        CASE
                            WHEN B.POSTPIPELINERUNDATE IS NULL OR B.POSTPIPELINERUNDATE > LAST_DAY(:v_period_startdate)
                                THEN 'SI'
                            ELSE NULL
                            END AS SOLO_DIFERENCIAS,
                        BAL_RPA_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ
                    FROM EXT.OUT_BAL_RPA_RESUMEN_REP BAL_RPA_RESUMEN
                        --Todas las reglas de balances de los meses anteriores al cierre menos la de pagos
                    LEFT JOIN (SELECT X.PAYEESEQ,X.POSITIONSEQ,MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE FROM TCMP.CS_PAYMENT X
                                WHERE X.PERIODSEQ = :i_PeriodSeq
                                GROUP BY X.PAYEESEQ,X.POSITIONSEQ, X.PERIODSEQ
                        ) B ON B.PAYEESEQ = BAL_RPA_RESUMEN.PARTICIPANTSEQ
                        AND B.POSITIONSEQ = BAL_RPA_RESUMEN.POSITIONSEQ_PRIN
                    -- Periodo en trimestre actual
                    WHERE BAL_RPA_RESUMEN.QUARTER = :v_period_quarter
                        -- Según el tipo de agente
                        AND (
                            (BAL_RPA_RESUMEN.ID_TIPO_AGENTE IN (28,32,37,38,39,40,42,43,44,45,49)
                            -- Periodo anterior que el actual
                            AND BAL_RPA_RESUMEN.STARTDATE <= :v_period_startdate)
                            OR 
                            (BAL_RPA_RESUMEN.ID_TIPO_AGENTE NOT IN (28,32,37,38,39,40,42,43,44,45,49)
                            -- Periodo actual
                            AND BAL_RPA_RESUMEN.PERIODSEQ = :i_PeriodSeq)
                        )
                        -- Sólo las posiciones que hayan tenido BAL en el mes actual
                        AND BAL_RPA_RESUMEN.POS_PRIN IN (SELECT DISTINCT POS_PRIN FROM EXT.OUT_BAL_RPA_RESUMEN_REP WHERE PERIODO = :v_period_name)
                )
                SELECT
                    --Cabecera
                    :v_period_name AS PERIODO_FILTRO,
                    :v_period_name_format AS PERIODO_FORMATO,
                    QO.PERIODO AS PERIODO_TABLA,
                    POS_PRIN,
                    TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
                    NIF,
                    NIF || ' - ' || TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NIF_NOMBRE,
                    TO_INTEGER(FIRST_VALUE(ID_TIPO_AGENTE) OVER (PARTITION BY POS_PRIN ORDER BY STARTDATE DESC)) || ' - ' || FIRST_VALUE(TIPO_AGENTE) OVER (PARTITION BY POS_PRIN ORDER BY STARTDATE DESC) AS TIPO_AGENTE,
                    
                    --Resumen Mensual
                    --Pólizas
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes' THEN V_MEDIDA ELSE 0 END) AS POL_CORR,
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN V_MEDIDA ELSE 0 END) AS PRIMA_RAPPEL, --Prima Total Productos --Reg Trim 7
                    --Productos
                    SUM(CASE WHEN N_MEDIDA IN (
                        'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-SinResto', 'SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-SinResto','SM-O-RPP-Agente-NumeroPolizas-998-Otros-Productos'
                        ) THEN V_MEDIDA ELSE 0 END) AS PROD_PERIODO_ACTUAL,
                    SUM(CASE WHEN N_MEDIDA IN (
                        'SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-01503-AgNO20-Mes-Anterior','SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-Campania-Mes-Anterior','SM-O-RPP-Agente-NumeroPolizas-998-Resto-Mes-Anterior'
                    ) THEN V_MEDIDA ELSE 0 END) AS PROD_PERIODO_ANTERIOR,
                    SUM(CASE WHEN N_MEDIDA IN (
                        'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-Resto','SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-Resto','SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes-Resto'
                    ) THEN V_MEDIDA ELSE 0 END) AS PROD_PERIODO_PROXIMO,
                    -- Objetivos Mínimos
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN V_MEDIDA ELSE 0 END) AS ASEG_RRTT, --Reg Trim 1
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' THEN V_MEDIDA ELSE 0 END) AS RRTT, --Reg Trim 3
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' THEN V_MEDIDA ELSE 0 END) AS HOGAR, --Reg Trim 5
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-003-TotalMes' THEN V_MEDIDA ELSE 0 END) AS VIDA_RIESGO,
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-004-TotalMes' THEN V_MEDIDA ELSE 0 END) AS VIDA_AHORRO,
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-005-SINCC-TotalMes' THEN V_MEDIDA ELSE 0 END) AS ACCIDENTES_SIN_CC,
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' THEN V_MEDIDA ELSE 0 END) AS RRPP, --Reg Trim 4
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-997-TotalMes' THEN V_MEDIDA ELSE 0 END) AS PRODUCTOS_PRIORITARIOS,

                    --Pago Mensual
                    SUM(CASE WHEN N_MEDIDA IN ('SM-O-RPP-Agente-Rappel-Pago-Mensual','SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual') THEN V_MEDIDA ELSE 0 END) AS IMPORTE_RAPPEL,
                    SUM(CASE WHEN N_MEDIDA IN ('SM-O-RPP-Agente-SuperRappel-Pago-Mensual','SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual') THEN V_MEDIDA ELSE 0 END) AS IMPORTE_SUPERRAPPEL,
                    SUM(CASE WHEN N_MEDIDA IN ('SM-O-RPP-Agente-Rappel-Pago-MensualXXL', 'SM-O-RPP-Agente-Rappel-Pago-MensualXL') THEN V_MEDIDA ELSE 0 END) AS IMPORTE_RAPPEL_XL,
                    SUM(CASE WHEN N_MEDIDA IN ('SM-O-RPP-Agente-Pago-Fijo-Mensual', 'SM-O-RPP-Agente-N2N3-Pago-Fijo-Mensual') THEN V_MEDIDA ELSE 0 END) AS INCENTIVO_ESPECIAL,
                    
                    --Regularización Trimestral (el resto están ya calculadas)
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizasCorregidas-998-TotalMes' THEN V_MEDIDA ELSE 0 END) AS POLIZAS_TR, --Reg Trim 2
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-007-TotalMes' THEN V_MEDIDA ELSE 0 END) AS OCASO_ORO, --Reg Trim 6
                    CASE WHEN LEFT(QO.PERIODO, LENGTH(QO.PERIODO)-5) IN ('Marzo','Junio','Septiembre', 'Diciembre')
                        THEN (CASE WHEN SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-CumpleObjetivos-RegulTrimestral' THEN V_MEDIDA ELSE 0 END) = 1
                            THEN 'SI'
                            ELSE 'NO'
                            END)
                        ELSE ' '
                        END AS CUMPLE_OBJ, --Reg Trim 8
                    SUM(CASE WHEN N_MEDIDA IN (
                        'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual','SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual','SM-O-RPP-Agente-Rappel-Pago-MensualXXL','SM-O-RPP-Agente-Rappel-Pago-MensualXL'
                        'SM-O-RPP-Agente-Rappel-Pago-Mensual', 'SM-O-RPP-Agente-SuperRappel-Pago-Mensual', 'SM-O-RPP-Agente-Rappel-Pago-MensualXL', 'SM-O-RPP-Agente-Pago-Fijo-Mensual'
                        ) THEN V_MEDIDA ELSE 0 END) AS RAPPEL_ABONADO_TRIMESTRE, --Reg Trim 9
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-Importe-RegTrim' THEN V_MEDIDA ELSE 0 END) AS ESCALADO_REG_TRIM, --Reg Trim 10
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-ImporteNeto-RegTrim' THEN V_MEDIDA ELSE 0 END) AS TOTAL_ABONO_REG_TRIM, --Reg Trim 11
                    
                    --Filtros
                    CASE WHEN QO.PERIODO = :v_period_name
                        THEN 'SI'
                        ELSE 'NO'
                    END AS IGUALES,
                    SOLO_DIFERENCIAS,
                    TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
                    POSITIONSEQ,
                    :i_PeriodSeq AS PERIODSEQ,
					--DTB 20260424 Nuevo campo REG_TRIM para filtrar los agentes que tienen regulación trimestral
					CASE
						WHEN
							(:v_period_year >= 2026
								AND TO_INTEGER(FIRST_VALUE(ID_TIPO_AGENTE) OVER (PARTITION BY POS_PRIN ORDER BY STARTDATE DESC)) IN (28,37,38,39,40,42,44,45))
							OR ((:v_period_year < 2026
								AND TO_INTEGER(FIRST_VALUE(ID_TIPO_AGENTE) OVER (PARTITION BY POS_PRIN ORDER BY STARTDATE DESC)) IN (28,32,37,38,39,40,42,43,44,45,49)))
						THEN 'SI'
						ELSE 'NO'
					END AS REG_TRIM
                FROM QUERY_ORACLE QO
                LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
                    AND F.TABLA = 'OUT_BAL_RPA_RESUMEN_REP'
                GROUP BY QO.PERIODO, POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, ID_TIPO_AGENTE, TIPO_AGENTE, 
                    SOLO_DIFERENCIAS, POSITIONSEQ, F.ULTIMA_ACTUALIZACION, STARTDATE;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_BAL_RPA_RESUMEN_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); 
			
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe S4 BAL RPA RESUMEN', i_log_count, i_id_proceso, 'info');

            --BRG LC
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S4 LC RPA RESUMEN', i_log_count, i_id_proceso, 'info');

            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_LC_RPA_RESUMEN_FINAL_REP', i_log_count, i_id_proceso, 'debug'); 
			DELETE FROM EXT.OUT_LC_RPA_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_LC_RPA_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); 

            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_LC_RPA_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug'); 
			INSERT INTO EXT.OUT_LC_RPA_RESUMEN_FINAL_REP (PERIODO_FILTRO, PERIODO_FORMATO, PERIODO_TABLA, POS_PRIN, NOMBRE, NIF, NIF_NOMBRE, TIPO_AGENTE, POL_CORR, PRIMA_RAPPEL, PROD_PERIODO_ACTUAL, PROD_PERIODO_ANTERIOR, PROD_PERIODO_PROXIMO, ASEG_RRTT, RRTT, HOGAR, VIDA_RIESGO, VIDA_AHORRO, ACCIDENTES_SIN_CC, RRPP, PRODUCTOS_PRIORITARIOS, IMPORTE_RAPPEL, IMPORTE_SUPERRAPPEL, IMPORTE_RAPPEL_XL, INCENTIVO_ESPECIAL, POLIZAS_TR, OCASO_ORO, CUMPLE_OBJ, RAPPEL_ABONADO_TRIMESTRE, ESCALADO_REG_TRIM, TOTAL_ABONO_REG_TRIM, IGUALES, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, POSITIONSEQ, PERIODSEQ)
				WITH QUERY_ORACLE AS (
                    SELECT
                        LC_RPA_RESUMEN.PERIODO, --Period Name
                        LC_RPA_RESUMEN.N_MEDIDA, --GENERICATTRIBUTE12
                        LC_RPA_RESUMEN.V_MEDIDA, --GENERICNUMBER5
                        LC_RPA_RESUMEN.POS_PRIN, --GENERICATTRIBUTE1
                        LC_RPA_RESUMEN.LASTNAME, --GENERICATTRIBUTE2
                        LC_RPA_RESUMEN.FIRSTNAME, --GENERICATTRIBUTE3
                        LC_RPA_RESUMEN.MIDDLENAME, --GENERICATTRIBUTE4
                        LC_RPA_RESUMEN.POSITIONNAME, --GENERICATTRIBUTE5
                        LC_RPA_RESUMEN.M_GN1, --GENERICNUMBER1
                        LC_RPA_RESUMEN.ID_TIPO_AGENTE, --GENERICNUMBER2
                        LC_RPA_RESUMEN.TIPO_AGENTE, --GENERICATTRIBUTE6
                        LC_RPA_RESUMEN.QUARTER, --Quarter
                        LC_RPA_RESUMEN.STARTDATE, --GENERICDATE1
                        LC_RPA_RESUMEN.NIF, --GENERICATTRIBUTE8
                        CASE WHEN B.POSTPIPELINERUNDATE IS NULL OR B.POSTPIPELINERUNDATE > LAST_DAY(LC_RPA_RESUMEN.STARTDATE)
                            THEN 'SI'
                        ELSE NULL
                        END AS SOLO_DIFERENCIAS,
                        LC_RPA_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ
                    FROM EXT.OUT_LC_RPA_RESUMEN_REP LC_RPA_RESUMEN
                    LEFT JOIN (SELECT X.PAYEESEQ,X.POSITIONSEQ,MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE, X.PERIODSEQ FROM TCMP.CS_PAYMENT X
                            GROUP BY X.PAYEESEQ, X.POSITIONSEQ, X.PERIODSEQ
                        ) B ON B.PAYEESEQ = LC_RPA_RESUMEN.PARTICIPANTSEQ
                        AND B.POSITIONSEQ = LC_RPA_RESUMEN.POSITIONSEQ_PRIN
                        AND B.PERIODSEQ = LC_RPA_RESUMEN.PERIODSEQ
                    --Periodo actual
                    WHERE LC_RPA_RESUMEN.PERIODSEQ = :i_PeriodSeq

                    UNION ALL

                    SELECT
                        BAL_RPA_RESUMEN.PERIODO, --Period Name
                        BAL_RPA_RESUMEN.N_MEDIDA, --GENERICATTRIBUTE12
                        BAL_RPA_RESUMEN.V_MEDIDA, --GENERICNUMBER5
                        BAL_RPA_RESUMEN.POS_PRIN, --GENERICATTRIBUTE1
                        BAL_RPA_RESUMEN.LASTNAME, --GENERICATTRIBUTE2
                        BAL_RPA_RESUMEN.FIRSTNAME, --GENERICATTRIBUTE3
                        BAL_RPA_RESUMEN.MIDDLENAME, --GENERICATTRIBUTE4
                        BAL_RPA_RESUMEN.POSITIONNAME, --GENERICATTRIBUTE5
                        BAL_RPA_RESUMEN.M_GN1, --GENERICNUMBER1
                        BAL_RPA_RESUMEN.ID_TIPO_AGENTE, --GENERICNUMBER2
                        BAL_RPA_RESUMEN.TIPO_AGENTE, --GENERICATTRIBUTE6
                        BAL_RPA_RESUMEN.QUARTER, --Quarter
                        BAL_RPA_RESUMEN.STARTDATE, --GENERICDATE1
                        BAL_RPA_RESUMEN.NIF, --GENERICATTRIBUTE8
                        CASE
                            WHEN B.POSTPIPELINERUNDATE IS NULL OR B.POSTPIPELINERUNDATE > LAST_DAY(:v_period_startdate)
                                THEN 'SI'
                            ELSE NULL
                            END AS SOLO_DIFERENCIAS,
                        BAL_RPA_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ
                    FROM EXT.OUT_BAL_RPA_RESUMEN_REP BAL_RPA_RESUMEN
                        --Todas las reglas de balances de los meses anteriores al cierre menos la de pagos
                    LEFT JOIN (SELECT X.PAYEESEQ,X.POSITIONSEQ,MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE FROM TCMP.CS_PAYMENT X
                                WHERE X.PERIODSEQ = :i_PeriodSeq
                                GROUP BY X.PAYEESEQ,X.POSITIONSEQ, X.PERIODSEQ
                        ) B ON B.PAYEESEQ = BAL_RPA_RESUMEN.PARTICIPANTSEQ
                        AND B.POSITIONSEQ = BAL_RPA_RESUMEN.POSITIONSEQ_PRIN
                    WHERE
                        -- Periodo en trimestre actual
                        BAL_RPA_RESUMEN.QUARTER = :v_period_quarter
                        AND
                        -- Según el tipo de agente
                        ((BAL_RPA_RESUMEN.ID_TIPO_AGENTE IN (28,32,37,38,39,40,42,43,44,45,49)
                        AND
						-- Periodo anterior que el actual
                        BAL_RPA_RESUMEN.STARTDATE < :v_period_startdate)
						OR
						(BAL_RPA_RESUMEN.ID_TIPO_AGENTE NOT IN (28,32,37,38,39,40,42,43,44,45,49)
						AND
						-- Periodo actual
						BAL_RPA_RESUMEN.PERIODSEQ = :i_PeriodSeq))
						AND
						-- No nos interesa generar LC si no ha habido en ese mes
						:v_period_name in (SELECT DISTINCT PERIODO FROM EXT.OUT_LC_RPA_RESUMEN_REP)
						AND
						-- Sólo las posiciones que hayan tenido LC en el mes
						BAL_RPA_RESUMEN.POS_PRIN IN (SELECT DISTINCT POS_PRIN FROM EXT.OUT_LC_RPA_RESUMEN_REP WHERE PERIODO = :v_period_name)
                )
                SELECT
                    --Cabecera
                    :v_period_name AS PERIODO_FILTRO,
                    :v_period_name_format AS PERIODO_FORMATO,
                    QO.PERIODO AS PERIODO_TABLA,
                    POS_PRIN,
                    TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
                    NIF,
                    NIF || ' - ' || TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NIF_NOMBRE,
                    TO_INTEGER(FIRST_VALUE(ID_TIPO_AGENTE) OVER (PARTITION BY POS_PRIN ORDER BY STARTDATE DESC)) || ' - ' || FIRST_VALUE(TIPO_AGENTE) OVER (PARTITION BY POS_PRIN ORDER BY STARTDATE DESC) AS TIPO_AGENTE,
                    
                    --Resumen Mensual
                    --Pólizas
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes' THEN V_MEDIDA ELSE 0 END) AS POL_CORR,
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-Prima-998-TotalMes' THEN V_MEDIDA ELSE 0 END) AS PRIMA_RAPPEL, --Prima Total Productos --Reg Trim 7
                    --Productos
                    SUM(CASE WHEN N_MEDIDA IN (
						'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-SinResto', 'SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-SinResto','SM-O-RPP-Agente-NumeroPolizas-998-Otros-Productos'
						) THEN V_MEDIDA ELSE 0 END) AS PROD_PERIODO_ACTUAL,
                    SUM(CASE WHEN N_MEDIDA IN (
						'SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-01503-AgNO20-Mes-Anterior','SM-O-RPP-Agente-NumeroPolizas-998-Resto-01501-Campania-Mes-Anterior','SM-O-RPP-Agente-NumeroPolizas-998-Resto-Mes-Anterior'
                    ) THEN V_MEDIDA ELSE 0 END) AS PROD_PERIODO_ANTERIOR,
                    SUM(CASE WHEN N_MEDIDA IN (
						'SM-O-RPP-Agente-NumeroPolizas-998-01501-01503-Recup-AgNO20-Resto','SM-O-RPP-Agente-NumeroPolizas-998-01501-Campania-Resto','SM-O-RPP-Agente-NumeroPolizas-998-Total-Mes-Resto'
                    ) THEN V_MEDIDA ELSE 0 END) AS PROD_PERIODO_PROXIMO,
                    -- Objetivos Mínimos
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumAsegurados-TotalMes' THEN V_MEDIDA ELSE 0 END) AS ASEG_RRTT, --Reg Trim 1
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-001-TotalMes' THEN V_MEDIDA ELSE 0 END) AS RRTT, --Reg Trim 3
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-002-TotalMes' THEN V_MEDIDA ELSE 0 END) AS HOGAR, --Reg Trim 5
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-003-TotalMes' THEN V_MEDIDA ELSE 0 END) AS VIDA_RIESGO,
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-004-TotalMes' THEN V_MEDIDA ELSE 0 END) AS VIDA_AHORRO,
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-005-SINCC-TotalMes' THEN V_MEDIDA ELSE 0 END) AS ACCIDENTES_SIN_CC,
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-906-TotalMes' THEN V_MEDIDA ELSE 0 END) AS RRPP, --Reg Trim 4
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-997-TotalMes' THEN V_MEDIDA ELSE 0 END) AS PRODUCTOS_PRIORITARIOS,

                    --Pago Mensual
                    SUM(CASE WHEN N_MEDIDA IN ('SM-O-RPP-Agente-Rappel-Pago-Mensual','SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual') THEN V_MEDIDA ELSE 0 END) AS IMPORTE_RAPPEL,
                    SUM(CASE WHEN N_MEDIDA IN ('SM-O-RPP-Agente-SuperRappel-Pago-Mensual','SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual') THEN V_MEDIDA ELSE 0 END) AS IMPORTE_SUPERRAPPEL,
                    SUM(CASE WHEN N_MEDIDA IN ('SM-O-RPP-Agente-Rappel-Pago-MensualXXL', 'SM-O-RPP-Agente-Rappel-Pago-MensualXL') THEN V_MEDIDA ELSE 0 END) AS IMPORTE_RAPPEL_XL,
                    SUM(CASE WHEN N_MEDIDA IN ('SM-O-RPP-Agente-Pago-Fijo-Mensual', 'SM-O-RPP-Agente-N2N3-Pago-Fijo-Mensual') THEN V_MEDIDA ELSE 0 END) AS INCENTIVO_ESPECIAL,
                    
                    --Regularización Trimestral (el resto están ya calculadas)
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizasCorregidas-998-TotalMes' THEN V_MEDIDA ELSE 0 END) AS POLIZAS_TR, --Reg Trim 2
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Agente-NumeroPolizas-007-TotalMes' THEN V_MEDIDA ELSE 0 END) AS OCASO_ORO, --Reg Trim 6
                    CASE WHEN LEFT(QO.PERIODO, LENGTH(QO.PERIODO)-5) IN ('Marzo','Junio','Septiembre', 'Diciembre')
                        THEN (CASE WHEN SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-CumpleObjetivos-RegulTrimestral' THEN V_MEDIDA ELSE 0 END) = 1
                            THEN 'SI'
                            ELSE 'NO'
                            END)
                        ELSE ' '
                        END AS CUMPLE_OBJ, --Reg Trim 8
                    SUM(CASE WHEN N_MEDIDA IN (
						'SM-O-RPP-Agente-N2N3-Rappel-Pago-Mensual','SM-O-RPP-Agente-N2N3-SuperRappel-Pago-Mensual','SM-O-RPP-Agente-Rappel-Pago-MensualXXL','SM-O-RPP-Agente-Rappel-Pago-MensualXL'
						'SM-O-RPP-Agente-Rappel-Pago-Mensual', 'SM-O-RPP-Agente-SuperRappel-Pago-Mensual', 'SM-O-RPP-Agente-Rappel-Pago-MensualXL', 'SM-O-RPP-Agente-Pago-Fijo-Mensual'
						) THEN V_MEDIDA ELSE 0 END) AS RAPPEL_ABONADO_TRIMESTRE, --Reg Trim 9
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-Importe-RegTrim' THEN V_MEDIDA ELSE 0 END) AS ESCALADO_REG_TRIM, --Reg Trim 10
                    SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-Agente-ImporteNeto-RegTrim' THEN V_MEDIDA ELSE 0 END) AS TOTAL_ABONO_REG_TRIM, --Reg Trim 11
                    
					--Filtros
					CASE WHEN QO.PERIODO = :v_period_name
						THEN 'SI'
						ELSE 'NO'
					END AS IGUALES,
                    SOLO_DIFERENCIAS,
                    F.ULTIMA_ACTUALIZACION AS FEC_ACTUALIZACION,
                    POSITIONSEQ,
                    :i_PeriodSeq AS PERIODSEQ
                FROM QUERY_ORACLE QO
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
					AND F.TABLA = 'OUT_LC_RPA_RESUMEN_REP'
                GROUP BY QO.PERIODO, POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, ID_TIPO_AGENTE, TIPO_AGENTE, 
                    SOLO_DIFERENCIAS, POSITIONSEQ, F.ULTIMA_ACTUALIZACION, STARTDATE;
            v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_LC_RPA_RESUMEN_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); 
			
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe S4 LC RPA RESUMEN', i_log_count, i_id_proceso, 'info');

			--BRG RPA DETALLE + BAL + LC
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S4 RPA DETALLE', i_log_count, i_id_proceso, 'info');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RPA_DETALLE_FINAL_REP', i_log_count, i_id_proceso, 'debug'); 
			DELETE FROM EXT.OUT_RPA_DETALLE_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RPA_DETALLE_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); 
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RPA_DETALLE_FINAL_REP. Cierre.', i_log_count, i_id_proceso, 'debug'); 
			INSERT INTO EXT.OUT_RPA_DETALLE_FINAL_REP (TIPO_INFORME, PERIODO, PERIODO_FORMATO, COD_AGENTE, NOMBRE_AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, COD_AGENTE_TABLA, ID_PROD, COD_POLIZA, PRODUCTO, TIPO_RECIBO, FECHA_EMISION, FECHA_COBRO, POL_FIS, POL_CORR, PRIMA, ASEG, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, POSITIONSEQ, PERIODSEQ)
				SELECT DISTINCT
					'CIERRE' AS TIPO_INFORME,
					:v_period_name AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					POS_PRIN AS COD_AGENTE,
					TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
					NIF,
					NIF || ' - ' || TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NIF_NOMBRE,
					TO_INTEGER(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGENTE,
					
					MAX(POSITIONNAME_AG) AS COD_AGENTE_TABLA,
					RIGHT(PRODUCTID, 5) AS ID_PROD,
					ST_GA1 AS COD_POLIZA,
					MAX(PRODUCTO) AS PRODUCTO,
					EVENTO AS TIPO_RECIBO,
					IFNULL(MAX(TO_VARCHAR(ST_GD3, 'MM-YYYY')), ' ') AS FECHA_EMISION,
					IFNULL(MAX(TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY')), ' ') AS FECHA_COBRO,
					SUM(CASE WHEN NAME LIKE '%Polizas%998'
						THEN VALUE
						ELSE 0 END) AS POL_FIS,
					SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN C_GN4
						ELSE 0 END) AS POL_CORR,
					SUM(CASE WHEN NAME LIKE '%Prima%'
						THEN VALUE
						ELSE 0 END) AS PRIMA,
					SUM(CASE WHEN NAME LIKE '%Asegurados'
						THEN VALUE
						ELSE 0 END) AS ASEG,
					
					NULL AS SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					POSITIONSEQ_PRIN AS POSITIONSEQ,
					:i_PeriodSeq AS PERIODSEQ
				FROM EXT.OUT_RPA_DETALLE_REP RPA_DETALLE
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
					AND TABLA = 'OUT_RPA_DETALLE_REP'
				WHERE RPA_DETALLE.PERIODSEQ = :i_PeriodSeq
				GROUP BY POS_PRIN, POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, ID_TIPO_AGENTE, TIPO_AGENTE,
					RIGHT(PRODUCTID, 5), ST_GA1, EVENTO, POSITIONSEQ_PRIN, F.ULTIMA_ACTUALIZACION;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPA_DETALLE_FINAL_REP. Cierre. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); 

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RPA_DETALLE_FINAL_REP. Balances.', i_log_count, i_id_proceso, 'debug'); 
			INSERT INTO EXT.OUT_RPA_DETALLE_FINAL_REP (TIPO_INFORME, PERIODO, PERIODO_FORMATO, COD_AGENTE, NOMBRE_AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, COD_AGENTE_TABLA, ID_PROD, COD_POLIZA, PRODUCTO, TIPO_RECIBO, FECHA_EMISION, FECHA_COBRO, POL_FIS, POL_CORR, PRIMA, ASEG, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, POSITIONSEQ, PERIODSEQ)
				SELECT DISTINCT
					'BAL' AS TIPO_INFORME,
					:v_period_name AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					POS_PRIN AS COD_AGENTE,
					TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
					NIF,
					NIF || ' - ' || TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NIF_NOMBRE,
					TO_INTEGER(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGENTE,
					
					MAX(POSITIONNAME_AG) AS COD_AGENTE_TABLA,
					RIGHT(PRODUCTID, 5) AS ID_PROD,
					ST_GA1 AS COD_POLIZA,
					MAX(PRODUCTO) AS PRODUCTO,
					EVENTO AS TIPO_RECIBO,
					IFNULL(MAX(TO_VARCHAR(ST_GD3, 'MM-YYYY')), ' ') AS FECHA_EMISION,
					IFNULL(MAX(TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY')), ' ') AS FECHA_COBRO,
					SUM(CASE WHEN NAME LIKE '%Polizas%998'
						THEN RPA_DETALLE.VALUE
						ELSE 0 END) AS POL_FIS,
					SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN C_GN4
						ELSE 0 END) AS POL_CORR,
					SUM(CASE WHEN NAME LIKE '%Prima%'
						THEN RPA_DETALLE.VALUE
						ELSE 0 END) AS PRIMA,
					SUM(CASE WHEN NAME LIKE '%Asegurados'
						THEN RPA_DETALLE.VALUE
						ELSE 0 END) AS ASEG,
					
					CASE WHEN B.BALANCESEQ IS NOT NULL 
						THEN 'SI'
						ELSE NULL END AS SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					POSITIONSEQ_PRIN AS POSITIONSEQ,
					:i_PeriodSeq AS PERIODSEQ
				FROM EXT.OUT_BAL_RPA_DETALLE_REP RPA_DETALLE
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
					AND TABLA = 'OUT_BAL_RPA_DETALLE_REP'
				LEFT JOIN TCMP.CS_BALANCE B ON B.PERIODSEQ = RPA_DETALLE.PERIODSEQ
					AND B.PAYEESEQ = RPA_DETALLE.PARTICIPANTSEQ
					AND B.POSITIONSEQ = RPA_DETALLE.POSITIONSEQ_PRIN
				WHERE RPA_DETALLE.PERIODSEQ = :i_PeriodSeq
				GROUP BY POS_PRIN, POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, ID_TIPO_AGENTE, TIPO_AGENTE,
					RIGHT(PRODUCTID, 5), ST_GA1, EVENTO, POSITIONSEQ_PRIN, F.ULTIMA_ACTUALIZACION,
					B.BALANCESEQ;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPA_DETALLE_FINAL_REP. Balances. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug'); 

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RPA_DETALLE_FINAL_REP. Liquidación Complementaria.', i_log_count, i_id_proceso, 'debug'); 
			INSERT INTO EXT.OUT_RPA_DETALLE_FINAL_REP (TIPO_INFORME, PERIODO, PERIODO_FORMATO, COD_AGENTE, NOMBRE_AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, COD_AGENTE_TABLA, ID_PROD, COD_POLIZA, PRODUCTO, TIPO_RECIBO, FECHA_EMISION, FECHA_COBRO, POL_FIS, POL_CORR, PRIMA, ASEG, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, POSITIONSEQ, PERIODSEQ)
				SELECT DISTINCT
					'LC' AS TIPO_INFORME,
					:v_period_name AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					POS_PRIN AS COD_AGENTE,
					TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
					NIF,
					NIF || ' - ' || TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NIF_NOMBRE,
					TO_INTEGER(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGENTE,
					
					MAX(POSITIONNAME_AG) AS COD_AGENTE_TABLA,
					RIGHT(PRODUCTID, 5) AS ID_PROD,
					ST_GA1 AS COD_POLIZA,
					MAX(PRODUCTO) AS PRODUCTO,
					EVENTO AS TIPO_RECIBO,
					IFNULL(MAX(TO_VARCHAR(ST_GD3, 'MM-YYYY')), ' ') AS FECHA_EMISION,
					IFNULL(MAX(TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY')), ' ') AS FECHA_COBRO,
					SUM(CASE WHEN NAME LIKE '%Polizas%998'
						THEN RPA_DETALLE.VALUE
						ELSE 0 END) AS POL_FIS,
					SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN C_GN4
						ELSE 0 END) AS POL_CORR,
					SUM(CASE WHEN NAME LIKE '%Prima%'
						THEN RPA_DETALLE.VALUE
						ELSE 0 END) AS PRIMA,
					SUM(CASE WHEN NAME LIKE '%Asegurados'
						THEN RPA_DETALLE.VALUE
						ELSE 0 END) AS ASEG,
					
					CASE WHEN P.POSTPIPELINERUNDATE IS NULL OR P.POSTPIPELINERUNDATE > LAST_DAY(:v_period_startdate)
						THEN 'SI'
						ELSE NULL END AS SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					POSITIONSEQ_PRIN AS POSITIONSEQ,
					:i_PeriodSeq AS PERIODSEQ
				FROM EXT.OUT_LC_RPA_DETALLE_REP RPA_DETALLE
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
					AND TABLA = 'OUT_LC_RPA_DETALLE_REP'
				LEFT JOIN (SELECT X.PAYEESEQ, X.POSITIONSEQ, MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE FROM TCMP.CS_PAYMENT X
						WHERE X.PERIODSEQ = :i_PeriodSeq
						GROUP BY X.PAYEESEQ,X.POSITIONSEQ
					) P ON P.PAYEESEQ = RPA_DETALLE.PARTICIPANTSEQ
					AND P.POSITIONSEQ = RPA_DETALLE.POSITIONSEQ_PRIN
				WHERE RPA_DETALLE.PERIODSEQ = :i_PeriodSeq
				GROUP BY POS_PRIN, POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, ID_TIPO_AGENTE, TIPO_AGENTE,
					RIGHT(PRODUCTID, 5), ST_GA1, EVENTO, POSITIONSEQ_PRIN, F.ULTIMA_ACTUALIZACION,
					P.POSTPIPELINERUNDATE;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPA_DETALLE_FINAL_REP. Liquidación Complementaria. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Insert de --SELECCIONAR-- en OUT_RPA_DETALLE_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
            INSERT INTO EXT.OUT_RPA_DETALLE_FINAL_REP (TIPO_INFORME, PERIODO, PERIODO_FORMATO, COD_AGENTE, NOMBRE_AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, COD_AGENTE_TABLA, ID_PROD, COD_POLIZA, PRODUCTO, TIPO_RECIBO, FECHA_EMISION, FECHA_COBRO, POL_FIS, POL_CORR, PRIMA, ASEG, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, POSITIONSEQ, PERIODSEQ)
				SELECT DISTINCT
					TIPO_INFORME,
					PERIODO,
					PERIODO_FORMATO,
					' ' AS COD_AGENTE,
					' ' AS NOMBRE_AGENTE,
					' ' AS NIF,
					'--SELECCIONAR--' AS NIF_NOMBRE,
					' ' AS TIPO_AGENTE,
					' ' AS COD_AGENTE_TABLA,
					' ' AS ID_PROD,
					' ' AS COD_POLIA,
					' ' AS PRODUCTO,
					' ' AS TIPO_RECIBO,
					' ' AS FECHA_EMISION,
					' ' AS FECHA_COBRO,
					NULL AS POL_FIS,
					NULL AS POL_CORR,
					NULL AS PRIMA,
					NULL AS ASEG,
					SOLO_DIFERENCIAS,
					FEC_ACTUALIZACION,
					-1 AS POSITIONSEQ,
					PERIODSEQ
				FROM EXT.OUT_RPA_DETALLE_FINAL_REP
                WHERE PERIODSEQ = :i_PeriodSeq;
            v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Insert de --SELECCIONAR-- en OUT_RPA_DETALLE_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');


            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe S4 RPA DETALLE', i_log_count, i_id_proceso, 'info');


		--FIN informe S4 RAPPEL PRODUCCIÓN AGENTES RESUMEN/DETALLE (RPA)
		END IF;
		
		------------------------------------------------------------------------------------------------------------------------
		--BRG 20251024
		--Inicio informes 1.27.1-2 y 1.27.3-4
		IF :i_lista_informes = 'REPEXT' OR :i_lista_informes LIKE '%|REPEXT|%' OR :i_lista_informes LIKE '%|REPEXT' OR :i_lista_informes LIKE 'REPEXT|%' OR :i_lista_informes = 'ALL' 
			THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tablas FINALES Informes 1.27.1-2 y 1.27.3-4 Reparto Pagos', i_log_count, i_id_proceso, 'info');
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_REPARTO_PAGOS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_REPARTO_PAGOS_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_REPARTO_PAGOS_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
		
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_REPARTO_PAGOS_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_REPARTO_PAGOS_FINAL_REP (COMPANYA, PERIODO, PERIODO_FORMATO, FEC_CARGO, EARNING_CODE, EARNING_GROUP, PROGRAMA, DEPOSITO, TIPO_PAGO, COD_AGENTE, IMPORTE, TIPO_REPARTO, COD_UNICO, NIF_NOMBRE, TIPO_AGENTE, MANAGER, ESTADO_REPARTO, POSITIONSEQ, PERIODSEQ)
				SELECT 
					SUBSTR(PAG.EARNINGGROUPID, 7, 2) AS COMPANYA,
					PER.NAME,
					:v_period_name_format AS PERIODO,
					PAG.FECHA_CARGO AS "FECHA CARGO",
					PAG.EARNINGCODEID AS "EARNING CODE",
					PAG.EARNINGGROUPID AS "EARNING GROUP",
					PAG.PROGRAMA,
					IFNULL(PAG.DEPOSITO, ' ') AS DEPOSITO,
					IFNULL(PAG.TIPO_PAGO, ' ') AS "TIPO PAGO",
					PAG.POS_PRIN AS "CODIGO AGENTE",
					ROUND(PAG.IMPORTE, 2) AS IMPORTE,
					IFNULL(CAST(TR.TIPO_REPARTO AS VARCHAR), ' ') AS "TIPO REPARTO",
					-- 1.27.2
					PAG.POS_CALLIDUS AS "CODIGO UNICO",
					PAG.NIF,
					CAST(TO_INTEGER(PAG.TIPO_AGENTE) AS VARCHAR) AS "TIPO AGENTE",
					PAG.MANAGER_POS_PRIN AS "MANAGER",
					CAST(PAG.ESTADO_REPARTO AS VARCHAR) AS "ESTADO REPARTO",
					PAG.POSITIONSEQ,
					PER.PERIODSEQ
				FROM EXT.FINAL_REPEXT_PAGOS_FILE AS PAG
				LEFT JOIN EXT.WF_REPEXT_TIPO_REPARTO_FILE AS TR
					ON PAG.TIPO_PAGO = TR.TIPO_PAGO
					AND SUBSTR(PAG.EARNINGGROUPID, 7, 2) = TR.CIA_CODIGO
					AND PAG.FECHA_CARGO BETWEEN TR.FECHA_INICIO AND TR.FECHA_FIN
					AND TR.FECHA_BAJA IS NULL
				INNER JOIN TCMP.CS_PERIOD PER
					ON PAG.PERIODSEQ = PER.PERIODSEQ
					AND PER.REMOVEDATE = TO_DATE('22000101','YYYYMMDD')
				WHERE PAG.POS_PRIN NOT LIKE '%999999'
					AND PAG.PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_REPARTO_PAGOS_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');


			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_REPARTO_PAGOS_COMMISSIONS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_REPARTO_PAGOS_COMMISSIONS_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_REPARTO_PAGOS_COMMISSIONS_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
		
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_REPARTO_PAGOS_COMMISSIONS_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_REPARTO_PAGOS_COMMISSIONS_FINAL_REP (COMPANYA, CONCEPTO_PAGO, GRUPO_PAGO, POS_PRIN, ANYO, PERIODO, PERIODO_FORMATO, NIF_NOMBRE, IMPORTE, POSITIONSEQ, PERIODSEQ)
				(SELECT
					SUBSTR(PAY.EARNINGGROUPID,7,2) AS CIA,
					PAY.EARNINGCODEID AS CONCEPTO_PAGO,
					PAY.EARNINGGROUPID AS GRUPO_PAGO,
					POS.GENERICATTRIBUTE3 AS POS_PRIN,
					PD.YEAR,
					PD.NAME AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					CAST(PAR.GENERICATTRIBUTE1 AS VARCHAR(255)) || ' - ' || TRIM(IFNULL(PAR.FIRSTNAME, '') || IFNULL(' ' || PAR.LASTNAME, '') || IFNULL(' ' || PAR.SUFFIX, '')) AS NIF_NOMBRE,
					SUM(ROUND(PAY.VALUE,2)) AS IMPORTE,
					PAY.POSITIONSEQ,
					PD.PERIODSEQ
				FROM TCMP.CS_PAYMENT PAY
				INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON PAY.PERIODSEQ = PD.PERIODSEQ
					AND PD.PERIODTYPESEQ = 2814749767106561
				INNER JOIN TCMP.CS_POSITION POS ON PAY.POSITIONSEQ = POS.RULEELEMENTOWNERSEQ
					AND POS.EFFECTIVESTARTDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND POS.EFFECTIVEENDDATE > ADD_SECONDS(PD.ENDDATE, -1)
					AND POS.CREATEDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND POS.REMOVEDATE > ADD_SECONDS(PD.ENDDATE, -1)
					AND POS.TITLESEQ <> 5629499534213290 --TTL SIN PLAN
					AND POS.GENERICATTRIBUTE3 NOT LIKE '%999999'
				INNER JOIN TCMP.CS_PARTICIPANT PAR ON POS.PAYEESEQ = PAR.PAYEESEQ
					AND PAR.EFFECTIVESTARTDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND PAR.EFFECTIVEENDDATE > ADD_SECONDS(PD.ENDDATE, -1)
					AND PAR.CREATEDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND PAR.REMOVEDATE > ADD_SECONDS(PD.ENDDATE, -1)
					AND (PAR.TERMINATIONDATE IS NULL OR PAR.TERMINATIONDATE > ADD_SECONDS(PD.ENDDATE, -1))
				WHERE SUBSTR(PAY.EARNINGCODEID,1,1) NOT IN ('6','8')
					AND PD.PERIODSEQ = :i_PeriodSeq
				GROUP BY
					PAY.EARNINGCODEID, PAY.EARNINGGROUPID,
					POS.GENERICATTRIBUTE3, 
					PD.YEAR, PD.QUARTER, PD.NAME,
					PAR.GENERICATTRIBUTE1, PAR.FIRSTNAME, PAR.LASTNAME, PAR.SUFFIX,
					PAY.POSITIONSEQ, PD.PERIODSEQ
				
				UNION ALL
				
				SELECT
					SUBSTR(CAR_DDEE.EARNINGGROUPID,7,2) AS CIA,
					CAR_DDEE.EARNINGCODEID AS CONCEPTO_PAGO,
					CAR_DDEE.EARNINGGROUPID AS GRUPO_PAGO,
					POS.GENERICATTRIBUTE3 AS POS_PRIN,
					PD.YEAR,
					PD.NAME AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					CAST(PAR.GENERICATTRIBUTE1 AS VARCHAR(255)) || ' - ' || TRIM(IFNULL(PAR.FIRSTNAME, '') || IFNULL(' ' || PAR.LASTNAME, '') || IFNULL(' ' || PAR.SUFFIX, '')) AS NIF_NOMBRE,
					SUM(ROUND(CAR_DDEE.IMPORTE,2)) AS IMPORTE,
					POS.RULEELEMENTOWNERSEQ,
					PD.PERIODSEQ
				FROM EXT.CARTERA_DDEE CAR_DDEE
				INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON CAR_DDEE.COMPENSATIONDATE = PD.STARTDATE
					AND PD.PERIODTYPESEQ = 2814749767106561
				INNER JOIN TCMP.CS_POSITION POS ON CAR_DDEE.POSITIONNAME = POS.NAME
					AND POS.EFFECTIVESTARTDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND POS.EFFECTIVEENDDATE > ADD_SECONDS(PD.ENDDATE, -1)
					AND POS.CREATEDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND POS.REMOVEDATE > ADD_SECONDS(PD.ENDDATE, -1)
				INNER JOIN TCMP.CS_PARTICIPANT PAR ON POS.PAYEESEQ = PAR.PAYEESEQ
					AND PAR.EFFECTIVESTARTDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND PAR.EFFECTIVEENDDATE > ADD_SECONDS(PD.ENDDATE, -1)
					AND PAR.CREATEDATE <= ADD_SECONDS(PD.ENDDATE, -1)
					AND PAR.REMOVEDATE > ADD_SECONDS(PD.ENDDATE, -1)
					AND (PAR.TERMINATIONDATE IS NULL OR PAR.TERMINATIONDATE > ADD_SECONDS(PD.ENDDATE, -1))
				WHERE CAR_DDEE.ESTADO = 'C'
					AND CAR_DDEE.SEQ_POST IS NOT NULL
					AND POS.GENERICATTRIBUTE3 NOT LIKE '%999999'
					AND PD.PERIODSEQ = :i_PeriodSeq
				GROUP BY
					CAR_DDEE.EARNINGCODEID, CAR_DDEE.EARNINGGROUPID,
					POS.GENERICATTRIBUTE3, 
					PD.YEAR, PD.QUARTER, PD.NAME,
					PAR.GENERICATTRIBUTE1, PAR.FIRSTNAME, PAR.LASTNAME, PAR.SUFFIX,
					POS.RULEELEMENTOWNERSEQ, PD.PERIODSEQ);
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_REPARTO_PAGOS_COMMISSIONS_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');


			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_DETALLE_REPARTO_PAGOS_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_DETALLE_REPARTO_PAGOS_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_DETALLE_REPARTO_PAGOS_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
		
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_DETALLE_REPARTO_PAGOS_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_DETALLE_REPARTO_PAGOS_FINAL_REP (PERIODO, PERIODO_FORMATO, NIF, COD_UNICO, COD_AGENTE, MANAGER, TIPO_AGENTE, TIPO_PAGO, CONCEPTO_PAGO, GRUPO_PAGO, IMPORTE, NUM_TRAMO, TIPO_REPARTO, REPARTO_TIPO_BASE, REPARTO_PORCENTAJE, PRODUCTO, CODIGO_POLIZA, CODIGO_RECIBO, PERMANENCIA, POLIZA_FISICA, POLIZA_CORREGIDA, PRIMA_CORREGIDA, PRIMA_NETA, PRIMA_NETA_ANUAL, PRIMA_COMIS, COEF_TIPO_BASE, COEF_CORRECTOR, IMPORTE_REPARTO, AGENCIA, PERIODSEQ, POSITIONSEQ)
				SELECT
					PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					
					NIF,
					POSITIONNAME AS "CODIGO UNICO", 
					POS_PRIN AS "CODIGO AGENTE",
					MANAGER_POS_PRIN AS MANAGER,
					TO_VARCHAR(TO_INTEGER(TIPO_AGENTE)),
					
					TIPO_PAGO,
					
					EARNINGCODEID AS "CONCEPTO DE PAGO",
					EARNINGGROUPID AS "GRUPO DE PAGO",
					ROUND(IMPORTE_PAGO, 2) AS IMPORTE,
					
					NUM_TRAMO,
					IFNULL(TIPO_REPARTO, ' '), 
					IFNULL(REPARTO_TIPO_BASE, ' '),
					IFNULL(TO_VARCHAR(REPARTO_PORCENTAJE), ' '),
					
					PRODUCTID AS PRODUCTO,
					CODIGO_POLIZA,
					CASE
						WHEN RIGHT(LEFT(PRODUCTID,3),1) = '2'
							THEN RIGHT(ORDERID,11)
						ELSE
							LEFT(TO_VARCHAR(SUBLINENUMBER),11)
						END AS "CODIGO RECIBO",
					EVENTTYPEID AS PERMANENCIA,
					ROUND(POLIZA_FISICA, 2) AS POLIZA_FISICA,
					ROUND(POLIZA_CORREGIDA, 2) AS POLIZA_CORREGIDA,
					ROUND(PRIMA_CORREGIDA, 2) AS PRIMA_CORREGIDA,
					ROUND(PRIMA_NETA, 2) AS PRIMA_NETA,
					ROUND(PRIMA_NETA_ANUAL, 2) AS PRIMA_NETA_ANUAL,
					ROUND(PRIMA_COMIS, 2) AS PRIMA_COMIS,
					IFNULL(COEF_TIPO_BASE, ' '),
					IFNULL(TO_VARCHAR(COEF_CORRECTOR), ' '),
					ROUND(IMPORTE, 2) AS IMPORTE_REPARTO,
					CASE
						WHEN POS_PRIN LIKE '%999999'
							THEN 'SI'
						ELSE 'NO' 
						END AS AGENCIA,
					PERIODSEQ,
					POSITIONSEQ
				FROM EXT.FINAL_REPEXT_FILE
				WHERE TIPO_PAGO IS NOT NULL
					AND PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_DETALLE_REPARTO_PAGOS_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RESUMEN_REPARTO_PAGOS_VB1_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_RESUMEN_REPARTO_PAGOS_VB1_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RESUMEN_REPARTO_PAGOS_VB1_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
		
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RESUMEN_REPARTO_PAGOS_VB1_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RESUMEN_REPARTO_PAGOS_VB1_FINAL_REP (PERIODSEQ, PERIODO, PERIODO_FORMATO, COMPANIA, CONCEPTO_CONTABLE, TIPO_PAGO, NUM_TRAMO, PRODUCTID, IMPORTE, AGENCIA)
				SELECT 
					PERIODSEQ,
					PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					SUBSTR(EARNINGGROUPID,7,2) AS COMPANIA,
                    EARNINGCODEID AS CONCEPTO_CONTABLE,
					TIPO_PAGO,
					NUM_TRAMO,
					PRODUCTID,
					SUM(ROUND(IMPORTE, 2)) AS IMPORTE,
					CASE WHEN POS_PRIN LIKE '%999999' THEN 'SI' ELSE 'NO' END AS AGENCIA
				FROM EXT.FINAL_REPEXT_FILE
				WHERE TIPO_PAGO IS NOT NULL
					AND PERIODSEQ = :i_PeriodSeq
				GROUP BY PERIODSEQ, PERIODO, SUBSTR(EARNINGGROUPID,7,2), EARNINGCODEID, TIPO_PAGO, NUM_TRAMO, PRODUCTID,
					CASE WHEN POS_PRIN LIKE '%999999' THEN 'SI' ELSE 'NO' END;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RESUMEN_REPARTO_PAGOS_VB1_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');


			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RESUMEN_REPARTO_PAGOS_VB2_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_RESUMEN_REPARTO_PAGOS_VB2_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RESUMEN_REPARTO_PAGOS_VB2_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
		
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RESUMEN_REPARTO_PAGOS_VB2_FINAL_REP. CIERRE', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RESUMEN_REPARTO_PAGOS_VB2_FINAL_REP (PERIODSEQ, PERIODO, PERIODO_FORMATO, COMPANIA, TIPO_PAGO, TRAMO, REPARTO, PAGO_MES, AGENCIA)
				(WITH BASE_PAGOS AS (
					SELECT 
						PERIODSEQ,
						SUBSTR(EARNINGGROUPID,7,2) AS COMPANIA,
						COALESCE(TIPO_PAGO, 'VACIO') AS TIPO_PAGO,
						IMPORTE,
						CASE WHEN POS_PRIN LIKE '%999999' THEN 'SI' ELSE 'NO' END AS AGENCIA
					FROM EXT.FINAL_REPEXT_PAGOS_FILE
					WHERE PERIODSEQ = :i_PeriodSeq), 
				BASE_REPEXT AS (
					SELECT 
						PERIODSEQ,
						SUBSTR(EARNINGGROUPID,7,2) AS COMPANIA,
						TIPO_PAGO,
						CASE WHEN POS_PRIN LIKE '%999999' THEN 'SI' ELSE 'NO' END AS AGENCIA,
						SUM(IMPORTE) AS SUM_REPEXT
					FROM EXT.FINAL_REPEXT_FILE
					WHERE TIPO_PAGO IS NOT NULL
						AND PERIODSEQ = :i_PeriodSeq
					GROUP BY PERIODSEQ, SUBSTR(EARNINGGROUPID,7,2), TIPO_PAGO,
						CASE WHEN POS_PRIN LIKE '%999999' THEN 'SI' ELSE 'NO' END), 
				JOINED AS (
					SELECT 
						PAG.PERIODSEQ,
						PAG.COMPANIA,
						PAG.TIPO_PAGO,
						'TOTAL' AS TRAMO,
						REP.SUM_REPEXT AS REPARTO,
						SUM(PAG.IMPORTE) AS PAGO_MES,
						PAG.AGENCIA
					FROM base_pagos PAG
					LEFT JOIN base_repext REP
						ON PAG.COMPANIA = REP.COMPANIA
						AND PAG.TIPO_PAGO = REP.TIPO_PAGO
						AND PAG.PERIODSEQ = REP.PERIODSEQ
						AND PAG.AGENCIA = REP.AGENCIA
					WHERE PAG.PERIODSEQ = :i_PeriodSeq
					GROUP BY PAG.PERIODSEQ, PAG.COMPANIA, PAG.TIPO_PAGO, REP.SUM_REPEXT, PAG.AGENCIA) 
				SELECT 
					P.PERIODSEQ AS PERIODSEQ,
					P.NAME AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					COMPANIA, 
					TIPO_PAGO, 
					TRAMO, 
					SUM(ROUND(REPARTO, 2)) AS REPARTO, 
					ROUND(PAGO_MES, 2) AS PAGO_MES, 
					AGENCIA
				FROM JOINED J
				INNER JOIN CS_PERIOD P ON P.PERIODSEQ = J.PERIODSEQ
					AND P.REMOVEDATE = TO_DATE('22000101','YYYYMMDD')
				WHERE P.PERIODSEQ = :i_PeriodSeq
				GROUP BY P.PERIODSEQ, P.NAME, COMPANIA, TIPO_PAGO, TRAMO, PAGO_MES, AGENCIA
				
				UNION ALL 
				
				SELECT
					P.PERIODSEQ AS PERIODSEQ,
					P.NAME AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					SUBSTR(EARNINGGROUPID,7,2) AS COMPANIA,
					TIPO_PAGO,
					TO_CHAR(NUM_TRAMO) AS TRAMO,
					SUM(IMPORTE) AS REPARTO,
					NULL AS PAGO_MES,
					CASE WHEN POS_PRIN LIKE '%999999' THEN 'SI' ELSE 'NO' END AS AGENCIA
				FROM EXT.FINAL_REPEXT_FILE REP
				INNER JOIN CS_PERIOD P ON P.PERIODSEQ = REP.PERIODSEQ
					AND P.REMOVEDATE = TO_DATE('22000101','YYYYMMDD')
				WHERE TIPO_PAGO IS NOT NULL
					AND P.PERIODSEQ = :i_PeriodSeq
				GROUP BY P.PERIODSEQ,
					P.NAME,
					SUBSTR(EARNINGGROUPID,7,2),
					TIPO_PAGO,
					NUM_TRAMO,
					CASE WHEN POS_PRIN LIKE '%999999' THEN 'SI' ELSE 'NO' END);
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RESUMEN_REPARTO_PAGOS_VB2_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tablas FINALES Informes 1.27.1-2 y 1.27.3-4 Reparto Pagos', i_log_count, i_id_proceso, 'info');

		--Fin informes 1.27.1-2 y 1.27.3-4
		END IF;
		
		---------------------------------------------------------------------------------------------------------------------------------------
		--Inicio informe S5 RAPPEL PRODUCCIÓN INSPECTORES RESUMEN (RPI) -- para cualquier mes --LLS 20251030
		IF :i_lista_informes = 'RPI' OR :i_lista_informes LIKE '%|RPI|%' OR :i_lista_informes LIKE '%|RPI' OR :i_lista_informes LIKE 'RPI|%' OR :i_lista_informes = 'ALL' 
			THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S5 RPI RESUMEN (mensual)', i_log_count, i_id_proceso, 'info');
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (mensual).', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_S5_RPI_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq AND ORIGEN = 'Mensual';
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (mensual). Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S5_RPI_RESUMEN_FINAL_REP (mensual). CIERRE', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_S5_RPI_RESUMEN_FINAL_REP (COMPANYA, TIPO_PAGO, ORIGEN, PERIODSEQ, PERIODO_ORIGINAL, PERIODO_CAMPO, PERIODO, QUARTER, NIF_NOMBRE, OFICINA, INSPECTOR, NIF, TIPO_AGENTE, POS_PRIN, POSITIONSEQ, PARTICIPANTSEQ, N_MEDIDA, V_MEDIDA, N_CREDITO, V_CREDITO
						, COMISION_PAGO, V_MEDIDA_CALC, POSITIONNAME_AG, NOMBRE_AGENTE, COMISION_AGENTE, VALOR_COMISION_AGENTE, RAPPEL_2_3, COMISION_OBJETIVOS
						, TIPO_SEGUIMIENTO, COMISION_SEGUIMIENTO, COMISION_TRIM_PAGOS, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, FEC_ACTUALIZACION_FORMATO)
						
				SELECT COMPANYA, TIPO_PAGO, ORIGEN, PERIODSEQ, PERIODO_ORIGINAL, PERIODO_CAMPO, PERIODO, QUARTER, NIF_NOMBRE, OFICINA, INSPECTOR, NIF, TIPO_AGENTE, POS_PRIN, POSITIONSEQ, PARTICIPANTSEQ, N_MEDIDA, V_MEDIDA, N_CREDITO, V_CREDITO
						, COMISION_PAGO, V_MEDIDA_CALC, POSITIONNAME_AG, NOMBRE_AGENTE, COMISION_AGENTE, VALOR_COMISION_AGENTE, RAPPEL_2_3, COMISION_OBJETIVOS
						, TIPO_SEGUIMIENTO, COMISION_SEGUIMIENTO, COMISION_TRIM_PAGOS, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, FEC_ACTUALIZACION_FORMATO
				FROM (
					SELECT DISTINCT 
						'OCASO' COMPANYA
						, 'CIERRE' TIPO_PAGO
						, 'Mensual' ORIGEN
						, RPI.PERIODSEQ
						, RPI.PERIODO PERIODO_ORIGINAL
						, RPI.PERIODO PERIODO_CAMPO
						, SUBSTR_AFTER(RPI.PERIODO, ' ') ||
											CASE WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Enero' THEN ' 01 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Febrero' THEN ' 02 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Marzo' THEN ' 03 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Abril' THEN ' 04 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Mayo' THEN ' 05 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Junio' THEN ' 06 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Julio' THEN ' 07 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Agosto' THEN ' 08 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Octubre' THEN ' 10 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
												END
											|| SUBSTR_BEFORE(RPI.PERIODO, ' ') PERIODO
						, RPI.QUARTER
						, RPI.NIF || ' - ' || RPI.NOMBRE_INSPECTOR NIF_NOMBRE
						, RPI.COD_OFICINA || ' - ' || RPI.OFICINA OFICINA
						, RIGHT(RPI.POS_PRIN,4) ||' - '|| RPI.POS_CALLIDUS ||' - ' || RPI.NOMBRE_INSPECTOR INSPECTOR
						, RPI.NIF
						, TO_INTEGER(RPI.ID_TIPO_AGENTE) ||' - '|| RPI.TIPO_AGENTE AS TIPO_AGENTE
						, POS_PRIN
						, POSITIONSEQ
						, PARTICIPANTSEQ
						, N_MEDIDA
						, ROUND(V_MEDIDA, 2) V_MEDIDA
						, N_CREDITO
						, ROUND(V_CREDITO, 2) V_CREDITO
						
						----MENSUAL
						--HOJA 1, COMISION_PAGO
						, CASE WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizas-998-TotalMes' THEN 'Total Pólizas Corregidas'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalMes' THEN 'Total Pólizas Corregidas'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizas-002-TotalMes' THEN 'Pólizas Corregidas Hogar'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-002-TotalMes' THEN 'Pólizas Corregidas Hogar'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizas-001-TotalMes' THEN 'Pólizas Corregidas RRTT'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-001-TotalMes' THEN 'Pólizas Corregidas RRTT'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizas-906-TotalMes' THEN 'Pólizas Corregidas RRPP excluir Superplan'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-906-TotalMes' THEN 'Pólizas Corregidas RRPP excluir Superplan'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-PrimaCorregida-998-TotalMes' THEN 'Primas Corregidas'
								WHEN RPI.N_MEDIDA = 'SM-RPP-Inspector-PagoMensual' THEN 'Importe Rappel'
								WHEN RPI.N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalMes' THEN 'Asegurados RRTT'
							ELSE NULL
							END COMISION_PAGO
						, ROUND(RPI.V_MEDIDA, 2) V_MEDIDA_CALC
						--HOJA 1, [COMISION_AGENTE]
						, RPI.POSITIONNAME_AG
						, RPI.NOMBRE_AGENTE
						, CASE WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-998%' THEN 'Total Pólizas Corregidas'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-998%' THEN 'Total Pólizas Corregidas'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-002%' THEN 'Pólizas Corregidas Hogar'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-002%' THEN 'Pólizas Corregidas Hogar'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-001%' THEN 'Pólizas Corregidas RRTT'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-001%' THEN 'Pólizas Corregidas RRTT'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-906%' THEN 'Pólizas Corregidas RRPP excluir Superplan'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-906%' THEN 'Pólizas Corregidas RRPP excluir Superplan'
								WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-PrimaCorregida-998%' THEN 'Primas Corregidas'
								WHEN N_MEDIDA = 'PM-O-GEN-Inspector-NumAsegurados-Agentes' THEN 'Asegurados RRTT'
								WHEN N_MEDIDA = 'PM-O-GEN-Agente-NumAsegurados' THEN 'Asegurados RRTT'
							ELSE NULL
							END COMISION_AGENTE
						, CASE WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-998%' 
									OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-998%' 
									OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-002%'
									OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-002%'
									OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-001%'
									OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-001%'
									OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-906%'
									OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-906%'
								THEN IFNULL(ROUND(RPI.C_GN4, 2), 0)
							WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-PrimaCorregida-998%'
									OR N_MEDIDA = 'PM-O-GEN-Inspector-NumAsegurados-Agentes'
									OR N_MEDIDA = 'PM-O-GEN-Agente-NumAsegurados'
								THEN IFNULL(ROUND(RPI.V_CREDITO, 2), 0)
							ELSE 0
							END VALOR_COMISION_AGENTE
						--HOJA 2, TABLA OBJETIVOS [Rappel_2_3]
						, CASE WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
								AND (N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-001'
									OR N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-002'
									OR N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-906'
									OR N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-998')
							THEN 'Rappel 2 ó 3'
							ELSE NULL
							END RAPPEL_2_3
						--HOJA 2, TABLA OBJETIVOS [COMISION_OBJETIVOS]
						, CASE WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') AND N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-998' THEN 'Nº Pólizas Corregidas Total Ramos'
								WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') AND N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-002' THEN 'Nº Pólizas Corregidas Hogar'
								WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') AND N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-001' THEN 'Nº Pólizas Corregidas RRTT'
								WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') AND N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-906' THEN 'Nº Pólizas Corregidas RRPP excluir Superplan'
							ELSE NULL
							END COMISION_OBJETIVOS
							
						----TRIMESTRAL
						, NULL TIPO_SEGUIMIENTO
						, NULL COMISION_SEGUIMIENTO
						, NULL COMISION_TRIM_PAGOS
						, NULL SOLO_DIFERENCIAS
						, CASE WHEN F.ULTIMA_ACTUALIZACION > ADD_MONTHS(RPI.STARTDATE, 1) 
								THEN LAST_DAY(RPI.STARTDATE)
								ELSE F.ULTIMA_ACTUALIZACION
							END FEC_ACTUALIZACION
						, TO_VARCHAR(CASE WHEN F.ULTIMA_ACTUALIZACION > ADD_MONTHS(RPI.STARTDATE, 1) 
										THEN LAST_DAY(RPI.STARTDATE)
										ELSE F.ULTIMA_ACTUALIZACION END
								, 'DD/MM/YYYY') FEC_ACTUALIZACION_FORMATO
						
						
					FROM 
					(	SELECT -- SELECT 1: Tabla OUT_RPI_RESUMEN_REP para el periodo
							'SELECT 1' N_SELECT,
							'Cierre' ORIGEN,
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.STARTDATE,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							SUM(INYC_RPI_RESUMEN.V_CREDITO) AS V_CREDITO,
							SUM(INYC_RPI_RESUMEN.C_GN4) AS C_GN4,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), '') NOMBRE_AGENTE,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), '') NOMBRE_INSPECTOR,
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
						FROM EXT.OUT_RPI_RESUMEN_REP INYC_RPI_RESUMEN
						INNER JOIN	(SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
									FROM EXT.OUT_JERARQUIA_REP
									WHERE POSITIONSEQ = POSITIONSEQ_PRIN --LLS 20251124: Añadido para eliminar posiciones secundarias
									) J
							ON INYC_RPI_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPI_RESUMEN.PERIODSEQ = J.PERIODSEQ
						WHERE 1 = 1
							--Todas las reglas de cierre del mes menos la de pagos
							AND INYC_RPI_RESUMEN.N_MEDIDA <> 'SM-RPP-Inspector-PagoMensual'
							AND INYC_RPI_RESUMEN.PERIODSEQ = :i_PeriodSeq
						GROUP BY INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.STARTDATE,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), ''),
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), ''),
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS

						UNION ALL

						SELECT  -- SELECT 2: Tabla OUT_BAL_RPI_RESUMEN_REP para el año hasta el mes incluído
							'SELECT 2' N_SELECT,
							'Balance' ORIGEN,
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.STARTDATE,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							SUM(INYC_RPI_RESUMEN.V_CREDITO) AS V_CREDITO,
							SUM(INYC_RPI_RESUMEN.C_GN4) AS C_GN4,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), '') NOMBRE_AGENTE,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), '') NOMBRE_INSPECTOR,
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
						FROM EXT.OUT_BAL_RPI_RESUMEN_REP INYC_RPI_RESUMEN--LLS 20251031
						INNER JOIN	(SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
									FROM EXT.OUT_JERARQUIA_REP
									WHERE POSITIONSEQ = POSITIONSEQ_PRIN --LLS 20251124: Añadido para eliminar posiciones secundarias
									) J
							ON INYC_RPI_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPI_RESUMEN.PERIODSEQ = J.PERIODSEQ
						WHERE 1 = 1
							--Todas las reglas de balances de los meses anteriores al cierre menos la de pagos
							AND INYC_RPI_RESUMEN.N_MEDIDA <> 'SM-RPP-Inspector-PagoMensual'
							AND INYC_RPI_RESUMEN.PERIODSEQ = :i_PeriodSeq
						GROUP BY 
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.STARTDATE,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), ''),
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), ''),
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
							
						UNION ALL
						
						SELECT DISTINCT-- SELECT 3: Tabla OUT_RPI_RESUMEN_REP para el año hasta el mes incluído --Regla de pagos de los cierres SÍ
							'SELECT 3' N_SELECT,
							'Cierre' ORIGEN,
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.STARTDATE,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							INYC_RPI_RESUMEN.V_CREDITO AS V_CREDITO,
							INYC_RPI_RESUMEN.C_GN4 AS C_GN4,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), '') NOMBRE_AGENTE,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), '') NOMBRE_INSPECTOR,
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
						FROM  EXT.OUT_RPI_RESUMEN_REP INYC_RPI_RESUMEN
						INNER JOIN	(SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
									FROM EXT.OUT_JERARQUIA_REP
									WHERE POSITIONSEQ = POSITIONSEQ_PRIN --LLS 20251124: Añadido para eliminar posiciones secundarias
									) J
							ON INYC_RPI_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPI_RESUMEN.PERIODSEQ = J.PERIODSEQ
						WHERE 1 = 1
							--Regla de pagos de los cierres
							AND INYC_RPI_RESUMEN.N_MEDIDA = 'SM-RPP-Inspector-PagoMensual'
							AND INYC_RPI_RESUMEN.PERIODSEQ = :i_PeriodSeq
							
						UNION ALL
						
						SELECT DISTINCT-- SELECT 4: Tabla OUT_BAL_RPI_RESUMEN_REP para el año hasta el mes incluído --Regla de pagos de los cierres SÍ
							'SELECT 4' N_SELECT,
							'Balance' ORIGEN,
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.STARTDATE,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							INYC_RPI_RESUMEN.V_CREDITO AS V_CREDITO,
							INYC_RPI_RESUMEN.C_GN4 AS C_GN4,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), '') NOMBRE_AGENTE,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), '') NOMBRE_INSPECTOR,
							INYC_RPI_RESUMEN.N_MEDIDA || '_Balance',
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
						FROM EXT.OUT_BAL_RPI_RESUMEN_REP INYC_RPI_RESUMEN--LLS 20251031
						INNER JOIN	(SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
									FROM EXT.OUT_JERARQUIA_REP
									WHERE POSITIONSEQ = POSITIONSEQ_PRIN --LLS 20251124: Añadido para eliminar posiciones secundarias
									) J
							ON INYC_RPI_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPI_RESUMEN.PERIODSEQ = J.PERIODSEQ
						WHERE 1 = 1
							--Regla de pagos de los balances
							AND INYC_RPI_RESUMEN.N_MEDIDA = 'SM-RPP-Inspector-PagoMensual'
							AND INYC_RPI_RESUMEN.PERIODSEQ = :i_PeriodSeq
							
					) AS RPI
					
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F
						ON F.TABLA = 'OUT_RPI_RESUMEN_REP'
							AND F.PERIODSEQ = :i_PeriodSeq
				)
				WHERE 1 = 1
					AND (COMISION_PAGO IS NOT NULL OR COMISION_AGENTE IS NOT NULL OR RAPPEL_2_3 IS NOT NULL)
					;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S5_RPI_RESUMEN_FINAL_REP (mensual). Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe S5 RPI RESUMEN (mensual)', i_log_count, i_id_proceso, 'info');


			--BRG 20260129 Informe RPI BAL
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S5 RPI RESUMEN BAL', i_log_count, i_id_proceso, 'info');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_BAL_RPI_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_BAL_RPI_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_BAL_RPI_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_BAL_RPI_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_BAL_RPI_RESUMEN_FINAL_REP (PERIODO_FILTRO, PERIODO_FORMATO, PERIODO_TABLA, STARTDATE, CODIGO_AGENTE, NOMBRE_AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, CODIGO_AGENTE_TABLA, NOMBRE_AGENTE_TABLA, TOTAL_POL_CORR, POL_CORR_RRTT, POL_CORR_HOGAR, POL_CORR_RRPP, ASEG_RRTT, PRIMAS_CORR, IMPORTE_RAPPEL, OBJ_POL_CORR_TOTAL, OBJ_POL_CORR_HOG, OBJ_POL_CORR_RRTT, OBJ_POL_CORR_RRPP, SEG_TOTAL_RAMOS, SEG_HOGAR, SEG_RRTT, SEG_RRPP, CONS_TOTAL_RAMOS, CONS_HOGAR, CONS_RRTT, CONS_RRPP, PAGO_MENSUAL, BAL_MESES_ANT, IMPORTE_A_REG, MIN_GAR, REG_TRIM, IGUALES, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, POSITIONSEQ, PERIODSEQ)
				WITH "QUERY_ORACLE" AS (
					SELECT
						BAL_RPI.POS_PRIN AS CODIGO_AGENTE, --GENERICATTRIBUTE1
						TRIM(IFNULL(BAL_RPI.FIRSTNAME, '') || IFNULL(' ' || BAL_RPI.MIDDLENAME, '') || IFNULL(' ' || BAL_RPI.LASTNAME, '')) AS NOMBRE_AGENTE,
						BAL_RPI.NIF, --GENERICATTRIBUTE14
						LAST_VALUE(TO_INTEGER(BAL_RPI.ID_TIPO_AGENTE) || ' - ' || BAL_RPI.TIPO_AGENTE) OVER (PARTITION BY BAL_RPI.POS_PRIN ORDER BY BAL_RPI.STARTDATE ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS TIPO_AGENTE,
						BAL_RPI.PERIODO, --Period Name
						BAL_RPI.QUARTER, --Quarter
						EXTRACT(MONTH FROM BAL_RPI.STARTDATE) AS MES_NUM,
						MOD(EXTRACT(MONTH FROM BAL_RPI.STARTDATE) - 1, 3) + 1 AS MES_TRIM_NUM,
						BAL_RPI.YEAR, --Year
						BAL_RPI.N_CREDITO, --GENERICATTRIBUTE11
						SUM(BAL_RPI.V_CREDITO) V_CREDITO, --GENERICNUMBER1
						SUM(BAL_RPI.C_GN4) C_GN4, --GENERICNUMBER3
						TRIM(IFNULL(BAL_RPI.FIRSTNAME_AG, '') || IFNULL(' ' || BAL_RPI.MIDDLENAME_AG, '') || IFNULL(' ' || BAL_RPI.LASTNAME_AG, '')) AS NOMBRE_AGENTE_TABLA,
						BAL_RPI.POSITIONNAME_AG AS CODIGO_AGENTE_TABLA,
						BAL_RPI.N_MEDIDA, --GENERICATTRIBUTE12
						BAL_RPI.V_MEDIDA, --GENERICNUMBER5
						BAL_RPI.POSITIONNAME, --GENERICATTRIBUTE5
						BAL_RPI.STARTDATE,
						B.BALANCESEQ,
						BAL_RPI.POSITIONSEQ_PRIN AS POSITIONSEQ
					FROM EXT.OUT_BAL_RPI_RESUMEN_REP BAL_RPI 
					LEFT JOIN (SELECT X.PAYEESEQ, X.POSITIONSEQ, MAX(X.BALANCESEQ) AS BALANCESEQ FROM TCMP.CS_BALANCE X
							WHERE X.PERIODSEQ = :i_PeriodSeq
							GROUP BY X.PAYEESEQ,X.POSITIONSEQ
						) B ON B.PAYEESEQ = BAL_RPI.PARTICIPANTSEQ
						AND B.POSITIONSEQ = BAL_RPI.POSITIONSEQ_PRIN
					WHERE BAL_RPI.QUARTER = :v_period_quarter
						AND BAL_RPI.STARTDATE <= :v_period_startdate
					GROUP BY BAL_RPI.PERIODO, BAL_RPI.QUARTER, BAL_RPI.YEAR, BAL_RPI.N_CREDITO,
						BAL_RPI.FIRSTNAME_AG, BAL_RPI.LASTNAME_AG, BAL_RPI.MIDDLENAME_AG, BAL_RPI.LASTNAME, BAL_RPI.FIRSTNAME, BAL_RPI.MIDDLENAME,
						BAL_RPI.N_MEDIDA, BAL_RPI.V_MEDIDA, BAL_RPI.POSITIONNAME, BAL_RPI.POSITIONNAME_AG,
						BAL_RPI.POS_PRIN, BAL_RPI.ID_TIPO_AGENTE, BAL_RPI.TIPO_AGENTE, BAL_RPI.NIF, BAL_RPI.STARTDATE, B.BALANCESEQ, BAL_RPI.POSITIONSEQ_PRIN
					),
				"VALORES_INTERMEDIOS" AS (
					SELECT
						--Cabecera y Filtros
						:v_period_name AS PERIODO_FILTRO,
						:v_period_name_format AS PERIODO_FORMATO,
						PERIODO AS PERIODO_TABLA,
						MES_NUM,
						MES_TRIM_NUM,
						STARTDATE,
						CODIGO_AGENTE,
						NOMBRE_AGENTE,
						NIF,
						NIF || ' - ' || NOMBRE_AGENTE AS NIF_NOMBRE,
						TIPO_AGENTE,
						
						--Tablas Información Pago Mensual
						CODIGO_AGENTE_TABLA,
						CASE WHEN NOMBRE_AGENTE_TABLA = ''
							THEN NULL
							ELSE NOMBRE_AGENTE_TABLA END AS NOMBRE_AGENTE_TABLA,
						SUM(CASE WHEN (N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-998%' OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-998%')
							THEN C_GN4
							ELSE 0 END) AS TOTAL_POL_CORR,
						SUM(CASE WHEN (N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-001%' OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-001%')
							THEN C_GN4
							ELSE 0 END) AS POL_CORR_RRTT,
						SUM(CASE WHEN (N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-002%' OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-002%')
							THEN C_GN4
							ELSE 0 END) AS POL_CORR_HOGAR,
						SUM(CASE WHEN (N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-906%' OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-906%')
							THEN C_GN4
							ELSE 0 END) AS POL_CORR_RRPP,
						SUM(CASE WHEN N_MEDIDA IN ('PM-O-GEN-Inspector-NumAsegurados-Agentes', 'PM-O-GEN-Agente-NumAsegurados')
							THEN V_CREDITO
							ELSE 0 END) AS ASEG_RRTT,
						SUM(CASE WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-PrimaCorregida-998%'
							THEN V_CREDITO
							ELSE 0 END) AS PRIMAS_CORR,
						NULL AS IMPORTE_RAPPEL,
						
						--Tabla Objetivos Trimestral
						NULL AS OBJ_POL_CORR_TOTAL, NULL AS OBJ_POL_CORR_HOG, NULL AS OBJ_POL_CORR_RRTT, NULL AS OBJ_POL_CORR_RRPP,
						
						--Tabla Seguimiento Trimestral
						NULL AS SEG_TOTAL_RAMOS, NULL AS SEG_HOGAR, NULL AS SEG_RRTT, NULL AS SEG_RRPP,
						NULL AS CONS_TOTAL_RAMOS, NULL AS CONS_HOGAR, NULL AS CONS_RRTT, NULL AS CONS_RRPP,
						
						--Tabla Pagos Trimestral
						NULL AS PAGO_MENSUAL, NULL AS PAGO_MENSUAL_BALANCES,
						NULL AS RAPPEL_MES1, NULL AS RAPPEL_MES2, NULL AS RAPPEL_MES3,
						NULL AS MIN_GAR_MES1, NULL AS MIN_GAR_MES2, NULL AS MIN_GAR_MES3,
						
						--Resto Filtros
						CASE WHEN PERIODO = :v_period_name
							THEN 'SI'
							ELSE 'NO' END AS IGUALES,
						BALANCESEQ,
						POSITIONSEQ
					FROM QUERY_ORACLE
					GROUP BY CODIGO_AGENTE, NOMBRE_AGENTE, NIF, TIPO_AGENTE, PERIODO, STARTDATE, CODIGO_AGENTE_TABLA, NOMBRE_AGENTE_TABLA, MES_NUM, MES_TRIM_NUM,
						BALANCESEQ, POSITIONSEQ 
				
					UNION ALL 
					
					SELECT
						--Cabecera y Filtros
						:v_period_name AS PERIODO_FILTRO,
						:v_period_name_format AS PERIODO_FORMATO,
						PERIODO AS PERIODO_TABLA,
						MES_NUM,
						MES_TRIM_NUM,
						STARTDATE,
						CODIGO_AGENTE,
						NOMBRE_AGENTE,
						NIF,
						NIF || ' - ' || NOMBRE_AGENTE AS NIF_NOMBRE,
						TIPO_AGENTE,
						
						--Tablas Información Pago Mensual
						NULL AS CODIGO_AGENTE_TABLA,
						NULL AS NOMBRE_AGENTE_TABLA,
						SUM(CASE WHEN N_MEDIDA IN ('SM-O-GEN-Inspector-NumeroPolizas-998-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalMes')
							THEN V_MEDIDA
							ELSE 0 END) AS TOTAL_POL_CORR,
						SUM(CASE WHEN N_MEDIDA IN ('SM-O-GEN-Inspector-NumeroPolizas-001-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-001-TotalMes')
							THEN V_MEDIDA
							ELSE 0 END) AS POL_CORR_RRTT,
						SUM(CASE WHEN N_MEDIDA IN ('SM-O-GEN-Inspector-NumeroPolizas-002-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-002-TotalMes')
							THEN V_MEDIDA
							ELSE 0 END) AS POL_CORR_HOGAR,
						SUM(CASE WHEN N_MEDIDA IN ('SM-O-GEN-Inspector-NumeroPolizas-906-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-906-TotalMes')
							THEN V_MEDIDA
							ELSE 0 END) AS POL_CORR_RRPP,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalMes'
							THEN V_MEDIDA
							ELSE 0 END) AS ASEG_RRTT,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Inspector-PrimaCorregida-998-TotalMes'
							THEN V_MEDIDA
							ELSE 0 END) AS PRIMAS_CORR,
						SUM(CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual'
							THEN V_MEDIDA
							ELSE 0 END) AS IMPORTE_RAPPEL,
							
						--Tabla Objetivos Trimestral
						SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-998'
							THEN V_MEDIDA
							ELSE 0 END) AS OBJ_POL_CORR_TOTAL,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-002'
							THEN V_MEDIDA
							ELSE 0 END) AS OBJ_POL_CORR_HOG,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-001'
							THEN V_MEDIDA
							ELSE 0 END) AS OBJ_POL_CORR_RRTT,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-906'
							THEN V_MEDIDA
							ELSE 0 END) AS OBJ_POL_CORR_RRPP,
						
						--Tabla Seguimiento Trimestral
						SUM(CASE WHEN N_MEDIDA IN ('SM-RPP-Inspector-NumeroPolizas-998-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalTrimestre')
							THEN V_MEDIDA 
							ELSE 0 END) AS SEG_TOTAL_RAMOS,
						SUM(CASE WHEN N_MEDIDA IN ('SM-RPP-Inspector-NumeroPolizas-002-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-002-TotalTrimestre')
							THEN V_MEDIDA
							ELSE 0 END) AS SEG_HOGAR,
						SUM(CASE WHEN N_MEDIDA IN ('SM-RPP-Inspector-NumeroPolizas-001-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-001-TotalTrimestre')
							THEN V_MEDIDA
							ELSE 0 END) AS SEG_RRTT,
						SUM(CASE WHEN N_MEDIDA IN ('SM-RPP-Inspector-NumeroPolizas-906-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-906-TotalTrimestre')
							THEN V_MEDIDA
							ELSE 0 END) AS SEG_RRPP,
						SUM(CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-998'
							THEN V_MEDIDA
							ELSE 0 END)*100 AS CONS_TOTAL_RAMOS,
						SUM(CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-002'
							THEN V_MEDIDA
							ELSE 0 END)*100 AS CONS_HOGAR,
						SUM(CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-001'
							THEN V_MEDIDA
							ELSE 0 END)*100 AS CONS_RRTT,
						SUM(CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-906'
							THEN V_MEDIDA
							ELSE 0 END)*100 AS CONS_RRPP,
						
						--Tabla Pagos Trimestral
						SUM(CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual'
							THEN V_MEDIDA
							ELSE 0 END) AS PAGO_MENSUAL,
						SUM(CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual_Balance'
							THEN V_MEDIDA
							ELSE 0 END) AS PAGO_MENSUAL_BALANCES,
						--RAPPEL
						SUM(CASE WHEN N_MEDIDA IN ('SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel1-Mes1', 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel2-Mes1')
							THEN V_MEDIDA
							ELSE 0 END) AS RAPPEL_MES1,
						SUM(CASE WHEN N_MEDIDA IN ('SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel1-Mes2', 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel2-Mes2')
							THEN V_MEDIDA
							ELSE 0 END) AS RAPPEL_MES2,
						SUM(CASE WHEN N_MEDIDA IN ('SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel1-Mes3', 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel2-Mes3')
							THEN V_MEDIDA
							ELSE 0 END) AS RAPPEL_MES3,
						--MIN_GAR
						SUM(CASE WHEN N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes1'
							THEN V_MEDIDA
							ELSE 0 END) AS MIN_GAR_MES1,
						SUM(CASE WHEN N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes2'
							THEN V_MEDIDA
							ELSE 0 END) AS MIN_GAR_MES2,
						SUM(CASE WHEN N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes3'
							THEN V_MEDIDA
							ELSE 0 END) AS MIN_GAR_MES3,
						
						--Resto Filtros
						CASE WHEN PERIODO = :v_period_name
							THEN 'SI'
							ELSE 'NO' END AS IGUALES,
						BALANCESEQ,
						POSITIONSEQ
					FROM QUERY_ORACLE
					GROUP BY CODIGO_AGENTE, NOMBRE_AGENTE, NIF, TIPO_AGENTE, PERIODO, STARTDATE, MES_NUM, MES_TRIM_NUM,
						BALANCESEQ, POSITIONSEQ
				), 
				"CALCULOS_FINALES" AS (
					SELECT 
						--Cabecera y Filtros
						PERIODO_FILTRO, PERIODO_FORMATO, PERIODO_TABLA, MES_NUM, MES_TRIM_NUM, STARTDATE, CODIGO_AGENTE, NOMBRE_AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE,
						
						--Tablas Información Pago Mensual
						CODIGO_AGENTE_TABLA, NOMBRE_AGENTE_TABLA, 
						SUM(TOTAL_POL_CORR) AS TOTAL_POL_CORR, SUM(POL_CORR_RRTT) AS POL_CORR_RRTT, SUM(POL_CORR_HOGAR) AS POL_CORR_HOGAR, 
						SUM(POL_CORR_RRPP) AS POL_CORR_RRPP, SUM(ASEG_RRTT) AS ASEG_RRTT, SUM(PRIMAS_CORR) AS PRIMAS_CORR, SUM(IMPORTE_RAPPEL) AS IMPORTE_RAPPEL,
						
						--Tabla Objetivos Trimestral
						SUM(OBJ_POL_CORR_TOTAL) AS OBJ_POL_CORR_TOTAL, SUM(OBJ_POL_CORR_HOG) AS OBJ_POL_CORR_HOG,
						SUM(OBJ_POL_CORR_RRTT) AS OBJ_POL_CORR_RRTT, SUM(OBJ_POL_CORR_RRPP) AS OBJ_POL_CORR_RRPP,
						
						--Tabla Seguimiento Trimestral
						SUM(SEG_TOTAL_RAMOS) AS SEG_TOTAL_RAMOS, SUM(SEG_HOGAR) AS SEG_HOGAR, SUM(SEG_RRTT) AS SEG_RRTT,
						SUM(SEG_RRPP) AS SEG_RRPP, SUM(CONS_TOTAL_RAMOS) AS CONS_TOTAL_RAMOS, SUM(CONS_HOGAR) AS CONS_HOGAR,
						SUM(CONS_RRTT) AS CONS_RRTT, SUM(CONS_RRPP) AS CONS_RRPP,
						
						--Tabla Pagos Trimestral
						SUM(PAGO_MENSUAL) AS PAGO_MENSUAL,
						SUM(PAGO_MENSUAL_BALANCES) AS PAGO_MENSUAL_BALANCES,
						MAX(CASE 
							WHEN MES_TRIM_NUM = 1
								THEN (SELECT VI2.RAPPEL_MES1 FROM VALORES_INTERMEDIOS VI2 WHERE VI1.CODIGO_AGENTE = VI2.CODIGO_AGENTE AND MES_TRIM_NUM = 3 AND RAPPEL_MES1 IS NOT NULL)
							WHEN MES_TRIM_NUM = 2
								THEN (SELECT VI2.RAPPEL_MES2 FROM VALORES_INTERMEDIOS VI2 WHERE VI1.CODIGO_AGENTE = VI2.CODIGO_AGENTE AND MES_TRIM_NUM = 3 AND RAPPEL_MES2 IS NOT NULL)
							WHEN MES_TRIM_NUM = 3
								THEN (SELECT VI2.RAPPEL_MES3 FROM VALORES_INTERMEDIOS VI2 WHERE VI1.CODIGO_AGENTE = VI2.CODIGO_AGENTE AND MES_TRIM_NUM = 3 AND RAPPEL_MES3 IS NOT NULL)
							END) AS RAPPEL,
						MAX(CASE
							WHEN MES_TRIM_NUM = 1
								THEN (SELECT VI2.MIN_GAR_MES1 FROM VALORES_INTERMEDIOS VI2 WHERE VI1.CODIGO_AGENTE = VI2.CODIGO_AGENTE AND MES_TRIM_NUM = 3 AND MIN_GAR_MES1 IS NOT NULL)
							WHEN MES_TRIM_NUM = 2
								THEN (SELECT VI2.MIN_GAR_MES2 FROM VALORES_INTERMEDIOS VI2 WHERE VI1.CODIGO_AGENTE = VI2.CODIGO_AGENTE AND MES_TRIM_NUM = 3 AND MIN_GAR_MES2 IS NOT NULL)
							WHEN MES_TRIM_NUM = 3
								THEN (SELECT VI2.MIN_GAR_MES3 FROM VALORES_INTERMEDIOS VI2 WHERE VI1.CODIGO_AGENTE = VI2.CODIGO_AGENTE AND MES_TRIM_NUM = 3 AND MIN_GAR_MES3 IS NOT NULL)
							END) AS MIN_GAR,
						
						--Resto Filtros
						IGUALES,
						BALANCESEQ,
						POSITIONSEQ
					FROM VALORES_INTERMEDIOS VI1
					GROUP BY PERIODO_FILTRO, PERIODO_FORMATO, PERIODO_TABLA, MES_NUM, MES_TRIM_NUM, STARTDATE, CODIGO_AGENTE, NOMBRE_AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE,
						CODIGO_AGENTE_TABLA, NOMBRE_AGENTE_TABLA, IGUALES, BALANCESEQ, POSITIONSEQ
				) 
				SELECT 
					--Cabecera y Filtros
					PERIODO_FILTRO, PERIODO_FORMATO, PERIODO_TABLA, STARTDATE, CODIGO_AGENTE, NOMBRE_AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE,
					
					--Tablas Información Pago Mensual
					CODIGO_AGENTE_TABLA, NOMBRE_AGENTE_TABLA, TOTAL_POL_CORR, POL_CORR_RRTT, POL_CORR_HOGAR, POL_CORR_RRPP, ASEG_RRTT, PRIMAS_CORR, IMPORTE_RAPPEL,
					
					--Tabla Objetivos Trimestral
					OBJ_POL_CORR_TOTAL, OBJ_POL_CORR_HOG, OBJ_POL_CORR_RRTT, OBJ_POL_CORR_RRPP,
					
					--Tabla Seguimiento Trimestral
					SEG_TOTAL_RAMOS, SEG_HOGAR, SEG_RRTT, SEG_RRPP, CONS_TOTAL_RAMOS, CONS_HOGAR, CONS_RRTT, CONS_RRPP,
					
					--Tabla Pagos Trimestral
					PAGO_MENSUAL,
					PAGO_MENSUAL_BALANCES AS BAL_MESES_ANT,
					--RAPPEL,
					CASE WHEN PAGO_MENSUAL > RAPPEL
						THEN 0
						ELSE RAPPEL
						END AS IMPORTE_A_REG,
					GREATEST(MIN_GAR, 0) AS MIN_GAR,
					CASE WHEN PAGO_MENSUAL > RAPPEL
						THEN 0
						ELSE RAPPEL - PAGO_MENSUAL
						END AS REG_TRIM,
					
					--Resto Filtros
					IGUALES,
					CASE WHEN BALANCESEQ IS NOT NULL
						THEN 'SI'
						ELSE NULL
						END AS SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					POSITIONSEQ,
					:i_PeriodSeq AS PERIODSEQ
				FROM CALCULOS_FINALES CF
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
					AND F.TABLA = 'OUT_BAL_RPI_RESUMEN_REP';
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_BAL_RPI_RESUMEN_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe S5 RPI RESUMEN BAL', i_log_count, i_id_proceso, 'info');


			--DTB 20251223 Informe RPI LC (utiliza una tabla distinta al de cierre)
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S5 RPI RESUMEN LC', i_log_count, i_id_proceso, 'info');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_LC_S5_RPI_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_LC_S5_RPI_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_LC_S5_RPI_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_LC_S5_RPI_RESUMEN_FINAL_REP. LC', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_LC_S5_RPI_RESUMEN_FINAL_REP(FECHA_ULT_ACT,SOLO_DIFERENCIAS,QUARTER,PERIODO_FILTRO,PERIODO_FILTRO_FORMATO,PERIODO,REGIONAL,SUCURSAL,OFICINA,TIPO_AGENTE,NIF,NOMBRE,AGENTE,NOMBRE_AG,POSITIONNAME_AG,POSITIONSEQ,PERIODSEQ,NOMBRE_FIL,TABLA_INFORME,PAGO_MENS_POLIZAS_CORREGIDAS_HOGAR,PAGO_MENS_POLIZAS_CORREGIDAS_RRTT,PAGO_MENS_POLIZAS_CORREGIDAS_RRPP_EXCLUIR_SUPERPLAN,PAGO_MENS_IMPORTE_RAPPEL,PAGO_MENS_TOTAL_POLIZAS_CORREGIDAS,PAGO_MENS_ASEGURADOS_RRTT,PAGO_MENS_PRIMAS_CORREGIDAS,PAGO_AGENTES_MENS_POLIZAS_CORREGIDAS_RRTT,PAGO_AGENTES_MENS_PRIMAS_CORREGIDAS,PAGO_AGENTES_MENS_ASEGURADOS_RRTT,PAGO_AGENTES_MENS_POLIZAS_CORREGIDAS_RRPP_EXCL_PUCC,PAGO_AGENTES_MENS_POLIZAS_CORREGIDAS_HOGAR,PAGO_AGENTES_MENS_TOTAL_POLIZAS_CORREGIDAS,OBJ_TRIMESTRAL_N_POLIZAS_CORREGIDAS_HOGAR,OBJ_TRIMESTRAL_N_POLIZAS_CORREGIDAS_RRPP_EXCL_PUCC,OBJ_TRIMESTRAL_N_POLIZAS_CORREGIDAS_RRTT,OBJ_TRIMESTRAL_N_POLIZAS_CORREGIDAS_TOTAL_RAMOS,SEG_TRIMESTRAL_ACUMULADO_HOGAR,SEG_TRIMESTRAL_ACUMULADO_RRTT,SEG_TRIMESTRAL_CONSECUCION_HOGAR,SEG_TRIMESTRAL_CONSECUCION_RRTT_EXCEL_PUCC,SEG_TRIMESTRAL_CONSECUCION_RRTT,SEG_TRIMESTRAL_ACUMULADO_RRTT_EXCEL_PUCC,SEG_TRIMESTRAL_ACUMULADO_TR,SEG_TRIMESTRAL_CONSECUCION_TR,PAGO_TRIMESTRAL_PAGO_MENSUAL,PAGO_TRIMESTRAL_BALANCES_MESES_ANTERIORES,PAGO_TRIMESTRAL_IMPORTE_A_REGULARIZAR,PAGO_TRIMESTRAL_MINIMOS_GARANTIZADOS,PAGO_TRIMESTRAL_REGULACION_TRIMESTRAL)
				WITH CTE_INFO_QUARTER AS (
					SELECT DISTINCT
						--P1.PARENTSEQ AS QSEQ_FILTRO,
						P3.NAME AS QUARTER_FILTRO,
						P1.PERIODSEQ AS PSEQ_FILTRO,
						P1.NAME AS PERIODO_FILTRO,
						P1.STARTDATE AS STARTDATE_FILTRO,
						--P2.PARENTSEQ AS QSEQ,
						P4.NAME AS QUARTER,
						--P2.PERIODSEQ AS PSEQ,
						P2.NAME AS PERIODO,
						P2.STARTDATE AS STARTDATE
					FROM CS_PERIOD P1
					LEFT JOIN CS_PERIOD P2 ON RIGHT(P1.NAME, 4) = RIGHT(P2.NAME, 4)
											AND P2.STARTDATE <= P1.STARTDATE
											AND P2.PERIODTYPESEQ = P1.PERIODTYPESEQ
					LEFT JOIN CS_PERIOD P3 ON P1.PARENTSEQ = P3.PERIODSEQ
					LEFT JOIN CS_PERIOD P4 ON P2.PARENTSEQ = P4.PERIODSEQ
					WHERE P1.PERIODSEQ = :i_PeriodSeq
					AND (P1.NAME LIKE 'Diciembre%' OR (P1.NAME NOT LIKE 'Diciembre%' AND P4.NAME = P3.NAME)) -- DTB solo hay pestaña anual en diciembre
					AND (SUBSTR_BEFORE(P1.NAME, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') OR SUBSTR_BEFORE(P1.NAME, ' ') NOT IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') AND P1.NAME = P2.NAME)
					ORDER BY STARTDATE DESC 
				),
				TBL_PER_FORMAT AS (SELECT DISTINCT
								J.PERIODO,
								SUBSTR_AFTER(J.PERIODO, ' ') || CASE 
									WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Enero' THEN ' 01 '
									WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Febrero' THEN ' 02 '
									WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Marzo' THEN ' 03 '
									WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Abril' THEN ' 04 '
									WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Mayo' THEN ' 05 '
									WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Junio' THEN ' 06 '
									WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Julio' THEN ' 07 '
									WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Agosto' THEN ' 08 '
									WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
									WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Octubre' THEN ' 10 '
									WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
									WHEN SUBSTR_BEFORE(J.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
									END || SUBSTR_BEFORE(J.PERIODO, ' ') AS PERIODO_FORMATO
							FROM EXT.OUT_JERARQUIA_REP J),
				CTE_TABLA_PREVIA AS (
				    SELECT --CONSULTA PARA LC SOLO DIFERENCIAS
				      OUT_LC_RPI_RESUMEN_REP.NIVEL_PTO_VENTA,
				      OUT_LC_RPI_RESUMEN_REP.COD_PTO_VENTA,
				      OUT_LC_RPI_RESUMEN_REP.PTO_VENTA,
				      OUT_LC_RPI_RESUMEN_REP.NIVEL_OFICINA,
				      OUT_LC_RPI_RESUMEN_REP.COD_OFICINA,
				      OUT_LC_RPI_RESUMEN_REP.OFICINA,
				      OUT_LC_RPI_RESUMEN_REP.NIVEL_SUCURSAL,
				      OUT_LC_RPI_RESUMEN_REP.COD_SUCURSAL,
				      OUT_LC_RPI_RESUMEN_REP.SUCURSAL,
				      OUT_LC_RPI_RESUMEN_REP.NIVEL_REGIONAL,
				      OUT_LC_RPI_RESUMEN_REP.COD_REGIONAL,
				      OUT_LC_RPI_RESUMEN_REP.REGIONAL,
				      OUT_LC_RPI_RESUMEN_REP.PERIODO,
				      OUT_LC_RPI_RESUMEN_REP.QUARTER,
				      OUT_LC_RPI_RESUMEN_REP.YEAR,
				      OUT_LC_RPI_RESUMEN_REP.N_CREDITO,
				      SUM(OUT_LC_RPI_RESUMEN_REP.V_CREDITO) AS V_CREDITO,
				      SUM(OUT_LC_RPI_RESUMEN_REP.C_GN4) AS C_GN4,
				      OUT_LC_RPI_RESUMEN_REP.FIRSTNAME_AG,
				      OUT_LC_RPI_RESUMEN_REP.LASTNAME_AG,
				      OUT_LC_RPI_RESUMEN_REP.MIDDLENAME_AG,
				      OUT_LC_RPI_RESUMEN_REP.LASTNAME,
				      OUT_LC_RPI_RESUMEN_REP.FIRSTNAME,
				      OUT_LC_RPI_RESUMEN_REP.MIDDLENAME,
				      OUT_LC_RPI_RESUMEN_REP.N_MEDIDA,
				      OUT_LC_RPI_RESUMEN_REP.V_MEDIDA,
				      OUT_LC_RPI_RESUMEN_REP.POSITIONNAME,
				      J.POS_CALLIDUS,
				      OUT_LC_RPI_RESUMEN_REP.POSITIONNAME_AG,
				      OUT_LC_RPI_RESUMEN_REP.POS_PRIN,
				      OUT_LC_RPI_RESUMEN_REP.ID_TIPO_AGENTE,
				      OUT_LC_RPI_RESUMEN_REP.TIPO_AGENTE,
				      OUT_LC_RPI_RESUMEN_REP.NIF,
				      'SI' AS SOLO_DIFERENCIAS,
				      Q.QUARTER_FILTRO,
					  Q.PSEQ_FILTRO,
					  Q.PERIODO_FILTRO,
					  Q.STARTDATE_FILTRO,
				      OUT_LC_RPI_RESUMEN_REP.POSITIONSEQ_PRIN AS POSITIONSEQ,
				      Q.PSEQ_FILTRO AS PERIODSEQ
				    FROM EXT.OUT_LC_RPI_RESUMEN_REP OUT_LC_RPI_RESUMEN_REP
				    INNER JOIN EXT.OUT_JERARQUIA_REP J
				      ON J.PERIODSEQ = :i_PeriodSeq
				      AND J.PARTICIPANTSEQ = OUT_LC_RPI_RESUMEN_REP.PARTICIPANTSEQ
				      AND J.POSITIONSEQ_PRIN = OUT_LC_RPI_RESUMEN_REP.POSITIONSEQ_PRIN
				    LEFT JOIN (SELECT X.PAYEESEQ,X.POSITIONSEQ,MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE FROM TCMP.CS_PAYMENT X
				               WHERE X.TENANTID = :v_idtenant AND X.PERIODSEQ = :i_PeriodSeq
				               GROUP BY X.PAYEESEQ,X.POSITIONSEQ
				        ) B ON B.PAYEESEQ = OUT_LC_RPI_RESUMEN_REP.PARTICIPANTSEQ
				        AND B.POSITIONSEQ = OUT_LC_RPI_RESUMEN_REP.POSITIONSEQ_PRIN
				    INNER JOIN (SELECT DISTINCT QUARTER_FILTRO, PSEQ_FILTRO, PERIODO_FILTRO, STARTDATE_FILTRO FROM CTE_INFO_QUARTER) Q ON OUT_LC_RPI_RESUMEN_REP.PERIODO = Q.PERIODO_FILTRO
				    WHERE 1 = 1
				       AND (B.POSTPIPELINERUNDATE IS NULL OR B.POSTPIPELINERUNDATE > LAST_DAY(Q.STARTDATE_FILTRO))

				    GROUP BY OUT_LC_RPI_RESUMEN_REP.NIVEL_PTO_VENTA, OUT_LC_RPI_RESUMEN_REP.COD_PTO_VENTA, OUT_LC_RPI_RESUMEN_REP.PTO_VENTA,
				    OUT_LC_RPI_RESUMEN_REP.NIVEL_OFICINA, OUT_LC_RPI_RESUMEN_REP.COD_OFICINA, OUT_LC_RPI_RESUMEN_REP.OFICINA,
				    OUT_LC_RPI_RESUMEN_REP.NIVEL_SUCURSAL, OUT_LC_RPI_RESUMEN_REP.COD_SUCURSAL, OUT_LC_RPI_RESUMEN_REP.SUCURSAL,
				    OUT_LC_RPI_RESUMEN_REP.NIVEL_REGIONAL, OUT_LC_RPI_RESUMEN_REP.COD_REGIONAL, OUT_LC_RPI_RESUMEN_REP.REGIONAL,
				    OUT_LC_RPI_RESUMEN_REP.PERIODO, OUT_LC_RPI_RESUMEN_REP.QUARTER, OUT_LC_RPI_RESUMEN_REP.YEAR, OUT_LC_RPI_RESUMEN_REP.N_CREDITO,
				    OUT_LC_RPI_RESUMEN_REP.FIRSTNAME_AG, OUT_LC_RPI_RESUMEN_REP.LASTNAME_AG, OUT_LC_RPI_RESUMEN_REP.MIDDLENAME_AG,
				    OUT_LC_RPI_RESUMEN_REP.LASTNAME, OUT_LC_RPI_RESUMEN_REP.FIRSTNAME, OUT_LC_RPI_RESUMEN_REP.MIDDLENAME,
				    OUT_LC_RPI_RESUMEN_REP.N_MEDIDA, OUT_LC_RPI_RESUMEN_REP.V_MEDIDA, OUT_LC_RPI_RESUMEN_REP.POSITIONNAME,
				    OUT_LC_RPI_RESUMEN_REP.POSITIONNAME_AG, OUT_LC_RPI_RESUMEN_REP.POS_PRIN, OUT_LC_RPI_RESUMEN_REP.ID_TIPO_AGENTE,
				    OUT_LC_RPI_RESUMEN_REP.TIPO_AGENTE, OUT_LC_RPI_RESUMEN_REP.NIF, Q.QUARTER_FILTRO, Q.PSEQ_FILTRO, Q.PERIODO_FILTRO,
				    Q.STARTDATE_FILTRO, OUT_LC_RPI_RESUMEN_REP.POSITIONSEQ_PRIN, Q.PSEQ_FILTRO, J.POS_CALLIDUS

				    UNION

				    SELECT --CONSULTA PARA LC NO DIFERENCIAS
				      OUT_LC_RPI_RESUMEN_REP.NIVEL_PTO_VENTA,
				      OUT_LC_RPI_RESUMEN_REP.COD_PTO_VENTA,
				      OUT_LC_RPI_RESUMEN_REP.PTO_VENTA,
				      OUT_LC_RPI_RESUMEN_REP.NIVEL_OFICINA,
				      OUT_LC_RPI_RESUMEN_REP.COD_OFICINA,
				      OUT_LC_RPI_RESUMEN_REP.OFICINA,
				      OUT_LC_RPI_RESUMEN_REP.NIVEL_SUCURSAL,
				      OUT_LC_RPI_RESUMEN_REP.COD_SUCURSAL,
				      OUT_LC_RPI_RESUMEN_REP.SUCURSAL,
				      OUT_LC_RPI_RESUMEN_REP.NIVEL_REGIONAL,
				      OUT_LC_RPI_RESUMEN_REP.COD_REGIONAL,
				      OUT_LC_RPI_RESUMEN_REP.REGIONAL,
				      OUT_LC_RPI_RESUMEN_REP.PERIODO,
				      OUT_LC_RPI_RESUMEN_REP.QUARTER,
				      OUT_LC_RPI_RESUMEN_REP.YEAR,
				      OUT_LC_RPI_RESUMEN_REP.N_CREDITO,
				      SUM(OUT_LC_RPI_RESUMEN_REP.V_CREDITO) AS V_CREDITO,
				      SUM(OUT_LC_RPI_RESUMEN_REP.C_GN4) AS C_GN4,
				      OUT_LC_RPI_RESUMEN_REP.FIRSTNAME_AG,
				      OUT_LC_RPI_RESUMEN_REP.LASTNAME_AG,
				      OUT_LC_RPI_RESUMEN_REP.MIDDLENAME_AG,
				      OUT_LC_RPI_RESUMEN_REP.LASTNAME,
				      OUT_LC_RPI_RESUMEN_REP.FIRSTNAME,
				      OUT_LC_RPI_RESUMEN_REP.MIDDLENAME,
				      OUT_LC_RPI_RESUMEN_REP.N_MEDIDA,
				      OUT_LC_RPI_RESUMEN_REP.V_MEDIDA,
				      OUT_LC_RPI_RESUMEN_REP.POSITIONNAME,
				      J.POS_CALLIDUS,
				      OUT_LC_RPI_RESUMEN_REP.POSITIONNAME_AG,
				      OUT_LC_RPI_RESUMEN_REP.POS_PRIN,
				      OUT_LC_RPI_RESUMEN_REP.ID_TIPO_AGENTE,
				      OUT_LC_RPI_RESUMEN_REP.TIPO_AGENTE,
				      OUT_LC_RPI_RESUMEN_REP.NIF,
				      'NO' AS SOLO_DIFERENCIAS,
				      Q.QUARTER_FILTRO,
					  Q.PSEQ_FILTRO,
					  Q.PERIODO_FILTRO,
					  Q.STARTDATE_FILTRO,
					  OUT_LC_RPI_RESUMEN_REP.POSITIONSEQ_PRIN AS POSITIONSEQ,
				      Q.PSEQ_FILTRO AS PERIODSEQ
				    FROM EXT.OUT_LC_RPI_RESUMEN_REP OUT_LC_RPI_RESUMEN_REP
				    INNER JOIN EXT.OUT_JERARQUIA_REP J
				      ON J.PERIODSEQ = :i_PeriodSeq
				      AND J.PARTICIPANTSEQ = OUT_LC_RPI_RESUMEN_REP.PARTICIPANTSEQ
				      AND J.POSITIONSEQ_PRIN = OUT_LC_RPI_RESUMEN_REP.POSITIONSEQ_PRIN
				    LEFT JOIN (SELECT X.PAYEESEQ,X.POSITIONSEQ,MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE FROM TCMP.CS_PAYMENT X
				               WHERE X.TENANTID = :v_idtenant AND X.PERIODSEQ = :i_PeriodSeq
				               GROUP BY X.PAYEESEQ,X.POSITIONSEQ
				        ) B ON B.PAYEESEQ = OUT_LC_RPI_RESUMEN_REP.PARTICIPANTSEQ
				        AND B.POSITIONSEQ = OUT_LC_RPI_RESUMEN_REP.POSITIONSEQ_PRIN
				    INNER JOIN (SELECT DISTINCT QUARTER_FILTRO, PSEQ_FILTRO, PERIODO_FILTRO, STARTDATE_FILTRO FROM CTE_INFO_QUARTER) Q ON OUT_LC_RPI_RESUMEN_REP.PERIODO = Q.PERIODO_FILTRO
				    WHERE 1 = 1

				       --AND (B.POSTPIPELINERUNDATE IS NULL OR B.POSTPIPELINERUNDATE > LAST_DAY(Q.STARTDATE_FILTRO))

				    GROUP BY OUT_LC_RPI_RESUMEN_REP.NIVEL_PTO_VENTA, OUT_LC_RPI_RESUMEN_REP.COD_PTO_VENTA, OUT_LC_RPI_RESUMEN_REP.PTO_VENTA,
				    OUT_LC_RPI_RESUMEN_REP.NIVEL_OFICINA, OUT_LC_RPI_RESUMEN_REP.COD_OFICINA, OUT_LC_RPI_RESUMEN_REP.OFICINA,
				    OUT_LC_RPI_RESUMEN_REP.NIVEL_SUCURSAL, OUT_LC_RPI_RESUMEN_REP.COD_SUCURSAL, OUT_LC_RPI_RESUMEN_REP.SUCURSAL,
				    OUT_LC_RPI_RESUMEN_REP.NIVEL_REGIONAL, OUT_LC_RPI_RESUMEN_REP.COD_REGIONAL, OUT_LC_RPI_RESUMEN_REP.REGIONAL,
				    OUT_LC_RPI_RESUMEN_REP.PERIODO, OUT_LC_RPI_RESUMEN_REP.QUARTER, OUT_LC_RPI_RESUMEN_REP.YEAR, OUT_LC_RPI_RESUMEN_REP.N_CREDITO,
				    OUT_LC_RPI_RESUMEN_REP.FIRSTNAME_AG, OUT_LC_RPI_RESUMEN_REP.LASTNAME_AG, OUT_LC_RPI_RESUMEN_REP.MIDDLENAME_AG,
				    OUT_LC_RPI_RESUMEN_REP.LASTNAME, OUT_LC_RPI_RESUMEN_REP.FIRSTNAME, OUT_LC_RPI_RESUMEN_REP.MIDDLENAME,
				    OUT_LC_RPI_RESUMEN_REP.N_MEDIDA, OUT_LC_RPI_RESUMEN_REP.V_MEDIDA, OUT_LC_RPI_RESUMEN_REP.POSITIONNAME,
				    OUT_LC_RPI_RESUMEN_REP.POSITIONNAME_AG, OUT_LC_RPI_RESUMEN_REP.POS_PRIN, OUT_LC_RPI_RESUMEN_REP.ID_TIPO_AGENTE,
				    OUT_LC_RPI_RESUMEN_REP.TIPO_AGENTE, OUT_LC_RPI_RESUMEN_REP.NIF, Q.QUARTER_FILTRO, Q.PSEQ_FILTRO, Q.PERIODO_FILTRO,
				    Q.STARTDATE_FILTRO, OUT_LC_RPI_RESUMEN_REP.POSITIONSEQ_PRIN, Q.PSEQ_FILTRO, J.POS_CALLIDUS

				    UNION

				    SELECT --CONSULTA PARA BAL SOLO DIFERENCIAS
				      OUT_BAL_RPI_RESUMEN_REP.NIVEL_PTO_VENTA,
				      OUT_BAL_RPI_RESUMEN_REP.COD_PTO_VENTA,
				      OUT_BAL_RPI_RESUMEN_REP.PTO_VENTA,
				      OUT_BAL_RPI_RESUMEN_REP.NIVEL_OFICINA,
				      OUT_BAL_RPI_RESUMEN_REP.COD_OFICINA,
				      OUT_BAL_RPI_RESUMEN_REP.OFICINA,
				      OUT_BAL_RPI_RESUMEN_REP.NIVEL_SUCURSAL,
				      OUT_BAL_RPI_RESUMEN_REP.COD_SUCURSAL,
				      OUT_BAL_RPI_RESUMEN_REP.SUCURSAL,
				      OUT_BAL_RPI_RESUMEN_REP.NIVEL_REGIONAL,
				      OUT_BAL_RPI_RESUMEN_REP.COD_REGIONAL,
				      OUT_BAL_RPI_RESUMEN_REP.REGIONAL,
				      OUT_BAL_RPI_RESUMEN_REP.PERIODO,
				      OUT_BAL_RPI_RESUMEN_REP.QUARTER,
				      OUT_BAL_RPI_RESUMEN_REP.YEAR,
				      OUT_BAL_RPI_RESUMEN_REP.N_CREDITO,
				      SUM(OUT_BAL_RPI_RESUMEN_REP.V_CREDITO) AS V_CREDITO,
				      SUM(OUT_BAL_RPI_RESUMEN_REP.C_GN4) AS C_GN4,
				      OUT_BAL_RPI_RESUMEN_REP.FIRSTNAME_AG,
				      OUT_BAL_RPI_RESUMEN_REP.LASTNAME_AG,
				      OUT_BAL_RPI_RESUMEN_REP.MIDDLENAME_AG,
				      OUT_BAL_RPI_RESUMEN_REP.LASTNAME,
				      OUT_BAL_RPI_RESUMEN_REP.FIRSTNAME,
				      OUT_BAL_RPI_RESUMEN_REP.MIDDLENAME,
				      OUT_BAL_RPI_RESUMEN_REP.N_MEDIDA,-- || '_Balances' AS N_MEDIDA,
				      OUT_BAL_RPI_RESUMEN_REP.V_MEDIDA,
				      OUT_BAL_RPI_RESUMEN_REP.POSITIONNAME,
				      J.POS_CALLIDUS,
				      OUT_BAL_RPI_RESUMEN_REP.POSITIONNAME_AG,
				      OUT_BAL_RPI_RESUMEN_REP.POS_PRIN,
				      OUT_BAL_RPI_RESUMEN_REP.ID_TIPO_AGENTE,
				      OUT_BAL_RPI_RESUMEN_REP.TIPO_AGENTE,
				      OUT_BAL_RPI_RESUMEN_REP.NIF,
				      'SI' AS SOLO_DIFERENCIAS,
				      Q.QUARTER_FILTRO,
					    Q.PSEQ_FILTRO,
					    Q.PERIODO_FILTRO,
					    Q.STARTDATE_FILTRO,
					    OUT_BAL_RPI_RESUMEN_REP.POSITIONSEQ_PRIN AS POSITIONSEQ,
				      Q.PSEQ_FILTRO AS PERIODSEQ
				    FROM EXT.OUT_BAL_RPI_RESUMEN_REP OUT_BAL_RPI_RESUMEN_REP
				    INNER JOIN EXT.OUT_JERARQUIA_REP J
				      ON J.PERIODSEQ = :i_PeriodSeq
				      AND J.PARTICIPANTSEQ = OUT_BAL_RPI_RESUMEN_REP.PARTICIPANTSEQ
				      AND J.POSITIONSEQ_PRIN = OUT_BAL_RPI_RESUMEN_REP.POSITIONSEQ_PRIN
				    LEFT JOIN (SELECT X.PAYEESEQ,X.POSITIONSEQ,MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE FROM TCMP.CS_PAYMENT X
				               WHERE X.TENANTID = :v_idtenant AND X.PERIODSEQ = :i_PeriodSeq
				               GROUP BY X.PAYEESEQ,X.POSITIONSEQ
				        ) B ON B.PAYEESEQ = OUT_BAL_RPI_RESUMEN_REP.PARTICIPANTSEQ
				        AND B.POSITIONSEQ = OUT_BAL_RPI_RESUMEN_REP.POSITIONSEQ_PRIN
				    INNER JOIN CTE_INFO_QUARTER Q ON OUT_BAL_RPI_RESUMEN_REP.PERIODO = Q.PERIODO
				    WHERE 1 = 1
				       AND (B.POSTPIPELINERUNDATE IS NULL OR B.POSTPIPELINERUNDATE > LAST_DAY(Q.STARTDATE_FILTRO))

				    GROUP BY OUT_BAL_RPI_RESUMEN_REP.NIVEL_PTO_VENTA, OUT_BAL_RPI_RESUMEN_REP.COD_PTO_VENTA, OUT_BAL_RPI_RESUMEN_REP.PTO_VENTA,
				    OUT_BAL_RPI_RESUMEN_REP.NIVEL_OFICINA, OUT_BAL_RPI_RESUMEN_REP.COD_OFICINA, OUT_BAL_RPI_RESUMEN_REP.OFICINA,
				    OUT_BAL_RPI_RESUMEN_REP.NIVEL_SUCURSAL, OUT_BAL_RPI_RESUMEN_REP.COD_SUCURSAL, OUT_BAL_RPI_RESUMEN_REP.SUCURSAL,
				    OUT_BAL_RPI_RESUMEN_REP.NIVEL_REGIONAL, OUT_BAL_RPI_RESUMEN_REP.COD_REGIONAL, OUT_BAL_RPI_RESUMEN_REP.REGIONAL,
				    OUT_BAL_RPI_RESUMEN_REP.PERIODO, OUT_BAL_RPI_RESUMEN_REP.QUARTER, OUT_BAL_RPI_RESUMEN_REP.YEAR, OUT_BAL_RPI_RESUMEN_REP.N_CREDITO,
				    OUT_BAL_RPI_RESUMEN_REP.FIRSTNAME_AG, OUT_BAL_RPI_RESUMEN_REP.LASTNAME_AG, OUT_BAL_RPI_RESUMEN_REP.MIDDLENAME_AG,
				    OUT_BAL_RPI_RESUMEN_REP.LASTNAME, OUT_BAL_RPI_RESUMEN_REP.FIRSTNAME, OUT_BAL_RPI_RESUMEN_REP.MIDDLENAME,
				    OUT_BAL_RPI_RESUMEN_REP.N_MEDIDA, OUT_BAL_RPI_RESUMEN_REP.V_MEDIDA, OUT_BAL_RPI_RESUMEN_REP.POSITIONNAME,
				    OUT_BAL_RPI_RESUMEN_REP.POSITIONNAME_AG, OUT_BAL_RPI_RESUMEN_REP.POS_PRIN, OUT_BAL_RPI_RESUMEN_REP.ID_TIPO_AGENTE,
				    OUT_BAL_RPI_RESUMEN_REP.TIPO_AGENTE, OUT_BAL_RPI_RESUMEN_REP.NIF, Q.QUARTER_FILTRO, Q.PSEQ_FILTRO, Q.PERIODO_FILTRO,
				    Q.STARTDATE_FILTRO, OUT_BAL_RPI_RESUMEN_REP.POSITIONSEQ_PRIN, Q.PSEQ_FILTRO, J.POS_CALLIDUS

				    UNION

				    SELECT --CONSULTA PARA LC NO DIFERENCIAS
				      OUT_BAL_RPI_RESUMEN_REP.NIVEL_PTO_VENTA,
				      OUT_BAL_RPI_RESUMEN_REP.COD_PTO_VENTA,
				      OUT_BAL_RPI_RESUMEN_REP.PTO_VENTA,
				      OUT_BAL_RPI_RESUMEN_REP.NIVEL_OFICINA,
				      OUT_BAL_RPI_RESUMEN_REP.COD_OFICINA,
				      OUT_BAL_RPI_RESUMEN_REP.OFICINA,
				      OUT_BAL_RPI_RESUMEN_REP.NIVEL_SUCURSAL,
				      OUT_BAL_RPI_RESUMEN_REP.COD_SUCURSAL,
				      OUT_BAL_RPI_RESUMEN_REP.SUCURSAL,
				      OUT_BAL_RPI_RESUMEN_REP.NIVEL_REGIONAL,
				      OUT_BAL_RPI_RESUMEN_REP.COD_REGIONAL,
				      OUT_BAL_RPI_RESUMEN_REP.REGIONAL,
				      OUT_BAL_RPI_RESUMEN_REP.PERIODO,
				      OUT_BAL_RPI_RESUMEN_REP.QUARTER,
				      OUT_BAL_RPI_RESUMEN_REP.YEAR,
				      OUT_BAL_RPI_RESUMEN_REP.N_CREDITO,
				      SUM(OUT_BAL_RPI_RESUMEN_REP.V_CREDITO) AS V_CREDITO,
				      SUM(OUT_BAL_RPI_RESUMEN_REP.C_GN4) AS C_GN4,
				      OUT_BAL_RPI_RESUMEN_REP.FIRSTNAME_AG,
				      OUT_BAL_RPI_RESUMEN_REP.LASTNAME_AG,
				      OUT_BAL_RPI_RESUMEN_REP.MIDDLENAME_AG,
				      OUT_BAL_RPI_RESUMEN_REP.LASTNAME,
				      OUT_BAL_RPI_RESUMEN_REP.FIRSTNAME,
				      OUT_BAL_RPI_RESUMEN_REP.MIDDLENAME,
				      OUT_BAL_RPI_RESUMEN_REP.N_MEDIDA,-- || '_Balances' AS N_MEDIDA,
				      OUT_BAL_RPI_RESUMEN_REP.V_MEDIDA,
				      OUT_BAL_RPI_RESUMEN_REP.POSITIONNAME,
				      J.POS_CALLIDUS,
				      OUT_BAL_RPI_RESUMEN_REP.POSITIONNAME_AG,
				      OUT_BAL_RPI_RESUMEN_REP.POS_PRIN,
				      OUT_BAL_RPI_RESUMEN_REP.ID_TIPO_AGENTE,
				      OUT_BAL_RPI_RESUMEN_REP.TIPO_AGENTE,
				      OUT_BAL_RPI_RESUMEN_REP.NIF,
				      'NO' AS SOLO_DIFERENCIAS,
				      Q.QUARTER_FILTRO,
					    Q.PSEQ_FILTRO,
					    Q.PERIODO_FILTRO,
					    Q.STARTDATE_FILTRO,
				      OUT_BAL_RPI_RESUMEN_REP.POSITIONSEQ_PRIN AS POSITIONSEQ,
				      Q.PSEQ_FILTRO AS PERIODSEQ
				    FROM EXT.OUT_BAL_RPI_RESUMEN_REP OUT_BAL_RPI_RESUMEN_REP
				    INNER JOIN EXT.OUT_JERARQUIA_REP J
				      ON J.PERIODSEQ = :i_PeriodSeq
				      AND J.PARTICIPANTSEQ = OUT_BAL_RPI_RESUMEN_REP.PARTICIPANTSEQ
				      AND J.POSITIONSEQ_PRIN = OUT_BAL_RPI_RESUMEN_REP.POSITIONSEQ_PRIN
				    LEFT JOIN (SELECT X.PAYEESEQ,X.POSITIONSEQ,MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE FROM TCMP.CS_PAYMENT X
				               WHERE X.TENANTID = :v_idtenant AND X.PERIODSEQ = :i_PeriodSeq
				               GROUP BY X.PAYEESEQ,X.POSITIONSEQ
				        ) B ON B.PAYEESEQ = OUT_BAL_RPI_RESUMEN_REP.PARTICIPANTSEQ
				        AND B.POSITIONSEQ = OUT_BAL_RPI_RESUMEN_REP.POSITIONSEQ_PRIN
				    INNER JOIN CTE_INFO_QUARTER Q ON OUT_BAL_RPI_RESUMEN_REP.PERIODO = Q.PERIODO
				    WHERE 1 = 1
				       --AND (B.POSTPIPELINERUNDATE IS NULL OR B.POSTPIPELINERUNDATE > LAST_DAY(Q.STARTDATE_FILTRO))

				    GROUP BY OUT_BAL_RPI_RESUMEN_REP.NIVEL_PTO_VENTA, OUT_BAL_RPI_RESUMEN_REP.COD_PTO_VENTA, OUT_BAL_RPI_RESUMEN_REP.PTO_VENTA,
				    OUT_BAL_RPI_RESUMEN_REP.NIVEL_OFICINA, OUT_BAL_RPI_RESUMEN_REP.COD_OFICINA, OUT_BAL_RPI_RESUMEN_REP.OFICINA,
				    OUT_BAL_RPI_RESUMEN_REP.NIVEL_SUCURSAL, OUT_BAL_RPI_RESUMEN_REP.COD_SUCURSAL, OUT_BAL_RPI_RESUMEN_REP.SUCURSAL,
				    OUT_BAL_RPI_RESUMEN_REP.NIVEL_REGIONAL, OUT_BAL_RPI_RESUMEN_REP.COD_REGIONAL, OUT_BAL_RPI_RESUMEN_REP.REGIONAL,
				    OUT_BAL_RPI_RESUMEN_REP.PERIODO, OUT_BAL_RPI_RESUMEN_REP.QUARTER, OUT_BAL_RPI_RESUMEN_REP.YEAR, OUT_BAL_RPI_RESUMEN_REP.N_CREDITO,
				    OUT_BAL_RPI_RESUMEN_REP.FIRSTNAME_AG, OUT_BAL_RPI_RESUMEN_REP.LASTNAME_AG, OUT_BAL_RPI_RESUMEN_REP.MIDDLENAME_AG,
				    OUT_BAL_RPI_RESUMEN_REP.LASTNAME, OUT_BAL_RPI_RESUMEN_REP.FIRSTNAME, OUT_BAL_RPI_RESUMEN_REP.MIDDLENAME,
				    OUT_BAL_RPI_RESUMEN_REP.N_MEDIDA, OUT_BAL_RPI_RESUMEN_REP.V_MEDIDA, OUT_BAL_RPI_RESUMEN_REP.POSITIONNAME,
				    OUT_BAL_RPI_RESUMEN_REP.POSITIONNAME_AG, OUT_BAL_RPI_RESUMEN_REP.POS_PRIN, OUT_BAL_RPI_RESUMEN_REP.ID_TIPO_AGENTE,
				    OUT_BAL_RPI_RESUMEN_REP.TIPO_AGENTE, OUT_BAL_RPI_RESUMEN_REP.NIF, Q.QUARTER_FILTRO, Q.PSEQ_FILTRO, Q.PERIODO_FILTRO,
				    Q.STARTDATE_FILTRO, OUT_BAL_RPI_RESUMEN_REP.POSITIONSEQ_PRIN, Q.PSEQ_FILTRO, J.POS_CALLIDUS
				), --CHECK
				CTE_TABLA_UNIFICADA AS (
				  SELECT
				    SOLO_DIFERENCIAS AS SOLO_DIFERENCIAS,
				    QUARTER AS QUARTER,
				    CASE WHEN QUARTER = QUARTER_FILTRO THEN 'TRUE' ELSE 'FALSE' END AS MISMO_QUARTER,
				    PERIODO_FILTRO  AS PERIODO_FILTRO,
				    PERIODO AS PERIODO,
				    CASE WHEN PERIODO = PERIODO_FILTRO THEN 'TRUE' ELSE 'FALSE' END AS MISMO_PERIODO,
				    IFNULL(COD_REGIONAL ||' - ', '') || IFNULL(REGIONAL,'') AS REGIONAL,
				    IFNULL(COD_SUCURSAL ||' - ', '') || IFNULL(SUCURSAL,'') AS SUCURSAL,
				    IFNULL(COD_OFICINA ||' - ', '') || IFNULL(OFICINA,'') AS OFICINA,
				    IFNULL(TO_INT(ID_TIPO_AGENTE) ||' - ', '') || IFNULL(TIPO_AGENTE,'')  AS TIPO_AGENTE,
				    NIF AS NIF,
				    IFNULL(FIRSTNAME || ' ', '') || IFNULL(MIDDLENAME ||'  ', '') || IFNULL(LASTNAME,'') AS NOMBRE,
				    RIGHT(POS_PRIN, 4) || ' - ' || POS_CALLIDUS || ' - ' || IFNULL(FIRSTNAME || ' ', '') || IFNULL(MIDDLENAME ||'  ', '') || IFNULL(LASTNAME,'') AS AGENTE,
				    IFNULL(FIRSTNAME_AG ||'  ', '') || IFNULL(MIDDLENAME_AG ||'  ', '') || IFNULL(LASTNAME_AG,'') AS NOMBRE_AG,
				    POSITIONNAME_AG  AS POSITIONNAME_AG,
				    N_CREDITO AS N_CREDITO,
				    V_CREDITO AS V_CREDITO,
				    C_GN4 AS C_GN4,
				    N_MEDIDA AS N_MEDIDA,
				    V_MEDIDA AS V_MEDIDA,
				    POSITIONSEQ AS POSITIONSEQ,
				    PERIODSEQ AS PERIODSEQ
				  FROM CTE_TABLA_PREVIA
				),--CHECK
				--PESTAÑA MENSUAL
				--TABLA INFORMACION PAGO MENSUAL
				CTE_INF_PAGO_MENS AS (
				  SELECT
				    SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    NULL AS NOMBRE_AG,
				    NULL AS POSITIONNAME_AG,
				    CASE
				      WHEN N_MEDIDA IN ('SM-O-GEN-Inspector-NumeroPolizas-998-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalMes') THEN 'Total Pólizas Corregidas'
				      WHEN N_MEDIDA IN ('SM-O-GEN-Inspector-NumeroPolizas-002-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-002-TotalMes') THEN 'Pólizas Corregidas Hogar'
				      WHEN N_MEDIDA IN ('SM-O-GEN-Inspector-NumeroPolizas-001-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-001-TotalMes') THEN 'Pólizas Corregidas RRTT'
				      WHEN N_MEDIDA IN ('SM-O-GEN-Inspector-NumeroPolizas-906-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-906-TotalMes') THEN 'Pólizas Corregidas RRPP excluir Superplan'
				      WHEN N_MEDIDA = 'SM-O-GEN-Inspector-PrimaCorregida-998-TotalMes' THEN 'Primas Corregidas'
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual' THEN 'Importe Rappel'
				      WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalMes' THEN 'Asegurados RRTT'
				    END AS NOMBRE_COL,
				    SUM(V_MEDIDA) AS VALOR,
				    POSITIONSEQ,
				    PERIODSEQ
				  FROM CTE_TABLA_UNIFICADA
				  WHERE MISMO_PERIODO = 'TRUE'
				    AND N_MEDIDA IN ('SM-O-GEN-Inspector-NumeroPolizas-998-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalMes',
				                    'SM-O-GEN-Inspector-NumeroPolizas-002-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-002-TotalMes',
				                    'SM-O-GEN-Inspector-NumeroPolizas-001-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-001-TotalMes',
				                    'SM-O-GEN-Inspector-NumeroPolizas-906-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-906-TotalMes',
				                    'SM-O-GEN-Inspector-PrimaCorregida-998-TotalMes', 'SM-RPP-Inspector-PagoMensual', 'SM-O-GEN-Inspector-NumAsegurados-TotalMes')
				  GROUP BY SOLO_DIFERENCIAS, QUARTER, PERIODO_FILTRO, PERIODO, REGIONAL, SUCURSAL, OFICINA, TIPO_AGENTE, NIF, NOMBRE,
				    CASE
				      WHEN N_MEDIDA IN ('SM-O-GEN-Inspector-NumeroPolizas-998-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalMes') THEN 'Total Pólizas Corregidas'
				      WHEN N_MEDIDA IN ('SM-O-GEN-Inspector-NumeroPolizas-002-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-002-TotalMes') THEN 'Pólizas Corregidas Hogar'
				      WHEN N_MEDIDA IN ('SM-O-GEN-Inspector-NumeroPolizas-001-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-001-TotalMes') THEN 'Pólizas Corregidas RRTT'
				      WHEN N_MEDIDA IN ('SM-O-GEN-Inspector-NumeroPolizas-906-TotalMes', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-906-TotalMes') THEN 'Pólizas Corregidas RRPP excluir Superplan'
				      WHEN N_MEDIDA = 'SM-O-GEN-Inspector-PrimaCorregida-998-TotalMes' THEN 'Primas Corregidas'
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual' THEN 'Importe Rappel'
				      WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalMes' THEN 'Asegurados RRTT'
				    END, AGENTE, POSITIONSEQ, PERIODSEQ
				),
				--TABLA PAGOS MENSUALES DETALLE AGENTE
				CTE_INF_PAGO_AGENTE_MENS_1 AS (
				  SELECT
				    SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    NOMBRE_AG,
				    POSITIONNAME_AG,
				    CASE
				      WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-998%' OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-998%' THEN 'Total Pólizas Corregidas'
				      WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-002%' OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-002%' THEN 'Pólizas Corregidas Hogar'
				      WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-001%' OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-001%' THEN 'Pólizas Corregidas RRTT'
				      WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-906%' OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-906%' THEN 'Pólizas Corregidas RRPP excl. PU/CC'
				      WHEN N_MEDIDA LIKE 'PM-O-GEN-Inspector-PrimaCorregida-998%' THEN 'Primas Corregidas'
				      WHEN N_MEDIDA IN ('PM-O-GEN-Inspector-NumAsegurados-Agentes', 'PM-O-GEN-Agente-NumAsegurados') THEN 'Asegurados RRTT'
				    END AS NOMBRE_COL,
				    CASE WHEN N_MEDIDA LIKE '%NumeroPolizas%' THEN C_GN4 ELSE V_CREDITO END AS VALOR,
				    POSITIONSEQ,
				    PERIODSEQ
				  FROM CTE_TABLA_UNIFICADA
				  WHERE MISMO_PERIODO = 'TRUE'
				    AND (N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-998%' OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-998%'
				      OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-002%' OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-002%'
				      OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-001%' OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-001%'
				      OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizas-906%' OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-NumeroPolizasCorregidas-906%'
				      OR N_MEDIDA LIKE 'PM-O-GEN-Inspector-PrimaCorregida-998%'
				      OR N_MEDIDA IN ('PM-O-GEN-Inspector-NumAsegurados-Agentes', 'PM-O-GEN-Agente-NumAsegurados'))
				),
				CTE_INF_PAGO_AGENTE_MENS AS (
				  SELECT
				    SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    NOMBRE_AG,
				    POSITIONNAME_AG,
				    NOMBRE_COL,
				    SUM(VALOR) AS VALOR,
				    POSITIONSEQ,
				    PERIODSEQ
				  FROM CTE_INF_PAGO_AGENTE_MENS_1
				  GROUP BY SOLO_DIFERENCIAS, QUARTER, PERIODO_FILTRO, PERIODO, REGIONAL, SUCURSAL, OFICINA, TIPO_AGENTE, NIF, NOMBRE, NOMBRE_AG, POSITIONNAME_AG,
				    NOMBRE_COL, AGENTE, POSITIONSEQ, PERIODSEQ
				), --CHECK
				--PESTAÑA TRIMESTRAL
				--TABLA OBJETIVOS
				CTE_OBJ_TRIM AS (
				  SELECT
				    SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    NULL AS NOMBRE_AG,
				    NULL AS POSITIONNAME_AG,
				    CASE
				      WHEN N_MEDIDA IN ('SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-998', 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel2-NumPolizas-998') THEN 'Nº Pólizas Corregidas Total Ramos'
				      WHEN N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-002' THEN 'Nº Pólizas Corregidas Hogar'
				      WHEN N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-001' THEN 'Nº Pólizas Corregidas RRTT'
				      WHEN N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-906' THEN 'Nº Pólizas Corregidas RRPP excl. PU/CC'
				    END AS NOMBRE_COL,
				    CASE
				      WHEN N_MEDIDA IN ('SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-001', 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-002',
				                          'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-906', 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-998')
				      THEN 'Rappel1'
				      ELSE 'Rappel2' END AS NOMBRE_FIL,
				    SUM(V_MEDIDA) AS V_MEDIDA,
				    POSITIONSEQ,
				    PERIODSEQ
				  FROM CTE_TABLA_UNIFICADA
				  WHERE MISMO_PERIODO = 'TRUE'
				    AND N_MEDIDA IN ('SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-998', 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel2-NumPolizas-998',
				                    'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-002', 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-001',
				                    'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-906', 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel2-NumPolizas-998')
				  GROUP BY SOLO_DIFERENCIAS, QUARTER, PERIODO_FILTRO, PERIODO, REGIONAL, SUCURSAL, OFICINA, TIPO_AGENTE, NIF, NOMBRE,
				    CASE
				      WHEN N_MEDIDA IN ('SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-998', 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel2-NumPolizas-998') THEN 'Nº Pólizas Corregidas Total Ramos'
				      WHEN N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-002' THEN 'Nº Pólizas Corregidas Hogar'
				      WHEN N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-001' THEN 'Nº Pólizas Corregidas RRTT'
				      WHEN N_MEDIDA = 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-906' THEN 'Nº Pólizas Corregidas RRPP excl. PU/CC'
				    END,
				    CASE
				      WHEN N_MEDIDA IN ('SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-001', 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-002',
				                          'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-906', 'SM-O-RPP-Inspector-ObjetivoTrimestral-Rappel1-NumPolizas-998')
				      THEN 'Rappel1'
				     ELSE 'Rappel2' END, AGENTE, POSITIONSEQ, PERIODSEQ
				),--CHECK
				CTE_SEG_TRIM AS (
				  SELECT
				    SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    NULL AS NOMBRE_AG,
				    NULL AS POSITIONNAME_AG,
				    CASE
				      WHEN N_MEDIDA IN ('SM-RPP-Inspector-NumeroPolizas-998-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalTrimestre') THEN 'Acumulado T.R'
				      WHEN N_MEDIDA IN ('SM-RPP-Inspector-NumeroPolizas-002-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-002-TotalTrimestre') THEN 'Acumulado HOGAR'
				      WHEN N_MEDIDA IN ('SM-RPP-Inspector-NumeroPolizas-001-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-001-TotalTrimestre') THEN 'Acumulado RRTT'
				      WHEN N_MEDIDA IN ('SM-RPP-Inspector-NumeroPolizas-906-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-906-TotalTrimestre') THEN 'Acumulado RRTT excel. PU/CC'
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-998' THEN 'Consecución T.R'
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-002' THEN 'Consecución HOGAR'
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-001' THEN 'Consecución RRTT'
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-906' THEN 'Consecución RRTT excel. PU/CC'
				    END AS NOMBRE_COL,
				    SUM(IFNULL(V_MEDIDA,0)) AS VALOR,
				    POSITIONSEQ,
				    PERIODSEQ
				  FROM CTE_TABLA_UNIFICADA
				  WHERE MISMO_QUARTER = 'TRUE'
				    AND N_MEDIDA IN ('SM-RPP-Inspector-NumeroPolizas-998-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalTrimestre',
				                     'SM-RPP-Inspector-NumeroPolizas-002-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-002-TotalTrimestre',
				                     'SM-RPP-Inspector-NumeroPolizas-001-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-001-TotalTrimestre',
				                     'SM-RPP-Inspector-NumeroPolizas-906-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-906-TotalTrimestre',
				                     'SM-RPP-Inspector-ConsecucionTrimestral-998', 'SM-RPP-Inspector-ConsecucionTrimestral-002',
				                     'SM-RPP-Inspector-ConsecucionTrimestral-001', 'SM-RPP-Inspector-ConsecucionTrimestral-906')
				  GROUP BY SOLO_DIFERENCIAS, QUARTER, PERIODO_FILTRO, PERIODO, REGIONAL, SUCURSAL, OFICINA, TIPO_AGENTE, NIF, NOMBRE,
				     CASE
				      WHEN N_MEDIDA IN ('SM-RPP-Inspector-NumeroPolizas-998-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalTrimestre') THEN 'Acumulado T.R'
				      WHEN N_MEDIDA IN ('SM-RPP-Inspector-NumeroPolizas-002-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-002-TotalTrimestre') THEN 'Acumulado HOGAR'
				      WHEN N_MEDIDA IN ('SM-RPP-Inspector-NumeroPolizas-001-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-001-TotalTrimestre') THEN 'Acumulado RRTT'
				      WHEN N_MEDIDA IN ('SM-RPP-Inspector-NumeroPolizas-906-TotalTrimestre', 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-906-TotalTrimestre') THEN 'Acumulado RRTT excel. PU/CC'
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-998' THEN 'Consecución T.R'
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-002' THEN 'Consecución HOGAR'
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-001' THEN 'Consecución RRTT'
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-906' THEN 'Consecución RRTT excel. PU/CC'
				    END, AGENTE, POSITIONSEQ, PERIODSEQ
				), --CHECK
				CTE_PAGO_TRIM_1 AS (
				  SELECT
				    SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    CASE
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual' THEN 'PAGO_MENSUAL'
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual_Balances' THEN 'PAGO_MENSUAL_BALANCES'
				      WHEN ((N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes1%' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Enero', 'Abril', 'Julio', 'Octubre'))
				        OR (N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes2%' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Febrero', 'Mayo', 'Agosto', 'Noviembre'))
				        OR (N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes3%' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')))
				        THEN 'RAPPEL_TRIM'
				      WHEN (N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes1' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Enero', 'Abril', 'Julio', 'Octubre')
				          OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes2' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Febrero', 'Mayo', 'Agosto', 'Noviembre')
				          OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes3' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre'))
				        THEN 'MIN_GARANTIZADO_TRIM'
				      ELSE NULL
				    END AS MEDIDAS,
				    SUM(V_MEDIDA) AS VALOR,
				    POSITIONSEQ,
				    PERIODSEQ
				  FROM CTE_TABLA_UNIFICADA
				  WHERE MISMO_QUARTER = 'TRUE'
				    AND CASE
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual' THEN 'PAGO_MENSUAL'
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual_Balances' THEN 'PAGO_MENSUAL_BALANCES'
				      WHEN (N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes1%' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Enero', 'Abril', 'Julio', 'Octubre')
				        OR N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes2%' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Febrero', 'Mayo', 'Agosto', 'Noviembre')
				        OR N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes3%' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre'))
				        THEN 'RAPPEL_TRIM'
				      WHEN (N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes1' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Enero', 'Abril', 'Julio', 'Octubre')
				          OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes2' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Febrero', 'Mayo', 'Agosto', 'Noviembre')
				          OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes3' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre'))
				        THEN 'MIN_GARANTIZADO_TRIM'
				      ELSE NULL
				    END IS NOT NULL
				  GROUP BY SOLO_DIFERENCIAS, QUARTER, PERIODO_FILTRO, PERIODO, REGIONAL, SUCURSAL, OFICINA, TIPO_AGENTE, NIF, NOMBRE,
				    CASE
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual' THEN 'PAGO_MENSUAL'
				      WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual_Balances' THEN 'PAGO_MENSUAL_BALANCES'
				      WHEN (N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes1%' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Enero', 'Abril', 'Julio', 'Octubre')
				        OR N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes2%' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Febrero', 'Mayo', 'Agosto', 'Noviembre')
				        OR N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes3%' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre'))
				        THEN 'RAPPEL_TRIM'
				      WHEN (N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes1' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Enero', 'Abril', 'Julio', 'Octubre')
				          OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes2' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Febrero', 'Mayo', 'Agosto', 'Noviembre')
				          OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes3' AND SUBSTR_BEFORE(PERIODO, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre'))
				        THEN 'MIN_GARANTIZADO_TRIM'
				      ELSE NULL
				    END, AGENTE, POSITIONSEQ, PERIODSEQ
				),--CHECK
				CTE_PAGO_TRIM AS (
				  SELECT
				    T.SOLO_DIFERENCIAS,
				    T.QUARTER,
				    T.PERIODO_FILTRO,
				    T.PERIODO,
				    T.REGIONAL,
				    T.SUCURSAL,
				    T.OFICINA,
				    T.TIPO_AGENTE,
				    T.NIF,
				    T.NOMBRE,
				    T.AGENTE,
				    T1.VALOR AS PAGO_MENSUAL,
				    T2.VALOR AS PAGO_MENSUAL_BALANCE,
				    T3.VALOR AS RAPPEL_TRIM,
				    T4.VALOR AS MINMOS_GARANTIZADOS_TRIM,
				    CASE WHEN T2.VALOR IS NULL THEN T1.VALOR ELSE T2.VALOR - T1.VALOR END AS BALANCES_MESES_ANTERIORES,
				    CASE WHEN T1.VALOR > T3.VALOR THEN 0 ELSE T3.VALOR END AS IMPORTE_A_REGULARIZAR,
				    CASE
				      WHEN SUBSTR_BEFORE(T.PERIODO_FILTRO, ' ') IN ('Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio')
				        THEN (CASE
				              WHEN T1.VALOR > T3.VALOR THEN 0
				              ELSE T3.VALOR - T1.VALOR - (CASE WHEN T2.VALOR IS NULL THEN T1.VALOR ELSE T2.VALOR - T1.VALOR END)
				            END)
				      ELSE (CASE
				              WHEN T1.VALOR > T3.VALOR THEN 0
				              ELSE T4.VALOR - (CASE WHEN T2.VALOR IS NULL THEN T1.VALOR ELSE T2.VALOR - T1.VALOR END)
				            END)
				    END AS REGULARIZACION_TRIMESTRAL,
				    T.POSITIONSEQ,
				    T.PERIODSEQ
				  FROM (SELECT DISTINCT SOLO_DIFERENCIAS,
				          QUARTER,
				          PERIODO_FILTRO,
				          PERIODO,
				          REGIONAL,
				          SUCURSAL,
				          OFICINA,
				          TIPO_AGENTE,
				          NIF,
				          NOMBRE,
				          AGENTE,
				          POSITIONSEQ,
				          PERIODSEQ
				        FROM CTE_PAGO_TRIM_1) T
				  LEFT JOIN (SELECT * FROM CTE_PAGO_TRIM_1 WHERE MEDIDAS = 'PAGO_MENSUAL' AND VALOR IS NOT NULL) T1
				    ON T.SOLO_DIFERENCIAS = T1.SOLO_DIFERENCIAS
				    AND T.QUARTER = T1.QUARTER
				    AND T.PERIODO_FILTRO = T1.PERIODO_FILTRO
				    AND T.PERIODO = T1.PERIODO
				    AND T.REGIONAL = T1.REGIONAL
				    AND T.SUCURSAL = T1.SUCURSAL
				    AND T.OFICINA = T1.OFICINA
				    AND T.TIPO_AGENTE = T1.TIPO_AGENTE
				    AND T.NIF = T1.NIF
				    AND T.AGENTE = T1.AGENTE
				    AND T.NOMBRE = T1.NOMBRE
				    AND T.POSITIONSEQ = T1.POSITIONSEQ
				    AND T.PERIODSEQ = T1.PERIODSEQ
				  LEFT JOIN (SELECT * FROM CTE_PAGO_TRIM_1 WHERE MEDIDAS = 'PAGO_MENSUAL_BALANCES' AND VALOR IS NOT NULL) T2
				    ON T.SOLO_DIFERENCIAS = T2.SOLO_DIFERENCIAS
				    AND T.QUARTER = T2.QUARTER
				    AND T.PERIODO_FILTRO = T2.PERIODO_FILTRO
				    AND T.PERIODO = T2.PERIODO
				    AND T.REGIONAL = T2.REGIONAL
				    AND T.SUCURSAL = T2.SUCURSAL
				    AND T.OFICINA = T2.OFICINA
				    AND T.TIPO_AGENTE = T2.TIPO_AGENTE
				    AND T.NIF = T2.NIF
				    AND T.AGENTE = T2.AGENTE
				    AND T.NOMBRE = T2.NOMBRE
				    AND T.POSITIONSEQ = T2.POSITIONSEQ
				    AND T.PERIODSEQ = T2.PERIODSEQ
				  LEFT JOIN (SELECT * FROM CTE_PAGO_TRIM_1 WHERE MEDIDAS = 'RAPPEL_TRIM' AND VALOR IS NOT NULL) T3
				    ON T.SOLO_DIFERENCIAS = T3.SOLO_DIFERENCIAS
				    AND T.QUARTER = T3.QUARTER
				    AND T.PERIODO_FILTRO = T3.PERIODO_FILTRO
				    AND T.PERIODO = T3.PERIODO
				    AND T.REGIONAL = T3.REGIONAL
				    AND T.SUCURSAL = T3.SUCURSAL
				    AND T.OFICINA = T3.OFICINA
				    AND T.TIPO_AGENTE = T3.TIPO_AGENTE
				    AND T.NIF = T3.NIF
				    AND T.NOMBRE = T3.NOMBRE
				    AND T.AGENTE = T3.AGENTE
				    AND T.POSITIONSEQ = T3.POSITIONSEQ
				    AND T.PERIODSEQ = T3.PERIODSEQ
				  LEFT JOIN (SELECT * FROM CTE_PAGO_TRIM_1 WHERE MEDIDAS = 'MIN_GARANTIZADO_TRIM' AND VALOR IS NOT NULL) T4
				    ON T.SOLO_DIFERENCIAS = T4.SOLO_DIFERENCIAS
				    AND T.QUARTER = T4.QUARTER
				    AND T.PERIODO_FILTRO = T4.PERIODO_FILTRO
				    AND T.PERIODO = T4.PERIODO
				    AND T.REGIONAL = T4.REGIONAL
				    AND T.SUCURSAL = T4.SUCURSAL
				    AND T.OFICINA = T4.OFICINA
				    AND T.TIPO_AGENTE = T4.TIPO_AGENTE
				    AND T.NIF = T4.NIF
				    AND T.NOMBRE = T4.NOMBRE
				    AND T.AGENTE = T4.AGENTE
				    AND T.POSITIONSEQ = T4.POSITIONSEQ
				    AND T.PERIODSEQ = T4.PERIODSEQ
				),
				CTE_TABLA_FINAL AS (
				  SELECT
				    SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    NULL AS NOMBRE_AG,
				    NULL AS POSITIONNAME_AG,
				    NOMBRE_COL,
				    NULL AS NOMBRE_FIL,
				    VALOR AS MEDIDA,
				    POSITIONSEQ,
				    PERIODSEQ,
				    'PAGO_MENS' AS TABLA_INFORME
				  FROM CTE_INF_PAGO_MENS

				  UNION ALL

				  SELECT
				    SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    NOMBRE_AG,
				    POSITIONNAME_AG,
				    NOMBRE_COL,
				    NULL AS NOMBRE_FIL,
				    VALOR AS MEDIDA,
				    POSITIONSEQ,
				    PERIODSEQ,
				    'PAGO_AGENTES_MENS' AS TABLA_INFORME
				  FROM CTE_INF_PAGO_AGENTE_MENS

				  UNION ALL

				  SELECT
				   SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    NULL AS NOMBRE_AG,
				    NULL AS POSITIONNAME_AG,
				    NOMBRE_COL,
				    NOMBRE_FIL,
				    V_MEDIDA AS MEDIDA,
				    POSITIONSEQ,
				    PERIODSEQ,
				    'OBJ_TRIMESTRAL' AS TABLA_INFORME
				  FROM CTE_OBJ_TRIM

				  UNION ALL

				  SELECT
				    SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    NULL AS NOMBRE_AG,
				    NULL AS POSITIONNAME_AG,
				    NOMBRE_COL,
				    NULL AS NOMBRE_FIL,
				    VALOR AS MEDIDA,
				    POSITIONSEQ,
				    PERIODSEQ,
				    'SEG_TRIMESTRAL' AS TABLA_INFORME
				  FROM CTE_SEG_TRIM

				  UNION ALL

				  SELECT
				    SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    NULL AS NOMBRE_AG,
				    NULL AS POSITIONNAME_AG,
				    'Pago Mensual' as NOMBRE_COL,
				    NULL AS NOMBRE_FIL,
				    PAGO_MENSUAL AS MEDIDA,
				    POSITIONSEQ,
				    PERIODSEQ,
				    'PAGO_TRIMESTRAL' AS TABLA_INFORME
				  FROM CTE_PAGO_TRIM

				  UNION ALL

				  SELECT
				    SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    NULL AS NOMBRE_AG,
				    NULL AS POSITIONNAME_AG,
				    'Balances Meses Anteriores' as NOMBRE_COL,
				    NULL AS NOMBRE_FIL,
				    BALANCES_MESES_ANTERIORES AS MEDIDA,
				    POSITIONSEQ,
				    PERIODSEQ,
				    'PAGO_TRIMESTRAL' AS TABLA_INFORME 
				  FROM CTE_PAGO_TRIM

				  UNION ALL

				  SELECT
				    SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    NULL AS NOMBRE_AG,
				    NULL AS POSITIONNAME_AG,
				    'Importe a Regularizar' as NOMBRE_COL,
				    NULL AS NOMBRE_FIL,
				    IMPORTE_A_REGULARIZAR AS MEDIDA,
				    POSITIONSEQ,
				    PERIODSEQ,
				    'PAGO_TRIMESTRAL' AS TABLA_INFORME  
				  FROM CTE_PAGO_TRIM

				  UNION ALL

				  SELECT
				    SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    NULL AS NOMBRE_AG,
				    NULL AS POSITIONNAME_AG,
				    'Mínimos Garantizados' as NOMBRE_COL,
				    NULL AS NOMBRE_FIL,
				    MINMOS_GARANTIZADOS_TRIM AS MEDIDA,
				    POSITIONSEQ,
				    PERIODSEQ,
				    'PAGO_TRIMESTRAL' AS TABLA_INFORME
				  FROM CTE_PAGO_TRIM

				  UNION ALL

				  SELECT
				    SOLO_DIFERENCIAS,
				    QUARTER,
				    PERIODO_FILTRO,
				    PERIODO,
				    REGIONAL,
				    SUCURSAL,
				    OFICINA,
				    TIPO_AGENTE,
				    NIF,
				    NOMBRE,
				    AGENTE,
				    NULL AS NOMBRE_AG,
				    NULL AS POSITIONNAME_AG,
				    'Regulación Trimestral' as NOMBRE_COL,
				    NULL AS NOMBRE_FIL,
				    REGULARIZACION_TRIMESTRAL AS MEDIDA,
				    POSITIONSEQ,
				    PERIODSEQ,
				    'PAGO_TRIMESTRAL' AS TABLA_INFORME
				  FROM CTE_PAGO_TRIM
				),
				CTE_TABLA_FINAL_2 AS (
					SELECT
					SOLO_DIFERENCIAS,
					QUARTER,
					PERIODO_FILTRO,
					PERIODO,
					REGIONAL,
					SUCURSAL,
					OFICINA,
					TIPO_AGENTE,
					NIF,
					NOMBRE,
					AGENTE,
					NOMBRE_AG,
					POSITIONNAME_AG,
					POSITIONSEQ,
					PERIODSEQ,
					NOMBRE_FIL,
					TABLA_INFORME,
					(CASE WHEN TABLA_INFORME = 'PAGO_MENS' AND NOMBRE_COL = 'Pólizas Corregidas Hogar' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_MENS_Polizas_Corregidas_Hogar,
					(CASE WHEN TABLA_INFORME = 'PAGO_MENS' AND NOMBRE_COL = 'Pólizas Corregidas RRTT' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_MENS_Polizas_Corregidas_RRTT,
					(CASE WHEN TABLA_INFORME = 'PAGO_MENS' AND NOMBRE_COL = 'Pólizas Corregidas RRPP excluir Superplan' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_MENS_Polizas_Corregidas_RRPP_excluir_Superplan,
					(CASE WHEN TABLA_INFORME = 'PAGO_MENS' AND NOMBRE_COL = 'Importe Rappel' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_MENS_Importe_Rappel,
					(CASE WHEN TABLA_INFORME = 'PAGO_MENS' AND NOMBRE_COL = 'Total Pólizas Corregidas' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_MENS_Total_Polizas_Corregidas,
					(CASE WHEN TABLA_INFORME = 'PAGO_MENS' AND NOMBRE_COL = 'Asegurados RRTT' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_MENS_Asegurados_RRTT,
					(CASE WHEN TABLA_INFORME = 'PAGO_MENS' AND NOMBRE_COL = 'Primas Corregidas' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_MENS_Primas_Corregidas,
					(CASE WHEN TABLA_INFORME = 'PAGO_AGENTES_MENS' AND NOMBRE_COL = 'Pólizas Corregidas RRTT' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_AGENTES_MENS_Polizas_Corregidas_RRTT,
					(CASE WHEN TABLA_INFORME = 'PAGO_AGENTES_MENS' AND NOMBRE_COL = 'Primas Corregidas' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_AGENTES_MENS_Primas_Corregidas,
					(CASE WHEN TABLA_INFORME = 'PAGO_AGENTES_MENS' AND NOMBRE_COL = 'Asegurados RRTT' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_AGENTES_MENS_Asegurados_RRTT,
					(CASE WHEN TABLA_INFORME = 'PAGO_AGENTES_MENS' AND NOMBRE_COL = 'Pólizas Corregidas RRPP excl. PU/CC' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_AGENTES_MENS_Polizas_Corregidas_RRPP_excl_PUCC,
					(CASE WHEN TABLA_INFORME = 'PAGO_AGENTES_MENS' AND NOMBRE_COL = 'Pólizas Corregidas Hogar' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_AGENTES_MENS_Polizas_Corregidas_Hogar,
					(CASE WHEN TABLA_INFORME = 'PAGO_AGENTES_MENS' AND NOMBRE_COL = 'Total Pólizas Corregidas' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_AGENTES_MENS_Total_Polizas_Corregidas,
					(CASE WHEN TABLA_INFORME = 'OBJ_TRIMESTRAL' AND NOMBRE_COL = 'Nº Pólizas Corregidas Hogar' AND NOMBRE_FIL IS NOT NULL THEN MEDIDA END) AS OBJ_TRIMESTRAL_N_Polizas_Corregidas_Hogar,
					(CASE WHEN TABLA_INFORME = 'OBJ_TRIMESTRAL' AND NOMBRE_COL = 'Nº Pólizas Corregidas RRPP excl. PU/CC' AND NOMBRE_FIL IS NOT NULL THEN MEDIDA END) AS OBJ_TRIMESTRAL_N_Polizas_Corregidas_RRPP_excl_PUCC,
					(CASE WHEN TABLA_INFORME = 'OBJ_TRIMESTRAL' AND NOMBRE_COL = 'Nº Pólizas Corregidas RRTT' AND NOMBRE_FIL IS NOT NULL THEN MEDIDA END) AS OBJ_TRIMESTRAL_N_Polizas_Corregidas_RRTT,
					(CASE WHEN TABLA_INFORME = 'OBJ_TRIMESTRAL' AND NOMBRE_COL = 'Nº Pólizas Corregidas Total Ramos' AND NOMBRE_FIL IS NOT NULL THEN MEDIDA END) AS OBJ_TRIMESTRAL_N_Polizas_Corregidas_Total_Ramos,
					(CASE WHEN TABLA_INFORME = 'SEG_TRIMESTRAL' AND NOMBRE_COL = 'Acumulado HOGAR' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS SEG_TRIMESTRAL_Acumulado_HOGAR,
					(CASE WHEN TABLA_INFORME = 'SEG_TRIMESTRAL' AND NOMBRE_COL = 'Acumulado RRTT' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS SEG_TRIMESTRAL_Acumulado_RRTT,
					(CASE WHEN TABLA_INFORME = 'SEG_TRIMESTRAL' AND NOMBRE_COL = 'Consecución HOGAR' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS SEG_TRIMESTRAL_Consecucion_HOGAR,
					(CASE WHEN TABLA_INFORME = 'SEG_TRIMESTRAL' AND NOMBRE_COL = 'Consecución RRTT excel. PU/CC' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS SEG_TRIMESTRAL_Consecucion_RRTT_excel_PUCC,
					(CASE WHEN TABLA_INFORME = 'SEG_TRIMESTRAL' AND NOMBRE_COL = 'Consecución RRTT' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS SEG_TRIMESTRAL_Consecucion_RRTT,
					(CASE WHEN TABLA_INFORME = 'SEG_TRIMESTRAL' AND NOMBRE_COL = 'Acumulado RRTT excel. PU/CC' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS SEG_TRIMESTRAL_Acumulado_RRTT_excel_PUCC,
					(CASE WHEN TABLA_INFORME = 'SEG_TRIMESTRAL' AND NOMBRE_COL = 'Acumulado T.R' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS SEG_TRIMESTRAL_Acumulado_TR,
					(CASE WHEN TABLA_INFORME = 'SEG_TRIMESTRAL' AND NOMBRE_COL = 'Consecución T.R' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS SEG_TRIMESTRAL_Consecucion_TR,
					(CASE WHEN TABLA_INFORME = 'PAGO_TRIMESTRAL' AND NOMBRE_COL = 'Pago Mensual' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_TRIMESTRAL_Pago_Mensual,
					(CASE WHEN TABLA_INFORME = 'PAGO_TRIMESTRAL' AND NOMBRE_COL = 'Balances Meses Anteriores' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_TRIMESTRAL_Balances_Meses_Anteriores,
					(CASE WHEN TABLA_INFORME = 'PAGO_TRIMESTRAL' AND NOMBRE_COL = 'Importe a Regularizar' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_TRIMESTRAL_Importe_a_Regularizar,
					(CASE WHEN TABLA_INFORME = 'PAGO_TRIMESTRAL' AND NOMBRE_COL = 'Mínimos Garantizados' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_TRIMESTRAL_Minimos_Garantizados,
					(CASE WHEN TABLA_INFORME = 'PAGO_TRIMESTRAL' AND NOMBRE_COL = 'Regulación Trimestral' AND NOMBRE_FIL IS NULL THEN MEDIDA END) AS PAGO_TRIMESTRAL_Regulacion_Trimestral
					FROM CTE_TABLA_FINAL
					GROUP BY SOLO_DIFERENCIAS, QUARTER, PERIODO_FILTRO, PERIODO, REGIONAL, SUCURSAL, OFICINA, TIPO_AGENTE, NIF, NOMBRE, AGENTE, NOMBRE_AG, POSITIONNAME_AG, POSITIONSEQ, PERIODSEQ,
					TABLA_INFORME, NOMBRE_COL, NOMBRE_FIL, TABLA_INFORME, MEDIDA
				)
				SELECT
				    TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FECHA_ULT_ACT,
						SOLO_DIFERENCIAS,
						QUARTER,
						PERIODO_FILTRO,
				    PER_FORMAT.PERIODO_FORMATO AS PERIODO_FILTRO_FORMATO,
						C2.PERIODO,
						C2.REGIONAL,
						C2.SUCURSAL,
						C2.OFICINA,
						C2.TIPO_AGENTE,
						C2.NIF,
						C2.NOMBRE,
						C2.AGENTE,
						C2.NOMBRE_AG,
						C2.POSITIONNAME_AG,
						C2.POSITIONSEQ,
						C2.PERIODSEQ,
				    C2.NOMBRE_FIL,
				    C2.TABLA_INFORME,
						SUM(IFNULL(PAGO_MENS_Polizas_Corregidas_Hogar, 0)) PAGO_MENS_Polizas_Corregidas_Hogar,
						SUM(IFNULL(PAGO_MENS_Polizas_Corregidas_RRTT, 0)) PAGO_MENS_Polizas_Corregidas_RRTT,
						SUM(IFNULL(PAGO_MENS_Polizas_Corregidas_RRPP_excluir_Superplan, 0)) PAGO_MENS_Polizas_Corregidas_RRPP_excluir_Superplan,
						SUM(IFNULL(PAGO_MENS_Importe_Rappel, 0)) PAGO_MENS_Importe_Rappel,
						SUM(IFNULL(PAGO_MENS_Total_Polizas_Corregidas, 0)) PAGO_MENS_Total_Polizas_Corregidas,
						SUM(IFNULL(PAGO_MENS_Asegurados_RRTT, 0)) PAGO_MENS_Asegurados_RRTT,
						SUM(IFNULL(PAGO_MENS_Primas_Corregidas, 0)) PAGO_MENS_Primas_Corregidas,
						SUM(IFNULL(PAGO_AGENTES_MENS_Polizas_Corregidas_RRTT, 0)) PAGO_AGENTES_MENS_Polizas_Corregidas_RRTT,
						SUM(IFNULL(PAGO_AGENTES_MENS_Primas_Corregidas, 0)) PAGO_AGENTES_MENS_Primas_Corregidas,
						SUM(IFNULL(PAGO_AGENTES_MENS_Asegurados_RRTT, 0)) PAGO_AGENTES_MENS_Asegurados_RRTT,
						SUM(IFNULL(PAGO_AGENTES_MENS_Polizas_Corregidas_RRPP_excl_PUCC, 0)) PAGO_AGENTES_MENS_Polizas_Corregidas_RRPP_excl_PUCC,
						SUM(IFNULL(PAGO_AGENTES_MENS_Polizas_Corregidas_Hogar, 0)) PAGO_AGENTES_MENS_Polizas_Corregidas_Hogar,
						SUM(IFNULL(PAGO_AGENTES_MENS_Total_Polizas_Corregidas, 0)) PAGO_AGENTES_MENS_Total_Polizas_Corregidas,
						SUM(IFNULL(OBJ_TRIMESTRAL_N_Polizas_Corregidas_Hogar, 0)) OBJ_TRIMESTRAL_N_Polizas_Corregidas_Hogar,
						SUM(IFNULL(OBJ_TRIMESTRAL_N_Polizas_Corregidas_RRPP_excl_PUCC, 0)) OBJ_TRIMESTRAL_N_Polizas_Corregidas_RRPP_excl_PUCC,
						SUM(IFNULL(OBJ_TRIMESTRAL_N_Polizas_Corregidas_RRTT, 0)) OBJ_TRIMESTRAL_N_Polizas_Corregidas_RRTT,
						SUM(IFNULL(OBJ_TRIMESTRAL_N_Polizas_Corregidas_Total_Ramos, 0)) OBJ_TRIMESTRAL_N_Polizas_Corregidas_Total_Ramos,
						SUM(IFNULL(SEG_TRIMESTRAL_Acumulado_HOGAR, 0)) SEG_TRIMESTRAL_Acumulado_HOGAR,
						SUM(IFNULL(SEG_TRIMESTRAL_Acumulado_RRTT, 0)) SEG_TRIMESTRAL_Acumulado_RRTT,
						100 * SUM(IFNULL(SEG_TRIMESTRAL_Consecucion_HOGAR, 0)) SEG_TRIMESTRAL_Consecucion_HOGAR,
						100 * SUM(IFNULL(SEG_TRIMESTRAL_Consecucion_RRTT_excel_PUCC, 0)) SEG_TRIMESTRAL_Consecucion_RRTT_excel_PUCC,
						100 * SUM(IFNULL(SEG_TRIMESTRAL_Consecucion_RRTT, 0)) SEG_TRIMESTRAL_Consecucion_RRTT,
						SUM(IFNULL(SEG_TRIMESTRAL_Acumulado_RRTT_excel_PUCC, 0)) SEG_TRIMESTRAL_Acumulado_RRTT_excel_PUCC,
						SUM(IFNULL(SEG_TRIMESTRAL_Acumulado_TR, 0)) SEG_TRIMESTRAL_Acumulado_TR,
						100 * SUM(IFNULL(SEG_TRIMESTRAL_Consecucion_TR, 0)) SEG_TRIMESTRAL_Consecucion_TR,
						SUM(IFNULL(PAGO_TRIMESTRAL_Pago_Mensual, 0)) PAGO_TRIMESTRAL_Pago_Mensual,
						SUM(IFNULL(PAGO_TRIMESTRAL_Balances_Meses_Anteriores, 0)) PAGO_TRIMESTRAL_Balances_Meses_Anteriores,
						SUM(IFNULL(PAGO_TRIMESTRAL_Importe_a_Regularizar, 0)) PAGO_TRIMESTRAL_Importe_a_Regularizar,
						SUM(IFNULL(PAGO_TRIMESTRAL_Minimos_Garantizados, 0)) PAGO_TRIMESTRAL_Minimos_Garantizados,
						SUM(IFNULL(PAGO_TRIMESTRAL_Regulacion_Trimestral, 0)) PAGO_TRIMESTRAL_Regulacion_Trimestral
				FROM CTE_TABLA_FINAL_2 C2
				INNER JOIN EXT.OUT_FECHAS_WEBI_REP F
				    ON C2.PERIODO_FILTRO = F.PERIODO
				    AND F.TABLA = 'OUT_LC_RPI_RESUMEN_REP'
				INNER JOIN TBL_PER_FORMAT PER_FORMAT
				    ON PER_FORMAT.PERIODO = C2.PERIODO_FILTRO
				GROUP BY
					C2.SOLO_DIFERENCIAS,
					C2.QUARTER,
					C2.PERIODO_FILTRO,
					C2.PERIODO,
					C2.REGIONAL,
					C2.SUCURSAL,
					C2.OFICINA,
					C2.TIPO_AGENTE,
					C2.NIF,
					C2.NOMBRE,
					C2.AGENTE,
					C2.NOMBRE_AG,
					C2.POSITIONNAME_AG,
					C2.POSITIONSEQ,
					C2.PERIODSEQ,
					C2.NOMBRE_FIL,
				    C2.TABLA_INFORME,
					F.ULTIMA_ACTUALIZACION,
				    PER_FORMAT.PERIODO_FORMATO;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_LC_S5_RPI_RESUMEN_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe S5 RPI RESUMEN LC', i_log_count, i_id_proceso, 'info');


			--Inicio informe S5 RAPPEL PRODUCCIÓN INSPECTORES RESUMEN (RPI) -- si fin de trimestre
			IF SUBSTR_BEFORE(:v_period_name, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre')
			THEN
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tabla FINAL Informe S5 RPI RESUMEN (trimestral)', i_log_count, i_id_proceso, 'info');
				
				--Borrado del periodo en los datos de Trimestral
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). PeriodSeq ' || i_PeriodSeq, i_log_count, i_id_proceso, 'debug');
				DELETE FROM EXT.OUT_S5_RPI_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq AND ORIGEN = 'Trimestral';
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
				
				--Borrado del periodo-1 en los datos de Trimestral
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). PeriodSeq-1 ' || v_PeriodSeq_1, i_log_count, i_id_proceso, 'debug');
				DELETE FROM EXT.OUT_S5_RPI_RESUMEN_FINAL_REP WHERE PERIODSEQ = :v_PeriodSeq_1 AND ORIGEN = 'Trimestral';
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
				
				--Borrado del periodo-2 en los datos de Trimestral
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). PeriodSeq-2 ' || v_PeriodSeq_2, i_log_count, i_id_proceso, 'debug');
				DELETE FROM EXT.OUT_S5_RPI_RESUMEN_FINAL_REP WHERE PERIODSEQ = :v_PeriodSeq_2 AND ORIGEN = 'Trimestral';
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');


				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). CIERRE', i_log_count, i_id_proceso, 'debug');
				INSERT INTO EXT.OUT_S5_RPI_RESUMEN_FINAL_REP (COMPANYA, TIPO_PAGO, ORIGEN, PERIODSEQ, PERIODO_ORIGINAL, PERIODO_CAMPO, PERIODO, QUARTER, NIF_NOMBRE, OFICINA, INSPECTOR, NIF, TIPO_AGENTE, POS_PRIN, POSITIONSEQ, PARTICIPANTSEQ, N_MEDIDA, V_MEDIDA, N_CREDITO, V_CREDITO
					, COMISION_PAGO, V_MEDIDA_CALC, POSITIONNAME_AG, NOMBRE_AGENTE, COMISION_AGENTE, VALOR_COMISION_AGENTE, RAPPEL_2_3, COMISION_OBJETIVOS
					, TIPO_SEGUIMIENTO, COMISION_SEGUIMIENTO, COMISION_TRIM_PAGOS, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, FEC_ACTUALIZACION_FORMATO)
					
					WITH "BALANCE" AS (SELECT PERIODSEQ, POSITIONSEQ_PRIN POSITIONSEQ, PARTICIPANTSEQ, N_MEDIDA || '_Balance', V_MEDIDA
										FROM EXT.OUT_BAL_RPI_RESUMEN_REP 
										WHERE N_MEDIDA = 'SM-RPP-Inspector-PagoMensual'
											AND PERIODSEQ IN (:i_PeriodSeq, :v_PeriodSeq_1, :v_PeriodSeq_2)
										)
					SELECT COMPANYA, TIPO_PAGO, ORIGEN, PERIODSEQ, PERIODO_ORIGINAL, PERIODO_CAMPO, PERIODO, QUARTER, NIF_NOMBRE, OFICINA, INSPECTOR, NIF, TIPO_AGENTE, POS_PRIN, POSITIONSEQ, PARTICIPANTSEQ, N_MEDIDA, V_MEDIDA, N_CREDITO, V_CREDITO
							, COMISION_PAGO, V_MEDIDA_CALC, POSITIONNAME_AG, NOMBRE_AGENTE, COMISION_AGENTE, VALOR_COMISION_AGENTE, RAPPEL_2_3, COMISION_OBJETIVOS
							, TIPO_SEGUIMIENTO, COMISION_SEGUIMIENTO, COMISION_TRIM_PAGOS, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, FEC_ACTUALIZACION_FORMATO
					FROM (
					SELECT DISTINCT 
						--N_SELECT,
						--	 ORIGEN,
						'OCASO' COMPANYA
						, 'CIERRE' TIPO_PAGO
						, 'Trimestral' ORIGEN
						, CASE WHEN N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes1' 
										OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes1' 
										OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-Mes1'
								THEN :v_PeriodSeq_2
								WHEN N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes2'  
										OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes2'
										OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-Mes2' 
								THEN :v_PeriodSeq_1
								ELSE RPI.PERIODSEQ 
							END PERIODSEQ
						, CASE WHEN SUBSTR_BEFORE(PERIODO_ORIGINAL, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') AND RPI.V_MEDIDA > 0
									AND (N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes1' 
										OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes1'
										OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-Mes1')
								THEN REPLACE(REPLACE(REPLACE(REPLACE(PERIODO_ORIGINAL, 'Marzo', 'Enero'), 'Junio', 'Abril'), 'Septiembre', 'Julio'), 'Diciembre', 'Octubre' )
								WHEN SUBSTR_BEFORE(PERIODO_ORIGINAL, ' ') IN ('Marzo', 'Junio', 'Septiembre', 'Diciembre') AND RPI.V_MEDIDA > 0
									AND (N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes2' 
										OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-MinMes2'
										OR N_MEDIDA = 'I-RPP-Inspector-ImporteRegTrimestral-Mes2')
								THEN REPLACE(REPLACE(REPLACE(REPLACE(PERIODO_ORIGINAL, 'Marzo', 'Febrero'), 'Junio', 'Mayo'), 'Septiembre', 'Agosto'), 'Diciembre', 'Noviembre' )
								ELSE RPI.PERIODO_ORIGINAL 
							END PERIODO_ORIGINAL
						, RPI.PERIODO PERIODO_CAMPO
						, SUBSTR_AFTER(RPI.PERIODO, ' ') ||
											CASE WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Enero' THEN ' 01 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Febrero' THEN ' 02 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Marzo' THEN ' 03 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Abril' THEN ' 04 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Mayo' THEN ' 05 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Junio' THEN ' 06 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Julio' THEN ' 07 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Agosto' THEN ' 08 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Septiembre' THEN ' 09 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Octubre' THEN ' 10 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Noviembre' THEN ' 11 '
												WHEN SUBSTR_BEFORE(RPI.PERIODO, ' ') = 'Diciembre' THEN ' 12 '
												END
											|| SUBSTR_BEFORE(RPI.PERIODO, ' ') PERIODO
						, RPI.QUARTER
						, RPI.NIF || ' - ' || RPI.NOMBRE_INSPECTOR NIF_NOMBRE
						, RPI.COD_OFICINA || ' - ' || RPI.OFICINA OFICINA
						, RIGHT(RPI.POS_PRIN,4) ||' - '|| RPI.POS_CALLIDUS ||' - ' || RPI.NOMBRE_INSPECTOR INSPECTOR
						, RPI.NIF
						, TO_INTEGER(RPI.ID_TIPO_AGENTE) ||' - '|| RPI.TIPO_AGENTE AS TIPO_AGENTE
						, POS_PRIN
						, RPI.POSITIONSEQ
						, RPI.PARTICIPANTSEQ
						, N_MEDIDA
						, ROUND(RPI.V_MEDIDA, 2) AS V_MEDIDA
						, N_CREDITO
						, ROUND(V_CREDITO, 2) AS V_CREDITO
						
						----MENSUAL
						--HOJA 1, COMISION_PAGO
						, NULL COMISION_PAGO
						, CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-998'
									OR N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-002'
									OR N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-001'
									OR N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-906'
								THEN ROUND(RPI.V_MEDIDA * 100, 2)
								WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual_Balance' THEN ROUND(IFNULL(BALANCE.V_MEDIDA, 0) - RPI.V_MEDIDA, 2)
								WHEN N_MEDIDA LIKE 'I-RPP-Inspector-ImporteRegTrimestral-MinMes%' AND RPI.V_MEDIDA < 0  THEN 0
							ELSE ROUND(RPI.V_MEDIDA, 2)
							END V_MEDIDA_CALC
						
						--HOJA 1, [COMISION_AGENTE]
						, RPI.POSITIONNAME_AG
						, RPI.NOMBRE_AGENTE
						, NULL COMISION_AGENTE
						, NULL VALOR_COMISION_AGENTE
						--HOJA 2, TABLA OBJETIVOS [Rappel_2_3]
						, NULL RAPPEL_2_3
						--HOJA 2, TABLA OBJETIVOS [COMISION_OBJETIVOS]
						, NULL COMISION_OBJETIVOS
							
						----TRIMESTRAL
						--HOJA 2, TABLA SEGUIMIENTO [TIPO_SEGUIMIENTO]
						, CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-998-TotalTrimestre' THEN 'Acumulado'
								WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalTrimestre' THEN 'Acumulado'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-002-TotalTrimestre' THEN 'Acumulado'
								WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-002-TotalTrimestre' THEN 'Acumulado'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-001-TotalTrimestre' THEN 'Acumulado'
								WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-001-TotalTrimestre' THEN 'Acumulado'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-906-TotalTrimestre' THEN 'Acumulado'
								WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-906-TotalTrimestre' THEN 'Acumulado'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-998' THEN 'Consecución %'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-002' THEN 'Consecución %'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-001' THEN 'Consecución %'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-906' THEN 'Consecución %'
							ELSE NULL
							END TIPO_SEGUIMIENTO
						--HOJA 2, TABLA SEGUIMIENTO [COMISION_SEGUIMIENTO]
						, CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-998-TotalTrimestre' THEN 'T.R.'
								WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalTrimestre' THEN 'T.R.'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-998' THEN 'T.R.'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-002-TotalTrimestre' THEN 'Hogar'
								WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-002-TotalTrimestre' THEN 'Hogar'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-002' THEN 'Hogar'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-001-TotalTrimestre' THEN 'RRTT'
								WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-001-TotalTrimestre' THEN 'RRTT'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-001' THEN 'RRTT'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-NumeroPolizas-906-TotalTrimestre' THEN 'RRPP excluir Superplan'
								WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumeroPolizasCorregidas-906-TotalTrimestre' THEN 'RRPP excluir Superplan'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-ConsecucionTrimestral-906' THEN 'RRPP excluir Superplan'
							ELSE NULL
							END COMISION_SEGUIMIENTO
						--HOJA 2, TABLA PAGOS [COMISION_TRIM_PAGOS]
						, CASE WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual' THEN '1-Pago Mensual'
								WHEN N_MEDIDA = 'SM-RPP-Inspector-PagoMensual_Balance' THEN '2-Balances Meses Anteriores'
								WHEN N_MEDIDA LIKE 'SM-RPP-Inspector-ImportesRegularizacionTrimestral-Rappel%-Mes%' THEN '3-Importe a Regularizar'
								WHEN N_MEDIDA LIKE 'I-RPP-Inspector-ImporteRegTrimestral-MinMes%' THEN '4-Mínimos Garantizados'
								WHEN N_MEDIDA LIKE 'I-RPP-Inspector-ImporteRegTrimestral-Mes%' THEN '5-Regulación Trimestral'
							ELSE NULL
							END COMISION_TRIM_PAGOS
						, NULL SOLO_DIFERENCIAS
						, NULL FEC_ACTUALIZACION
						, NULL FEC_ACTUALIZACION_FORMATO
							
						
					FROM 
					(	SELECT -- SELECT 1: Tabla OUT_RPI_RESUMEN_REP para el periodo
							'SELECT 1' N_SELECT,
							'Cierre' ORIGEN,
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO PERIODO_ORIGINAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							SUM(INYC_RPI_RESUMEN.V_CREDITO) AS V_CREDITO,
							SUM(INYC_RPI_RESUMEN.C_GN4) AS C_GN4,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), '') NOMBRE_AGENTE,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), '') NOMBRE_INSPECTOR,
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
						FROM EXT.OUT_RPI_RESUMEN_REP INYC_RPI_RESUMEN
						INNER JOIN	(SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
									FROM EXT.OUT_JERARQUIA_REP
									WHERE POSITIONSEQ = POSITIONSEQ_PRIN --LLS 20251124: Añadido para eliminar posiciones secundarias
									) J
							ON INYC_RPI_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPI_RESUMEN.PERIODSEQ = J.PERIODSEQ
						WHERE 1 = 1
							--Todas las reglas de cierre del mes menos la de pagos
							AND INYC_RPI_RESUMEN.N_MEDIDA <> 'SM-RPP-Inspector-PagoMensual'
							AND INYC_RPI_RESUMEN.PERIODSEQ = :i_PeriodSeq
						GROUP BY INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), ''),
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), ''),
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS

						UNION ALL

						SELECT  -- SELECT 2: Tabla OUT_BAL_RPI_RESUMEN_REP para el año hasta el mes incluído
							'SELECT 2' N_SELECT,
							'Balance' ORIGEN,
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO PERIODO_ORIGINAL,
							CASE WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Enero' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Febrero'
									THEN 'Marzo ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Abril' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Mayo'
									THEN 'Junio ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Julio' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Agosto'
									THEN 'Septiembre ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Octubre' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Noviembre'
									THEN 'Diciembre ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								ELSE INYC_RPI_RESUMEN.PERIODO
								END PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							SUM(INYC_RPI_RESUMEN.V_CREDITO) AS V_CREDITO,
							SUM(INYC_RPI_RESUMEN.C_GN4) AS C_GN4,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), '') NOMBRE_AGENTE,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), '') NOMBRE_INSPECTOR,
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
						FROM EXT.OUT_BAL_RPI_RESUMEN_REP INYC_RPI_RESUMEN--LLS 20251031
						INNER JOIN	(SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
									FROM EXT.OUT_JERARQUIA_REP
									WHERE POSITIONSEQ = POSITIONSEQ_PRIN --LLS 20251124: Añadido para eliminar posiciones secundarias
										) J
							ON INYC_RPI_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPI_RESUMEN.PERIODSEQ = J.PERIODSEQ
						WHERE 1 = 1
							--Todas las reglas de balances de los meses anteriores al cierre menos la de pagos
							AND INYC_RPI_RESUMEN.N_MEDIDA <> 'SM-RPP-Inspector-PagoMensual'
							AND INYC_RPI_RESUMEN.PERIODSEQ IN (:i_PeriodSeq, :v_PeriodSeq_1, :v_PeriodSeq_2)
						GROUP BY 
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), ''),
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), ''),
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
							
						UNION ALL
						
						SELECT -- SELECT 3: Tabla OUT_RPI_RESUMEN_REP para el año hasta el mes incluído --Regla de pagos de los cierres SÍ
							'SELECT 3' N_SELECT,
							'Cierre' ORIGEN,
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO PERIODO_ORIGINAL,
							CASE WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Enero' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Febrero'
									THEN 'Marzo ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Abril' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Mayo'
									THEN 'Junio ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Julio' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Agosto'
									THEN 'Septiembre ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Octubre' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Noviembre'
									THEN 'Diciembre ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								ELSE INYC_RPI_RESUMEN.PERIODO
								END PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							INYC_RPI_RESUMEN.V_CREDITO AS V_CREDITO,
							INYC_RPI_RESUMEN.C_GN4 AS C_GN4,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), '') NOMBRE_AGENTE,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), '') NOMBRE_INSPECTOR,
							INYC_RPI_RESUMEN.N_MEDIDA,
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
						FROM  EXT.OUT_RPI_RESUMEN_REP INYC_RPI_RESUMEN
						INNER JOIN	(SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
									FROM EXT.OUT_JERARQUIA_REP
									WHERE POSITIONSEQ = POSITIONSEQ_PRIN --LLS 20251124: Añadido para eliminar posiciones secundarias
									) J
							ON INYC_RPI_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPI_RESUMEN.PERIODSEQ = J.PERIODSEQ
						WHERE 1 = 1
							--Regla de pagos de los cierres
							AND INYC_RPI_RESUMEN.N_MEDIDA = 'SM-RPP-Inspector-PagoMensual'
							AND INYC_RPI_RESUMEN.PERIODSEQ IN (:i_PeriodSeq, :v_PeriodSeq_1, :v_PeriodSeq_2)
							
						UNION ALL
						
						SELECT -- SELECT 4: Tabla OUT_BAL_RPI_RESUMEN_REP para el año hasta el mes incluído --Regla de pagos de los cierres SÍ
							'SELECT 4' N_SELECT,
							'Balance' ORIGEN,
							INYC_RPI_RESUMEN.NIVEL_PTO_VENTA,
							INYC_RPI_RESUMEN.COD_PTO_VENTA,
							INYC_RPI_RESUMEN.PTO_VENTA,
							INYC_RPI_RESUMEN.NIVEL_OFICINA,
							INYC_RPI_RESUMEN.COD_OFICINA,
							INYC_RPI_RESUMEN.OFICINA,
							INYC_RPI_RESUMEN.NIVEL_SUCURSAL,
							INYC_RPI_RESUMEN.COD_SUCURSAL,
							INYC_RPI_RESUMEN.SUCURSAL,
							INYC_RPI_RESUMEN.NIVEL_REGIONAL,
							INYC_RPI_RESUMEN.COD_REGIONAL,
							INYC_RPI_RESUMEN.REGIONAL,
							INYC_RPI_RESUMEN.PERIODO PERIODO_ORIGINAL,
							CASE WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Enero' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Febrero'
									THEN 'Marzo ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Abril' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Mayo'
									THEN 'Junio ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Julio' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Agosto'
									THEN 'Septiembre ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								WHEN SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Octubre' OR SUBSTR_BEFORE(INYC_RPI_RESUMEN.PERIODO, ' ') = 'Noviembre'
									THEN 'Diciembre ' || SUBSTR_AFTER(INYC_RPI_RESUMEN.PERIODO, ' ')
								ELSE INYC_RPI_RESUMEN.PERIODO
								END PERIODO,
							INYC_RPI_RESUMEN.PERIODSEQ,
							INYC_RPI_RESUMEN.QUARTER,
							INYC_RPI_RESUMEN.YEAR,
							INYC_RPI_RESUMEN.N_CREDITO,
							INYC_RPI_RESUMEN.V_CREDITO AS V_CREDITO,
							INYC_RPI_RESUMEN.C_GN4 AS C_GN4,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME_AG) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME_AG), '') NOMBRE_AGENTE,
							IFNULL(RTRIM(INYC_RPI_RESUMEN.FIRSTNAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.MIDDLENAME) || ' ', '') || IFNULL(RTRIM(INYC_RPI_RESUMEN.LASTNAME), '') NOMBRE_INSPECTOR,
							INYC_RPI_RESUMEN.N_MEDIDA || '_Balance',
							INYC_RPI_RESUMEN.V_MEDIDA,
							INYC_RPI_RESUMEN.POSITIONNAME,
							INYC_RPI_RESUMEN.POSITIONNAME_AG,
							INYC_RPI_RESUMEN.POS_PRIN,
							INYC_RPI_RESUMEN.POSITIONSEQ_PRIN POSITIONSEQ,
							INYC_RPI_RESUMEN.PARTICIPANTSEQ,
							INYC_RPI_RESUMEN.ID_TIPO_AGENTE,
							INYC_RPI_RESUMEN.TIPO_AGENTE,
							INYC_RPI_RESUMEN.NIF,
							J.POS_CALLIDUS
						FROM EXT.OUT_BAL_RPI_RESUMEN_REP INYC_RPI_RESUMEN --LLS 20251031
						INNER JOIN	(SELECT DISTINCT POSITIONSEQ_PRIN, PERIODSEQ, POS_CALLIDUS
									FROM EXT.OUT_JERARQUIA_REP
									WHERE POSITIONSEQ = POSITIONSEQ_PRIN --LLS 20251124: Añadido para eliminar posiciones secundarias
									) J
							ON INYC_RPI_RESUMEN.POSITIONSEQ_PRIN = J.POSITIONSEQ_PRIN
								AND INYC_RPI_RESUMEN.PERIODSEQ = J.PERIODSEQ
						WHERE 1 = 1
							--Regla de pagos de los balances
							AND INYC_RPI_RESUMEN.N_MEDIDA = 'SM-RPP-Inspector-PagoMensual'
							AND INYC_RPI_RESUMEN.PERIODSEQ IN (:i_PeriodSeq, :v_PeriodSeq_1, :v_PeriodSeq_2)
							
					) AS RPI
										
					LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F
						ON F.TABLA = 'OUT_RPI_RESUMEN_REP'
							AND F.PERIODSEQ = :i_PeriodSeq
							
					LEFT JOIN BALANCE ON BALANCE.PERIODSEQ = RPI.PERIODSEQ AND BALANCE.POSITIONSEQ = RPI.POSITIONSEQ AND BALANCE.PARTICIPANTSEQ = RPI.PARTICIPANTSEQ

					)
					WHERE 1 = 1
						AND (COMISION_SEGUIMIENTO IS NOT NULL OR COMISION_TRIM_PAGOS IS NOT NULL);
				v_num_rows := ::ROWCOUNT;
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_S5_RPI_RESUMEN_FINAL_REP (trimestral). Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
				
				CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tabla FINAL Informe S5 RPI RESUMEN (trimestral)', i_log_count, i_id_proceso, 'info');

			END IF;
		
		CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Creación Informe Rappel Producción Inspectores -S5- Resumen', i_log_count, i_id_proceso, 'info');
		--FIN informe S5 RAPPEL PRODUCCIÓN INSPECTORES RESUMEN (RPI) -- para cualquier mes
		END IF;
		
		------------------------------------------------------------------------------------------------------------------------
		--Inicio informe S4 Rappel Producción Propia Ag. con Grupo
		IF :i_lista_informes = 'RPP' OR :i_lista_informes LIKE '%|RPP|%' OR :i_lista_informes LIKE '%|RPP' OR :i_lista_informes LIKE 'RPP|%' OR :i_lista_informes = 'ALL' 
			THEN

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tablas FINALES Informe RPP', i_log_count, i_id_proceso, 'info');
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RPP_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_RPP_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RPP_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RPP_RESUMEN_FINAL_REP', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RPP_RESUMEN_FINAL_REP (TIPO_INFORME, PERIODSEQ, POSITIONSEQ, PERIODO, PERIODO_FORMATO, COD_AGENTE, NOMBRE_AGENTE, NIF, TIPO_AGENTE, POL_CORR, PRIMAS, PAGOS, SOLO_DIFERENCIAS, FEC_ACTUALIZACION)
				(SELECT
					'CIERRE' AS TIPO_INFORME,
					RPP_RESUMEN.PERIODSEQ AS PERIODSEQ,
					RPP_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ,
					RPP_RESUMEN.PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					POS_PRIN AS COD_AGENTE,
					TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
					NIF,
					TO_INT(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGE,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-NumeroPolizas-998-Total-Mes'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0 
					END) AS POL_CORR,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-Primas-998-Total-Mes'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0
					END) AS PRIMAS,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-Pago-Mensual'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0
					END) AS PAGOS,
					NULL AS SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION
				FROM EXT.OUT_RPP_RESUMEN_REP RPP_RESUMEN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = RPP_RESUMEN.PERIODO
					AND F.TABLA = 'OUT_RPP_RESUMEN_REP'
				WHERE RPP_RESUMEN.PERIODSEQ = :i_PeriodSeq
				GROUP BY RPP_RESUMEN.PERIODSEQ, RPP_RESUMEN.POSITIONSEQ_PRIN, RPP_RESUMEN.PERIODO, 
				POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, F.ULTIMA_ACTUALIZACION

				UNION ALL

				SELECT
					'BALANCE',
					RPP_RESUMEN.PERIODSEQ,
					RPP_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ,
					RPP_RESUMEN.PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					POS_PRIN AS COD_AGENTE,
					TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
					NIF,
					TO_INT(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGE,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-NumeroPolizas-998-Total-Mes'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0 
					END) AS POL_CORR,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-Primas-998-Total-Mes'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0
					END) AS PRIMAS,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-Pago-Mensual'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0
					END) AS PAGOS,
					CASE WHEN B.BALANCESEQ IS NOT NULL 
						THEN 'SI' 
						ELSE NULL 
					END AS SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION
				FROM EXT.OUT_BAL_RPP_RESUMEN_REP RPP_RESUMEN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = RPP_RESUMEN.PERIODO
					AND F.TABLA = 'OUT_BAL_RPP_RESUMEN_REP'
				LEFT JOIN (
					SELECT X.PAYEESEQ,
						X.POSITIONSEQ,
						X.PERIODSEQ,
						MAX(X.BALANCESEQ) AS BALANCESEQ 
					FROM TCMP.CS_BALANCE X
					GROUP BY X.PAYEESEQ, X.POSITIONSEQ, X.PERIODSEQ
					) B ON B.PAYEESEQ = RPP_RESUMEN.PARTICIPANTSEQ
					AND B.POSITIONSEQ = RPP_RESUMEN.POSITIONSEQ_PRIN
					AND B.PERIODSEQ = RPP_RESUMEN.PERIODSEQ
				WHERE RPP_RESUMEN.PERIODSEQ = :i_PeriodSeq
				GROUP BY RPP_RESUMEN.PERIODSEQ, RPP_RESUMEN.POSITIONSEQ_PRIN, RPP_RESUMEN.PERIODO, 
				POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, B.BALANCESEQ, F.ULTIMA_ACTUALIZACION

				UNION ALL

				SELECT
					'LC',
					RPP_RESUMEN.PERIODSEQ AS PERIODSEQ,
					RPP_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ,
					RPP_RESUMEN.PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					POS_PRIN AS COD_AGENTE,
					TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
					NIF,
					TO_INT(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGE,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-NumeroPolizas-998-Total-Mes'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0 
					END) AS POL_CORR,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-Primas-998-Total-Mes'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0
					END) AS PRIMAS,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RPP-AgenteGrupo-Pago-Mensual'
						THEN ROUND(V_MEDIDA, 2)
						ELSE 0
					END) AS PAGOS,
					CASE WHEN (P.POSTPIPELINERUNDATE IS NULL OR P.POSTPIPELINERUNDATE > LAST_DAY(RPP_RESUMEN.STARTDATE)) 
						THEN 'SI' 
						ELSE NULL 
					END AS SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION
				FROM EXT.OUT_LC_RPP_RESUMEN_REP RPP_RESUMEN
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = RPP_RESUMEN.PERIODO
					AND F.TABLA = 'OUT_LC_RPP_RESUMEN_REP'
				LEFT JOIN (
					SELECT X.PAYEESEQ,
						X.POSITIONSEQ,
						X.PERIODSEQ,
						MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE 
						FROM TCMP.CS_PAYMENT X
						GROUP BY X.PAYEESEQ, X.POSITIONSEQ, X.PERIODSEQ
					) P ON P.PAYEESEQ = RPP_RESUMEN.PARTICIPANTSEQ
					AND P.POSITIONSEQ = RPP_RESUMEN.POSITIONSEQ_PRIN
					AND P.PERIODSEQ = RPP_RESUMEN.PERIODSEQ
				WHERE RPP_RESUMEN.PERIODSEQ = :i_PeriodSeq
				GROUP BY RPP_RESUMEN.PERIODSEQ, RPP_RESUMEN.POSITIONSEQ_PRIN, RPP_RESUMEN.PERIODO, 
				POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, 
				P.POSTPIPELINERUNDATE, RPP_RESUMEN.STARTDATE, F.ULTIMA_ACTUALIZACION);
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPP_RESUMEN_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

            --BRG 20251126 Añadido
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Insert de --SELECCIONAR-- en OUT_RPP_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RPP_RESUMEN_FINAL_REP (TIPO_INFORME, PERIODSEQ, POSITIONSEQ, PERIODO, PERIODO_FORMATO, COD_AGENTE, NOMBRE_AGENTE, NIF, TIPO_AGENTE, POL_CORR, PRIMAS, PAGOS, SOLO_DIFERENCIAS, FEC_ACTUALIZACION)
                SELECT DISTINCT
					TIPO_INFORME,
					PERIODSEQ,
					-1 AS POSITIONSEQ,
					PERIODO,
					PERIODO_FORMATO,
					' ' AS COD_AGENTE,
					'--SELECCIONAR--' AS NOMBRE_AGENTE,
					' ' AS NIF,
					' ' AS TIPO_AGE,
					NULL AS POL_CORR,
					NULL AS PRIMAS,
					NULL AS PAGOS,
					SOLO_DIFERENCIAS,
					FEC_ACTUALIZACION
                FROM EXT.OUT_RPP_RESUMEN_FINAL_REP
                WHERE PERIODSEQ = :i_PeriodSeq;
            v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Insert de --SELECCIONAR-- en OUT_RPP_RESUMEN_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');


			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RPP_DETALLE_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_RPP_DETALLE_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RPP_DETALLE_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Creación TBL_RPP_DET_FINAL.', i_log_count, i_id_proceso, 'debug');
			TBL_RPP_DET_FINAL =
				(SELECT
					'CIERRE' AS TIPO_INFORME,
					RPP_DETALLE.PERIODSEQ AS PERIODSEQ,
					RPP_DETALLE.POSITIONSEQ_PRIN AS POSITIONSEQ,
					RPP_DETALLE.PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					POS_PRIN AS COD_AGENTE,
					TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
					NIF,
					TO_INT(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGE,
					RIGHT(PRODUCTID, 5) AS COD_PROD,
					ST_GA1 AS CODIGO_POLIZA,
					PRODUCTO AS NOMBRE_PRODUCTO,
					EVENTO AS TIPO_RECIBO,
					TO_VARCHAR(ST_GD3, 'MM-YYYY') AS FECHA_EMISION,
					TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY') AS FECHA_COBRO,
					SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN ROUND(VALUE, 2)
						ELSE 0
					END) AS POLIZAS_FIS,
					SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN ROUND(C_GN1, 2)
						ELSE 0
					END) AS POLIZAS_CORR,
					SUM(CASE WHEN NAME LIKE '%Prima%'
						THEN ROUND(VALUE, 2)
						ELSE 0
					END) AS PRIMAS,
					NULL AS SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					MIN(RIGHT(PRODUCTID, 5) || PRODUCTO) OVER (
						PARTITION BY RPP_DETALLE.PERIODSEQ, RPP_DETALLE.POSITIONSEQ_PRIN, RPP_DETALLE.PERIODO, POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, 
						TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, ST_GA1, EVENTO, TO_VARCHAR(ST_GD3, 'MM-YYYY'), TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY')) AS PROD_PRIN
				FROM EXT.OUT_RPP_DETALLE_REP RPP_DETALLE
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = RPP_DETALLE.PERIODO
					AND F.TABLA = 'OUT_RPP_DETALLE_REP'
				WHERE RPP_DETALLE.PERIODSEQ = :i_PeriodSeq
				GROUP BY RPP_DETALLE.PERIODSEQ, RPP_DETALLE.POSITIONSEQ_PRIN, RPP_DETALLE.PERIODO, 
				POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, 
				PRODUCTID, ST_GA1, PRODUCTO, EVENTO, TO_VARCHAR(ST_GD3, 'MM-YYYY'), TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY'),
				F.ULTIMA_ACTUALIZACION

				UNION ALL

				SELECT
					'BALANCE' AS TIPO_INFORME,
					RPP_DETALLE.PERIODSEQ AS PERIODSEQ,
					RPP_DETALLE.POSITIONSEQ_PRIN AS POSITIONSEQ,
					RPP_DETALLE.PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					POS_PRIN AS COD_AGENTE,
					TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
					NIF,
					TO_INT(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGE,
					RIGHT(PRODUCTID, 5) AS COD_PROD,
					ST_GA1 AS CODIGO_POLIZA,
					PRODUCTO AS NOMBRE_PRODUCTO,
					EVENTO AS TIPO_RECIBO,
					TO_VARCHAR(ST_GD3, 'MM-YYYY') AS FECHA_EMISION,
					TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY') AS FECHA_COBRO,
					SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN ROUND(VALUE, 2)
						ELSE 0
					END) AS POLIZAS_FIS,
					SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN ROUND(C_GN1, 2)
						ELSE 0
					END) AS POLIZAS_CORR,
					SUM(CASE WHEN NAME LIKE '%Prima%'
						THEN ROUND(VALUE, 2)
						ELSE 0
					END) AS PRIMAS,
					CASE WHEN B.BALANCESEQ IS NOT NULL 
						THEN 'SI' 
						ELSE NULL 
					END AS SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					MIN(RIGHT(PRODUCTID, 5) || PRODUCTO) OVER (
						PARTITION BY RPP_DETALLE.PERIODSEQ, RPP_DETALLE.POSITIONSEQ_PRIN, RPP_DETALLE.PERIODO, POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, 
						TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, ST_GA1, EVENTO, TO_VARCHAR(ST_GD3, 'MM-YYYY'), TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY')) AS PROD_PRIN
				FROM EXT.OUT_BAL_RPP_DETALLE_REP RPP_DETALLE
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = RPP_DETALLE.PERIODO
					AND F.TABLA = 'OUT_BAL_RPP_DETALLE_REP'
				LEFT JOIN (
					SELECT X.PAYEESEQ,
						X.POSITIONSEQ,
						X.PERIODSEQ,
						MAX(X.BALANCESEQ) AS BALANCESEQ 
					FROM TCMP.CS_BALANCE X
					GROUP BY X.PAYEESEQ, X.POSITIONSEQ, X.PERIODSEQ
					) B ON B.PAYEESEQ = RPP_DETALLE.PARTICIPANTSEQ
					AND B.POSITIONSEQ = RPP_DETALLE.POSITIONSEQ_PRIN
					AND B.PERIODSEQ = RPP_DETALLE.PERIODSEQ
				WHERE RPP_DETALLE.PERIODSEQ = :i_PeriodSeq
				GROUP BY RPP_DETALLE.PERIODSEQ, RPP_DETALLE.POSITIONSEQ_PRIN, RPP_DETALLE.PERIODO, 
				POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, 
				PRODUCTID, ST_GA1, PRODUCTO, EVENTO, TO_VARCHAR(ST_GD3, 'MM-YYYY'), TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY'),
				B.BALANCESEQ, F.ULTIMA_ACTUALIZACION

				UNION ALL

				SELECT
					'LC' AS TIPO_INFORME,
					RPP_DETALLE.PERIODSEQ AS PERIODSEQ,
					RPP_DETALLE.POSITIONSEQ_PRIN AS POSITIONSEQ,
					RPP_DETALLE.PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					POS_PRIN AS COD_AGENTE,
					TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
					NIF,
					TO_INT(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGE,
					RIGHT(PRODUCTID, 5) AS COD_PROD,
					ST_GA1 AS CODIGO_POLIZA,
					PRODUCTO AS NOMBRE_PRODUCTO,
					EVENTO AS TIPO_RECIBO,
					TO_VARCHAR(ST_GD3, 'MM-YYYY') AS FECHA_EMISION,
					TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY') AS FECHA_COBRO,
					SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN ROUND(VALUE, 2)
						ELSE 0
					END) AS POLIZAS_FIS,
					SUM(CASE WHEN NAME LIKE '%Poliza%'
						THEN ROUND(C_GN1, 2)
						ELSE 0
					END) AS POLIZAS_CORR,
					SUM(CASE WHEN NAME LIKE '%Prima%'
						THEN ROUND(VALUE, 2)
						ELSE 0
					END) AS PRIMAS,
					CASE 
						WHEN (P.POSTPIPELINERUNDATE IS NULL 
						OR P.POSTPIPELINERUNDATE > LAST_DAY(
							(SELECT STARTDATE 
							FROM CS_PERIOD 
							WHERE PERIODSEQ = RPP_DETALLE.PERIODSEQ 
								AND REMOVEDATE = :v_eot
					)))
						THEN 'SI' 
						ELSE NULL 
					END AS SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					MIN(RIGHT(PRODUCTID, 5) || PRODUCTO) OVER (
						PARTITION BY RPP_DETALLE.PERIODSEQ, RPP_DETALLE.POSITIONSEQ_PRIN, RPP_DETALLE.PERIODO, POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, 
						TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, ST_GA1, EVENTO, TO_VARCHAR(ST_GD3, 'MM-YYYY'), TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY')) AS PROD_PRIN
				FROM EXT.OUT_BAL_RPP_DETALLE_REP RPP_DETALLE
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = RPP_DETALLE.PERIODO
					AND F.TABLA = 'OUT_LC_RPP_DETALLE_REP'
				LEFT JOIN (
					SELECT X.PAYEESEQ,
						X.POSITIONSEQ,
						X.PERIODSEQ,
						MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE 
						FROM TCMP.CS_PAYMENT X
						GROUP BY X.PAYEESEQ, X.POSITIONSEQ, X.PERIODSEQ
					) P ON P.PAYEESEQ = RPP_DETALLE.PARTICIPANTSEQ
					AND P.POSITIONSEQ = RPP_DETALLE.POSITIONSEQ_PRIN
					AND P.PERIODSEQ = RPP_DETALLE.PERIODSEQ
				WHERE RPP_DETALLE.PERIODSEQ = :i_PeriodSeq
				GROUP BY RPP_DETALLE.PERIODSEQ, RPP_DETALLE.POSITIONSEQ_PRIN, RPP_DETALLE.PERIODO, 
				POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, TO_INT(ID_TIPO_AGENTE), TIPO_AGENTE, 
				PRODUCTID, ST_GA1, PRODUCTO, EVENTO, TO_VARCHAR(ST_GD3, 'MM-YYYY'), TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY'),
				P.POSTPIPELINERUNDATE, F.ULTIMA_ACTUALIZACION);
			v_num_rows := RECORD_COUNT(:TBL_RPP_DET_FINAL);
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'TBL_RPP_DET_FINAL creada. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			--BRG 20251202 Dividimos el INSERT en la final en 2 partes, RRTT agrupado y el resto de ramos sin agrupar
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RPP_DETALLE_FINAL_REP RRTT agrupado.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RPP_DETALLE_FINAL_REP(TIPO_INFORME,PERIODSEQ,POSITIONSEQ,PERIODO,PERIODO_FORMATO,COD_AGENTE,NOMBRE_AGENTE,NIF,TIPO_AGE,COD_PROD,CODIGO_POLIZA,NOMBRE_PRODUCTO,TIPO_RECIBO,FECHA_EMISION,FECHA_COBRO,POLIZAS_FIS,POLIZAS_CORR,PRIMAS,SOLO_DIFERENCIAS,FEC_ACTUALIZACION)
				SELECT 
					TIPO_INFORME, PERIODSEQ, POSITIONSEQ, PERIODO, PERIODO_FORMATO, 
					COD_AGENTE, NOMBRE_AGENTE, NIF, TIPO_AGE,
					--BRG 20260423 Transformamos para que los productos se vean bien cuando falta el principal
					LEFT(PROD_PRIN, 2) || '0' || RIGHT(LEFT(PROD_PRIN, 5), 2) AS COD_PROD, --BRG 20251202 En vez de COD_PRODUCTO
					CODIGO_POLIZA,
					RIGHT(PROD_PRIN, LENGTH(PROD_PRIN)-5) AS NOMBRE_PRODUCTO, --BRG 20251201 En vez de NOMBRE_PRODUCTO
					TIPO_RECIBO, FECHA_EMISION, FECHA_COBRO, 
					SUM(POLIZAS_FIS), SUM(POLIZAS_CORR), SUM(PRIMAS),
					SOLO_DIFERENCIAS, FEC_ACTUALIZACION					
				FROM :TBL_RPP_DET_FINAL
				WHERE PROD_PRIN LIKE '2%'
				GROUP BY TIPO_INFORME, PERIODSEQ, POSITIONSEQ, PERIODO, PERIODO_FORMATO,
					COD_AGENTE, NOMBRE_AGENTE, NIF, TIPO_AGE,
					PROD_PRIN, CODIGO_POLIZA, TIPO_RECIBO, FECHA_EMISION, FECHA_COBRO,
					SOLO_DIFERENCIAS, FEC_ACTUALIZACION; 
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPP_DETALLE_FINAL_REP RRTT agrupado. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RPP_DETALLE_FINAL_REP Resto Ramos.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RPP_DETALLE_FINAL_REP(TIPO_INFORME,PERIODSEQ,POSITIONSEQ,PERIODO,PERIODO_FORMATO,COD_AGENTE,NOMBRE_AGENTE,NIF,TIPO_AGE,COD_PROD,CODIGO_POLIZA,NOMBRE_PRODUCTO,TIPO_RECIBO,FECHA_EMISION,FECHA_COBRO,POLIZAS_FIS,POLIZAS_CORR,PRIMAS,SOLO_DIFERENCIAS,FEC_ACTUALIZACION)
				SELECT 
					TIPO_INFORME, PERIODSEQ, POSITIONSEQ, PERIODO, PERIODO_FORMATO,
					COD_AGENTE, NOMBRE_AGENTE, NIF, TIPO_AGE,
					COD_PROD,
					CODIGO_POLIZA,
					NOMBRE_PRODUCTO,
					TIPO_RECIBO, FECHA_EMISION, FECHA_COBRO,
					POLIZAS_FIS, POLIZAS_CORR, PRIMAS,
					SOLO_DIFERENCIAS, FEC_ACTUALIZACION
				FROM :TBL_RPP_DET_FINAL
				WHERE PROD_PRIN NOT LIKE '2%';
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RPP_DETALLE_FINAL_REP Resto Ramos. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			--BRG 20251126 Añadido
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Insert de --SELECCIONAR-- en OUT_RPP_DETALLE_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
            INSERT INTO EXT.OUT_RPP_DETALLE_FINAL_REP(TIPO_INFORME,PERIODSEQ,POSITIONSEQ,PERIODO,PERIODO_FORMATO,COD_AGENTE,NOMBRE_AGENTE,NIF,TIPO_AGE,COD_PROD,CODIGO_POLIZA,NOMBRE_PRODUCTO,TIPO_RECIBO,FECHA_EMISION,FECHA_COBRO,POLIZAS_FIS,POLIZAS_CORR,PRIMAS,SOLO_DIFERENCIAS,FEC_ACTUALIZACION)
				SELECT DISTINCT
					TIPO_INFORME,
					PERIODSEQ,
					-1 AS POSITIONSEQ,
					PERIODO,
					PERIODO_FORMATO,
					' ' AS COD_AGENTE,
					'--SELECCIONAR--' AS NOMBRE_AGENTE,
					' ' AS NIF,
					' ' AS TIPO_AGE,
					' ' AS COD_PROD,
					' ' AS CODIGO_POLIZA,
					' ' AS NOMBRE_PRODUCTO,
					' ' AS TIPO_RECIBO,
					' ' AS FECHA_EMISION,
					' ' AS FECHA_COBRO,
					NULL AS POLIZAS_FIS,
					NULL AS POLIZAS_CORR,
					NULL AS PRIMAS,
					SOLO_DIFERENCIAS,
					FEC_ACTUALIZACION
				FROM EXT.OUT_RPP_DETALLE_FINAL_REP
                WHERE PERIODSEQ = :i_PeriodSeq;
            v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Insert de --SELECCIONAR-- en OUT_RPP_DETALLE_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tablas FINALES Informe RPP', i_log_count, i_id_proceso, 'info');

		--FIN informe S4 Rappel Producción Propia Ag. con Grupo
		END IF;

		------------------------------------------------------------------------------------------------------------------------
		--Inicio informe S4 Rappel Especial
		IF :i_lista_informes = 'RE' OR :i_lista_informes LIKE '%|RE|%' OR :i_lista_informes LIKE '%|RE' OR :i_lista_informes LIKE 'RE|%' OR :i_lista_informes = 'ALL'
			THEN

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tablas FINALES Informe RE', i_log_count, i_id_proceso, 'info');
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RE_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_RE_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RE_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RE_RESUMEN_FINAL_REP. Cierre', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RE_RESUMEN_FINAL_REP (TIPO_INFORME, PERIODO, PERIODO_FORMATO, CODIGO_AGENTE, NIF, NOMBRE_AGENTE, NIF_NOMBRE, TIPO_AGENTE, RRPP, ASEG_RRTT, PRIMA_ANUALIZ, IMPORTE_RRPP, IMPORTE_ASEG_RRTT, CODIGO_AGENTE_TABLA, NOMBRE_AGENTE_TABLA, RRPP_TABLA, ASEG_RRTT_TABLA, FEC_ACTUALIZACION, SOLO_DIFERENCIAS, POSITIONSEQ, PERIODSEQ)
                (WITH QUERY_ORACLE AS (
                    SELECT
                        PERIODO, --Period Name
                        N_CREDITO, --GENERICATTRIBUTE11
                        SUM(V_CREDITO) AS V_CREDITO, --GENERICNUMBER1
                        FIRSTNAME_AG, --GENERICATTRIBUTE8
                        LASTNAME_AG, --GENERICATTRIBUTE9
                        MIDDLENAME_AG, --GENERICATTRIBUTE10
                        FIRSTNAME, --GENERICATTRIBUTE3
                        LASTNAME, --GENERICATTRIBUTE2
                        MIDDLENAME, --GENERICATTRIBUTE4
                        N_MEDIDA, --GENERICATTRIBUTE12
                        V_MEDIDA, --GENERICNUMBER5
                        SUM(VCORRECCION) AS VCORRECCION,--GENERICNUMBER6
                        POSITIONNAME, --GENERICATTRIBUTE5
                        POSITIONNAME_AG, --GENERICATTRIBUTE13
                        POS_PRIN, --GENERICATTRIBUTE1
                        ID_TIPO_AGENTE, --GENERICNUMBER2
                        TIPO_AGENTE, --GENERICATTRIBUTE6
                        EXTRACT(MONTH FROM STARTDATE) AS MES_NUM,
                        POSITIONSEQ_PRIN AS POSITIONSEQ
                    FROM EXT.OUT_RE_RESUMEN_REP RE_RESUMEN
                    WHERE PERIODSEQ = :i_PeriodSeq
                        AND ID_TIPO_AGENTE < 70
                    GROUP BY PERIODO, N_CREDITO, FIRSTNAME_AG, LASTNAME_AG, MIDDLENAME_AG, FIRSTNAME, LASTNAME, MIDDLENAME,
                        N_MEDIDA, V_MEDIDA, VCORRECCION, POSITIONNAME, POSITIONNAME_AG, POS_PRIN, ID_TIPO_AGENTE, TIPO_AGENTE,
                        STARTDATE, POSITIONSEQ_PRIN
                    
                    UNION ALL
                    
                    SELECT
                        PERIODO, --Period Name
                        N_CREDITO, --GENERICATTRIBUTE11
                        SUM(V_CREDITO) AS V_CREDITO, --GENERICNUMBER1
                        FIRSTNAME_AG, --GENERICATTRIBUTE8
                        LASTNAME_AG, --GENERICATTRIBUTE9
                        MIDDLENAME_AG, --GENERICATTRIBUTE10
                        FIRSTNAME, --GENERICATTRIBUTE3
                        LASTNAME, --GENERICATTRIBUTE2
                        MIDDLENAME, --GENERICATTRIBUTE4
                        N_MEDIDA, --GENERICATTRIBUTE12
                        V_MEDIDA, --GENERICNUMBER5
                        SUM(VCORRECCION) AS VCORRECCION,--GENERICNUMBER6
                        POSITIONNAME, --GENERICATTRIBUTE5
                        POSITIONNAME_AG, --GENERICATTRIBUTE13
                        POS_PRIN, --GENERICATTRIBUTE1
                        ID_TIPO_AGENTE, --GENERICNUMBER2
                        TIPO_AGENTE, --GENERICATTRIBUTE6
                        EXTRACT(MONTH FROM STARTDATE) AS MES_NUM,
                        POSITIONSEQ_PRIN AS POSITIONSEQ
                    FROM EXT.OUT_BAL_RE_RESUMEN_REP
                    WHERE QUARTER = :v_period_quarter
                    AND STARTDATE < :v_period_startdate
                    AND ID_TIPO_AGENTE < 70
                    GROUP BY PERIODO, N_CREDITO, FIRSTNAME_AG, LASTNAME_AG, MIDDLENAME_AG, FIRSTNAME, LASTNAME, MIDDLENAME,
                        N_MEDIDA, V_MEDIDA, VCORRECCION, POSITIONNAME, POSITIONNAME_AG, POS_PRIN, ID_TIPO_AGENTE, TIPO_AGENTE,
                        STARTDATE, POSITIONSEQ_PRIN
                ),
                VALORES_TABLA AS (
                    SELECT
                        :v_period_name AS PERIODO,
                        POS_PRIN AS CODIGO_AGENTE,
                        TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
                        TO_INTEGER(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGENTE,
                        SUM(CASE WHEN N_MEDIDA = 'SM-O-REP-Inspector-NumeroPolizasCorregidas-VidaAccidentes-TotalMes'
                            THEN V_MEDIDA
                            ELSE 0 END) AS RRPP,
                        SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalMes'
                            THEN V_MEDIDA
                            ELSE 0 END) AS ASEG_RRTT,
                        SUM(CASE WHEN (N_MEDIDA = 'SM-O-REP-Inspector-PrimaAnual-VidaAccidentes-Trim' AND PERIODO = :v_period_name)
                            THEN V_MEDIDA 
                            ELSE 0 END) AS PRIMA_ANUALIZ,
                        SUM(CASE WHEN N_MEDIDA LIKE 'SM-O-REP-Inspector-Pago%' AND MES_NUM IN (3, 6, 9, 12)
                            THEN V_MEDIDA 
                            ELSE 0 END) AS IMPORTE_RRPP,
                        SUM(CASE WHEN N_MEDIDA = 'SM-O-REAS-Inspector-Pago' AND MES_NUM IN (3, 6, 9, 12)
                            THEN V_MEDIDA 
                            ELSE 0 END) AS IMPORTE_ASEG_RRTT,
                        POSITIONNAME_AG AS CODIGO_AGENTE_TABLA,
                        TRIM(IFNULL(FIRSTNAME_AG, '') || IFNULL(' ' || MIDDLENAME_AG, '') || IFNULL(' ' || LASTNAME_AG, '')) AS NOMBRE_AGENTE_TABLA,
                        SUM(CASE WHEN POSITIONNAME_AG IS NOT NULL
                            THEN CASE WHEN N_MEDIDA = 'PM-O-REP-Inspector-NumeroPolizasCorregidas-VidaAccidentes-Agentes' 
                                THEN VCORRECCION 
                                ELSE 0 END
                            ELSE 0 END) AS RRPP_TABLA,
                        SUM(CASE WHEN POSITIONNAME_AG IS NOT NULL
                            THEN (CASE WHEN N_MEDIDA = 'PM-O-REP-Inspector-NumeroPolizasCorregidas-VidaAccidentes-Agentes' 
                                THEN V_CREDITO 
                                ELSE 0 END)
                            ELSE 0 END) AS ASEG_RRTT_TABLA,
                        POSITIONSEQ
                    FROM QUERY_ORACLE QO
                    GROUP BY POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, ID_TIPO_AGENTE, TIPO_AGENTE, N_MEDIDA,
                        POSITIONNAME_AG, FIRSTNAME_AG, MIDDLENAME_AG, LASTNAME_AG, POSITIONSEQ
                )
                SELECT
                    'CIERRE' AS TIPO_INFORME,
                    RE.PERIODO,
                    :v_period_name_format AS PERIODO_FORMATO,
                    RE.CODIGO_AGENTE,
                    J.NIF,
                    RE.NOMBRE_AGENTE,
                    J.NIF || ' - ' || RE.NOMBRE_AGENTE AS NIF_NOMBRE,
                    RE.TIPO_AGENTE,
                    SUM(RE.RRPP) AS RRPP,
                    SUM(RE.ASEG_RRTT) AS ASEG_RRTT,
                    SUM(RE.PRIMA_ANUALIZ) AS PRIMA_ANUALIZ,
                    SUM(RE.IMPORTE_RRPP) AS IMPORTE_RRPP,
                    SUM(RE.IMPORTE_ASEG_RRTT) AS IMPORTE_ASEG_RRTT,
                    RE.CODIGO_AGENTE_TABLA,
                    RE.NOMBRE_AGENTE_TABLA,
                    SUM(RE.RRPP_TABLA) AS RRPP_TABLA,
                    SUM(RE.ASEG_RRTT_TABLA) AS ASEG_RRTT_TABLA,
                    TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
                    NULL AS SOLO_DIFERENCIAS,
                    RE.POSITIONSEQ,
                    :i_PeriodSeq AS PERIODSEQ
                FROM VALORES_TABLA RE
                INNER JOIN (SELECT DISTINCT NIF, POSITIONSEQ, PERIODSEQ FROM EXT.OUT_JERARQUIA_REP) J ON J.PERIODSEQ = :i_PeriodSeq
                    AND J.POSITIONSEQ = RE.POSITIONSEQ
                LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
                    AND F.TABLA = 'OUT_RE_RESUMEN_REP'
                GROUP BY RE.PERIODO, RE.CODIGO_AGENTE, J.NIF, RE.NOMBRE_AGENTE, RE.TIPO_AGENTE,
                RE.CODIGO_AGENTE_TABLA, RE.NOMBRE_AGENTE_TABLA, RE.POSITIONSEQ, F.ULTIMA_ACTUALIZACION);
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RE_RESUMEN_FINAL_REP. Cierre. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RE_RESUMEN_FINAL_REP. Balance', i_log_count, i_id_proceso, 'debug');
            INSERT INTO EXT.OUT_RE_RESUMEN_FINAL_REP (TIPO_INFORME, PERIODO, PERIODO_FORMATO, CODIGO_AGENTE, NIF, NOMBRE_AGENTE, NIF_NOMBRE, TIPO_AGENTE, RRPP, ASEG_RRTT, PRIMA_ANUALIZ, IMPORTE_RRPP, IMPORTE_ASEG_RRTT, CODIGO_AGENTE_TABLA, NOMBRE_AGENTE_TABLA, RRPP_TABLA, ASEG_RRTT_TABLA, FEC_ACTUALIZACION, SOLO_DIFERENCIAS, POSITIONSEQ, PERIODSEQ)
                WITH QUERY_ORACLE AS (
                    SELECT
                        BAL_RE.PERIODO, --Period Name
                        BAL_RE.N_CREDITO, --GENERICATTRIBUTE11
                        SUM(BAL_RE.V_CREDITO) AS V_CREDITO, --GENERICNUMBER1
                        BAL_RE.FIRSTNAME_AG, --GENERICATTRIBUTE8
                        BAL_RE.LASTNAME_AG, --GENERICATTRIBUTE9
                        BAL_RE.MIDDLENAME_AG, --GENERICATTRIBUTE10
                        BAL_RE.FIRSTNAME, --GENERICATTRIBUTE3
                        BAL_RE.LASTNAME, --GENERICATTRIBUTE2
                        BAL_RE.MIDDLENAME, --GENERICATTRIBUTE4
                        BAL_RE.N_MEDIDA, --GENERICATTRIBUTE12
                        BAL_RE.V_MEDIDA, --GENERICNUMBER5
                        SUM( BAL_RE.VCORRECCION) AS VCORRECCION,--GENERICNUMBER6
                        BAL_RE.POSITIONNAME, --GENERICATTRIBUTE5
                        BAL_RE.POSITIONNAME_AG, --GENERICATTRIBUTE13
                        BAL_RE.POS_PRIN, --GENERICATTRIBUTE1
                        BAL_RE.ID_TIPO_AGENTE, --GENERICNUMBER2
                        BAL_RE.TIPO_AGENTE, --GENERICATTRIBUTE6
                        B.BALANCESEQ,
                        EXTRACT(MONTH FROM BAL_RE.STARTDATE) AS MES_NUM,
                        BAL_RE.POSITIONSEQ_PRIN AS POSITIONSEQ
                    FROM EXT.OUT_BAL_RE_RESUMEN_REP BAL_RE
                    LEFT JOIN (SELECT X.PERIODSEQ,X.PAYEESEQ,X.POSITIONSEQ,MAX(X.BALANCESEQ) AS BALANCESEQ FROM TCMP.CS_BALANCE X
                            WHERE X.PERIODSEQ = :i_PeriodSeq
                            GROUP BY X.PERIODSEQ,X.PAYEESEQ,X.POSITIONSEQ
                        ) B ON B.PAYEESEQ = BAL_RE.PARTICIPANTSEQ
                        AND B.POSITIONSEQ = BAL_RE.POSITIONSEQ_PRIN
                    WHERE BAL_RE.QUARTER = :v_period_quarter
                    AND BAL_RE.STARTDATE <= :v_period_startdate
                    AND BAL_RE.ID_TIPO_AGENTE < 70  --Para el informe de Incentivo Especial Resumen >= 70
                    GROUP BY BAL_RE.PERIODO, BAL_RE.N_CREDITO, BAL_RE.FIRSTNAME_AG, BAL_RE.LASTNAME_AG, BAL_RE.MIDDLENAME_AG, 
                        BAL_RE.FIRSTNAME, BAL_RE.LASTNAME, BAL_RE.MIDDLENAME, BAL_RE.N_MEDIDA, BAL_RE.V_MEDIDA, B.BALANCESEQ,
                        BAL_RE.POSITIONNAME, BAL_RE.POSITIONNAME_AG, BAL_RE.POS_PRIN, BAL_RE.ID_TIPO_AGENTE, BAL_RE.TIPO_AGENTE,
                        BAL_RE.STARTDATE, BAL_RE.POSITIONSEQ_PRIN
                ),
                VALORES_TABLA AS (
                    SELECT
                        :v_period_name AS PERIODO,
                        POS_PRIN AS CODIGO_AGENTE,
                        TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
                        TO_INTEGER(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGENTE,
                        SUM(CASE WHEN N_MEDIDA = 'SM-O-REP-Inspector-NumeroPolizasCorregidas-VidaAccidentes-TotalMes'
                            THEN V_MEDIDA
                            ELSE 0 END) AS RRPP,
                        SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalMes'
                            THEN V_MEDIDA
                            ELSE 0 END) AS ASEG_RRTT,
                        SUM(CASE WHEN (N_MEDIDA = 'SM-O-REP-Inspector-PrimaAnual-VidaAccidentes-Trim' AND PERIODO = :v_period_name)
                            THEN V_MEDIDA 
                            ELSE 0 END) AS PRIMA_ANUALIZ,
                        SUM(CASE WHEN N_MEDIDA LIKE 'SM-O-REP-Inspector-Pago%' AND MES_NUM IN (3, 6, 9, 12)
                            THEN V_MEDIDA 
                            ELSE 0 END) AS IMPORTE_RRPP,
                        SUM(CASE WHEN N_MEDIDA = 'SM-O-REAS-Inspector-Pago' AND MES_NUM IN (3, 6, 9, 12)
                            THEN V_MEDIDA 
                            ELSE 0 END) AS IMPORTE_ASEG_RRTT,
                        POSITIONNAME_AG AS CODIGO_AGENTE_TABLA,
                        TRIM(IFNULL(FIRSTNAME_AG, '') || IFNULL(' ' || MIDDLENAME_AG, '') || IFNULL(' ' || LASTNAME_AG, '')) AS NOMBRE_AGENTE_TABLA,
                        SUM(CASE WHEN N_MEDIDA = 'PM-O-REP-Inspector-NumeroPolizasCorregidas-VidaAccidentes-Agentes' 
                                THEN VCORRECCION 
                                ELSE 0 END) AS RRPP_TABLA,
                        SUM(CASE WHEN N_MEDIDA = 'PM-O-GEN-Inspector-NumAsegurados-Agentes' 
                                THEN V_CREDITO 
                                ELSE 0 END) AS ASEG_RRTT_TABLA,
                        POSITIONSEQ,
                        BALANCESEQ
                    FROM QUERY_ORACLE QO
                    GROUP BY POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, ID_TIPO_AGENTE, TIPO_AGENTE, N_MEDIDA,
                        POSITIONNAME_AG, FIRSTNAME_AG, MIDDLENAME_AG, LASTNAME_AG, POSITIONSEQ, BALANCESEQ
                )
                SELECT
                    'BAL' AS TIPO_INFORME,
                    RE.PERIODO,
                    :v_period_name_format AS PERIODO_FORMATO,
                    RE.CODIGO_AGENTE,
                    J.NIF,
                    RE.NOMBRE_AGENTE,
                    J.NIF || ' - ' || RE.NOMBRE_AGENTE AS NIF_NOMBRE,
                    RE.TIPO_AGENTE,
                    SUM(RE.RRPP) AS RRPP,
                    SUM(RE.ASEG_RRTT) AS ASEG_RRTT,
                    SUM(RE.PRIMA_ANUALIZ) AS PRIMA_ANUALIZ,
                    SUM(RE.IMPORTE_RRPP) AS IMPORTE_RRPP,
                    SUM(RE.IMPORTE_ASEG_RRTT) AS IMPORTE_ASEG_RRTT,
                    RE.CODIGO_AGENTE_TABLA,
                    RE.NOMBRE_AGENTE_TABLA,
                    SUM(RE.RRPP_TABLA) AS RRPP_TABLA,
                    SUM(RE.ASEG_RRTT_TABLA) AS ASEG_RRTT_TABLA,
                    TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
                    CASE WHEN BALANCESEQ IS NOT NULL
                        THEN 'SI'
                        ELSE NULL END AS SOLO_DIFERENCIAS,
                    RE.POSITIONSEQ,
                    :i_PeriodSeq AS PERIODSEQ
                FROM VALORES_TABLA RE
                INNER JOIN (SELECT DISTINCT NIF, POSITIONSEQ, PERIODSEQ FROM EXT.OUT_JERARQUIA_REP) J ON J.PERIODSEQ = :i_PeriodSeq
                    AND J.POSITIONSEQ = RE.POSITIONSEQ
                LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
                    AND F.TABLA = 'OUT_BAL_RE_RESUMEN_REP'
                GROUP BY RE.PERIODO, RE.CODIGO_AGENTE, J.NIF, RE.NOMBRE_AGENTE, RE.TIPO_AGENTE, RE.CODIGO_AGENTE_TABLA,
                	RE.NOMBRE_AGENTE_TABLA, RE.POSITIONSEQ, F.ULTIMA_ACTUALIZACION, RE.BALANCESEQ;
            v_num_rows := ::ROWCOUNT;
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RE_RESUMEN_FINAL_REP. Balance. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RE_RESUMEN_FINAL_REP. Liquidación Complementaria', i_log_count, i_id_proceso, 'debug');
            INSERT INTO EXT.OUT_RE_RESUMEN_FINAL_REP (TIPO_INFORME, PERIODO, PERIODO_FORMATO, CODIGO_AGENTE, NIF, NOMBRE_AGENTE, NIF_NOMBRE, TIPO_AGENTE, RRPP, ASEG_RRTT, PRIMA_ANUALIZ, IMPORTE_RRPP, IMPORTE_ASEG_RRTT, CODIGO_AGENTE_TABLA, NOMBRE_AGENTE_TABLA, RRPP_TABLA, ASEG_RRTT_TABLA, FEC_ACTUALIZACION, SOLO_DIFERENCIAS, POSITIONSEQ, PERIODSEQ)
            	WITH QUERY_ORACLE AS (
					SELECT DISTINCT
						LC_RE.PERIODO, --Period Name
						LC_RE.N_CREDITO, --GENERICATTRIBUTE11
						SUM(LC_RE.V_CREDITO) AS V_CREDITO, --GENERICNUMBER1
						LC_RE.FIRSTNAME_AG, --GENERICATTRIBUTE8
						LC_RE.LASTNAME_AG, --GENERICATTRIBUTE9
						LC_RE.MIDDLENAME_AG, --GENERICATTRIBUTE10
						LC_RE.FIRSTNAME, --GENERICATTRIBUTE3
						LC_RE.LASTNAME, --GENERICATTRIBUTE2
						LC_RE.MIDDLENAME, --GENERICATTRIBUTE4
						LC_RE.N_MEDIDA, --GENERICATTRIBUTE12
						LC_RE.V_MEDIDA, --GENERICNUMBER5
						SUM(LC_RE.VCORRECCION) AS VCORRECCION,--GENERICNUMBER6
						LC_RE.POSITIONNAME, --GENERICATTRIBUTE5
						LC_RE.POSITIONNAME_AG, --GENERICATTRIBUTE13
						LC_RE.POS_PRIN, --GENERICATTRIBUTE1
						LC_RE.ID_TIPO_AGENTE, --GENERICNUMBER2
						LC_RE.TIPO_AGENTE, --GENERICATTRIBUTE6
						P.POSTPIPELINERUNDATE,
						EXTRACT(MONTH FROM LC_RE.STARTDATE) AS MES_NUM,
						LC_RE.POSITIONSEQ_PRIN AS POSITIONSEQ
					FROM EXT.OUT_LC_RE_RESUMEN_REP LC_RE 
					LEFT JOIN (SELECT X.PAYEESEQ, X.POSITIONSEQ, MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE FROM TCMP.CS_PAYMENT X
							WHERE X.PERIODSEQ = :i_PeriodSeq
							GROUP BY X.PAYEESEQ, X.POSITIONSEQ
						) P ON P.PAYEESEQ = LC_RE.PARTICIPANTSEQ
						AND P.POSITIONSEQ = LC_RE.POSITIONSEQ_PRIN
					WHERE LC_RE.PERIODSEQ = :i_PeriodSeq
						AND LC_RE.ID_TIPO_AGENTE < 70
					GROUP BY LC_RE.PERIODO, LC_RE.N_CREDITO, LC_RE.FIRSTNAME_AG, LC_RE.LASTNAME_AG, LC_RE.MIDDLENAME_AG,
						LC_RE.FIRSTNAME, LC_RE.LASTNAME, LC_RE.MIDDLENAME, LC_RE.N_MEDIDA, LC_RE.V_MEDIDA,
						LC_RE.POSITIONNAME, LC_RE.POSITIONNAME_AG, LC_RE.POS_PRIN, LC_RE.ID_TIPO_AGENTE, LC_RE.TIPO_AGENTE,
						LC_RE.STARTDATE, LC_RE.POSITIONSEQ_PRIN, P.POSTPIPELINERUNDATE
					
					UNION ALL
					
					SELECT DISTINCT
						BAL_RE.PERIODO, --Period Name
						BAL_RE.N_CREDITO, --GENERICATTRIBUTE11
						SUM(BAL_RE.V_CREDITO) AS V_CREDITO, --GENERICNUMBER1
						BAL_RE.FIRSTNAME_AG, --GENERICATTRIBUTE8
						BAL_RE.LASTNAME_AG, --GENERICATTRIBUTE9
						BAL_RE.MIDDLENAME_AG, --GENERICATTRIBUTE10
						BAL_RE.FIRSTNAME, --GENERICATTRIBUTE3
						BAL_RE.LASTNAME, --GENERICATTRIBUTE2
						BAL_RE.MIDDLENAME, --GENERICATTRIBUTE4
						BAL_RE.N_MEDIDA, --GENERICATTRIBUTE12
						BAL_RE.V_MEDIDA, --GENERICNUMBER5
						SUM(BAL_RE.VCORRECCION) AS VCORRECCION,--GENERICNUMBER6
						BAL_RE.POSITIONNAME, --GENERICATTRIBUTE5
						BAL_RE.POSITIONNAME_AG, --GENERICATTRIBUTE13
						BAL_RE.POS_PRIN, --GENERICATTRIBUTE1
						BAL_RE.ID_TIPO_AGENTE, --GENERICNUMBER2
						BAL_RE.TIPO_AGENTE, --GENERICATTRIBUTE6
						P.POSTPIPELINERUNDATE,
						EXTRACT(MONTH FROM BAL_RE.STARTDATE) AS MES_NUM,
						BAL_RE.POSITIONSEQ_PRIN
					FROM EXT.OUT_BAL_RE_RESUMEN_REP BAL_RE
					LEFT JOIN (SELECT X.PAYEESEQ,X.POSITIONSEQ,MAX(X.POSTPIPELINERUNDATE) AS POSTPIPELINERUNDATE 
							FROM TCMP.CS_PAYMENT X
							WHERE X.PERIODSEQ = :i_PeriodSeq
							GROUP BY X.PAYEESEQ,X.POSITIONSEQ
						) P ON P.PAYEESEQ = BAL_RE.PARTICIPANTSEQ
						AND P.POSITIONSEQ = BAL_RE.POSITIONSEQ_PRIN
					WHERE BAL_RE.QUARTER = :v_period_quarter
						AND BAL_RE.STARTDATE < :v_period_startdate
						AND BAL_RE.ID_TIPO_AGENTE < 70
						-- No nos interesa generar LC si no ha habido en ese mes
						AND :v_period_name IN (SELECT DISTINCT PERIODO FROM EXT.OUT_LC_RE_RESUMEN_REP)
						-- Sólo las posiciones que hayan tenido LC en el mes
						AND BAL_RE.POS_PRIN IN (SELECT DISTINCT POS_PRIN FROM EXT.OUT_LC_RE_RESUMEN_REP WHERE PERIODO = :v_period_name)
					GROUP BY BAL_RE.PERIODO, BAL_RE.N_CREDITO, BAL_RE.FIRSTNAME_AG, BAL_RE.LASTNAME_AG, BAL_RE.MIDDLENAME_AG,
						BAL_RE.FIRSTNAME, BAL_RE.LASTNAME, BAL_RE.MIDDLENAME, BAL_RE.N_MEDIDA, BAL_RE.V_MEDIDA,
						BAL_RE.POSITIONNAME, BAL_RE.POSITIONNAME_AG, BAL_RE.POS_PRIN, BAL_RE.ID_TIPO_AGENTE, BAL_RE.TIPO_AGENTE,
						BAL_RE.STARTDATE, BAL_RE.POSITIONSEQ_PRIN, P.POSTPIPELINERUNDATE
				),
				VALORES_TABLA AS (
					SELECT DISTINCT
						:v_period_name AS PERIODO,
						POS_PRIN AS CODIGO_AGENTE,
						TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
						TO_INTEGER(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGENTE,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-REP-Inspector-NumeroPolizasCorregidas-VidaAccidentes-TotalMes'
							THEN V_MEDIDA
							ELSE 0 END) AS RRPP,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-GEN-Inspector-NumAsegurados-TotalMes'
							THEN V_MEDIDA
							ELSE 0 END) AS ASEG_RRTT,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-REP-Inspector-PrimaAnual-VidaAccidentes-Trim' AND PERIODO = :v_period_name
							THEN V_MEDIDA 
							ELSE 0 END) AS PRIMA_ANUALIZ,
						SUM(CASE WHEN N_MEDIDA LIKE 'SM-O-REP-Inspector-Pago%' AND MES_NUM IN (3, 6, 9, 12)
							THEN V_MEDIDA 
							ELSE 0 END) AS IMPORTE_RRPP,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-REAS-Inspector-Pago' AND MES_NUM IN (3, 6, 9, 12)
							THEN V_MEDIDA 
							ELSE 0 END) AS IMPORTE_ASEG_RRTT,
						POSITIONNAME_AG AS CODIGO_AGENTE_TABLA,
						TRIM(IFNULL(FIRSTNAME_AG, '') || IFNULL(' ' || MIDDLENAME_AG, '') || IFNULL(' ' || LASTNAME_AG, '')) AS NOMBRE_AGENTE_TABLA,
						SUM(CASE WHEN N_MEDIDA = 'PM-O-REP-Inspector-NumeroPolizasCorregidas-VidaAccidentes-Agentes' 
								THEN VCORRECCION 
								ELSE 0 END) AS RRPP_TABLA,
						SUM(CASE WHEN N_MEDIDA = 'PM-O-GEN-Inspector-NumAsegurados-Agentes' 
								THEN V_CREDITO 
								ELSE 0 END) AS ASEG_RRTT_TABLA,
						POSITIONSEQ,
						POSTPIPELINERUNDATE
					FROM QUERY_ORACLE QO
					GROUP BY POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, ID_TIPO_AGENTE, TIPO_AGENTE, N_MEDIDA,
						POSITIONNAME_AG, FIRSTNAME_AG, MIDDLENAME_AG, LASTNAME_AG, POSITIONSEQ, POSTPIPELINERUNDATE
				)
				SELECT DISTINCT
					'LC' AS TIPO_INFORME,
					RE.PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					RE.CODIGO_AGENTE,
					J.NIF,
					RE.NOMBRE_AGENTE,
					J.NIF || ' - ' || RE.NOMBRE_AGENTE AS NIF_NOMBRE,
					RE.TIPO_AGENTE,
					SUM(RE.RRPP) AS RRPP,
					SUM(RE.ASEG_RRTT) AS ASEG_RRTT,
					SUM(RE.PRIMA_ANUALIZ) AS PRIMA_ANUALIZ,
					SUM(RE.IMPORTE_RRPP) AS IMPORTE_RRPP,
					SUM(RE.IMPORTE_ASEG_RRTT) AS IMPORTE_ASEG_RRTT,
					RE.CODIGO_AGENTE_TABLA,
					RE.NOMBRE_AGENTE_TABLA,
					SUM(RE.RRPP_TABLA) AS RRPP_TABLA,
					SUM(RE.ASEG_RRTT_TABLA) AS ASEG_RRTT_TABLA,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					CASE WHEN RE.POSTPIPELINERUNDATE IS NULL OR RE.POSTPIPELINERUNDATE > LAST_DAY(:v_period_startdate)
						THEN 'SI'
						ELSE NULL END AS SOLO_DIFERENCIAS,
					RE.POSITIONSEQ,
					:i_PeriodSeq AS PERIODSEQ
				FROM VALORES_TABLA RE
				INNER JOIN (SELECT DISTINCT NIF, PERIODSEQ, POSITIONSEQ FROM EXT.OUT_JERARQUIA_REP) J ON J.PERIODSEQ = :i_PeriodSeq
					AND J.POSITIONSEQ = RE.POSITIONSEQ
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
					AND F.TABLA = 'OUT_LC_RE_RESUMEN_REP'
				GROUP BY RE.PERIODO, RE.CODIGO_AGENTE, J.NIF, 
					RE.NOMBRE_AGENTE, RE.TIPO_AGENTE, RE.CODIGO_AGENTE_TABLA,
					RE.NOMBRE_AGENTE_TABLA, RE.POSITIONSEQ, F.ULTIMA_ACTUALIZACION, RE.POSTPIPELINERUNDATE;
            v_num_rows := ::ROWCOUNT;
            CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RE_RESUMEN_FINAL_REP. Liquidación Complementaria. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tablas FINALES Informe RE', i_log_count, i_id_proceso, 'info');
        
        --FIN informe S4 Rappel Especial
        END IF;

		------------------------------------------------------------------------------------------------------------------------
		--Inicio informe S4 Rappel Mantenimiento
		IF :i_lista_informes = 'RDC' OR :i_lista_informes LIKE '%|RDC|%' OR :i_lista_informes LIKE '%|RDC' OR :i_lista_informes LIKE 'RDC|%' OR :i_lista_informes = 'ALL'
			THEN

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tablas FINALES Informe RDC Resumen', i_log_count, i_id_proceso, 'info');
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RDC_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_RDC_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RDC_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RDC_RESUMEN_FINAL_REP. Cierre', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RDC_RESUMEN_FINAL_REP (TIPO_INFORME, PERIODO_FILTRO, PERIODO_FORMATO, PERIODO_TABLA, COD_AGENTE, NOMBRE_AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, POL_FIS_REC, POL_CORR_REC, PRIMA_CORR, IMPORTE_PAGO, BALANCES_MESES_ANT, IMPORTE_TOTAL_PAGADO, OBJ_REG_CUAT, COMP_CUAT_RAPPEL, IGUALES, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, POSITIONSEQ, PERIODSEQ, STARTDATE)
                WITH QUERY_ORACLE AS (
					SELECT DISTINCT
						RDC_RESUMEN.PERIODO, --Period Name
						RDC_RESUMEN.N_CREDITO, --GENERICATTRIBUTE11
						RDC_RESUMEN.V_CREDITO, --GENERICNUMBER1
						RDC_RESUMEN.FIRSTNAME, --GENERICATTRIBUTE3
						RDC_RESUMEN.LASTNAME, --GENERICATTRIBUTE2
						RDC_RESUMEN.MIDDLENAME, --GENERICATTRIBUTE4
						RDC_RESUMEN.N_MEDIDA, --GENERICATTRIBUTE12
						RDC_RESUMEN.V_MEDIDA, --GENERICNUMBER5
						RDC_RESUMEN.POSITIONNAME, --GENERICATTRIBUTE5
						RDC_RESUMEN.POSITIONNAME_AG, --GENERICATTRIBUTE13
						RDC_RESUMEN.POS_PRIN, --GENERICATTRIBUTE1
						RDC_RESUMEN.ID_TIPO_AGENTE, --GENERICNUMBER2
						RDC_RESUMEN.TIPO_AGENTE, --GENERICATTRIBUTE6
						RDC_RESUMEN.NIF, --GENERICATTRIBUTE8
						RDC_RESUMEN.STARTDATE,
						RDC_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ
					FROM EXT.OUT_RDC_RESUMEN_REP RDC_RESUMEN 
						--Todas las reglas de cierre del mes de cierre menos la de pagos
					WHERE RDC_RESUMEN.N_MEDIDA <> 'SM-O-RDC-Agente-Pago'
					AND RDC_RESUMEN.PERIODSEQ = :i_PeriodSeq
					
					UNION ALL
					
					SELECT DISTINCT
						RDC_RESUMEN.PERIODO, --Period Name
						RDC_RESUMEN.N_CREDITO, --GENERICATTRIBUTE11
						RDC_RESUMEN.V_CREDITO, --GENERICNUMBER1
						RDC_RESUMEN.FIRSTNAME, --GENERICATTRIBUTE3
						RDC_RESUMEN.LASTNAME, --GENERICATTRIBUTE2
						RDC_RESUMEN.MIDDLENAME, --GENERICATTRIBUTE4
						RDC_RESUMEN.N_MEDIDA, --GENERICATTRIBUTE12
						RDC_RESUMEN.V_MEDIDA, --GENERICNUMBER5
						RDC_RESUMEN.POSITIONNAME, --GENERICATTRIBUTE5
						RDC_RESUMEN.POSITIONNAME_AG, --GENERICATTRIBUTE13
						RDC_RESUMEN.POS_PRIN, --GENERICATTRIBUTE1
						RDC_RESUMEN.ID_TIPO_AGENTE, --GENERICNUMBER2
						RDC_RESUMEN.TIPO_AGENTE, --GENERICATTRIBUTE6
						RDC_RESUMEN.NIF, --GENERICATTRIBUTE8
						RDC_RESUMEN.STARTDATE,
						RDC_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ
					FROM EXT.OUT_BAL_RDC_RESUMEN_REP RDC_RESUMEN 
					--Todas las reglas de balances de los meses anteriores al cierre menos la de pagos
					WHERE RDC_RESUMEN.N_MEDIDA <> 'SM-O-RDC-Agente-Pago'
					AND RDC_RESUMEN.YEAR = :v_period_year
					AND RDC_RESUMEN.STARTDATE < :v_period_startdate
					AND (
					CASE WHEN EXTRACT(MONTH FROM :v_period_startdate) BETWEEN 5 AND 8 THEN 4
							WHEN EXTRACT(MONTH FROM :v_period_startdate) > 8 THEN 8
							ELSE 0
					END) < EXTRACT(MONTH FROM RDC_RESUMEN.STARTDATE)    
					
					UNION ALL
					
					SELECT DISTINCT
						RDC_RESUMEN.PERIODO, --Period Name
						RDC_RESUMEN.N_CREDITO, --GENERICATTRIBUTE11
						RDC_RESUMEN.V_CREDITO, --GENERICNUMBER1
						RDC_RESUMEN.FIRSTNAME, --GENERICATTRIBUTE3
						RDC_RESUMEN.LASTNAME, --GENERICATTRIBUTE2
						RDC_RESUMEN.MIDDLENAME, --GENERICATTRIBUTE4
						RDC_RESUMEN.N_MEDIDA, --GENERICATTRIBUTE12
						RDC_RESUMEN.V_MEDIDA, --GENERICNUMBER5
						RDC_RESUMEN.POSITIONNAME, --GENERICATTRIBUTE5
						RDC_RESUMEN.POSITIONNAME_AG, --GENERICATTRIBUTE13
						RDC_RESUMEN.POS_PRIN, --GENERICATTRIBUTE1
						RDC_RESUMEN.ID_TIPO_AGENTE, --GENERICNUMBER2
						RDC_RESUMEN.TIPO_AGENTE, --GENERICATTRIBUTE6
						RDC_RESUMEN.NIF, --GENERICATTRIBUTE8
						RDC_RESUMEN.STARTDATE,
						RDC_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ
					FROM EXT.OUT_RDC_RESUMEN_REP RDC_RESUMEN  
					--Regla de pagos de los cierres
					WHERE RDC_RESUMEN.N_MEDIDA = 'SM-O-RDC-Agente-Pago'
					AND RDC_RESUMEN.YEAR = :v_period_year
					AND RDC_RESUMEN.STARTDATE <= :v_period_startdate
					AND (
					CASE WHEN EXTRACT(MONTH FROM :v_period_startdate) BETWEEN 5 AND 8 THEN 4
							WHEN EXTRACT(MONTH FROM :v_period_startdate) > 8 THEN 8
							ELSE 0
					END) < EXTRACT(MONTH FROM RDC_RESUMEN.STARTDATE)    
					
					UNION ALL
					
					SELECT DISTINCT
						RDC_RESUMEN.PERIODO, --Period Name
						RDC_RESUMEN.N_CREDITO, --GENERICATTRIBUTE11
						RDC_RESUMEN.V_CREDITO, --GENERICNUMBER1
						RDC_RESUMEN.FIRSTNAME, --GENERICATTRIBUTE3
						RDC_RESUMEN.LASTNAME, --GENERICATTRIBUTE2
						RDC_RESUMEN.MIDDLENAME, --GENERICATTRIBUTE4
						RDC_RESUMEN.N_MEDIDA || '_Balance', --GENERICATTRIBUTE12
						RDC_RESUMEN.V_MEDIDA, --GENERICNUMBER5
						RDC_RESUMEN.POSITIONNAME, --GENERICATTRIBUTE5
						RDC_RESUMEN.POSITIONNAME_AG, --GENERICATTRIBUTE13
						RDC_RESUMEN.POS_PRIN, --GENERICATTRIBUTE1
						RDC_RESUMEN.ID_TIPO_AGENTE, --GENERICNUMBER2
						RDC_RESUMEN.TIPO_AGENTE, --GENERICATTRIBUTE6
						RDC_RESUMEN.NIF, --GENERICATTRIBUTE8
						RDC_RESUMEN.STARTDATE,
						RDC_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ
					FROM EXT.OUT_BAL_RDC_RESUMEN_REP RDC_RESUMEN
					--Regla de pagos de los balances
					WHERE RDC_RESUMEN.N_MEDIDA = 'SM-O-RDC-Agente-Pago'
					AND RDC_RESUMEN.YEAR = :v_period_year
					AND RDC_RESUMEN.STARTDATE < :v_period_startdate
					AND (
					CASE WHEN EXTRACT(MONTH FROM :v_period_startdate) BETWEEN 5 AND 8 THEN 4
							WHEN EXTRACT(MONTH FROM :v_period_startdate) > 8 THEN 8
							ELSE 0
					END) < EXTRACT(MONTH FROM RDC_RESUMEN.STARTDATE)    
				),
				VALORES_INTERMEDIOS AS (
					SELECT 
						:v_period_name AS PERIODO_FILTRO,
						STARTDATE,
						PERIODO,
						POS_PRIN AS COD_AGENTE,
						TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
						NIF,
						TO_INTEGER(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGENTE,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-RDC-Agente-Polizas' 
							THEN V_MEDIDA 
							ELSE 0 END) AS POL_FIS_REC,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-RDC-Agente-PolizasCorregidas'
							THEN V_MEDIDA
							ELSE 0 END) AS POL_CORR_REC,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-RDC-Agente-PrimaCorregida'
							THEN V_MEDIDA
							ELSE 0 END) AS PRIMA_CORR,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-RDC-Agente-Pago'
							THEN V_MEDIDA
							ELSE 0 END) AS IMPORTE_PAGO,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-RDC-Agente-Pago_Balance'
							THEN V_MEDIDA
							ELSE 0 END) AS BALANCE_MENSUAL,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-RDC-ImportePagoCuatrim'
							THEN V_MEDIDA
							ELSE 0 END) AS OBJ_REG_CUAT,
						SUM(CASE WHEN N_MEDIDA = 'SM-O-RDC-ImportePagoCuatrim-Final'
							THEN V_MEDIDA
							ELSE 0 END)	AS COMP_CUAT_RAPPEL,
						POSITIONSEQ
					FROM QUERY_ORACLE
					GROUP BY PERIODO, POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, ID_TIPO_AGENTE, TIPO_AGENTE,
						STARTDATE, POSITIONSEQ
				)
				SELECT
					'CIERRE' AS TIPO_INFORME,
					VI.PERIODO_FILTRO,
					:v_period_name_format AS PERIODO_FORMATO,
					VI.PERIODO AS PERIODO_TABLA,
					VI.COD_AGENTE,
					VI.NOMBRE_AGENTE,
					VI.NIF,
					VI.NIF || ' - ' || NOMBRE_AGENTE AS NIF_NOMBRE,
					VI.TIPO_AGENTE,
					VI.POL_FIS_REC,
					VI.POL_CORR_REC,
					VI.PRIMA_CORR,
					VI.IMPORTE_PAGO,
					CASE WHEN VI.BALANCE_MENSUAL IS NULL OR VI.BALANCE_MENSUAL = 0
						THEN 0
						ELSE VI.BALANCE_MENSUAL - VI.IMPORTE_PAGO END AS BALANCES_MESES_ANT,
					CASE WHEN VI.BALANCE_MENSUAL IS NULL OR VI.BALANCE_MENSUAL = 0
						THEN VI.IMPORTE_PAGO
						ELSE VI.BALANCE_MENSUAL END AS IMPORTE_TOTAL_PAGADO,
					VI.OBJ_REG_CUAT,
					VI.COMP_CUAT_RAPPEL,
					
					CASE WHEN VI.PERIODO = :v_period_name
						THEN 'SI'
						ELSE 'NO' END AS IGUALES,
					NULL AS SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					VI.POSITIONSEQ,
					:i_PeriodSeq AS PERIODSEQ,
					VI.STARTDATE
				FROM VALORES_INTERMEDIOS VI
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
					AND F.TABLA = 'OUT_RDC_RESUMEN_REP';
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RDC_RESUMEN_FINAL_REP. Cierre. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RDC_RESUMEN_FINAL_REP. Balances', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RDC_RESUMEN_FINAL_REP (TIPO_INFORME, PERIODO_FILTRO, PERIODO_FORMATO, PERIODO_TABLA, COD_AGENTE, NOMBRE_AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, POL_FIS_REC, POL_CORR_REC, PRIMA_CORR, IMPORTE_PAGO, BALANCES_MESES_ANT, IMPORTE_TOTAL_PAGADO, OBJ_REG_CUAT, COMP_CUAT_RAPPEL, IGUALES, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, POSITIONSEQ, PERIODSEQ, STARTDATE)
				WITH QUERY_ORACLE AS (
					SELECT DISTINCT
						RDC_RESUMEN.PERIODO, --Period Name
						RDC_RESUMEN.N_CREDITO, --GENERICATTRIBUTE11
						RDC_RESUMEN.V_CREDITO, --GENERICNUMBER1
						RDC_RESUMEN.FIRSTNAME, --GENERICATTRIBUTE3
						RDC_RESUMEN.LASTNAME, --GENERICATTRIBUTE2
						RDC_RESUMEN.MIDDLENAME, --GENERICATTRIBUTE4
						RDC_RESUMEN.N_MEDIDA, --GENERICATTRIBUTE12
						RDC_RESUMEN.V_MEDIDA, --GENERICNUMBER5
						RDC_RESUMEN.POSITIONNAME, --GENERICATTRIBUTE5
						RDC_RESUMEN.POSITIONNAME_AG, --GENERICATTRIBUTE13
						RDC_RESUMEN.POS_PRIN, --GENERICATTRIBUTE1
						RDC_RESUMEN.ID_TIPO_AGENTE, --GENERICNUMBER2
						RDC_RESUMEN.TIPO_AGENTE, --GENERICATTRIBUTE6
						RDC_RESUMEN.NIF, --GENERICATTRIBUTE8
						RDC_RESUMEN.STARTDATE,
						RDC_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ,
						CASE WHEN B.BALANCESEQ IS NOT NULL
							THEN 'SI'
							ELSE NULL END AS SOLO_DIFERENCIAS
					FROM EXT.OUT_BAL_RDC_RESUMEN_REP RDC_RESUMEN 
					LEFT JOIN TCMP.CS_BALANCE B ON B.PAYEESEQ = RDC_RESUMEN.PARTICIPANTSEQ
						AND B.POSITIONSEQ = RDC_RESUMEN.POSITIONSEQ_PRIN
						AND B.PERIODSEQ = RDC_RESUMEN.PERIODSEQ
					WHERE RDC_RESUMEN.YEAR = :v_period_year
						AND RDC_RESUMEN.STARTDATE <= :v_period_startdate
						AND (
						CASE WHEN EXTRACT(MONTH FROM :v_period_startdate) BETWEEN 5 AND 8 THEN 4
								WHEN EXTRACT(MONTH FROM :v_period_startdate) > 8 THEN 8
								ELSE 0
						END) < EXTRACT(MONTH FROM RDC_RESUMEN.STARTDATE)
						--BRG 20260305 Excluimos meses para los que aún no se haya hecho el balance
						AND EXISTS(SELECT 1 FROM EXT.OUT_BAL_RDC_RESUMEN_REP WHERE PERIODSEQ = :i_PeriodSeq)
				)
				SELECT 
					'BAL' AS TIPO_INFORME,
					:v_period_name AS PERIODO_FILTRO,
					:v_period_name_format AS PERIODO_FORMATO,
					QO.PERIODO AS PERIODO_TABLA,
					POS_PRIN AS COD_AGENTE,
					TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
					NIF,
					NIF || ' - ' || TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NIF_NOMBRE,
					TO_INTEGER(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGENTE,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RDC-Agente-Polizas' 
						THEN V_MEDIDA 
						ELSE 0 END) AS POL_FIS_REC,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RDC-Agente-PolizasCorregidas'
						THEN V_MEDIDA
						ELSE 0 END) AS POL_CORR_REC,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RDC-Agente-PrimaCorregida'
						THEN V_MEDIDA
						ELSE 0 END) AS PRIMA_CORR,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RDC-Agente-Pago'
						THEN V_MEDIDA
						ELSE 0 END) AS IMPORTE_PAGO,
					NULL AS BALANCES_MESES_ANT,
					NULL AS IMPORTE_TOTAL_PAGADO,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RDC-ImportePagoCuatrim'
						THEN V_MEDIDA
						ELSE 0 END) AS OBJ_REG_CUAT,
					SUM(CASE WHEN N_MEDIDA = 'SM-O-RDC-ImportePagoCuatrim-Final'
						THEN V_MEDIDA
						ELSE 0 END)	AS COMP_CUAT_RAPPEL,
						
					CASE WHEN QO.PERIODO = :v_period_name
						THEN 'SI'
						ELSE 'NO' END AS IGUALES,
					QO.SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					POSITIONSEQ,
					:i_PeriodSeq AS PERIODSEQ,
					STARTDATE
				FROM QUERY_ORACLE QO
				INNER JOIN :TBL_PER_FORMAT PF ON PF.PERIODO = :v_period_name
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
					AND F.TABLA = 'OUT_BAL_RDC_RESUMEN_REP'
				GROUP BY QO.PERIODO, POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, ID_TIPO_AGENTE, TIPO_AGENTE,
					STARTDATE, POSITIONSEQ, QO.SOLO_DIFERENCIAS, F.ULTIMA_ACTUALIZACION;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RDC_RESUMEN_FINAL_REP. Balances. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tablas FINALES Informe RDC Resumen', i_log_count, i_id_proceso, 'info');


			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tablas FINALES Informe RDC Detalle', i_log_count, i_id_proceso, 'info');
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_RDC_DETALLE_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_RDC_DETALLE_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_RDC_DETALLE_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RDC_DETALLE_FINAL_REP. Cierre', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RDC_DETALLE_FINAL_REP (TIPO_INFORME, PERIODO, PERIODO_FORMATO, COD_AGENTE, NOMBRE_AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, COD_AGENTE_TABLA, NOMBRE_AGENTE_TABLA, COD_PROD, POLIZA, PRODUCTO, TIPO_REC, FEC_EMISION, FEC_COBRO, POL_FIS, POL_CORR, PRIMA, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, PERIODSEQ, POSITIONSEQ)
				(SELECT
					'CIERRE' AS TIPO_INFORME,
					:v_period_name AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					POS_PRIN AS COD_AGENTE,
					TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
					NIF,
					NIF || ' - ' || TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NIF_NOMBRE,
					TO_INTEGER(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGENTE,
					
					MAX(POSITIONNAME_AG) AS COD_AGENTE_TABLA,
					MAX(TRIM(IFNULL(FIRSTNAME_AG, '') || IFNULL(' ' || MIDDLENAME_AG, '') || IFNULL(' ' || LASTNAME_AG, ''))) AS NOMBRE_AGENTE_TABLA,
					RIGHT(PRODUCTID,5) AS COD_PROD,
					ST_GA1 AS POLIZA,
					MAX(PRODUCTO) AS PRODUCTO,
					MAX(EVENTO) AS TIPO_REC,
					IFNULL(MAX(TO_VARCHAR(ST_GD3, 'MM-YYYY')), ' ') AS FEC_EMISION,
					IFNULL(MAX(TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY')), ' ') AS FEC_COBRO,
					SUM(CASE WHEN NAME = 'DC-O-RDC-Agente-Polizas'
						THEN VALUE
						ELSE 0 END) AS POL_FIS,
					SUM(CASE WHEN NAME = 'DC-O-RDC-Agente-PolizasCorregidas'
						THEN VALUE
						ELSE 0 END) AS POL_CORR,
					MAX(ST_GN1) AS PRIMA,
					
					NULL AS SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					:i_PeriodSeq AS PERIODSEQ,
					POSITIONSEQ_PRIN AS POSITIONSEQ
				FROM EXT.OUT_RDC_DETALLE_REP RDC_DETALLE
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
					AND TABLA = 'OUT_RDC_DETALLE_REP'
				WHERE RDC_DETALLE.PERIODSEQ = :i_PeriodSeq
				GROUP BY POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, ID_TIPO_AGENTE, TIPO_AGENTE,
					PRODUCTID, ST_GA1, F.ULTIMA_ACTUALIZACION, POSITIONSEQ_PRIN);
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RDC_DETALLE_FINAL_REP. Cierre. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_RDC_DETALLE_FINAL_REP. Balance', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RDC_DETALLE_FINAL_REP (TIPO_INFORME, PERIODO, PERIODO_FORMATO, COD_AGENTE, NOMBRE_AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, COD_AGENTE_TABLA, NOMBRE_AGENTE_TABLA, COD_PROD, POLIZA, PRODUCTO, TIPO_REC, FEC_EMISION, FEC_COBRO, POL_FIS, POL_CORR, PRIMA, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, PERIODSEQ, POSITIONSEQ)
				SELECT DISTINCT
					'BAL' AS TIPO_INFORME,
					:v_period_name AS PERIODO,
					:v_period_name_format AS PERIODO_FORMATO,
					POS_PRIN AS COD_AGENTE,
					TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NOMBRE_AGENTE,
					NIF,
					NIF || ' - ' || TRIM(IFNULL(FIRSTNAME, '') || IFNULL(' ' || MIDDLENAME, '') || IFNULL(' ' || LASTNAME, '')) AS NIF_NOMBRE,
					TO_INTEGER(ID_TIPO_AGENTE) || ' - ' || TIPO_AGENTE AS TIPO_AGENTE,
					
					MAX(POSITIONNAME_AG) AS COD_AGENTE_TABLA,
					MAX(TRIM(IFNULL(FIRSTNAME_AG, '') || IFNULL(' ' || MIDDLENAME_AG, '') || IFNULL(' ' || LASTNAME_AG, ''))) AS NOMBRE_AGENTE_TABLA,
					RIGHT(PRODUCTID,5) AS COD_PROD,
					ST_GA1 AS POLIZA,
					MAX(PRODUCTO) AS PRODUCTO,
					MAX(EVENTO) AS TIPO_REC,
					IFNULL(MAX(TO_VARCHAR(ST_GD3, 'MM-YYYY')), ' ') AS FEC_EMISION,
					IFNULL(MAX(TO_VARCHAR(ACCOUNTINGDATE, 'MM-YYYY')), ' ') AS FEC_COBRO,
					SUM(CASE WHEN NAME = 'DC-O-RDC-Agente-Polizas'
						THEN RDC_DETALLE.VALUE
						ELSE 0 END) AS POL_FIS,
					SUM(CASE WHEN NAME = 'DC-O-RDC-Agente-PolizasCorregidas'
						THEN RDC_DETALLE.VALUE
						ELSE 0 END) AS POL_CORR,
					MAX(ST_GN1) AS PRIMA,
					
					CASE WHEN B.BALANCESEQ IS NOT NULL THEN 'SI'
						ELSE NULL END AS SOLO_DIFERENCIAS,
					TO_VARCHAR(F.ULTIMA_ACTUALIZACION, 'DD/MM/YYYY') AS FEC_ACTUALIZACION,
					:i_PeriodSeq AS PERIODSEQ,
					POSITIONSEQ_PRIN AS POSITIONSEQ
				FROM EXT.OUT_BAL_RDC_DETALLE_REP RDC_DETALLE
				LEFT JOIN TCMP.CS_BALANCE B ON B.PERIODSEQ = RDC_DETALLE.PERIODSEQ
					AND B.PAYEESEQ = RDC_DETALLE.PARTICIPANTSEQ
					AND B.POSITIONSEQ = RDC_DETALLE.POSITIONSEQ_PRIN
				INNER JOIN :TBL_PER_FORMAT PF ON PF.PERIODO = :v_period_name
				LEFT JOIN EXT.OUT_FECHAS_WEBI_REP F ON F.PERIODO = :v_period_name
					AND TABLA = 'OUT_BAL_RDC_DETALLE_REP'
				WHERE RDC_DETALLE.PERIODSEQ = :i_PeriodSeq
				GROUP BY POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, ID_TIPO_AGENTE, TIPO_AGENTE,
					PRODUCTID, ST_GA1, F.ULTIMA_ACTUALIZACION, POSITIONSEQ_PRIN,
					B.BALANCESEQ;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_RDC_DETALLE_FINAL_REP. Balance. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Insert de --SELECCIONAR-- en OUT_RDC_DETALLE_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_RDC_DETALLE_FINAL_REP (TIPO_INFORME, PERIODO, PERIODO_FORMATO, COD_AGENTE, NOMBRE_AGENTE, NIF, NIF_NOMBRE, TIPO_AGENTE, COD_AGENTE_TABLA, NOMBRE_AGENTE_TABLA, COD_PROD, POLIZA, PRODUCTO, TIPO_REC, FEC_EMISION, FEC_COBRO, POL_FIS, POL_CORR, PRIMA, SOLO_DIFERENCIAS, FEC_ACTUALIZACION, PERIODSEQ, POSITIONSEQ)
                SELECT DISTINCT
					TIPO_INFORME,
					PERIODO,
					PERIODO_FORMATO,
					' ' AS COD_AGENTE,
					' ' AS NOMBRE_AGENTE,
					' ' AS NIF,
					'--SELECCIONAR--' AS NIF_NOMBRE,
					' ' AS TIPO_AGENTE,
					' ' AS COD_AGENTE_TABLA,
					' ' AS NOMBRE_AGENTE_TABLA,
					' ' AS COD_PROD,
					' ' AS POLIZA,
					' ' AS PRODUCTO,
					' ' AS TIPO_REC,
					' ' AS FEC_EMISION,
					' ' AS FEC_COBRO,
					NULL AS POL_FIS,
					NULL AS POL_CORR,
					NULL AS PRIMA,
					SOLO_DIFERENCIAS,
					FEC_ACTUALIZACION,
					PERIODSEQ,
					-1 AS POSITIONSEQ
                FROM EXT.OUT_RDC_DETALLE_FINAL_REP
                WHERE PERIODSEQ = :i_PeriodSeq;
            v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Insert de --SELECCIONAR-- en OUT_RDC_DETALLE_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');


			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tablas FINALES Informe RDC Detalle', i_log_count, i_id_proceso, 'info');

        --FIN informe S4 Rappel Mantenimiento
        END IF;

		------------------------------------------------------------------------------------------------------------------------
		--Inicio informes 1.23 Cartera
		IF ((:i_lista_informes = 'CARTERA' OR :i_lista_informes LIKE '%|CARTERA|%' OR :i_lista_informes LIKE '%|CARTERA' OR :i_lista_informes LIKE 'CARTERA|%')
				AND
			(:i_lista_informes = 'PRAG' OR :i_lista_informes LIKE '%|PRAG|%' OR :i_lista_informes LIKE '%|PRAG' OR :i_lista_informes LIKE 'PRAG|%')
				AND
			(:i_lista_informes = 'S4' OR :i_lista_informes LIKE '%|S4|%' OR :i_lista_informes LIKE '%|S4' OR :i_lista_informes LIKE 'S4|%'))
			OR :i_lista_informes = 'ALL'
			THEN
			
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tablas FINALES Informes Cartera', i_log_count, i_id_proceso, 'info');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_CARTERA_AGENTES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_CARTERA_AGENTES_FINAL_REP WHERE YEAR = :v_period_year;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_CARTERA_AGENTES_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_CARTERA_AGENTES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_CARTERA_AGENTES_FINAL_REP (YEAR, COMPANIA, AGENTE, NIF, ID_TIPO_AGENTE, TABLA, PRODUCTO, POLIZAS, PRIMAS, PRODUCCION, CARTERA, TOTAL, ULTIMA_ACTUALIZACION, POSITIONSEQ, PERIODSEQ)
				WITH QUERY_ORACLE AS 
					(SELECT DISTINCT
						'Q1' AS QUERY,
						'01' AS COMPANIA,
						S4_POL.NOMBRE, --GENERICATTRIBUTE2
						S4_POL.PRODUCTID, --GENERICATTRIBUTE6
						S4_POL.POS_PRIN, --GENERICATTRIBUTE7
						S4_POL.PRODUCTO, --GENERICATTRIBUTE8
						S4_POL.PRIMA_COMIS, --GENERICNUMBER1
						S4_POL.PRIMA_NETA, --GENERICNUMBER4
						S4_POL.VALUE, --GENERICNUMBER2
						S4_POL.POLIZ_CORR, --GENERICNUMBER3
						S4_POL.POLIZ_NP, --GENERICNUMBER5
						S4_POL.NIF, --GENERICATTRIBUTE12
						S4_POL.NAME, --GENERICATTRIBUTE13
						S4_POL.PERIODO, --PERIOD NAME
						S4_POL.SALESTRANSACTIONSEQ, --GENERICATTRIBUTE15
						S4_POL.ID_TIPO_AGENTE, --GENERICNUMBER6
						S4_POL.TIPO_AGENTE, --GENERICATTRIBUTE16
						S4_POL.POSITIONSEQ_PRIN AS POSITIONSEQ
					FROM EXT.OUT_BAL_S4_POLIZAS_REP S4_POL
					WHERE RIGHT(S4_POL.PERIODO, 4) = :v_period_year
						AND (NAME LIKE 'DC-O-COM%-GestionCobro' OR NAME LIKE 'DC-O-COM%-GestionCobro-ComisionCalculada' OR NAME LIKE 'DC-O-COM%-GestionCobro-PorcentajeFijo' OR
							NAME LIKE 'DC-O-COM%-Conservacion-PorcentajeFijo' OR NAME LIKE 'DC-O-COM%-Conservacion-ComisionCalculada' OR NAME LIKE 'DC-O-COM%-Conservacion-RecalcularPorcentaje' OR
							NAME LIKE 'DC-O-COM%-Conservacion-Consolidacion' OR NAME LIKE 'DC-O-COM%-Cartera-PorcentajeFijo' OR NAME LIKE 'DC-O-COM%-Cartera-ComisionCalculada' OR
							NAME LIKE 'DC-O-COM%-Cartera-Porcentaje' OR NAME LIKE 'DC-O-COM%-Cartera-Importe' OR NAME LIKE 'DC-O-COM%-Conservacion-Recuperadas' OR
							NAME LIKE 'DC-O-COM%-ServiciosAsistencia-Importe' OR NAME LIKE 'DC-O-SER-%' OR NAME LIKE 'CARTERA_%' OR
							NAME LIKE 'DC-O-COM%-NuevaProduccion-Emision' OR NAME LIKE 'DC-O-COM%-NuevaProduccion-Suplementos' OR NAME LIKE 'DC-O-COM%-NuevaProduccion-PorcentajeFijo' OR
							NAME LIKE 'DC-O-COM%-NuevaProduccion-ComisionCalculada' OR NAME LIKE 'DC-O-COM%-NuevaProduccion-SECI' OR
							SALESTRANSACTIONSEQ IN ('101', '102', '106', '107', '109', '123', '124', '125', '126', '127', '150', '153'))
					
					UNION ALL

					SELECT DISTINCT
						'Q1' AS QUERY,
						'03' AS COMPANIA,
						S4_POL.NOMBRE, --GENERICATTRIBUTE2
						S4_POL.PRODUCTID, --GENERICATTRIBUTE6
						S4_POL.POS_PRIN, --GENERICATTRIBUTE7
						S4_POL.PRODUCTO, --GENERICATTRIBUTE8
						S4_POL.PRIMA_COMIS, --GENERICNUMBER1
						S4_POL.PRIMA_NETA, --GENERICNUMBER4
						S4_POL.VALUE, --GENERICNUMBER2
						S4_POL.POLIZ_CORR, --GENERICNUMBER3
						S4_POL.POLIZ_NP, --GENERICNUMBER5
						S4_POL.NIF, --GENERICATTRIBUTE12
						S4_POL.NAME, --GENERICATTRIBUTE13
						S4_POL.PERIODO, --PERIOD NAME
						S4_POL.SALESTRANSACTIONSEQ, --GENERICATTRIBUTE15
						S4_POL.ID_TIPO_AGENTE, --GENERICNUMBER6
						S4_POL.TIPO_AGENTE, --GENERICATTRIBUTE16
						S4_POL.POSITIONSEQ_PRIN AS POSITIONSEQ
					FROM EXT.OUT_BAL_S4_E_POLIZAS_REP S4_POL
					WHERE RIGHT(S4_POL.PERIODO, 4) = :v_period_year
						AND (NAME LIKE 'DC-E-COM%-GestionCobro' OR NAME LIKE 'DC-E-COM%-GestionCobro-ComisionCalculada' OR NAME LIKE 'DC-E-COM%-GestionCobro-PorcentajeFijo' OR
							NAME LIKE 'DC-E-COM%-Conservacion-PorcentajeFijo' OR NAME LIKE 'DC-E-COM%-Conservacion-ComisionCalculada' OR NAME LIKE 'DC-E-COM%-Conservacion-RecalcularPorcentaje' OR
							NAME LIKE 'DC-E-COM%-Conservacion-Consolidacion' OR NAME LIKE 'DC-E-COM%-Cartera-PorcentajeFijo' OR NAME LIKE 'DC-E-COM%-Cartera-ComisionCalculada' OR
							NAME LIKE 'DC-E-COM%-Cartera-Porcentaje' OR NAME LIKE 'DC-E-COM%-Cartera-Importe' OR NAME LIKE 'DC-E-COM%-Conservacion-Recuperadas' OR
							NAME LIKE 'DC-E-COM%-ServiciosAsistencia-Importe' OR NAME LIKE 'DC-E-SER-%' OR NAME LIKE 'CARTERA_%' OR
							NAME LIKE 'DC-E-COM%-NuevaProduccion-Emision' OR NAME LIKE 'DC-E-COM%-NuevaProduccion-Suplementos' OR NAME LIKE 'DC-E-COM%-NuevaProduccion-PorcentajeFijo' OR
							NAME LIKE 'DC-E-COM%-NuevaProduccion-ComisionCalculada' OR NAME LIKE 'DC-E-COM%-NuevaProduccion-SECI' OR
							SALESTRANSACTIONSEQ IN ('101', '102', '106', '107', '109', '123', '124', '125', '126', '127', '150', '153'))

					UNION ALL
					
					SELECT DISTINCT
						'Q2' AS QUERY,
						PROD_AGENTES.COMPANIA,
						J.NOMBRE, --GENERICATTRIBUTE2
						PROD_AGENTES.PRODUCTID, --GENERICATTRIBUTE6
						J.POS_PRIN, --GENERICATTRIBUTE7
						PROD_AGENTES.PRODUCTO, --GENERICATTRIBUTE8 
						NULL AS PRIMA_COMIS,
						NULL AS PRIMA_NETA,
						PROD_AGENTES.VALUE, --GENERICNUMBER2
						NULL AS POLIZ_CORR,
						NULL AS POLIZ_NP,
						J.NIF, --GENERICATTRIBUTE12
						PROD_AGENTES.NAME, --GENERICATTRIBUTE13
						J.PERIODO, --PERIOD NAME
						PROD_AGENTES.SALESTRANSACTIONSEQ, --GENERICATTRIBUTE15
						J.ID_TIPO_AGENTE, --GENERICNUMBER6
						J.TIPO_AGENTE, --GENERICATTRIBUTE16
						J.POSITIONSEQ_PRIN AS POSITIONSEQ
					FROM EXT.OUT_JERARQUIA_REP J
					LEFT JOIN EXT.OUT_PROD_AGENTES_REP PROD_AGENTES ON J.PARTICIPANTSEQ = PROD_AGENTES.PARTICIPANTSEQ
						AND J.POSITIONSEQ_PRIN = PROD_AGENTES.POSITIONSEQ_PRIN
					WHERE J.PERIODO = :v_period_name
						AND RIGHT(PROD_AGENTES.PERIODO, 4) = :v_period_year
						AND (NAME LIKE 'DC-%-GEN-Agente-NumeroPolizas-998' OR NAME LIKE 'DC-%-GEN-Agente-NumeroPolizas-998-Recup' OR NAME LIKE 'DC-%-GEN-Agente-NumeroPolizas-998-Renov' OR 
							NAME LIKE 'DC-%-GEN-Agente-Prima-998' OR NAME LIKE 'DC-%-CA-NumeroPolizas' OR NAME LIKE 'DC-%-CA-Prima' OR NAME IN ('CARTERA_DDEE','CARTERA_LP'))

					UNION ALL
					
					SELECT DISTINCT
						'Q2' AS QUERY,
						CARTERA_AGENTES.COMPANIA,
						J.NOMBRE, --GENERICATTRIBUTE2
						CARTERA_AGENTES.PRODUCTID, --GENERICATTRIBUTE6
						J.POS_PRIN, --GENERICATTRIBUTE7
						CARTERA_AGENTES.PRODUCTO, --GENERICATTRIBUTE8 
						NULL AS PRIMA_COMIS,
						NULL AS PRIMA_NETA,
						CASE
							WHEN CARTERA_AGENTES.NAME = 'CARTERA_DDEE' THEN CARTERA_AGENTES.PRIMA
							ELSE CARTERA_AGENTES.VALUE
						END	AS VALUE, --GENERICNUMBER2 --DTB 20260324 Cambiado CARTERA_AGENTES.VALUE a CARTERA_AGENTES.PRIMA para DDEE
						NULL AS POLIZ_CORR,
						NULL AS POLIZ_NP,
						J.NIF, --GENERICATTRIBUTE12
						CARTERA_AGENTES.NAME, --GENERICATTRIBUTE13
						J.PERIODO, --PERIOD NAME
						CARTERA_AGENTES.SALESTRANSACTIONSEQ, --GENERICATTRIBUTE15
						J.ID_TIPO_AGENTE, --GENERICNUMBER6
						J.TIPO_AGENTE, --GENERICATTRIBUTE16
						J.POSITIONSEQ_PRIN AS POSITIONSEQ
					FROM EXT.OUT_JERARQUIA_REP J
					LEFT JOIN EXT.OUT_CARTERA_AGENTES_REP CARTERA_AGENTES ON J.PARTICIPANTSEQ = CARTERA_AGENTES.PARTICIPANTSEQ
						AND J.POSITIONSEQ_PRIN = CARTERA_AGENTES.POSITIONSEQ_PRIN
					WHERE J.PERIODO = :v_period_name
						AND RIGHT(CARTERA_AGENTES.PERIODO, 4) = :v_period_year
						AND (NAME LIKE 'DC-%-GEN-Agente-NumeroPolizas-998' OR NAME LIKE 'DC-%-GEN-Agente-NumeroPolizas-998-Recup' OR NAME LIKE 'DC-%-GEN-Agente-NumeroPolizas-998-Renov' OR
							NAME LIKE 'DC-%-GEN-Agente-Prima-998' OR NAME LIKE 'DC-%-CA-NumeroPolizas' OR NAME LIKE 'DC-%-CA-Prima' OR NAME IN ('CARTERA_DDEE', 'CARTERA_LP'))
				)
				-- TABLA PRODUCCION
				SELECT
					:v_period_year AS YEAR,
					COMPANIA,
					LEFT(POS_PRIN, 4) || '-' || RIGHT(POS_PRIN, 4) || '  ' || TRIM(NOMBRE) AS AGENTE,
					NIF,
					ID_TIPO_AGENTE,
					'PRODUCCION' AS TABLA,
					LEFT(RIGHT(PRODUCTID, 5), 3) AS PRODUCTO,
					SUM(CASE WHEN NAME LIKE '%Poliza%'
							THEN VALUE
						WHEN NAME LIKE 'CARTERA_%'
							THEN 1
						ELSE 0 END) AS POLIZAS,
					SUM(CASE WHEN (NAME LIKE '%Prima%' OR NAME LIKE 'CARTERA_%')
							THEN VALUE
						ELSE 0 END) AS PRIMAS,
					NULL AS PRODUCCION,
					NULL AS CARTERA,
					NULL AS TOTAL,
					TO_VARCHAR((SELECT MAX(ULTIMA_ACTUALIZACION) FROM EXT.OUT_FECHAS_WEBI_REP WHERE RIGHT(PERIODO, 4) = :v_period_year), 'DD/MM/YYYY') AS ULTIMA_ACTUALIZACION,
					POSITIONSEQ,
					:i_PeriodSeq AS PERIODSEQ
				FROM QUERY_ORACLE QO
				WHERE (NAME LIKE 'DC-%-GEN-Agente-NumeroPolizas-998' OR NAME LIKE 'DC-%-GEN-Agente-NumeroPolizas-998-Recup' OR NAME LIKE 'DC-%-GEN-Agente-NumeroPolizas-998-Renov' OR NAME LIKE 'DC-%-GEN-Agente-Prima-998')
					AND QUERY = 'Q2'
				GROUP BY COMPANIA, LEFT(POS_PRIN, 4) || '-' || RIGHT(POS_PRIN, 4) || '  ' || TRIM(NOMBRE), LEFT(RIGHT(PRODUCTID, 5), 3), ID_TIPO_AGENTE, NIF, POSITIONSEQ

				UNION ALL

				-- TABLA CARTERA
				SELECT
					:v_period_year AS YEAR,
					COMPANIA,
					LEFT(POS_PRIN, 4) || '-' || RIGHT(POS_PRIN, 4) || '  ' || TRIM(NOMBRE) AS AGENTE,
					NIF,
					ID_TIPO_AGENTE,
					'CARTERA' AS TABLA,
					LEFT(RIGHT(PRODUCTID, 5), 3) AS PRODUCTO,
					SUM(CASE WHEN NAME LIKE '%Poliza%'
							THEN VALUE
						WHEN NAME LIKE 'CARTERA_%'
							THEN 1
						ELSE 0 END) AS POLIZAS,
					SUM(CASE WHEN (NAME LIKE '%Prima%' OR NAME LIKE 'CARTERA_%')
							THEN VALUE
						ELSE 0 END) AS PRIMAS,
					NULL AS PRODUCCION,
					NULL AS CARTERA,
					NULL AS TOTAL,
					TO_VARCHAR((SELECT MAX(ULTIMA_ACTUALIZACION) FROM EXT.OUT_FECHAS_WEBI_REP WHERE RIGHT(PERIODO, 4) = :v_period_year), 'DD/MM/YYYY') AS ULTIMA_ACTUALIZACION,
					POSITIONSEQ,
					:i_PeriodSeq AS PERIODSEQ
				FROM QUERY_ORACLE QO
				WHERE (NAME LIKE 'DC-%-CA-NumeroPolizas' OR NAME LIKE 'DC-%-CA-Prima' OR NAME IN ('CARTERA_DDEE', 'CARTERA_LP'))
					AND QUERY = 'Q2'
				GROUP BY COMPANIA, LEFT(POS_PRIN, 4) || '-' || RIGHT(POS_PRIN, 4) || '  ' || TRIM(NOMBRE), LEFT(RIGHT(PRODUCTID, 5), 3), ID_TIPO_AGENTE, NIF, POSITIONSEQ
					
				UNION ALL

				-- TABLA PERCEPCIONES
				SELECT
					:v_period_year AS YEAR,
					COMPANIA,
					LEFT(POS_PRIN, 4) || '-' || RIGHT(POS_PRIN, 4) || '  ' || TRIM(NOMBRE) AS AGENTE,
					NIF,
					ID_TIPO_AGENTE,
					'PERCEPCIONES' AS TABLA,
					RIGHT(PRODUCTID, 5) || ' - ' || PRODUCTO,
					NULL AS POLIZAS,
					NULL AS PRIMAS,
					SUM(CASE WHEN (NAME LIKE 'DC-%-COM%-NuevaProduccion-Emision' OR NAME LIKE 'DC-%-COM%-NuevaProduccion-Suplementos' OR NAME LIKE 'DC-%-COM%-NuevaProduccion-PorcentajeFijo' OR
							NAME LIKE 'DC-%-COM%-NuevaProduccion-ComisionCalculada' OR NAME LIKE 'DC-%-COM%-NuevaProduccion-SECI' OR SALESTRANSACTIONSEQ = '101')
						THEN VALUE 
						ELSE 0 END) AS PRODUCCION,
					SUM(CASE WHEN (NAME LIKE 'DC-%-COM%-GestionCobro' OR NAME LIKE 'DC-%-COM%-GestionCobro-ComisionCalculada' OR NAME LIKE 'DC-%-COM%-GestionCobro-PorcentajeFijo' OR
							NAME LIKE 'DC-%-COM%-Conservacion-PorcentajeFijo' OR NAME LIKE 'DC-%-COM%-Conservacion-ComisionCalculada' OR NAME LIKE 'DC-%-COM%-Conservacion-RecalcularPorcentaje' OR
							NAME LIKE 'DC-%-COM%-Conservacion-Consolidacion' OR NAME LIKE 'DC-%-COM%-Cartera-PorcentajeFijo' OR NAME LIKE 'DC-%-COM%-Cartera-ComisionCalculada' OR
							NAME LIKE 'DC-%-COM%-Cartera-Porcentaje' OR NAME LIKE 'DC-%-COM%-Cartera-Importe' OR NAME LIKE 'DC-%-COM%-Conservacion-Recuperadas' OR
							NAME LIKE 'DC-%-COM%-ServiciosAsistencia-Importe' OR NAME LIKE 'DC-%-SER-%' OR NAME LIKE 'CARTERA_%' OR
							SALESTRANSACTIONSEQ IN ('102', '106', '107', '109', '123', '124', '125', '126', '127', '150', '153'))
						THEN VALUE 
						ELSE 0 END) AS CARTERA,
					SUM(CASE WHEN (NAME LIKE 'DC-%-COM%-NuevaProduccion-Emision' OR NAME LIKE 'DC-%-COM%-NuevaProduccion-Suplementos' OR NAME LIKE 'DC-%-COM%-NuevaProduccion-PorcentajeFijo' OR
							NAME LIKE 'DC-%-COM%-NuevaProduccion-ComisionCalculada' OR NAME LIKE 'DC-%-COM%-NuevaProduccion-SECI' OR 
							NAME LIKE 'DC-%-COM%-GestionCobro' OR NAME LIKE 'DC-%-COM%-GestionCobro-ComisionCalculada' OR NAME LIKE 'DC-%-COM%-GestionCobro-PorcentajeFijo' OR
							NAME LIKE 'DC-%-COM%-Conservacion-PorcentajeFijo' OR NAME LIKE 'DC-%-COM%-Conservacion-ComisionCalculada' OR NAME LIKE 'DC-%-COM%-Conservacion-RecalcularPorcentaje' OR
							NAME LIKE 'DC-%-COM%-Conservacion-Consolidacion' OR NAME LIKE 'DC-%-COM%-Cartera-PorcentajeFijo' OR NAME LIKE 'DC-%-COM%-Cartera-ComisionCalculada' OR
							NAME LIKE 'DC-%-COM%-Cartera-Porcentaje' OR NAME LIKE 'DC-%-COM%-Cartera-Importe' OR NAME LIKE 'DC-%-COM%-Conservacion-Recuperadas' OR
							NAME LIKE 'DC-%-COM%-ServiciosAsistencia-Importe' OR NAME LIKE 'DC-%-SER-%' OR NAME LIKE 'CARTERA_%' OR
							SALESTRANSACTIONSEQ IN ('101', '102', '106', '107', '109', '123', '124', '125', '126', '127', '150', '153'))
						THEN VALUE
						ELSE 0 END) AS TOTAL,
					TO_VARCHAR((SELECT MAX(ULTIMA_ACTUALIZACION) FROM EXT.OUT_FECHAS_WEBI_REP WHERE RIGHT(PERIODO, 4) = :v_period_year), 'DD/MM/YYYY') AS ULTIMA_ACTUALIZACION,
					POSITIONSEQ,
					:i_PeriodSeq AS PERIODSEQ
				FROM QUERY_ORACLE QO
				WHERE QUERY = 'Q1'
				GROUP BY COMPANIA, LEFT(POS_PRIN, 4) || '-' || RIGHT(POS_PRIN, 4) || '  ' || TRIM(NOMBRE), RIGHT(PRODUCTID, 5) || ' - ' || PRODUCTO, ID_TIPO_AGENTE, NIF, POSITIONSEQ;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Carga OUT_CARTERA_AGENTES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Insert de --SELECCIONAR-- en OUT_CARTERA_AGENTES_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			INSERT INTO EXT.OUT_CARTERA_AGENTES_FINAL_REP (YEAR, COMPANIA, AGENTE, NIF, ID_TIPO_AGENTE, TABLA, PRODUCTO, POLIZAS, PRIMAS, PRODUCCION, CARTERA, TOTAL, ULTIMA_ACTUALIZACION, POSITIONSEQ, PERIODSEQ)
                SELECT DISTINCT
					YEAR,
					COMPANIA,
					' ' AS AGENTE,
					'--SELECCIONAR--' AS NIF,
					ID_TIPO_AGENTE,
					' ' AS TABLA,
					' ' AS PRODUCTO,
					NULL AS POLIZAS,
					NULL AS PRIMAS,
					NULL AS PRODUCCION,
					NULL AS CARTERA,
					NULL AS TOTAL,
					ULTIMA_ACTUALIZACION,
					-1 AS POSITIONSEQ,
					PERIODSEQ
                FROM EXT.OUT_CARTERA_AGENTES_FINAL_REP
                WHERE YEAR = :v_period_year;
            v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Insert de --SELECCIONAR-- en OUT_CARTERA_AGENTES_FINAL_REP. Filas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');			

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Rellenado Tablas FINALES Informes Cartera', i_log_count, i_id_proceso, 'info');

		--Fin informes 1.23 Cartera
		END IF;

		------------------------------------------------------------------------------------------------------------------------
		--Inicio informes Producción Propia Agentes con Grupo
		IF :i_lista_informes = 'PP' OR :i_lista_informes LIKE '%|PP|%' OR :i_lista_informes LIKE '%|PP' OR :i_lista_informes LIKE 'PP|%' OR :i_lista_informes = 'ALL'
			THEN

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, '----------------------------------------', i_log_count, i_id_proceso, 'info');
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Rellenado Tablas FINALES Informes PP Resumen', i_log_count, i_id_proceso, 'info');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Borrado OUT_PP_RESUMEN_FINAL_REP.', i_log_count, i_id_proceso, 'debug');
			DELETE FROM EXT.OUT_PP_RESUMEN_FINAL_REP WHERE PERIODSEQ = :i_PeriodSeq;
			v_num_rows := ::ROWCOUNT;
			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Fin Borrado OUT_PP_RESUMEN_FINAL_REP. Filas borradas: ' || v_num_rows, i_log_count, i_id_proceso, 'debug');

			CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, proc_name, 'Inicio Carga OUT_PP_RESUMEN_FINAL_REP. Cierre', i_log_count, i_id_proceso, 'debug');
