						PP_RESUMEN.TIPO_AGENTE, --GENERICATTRIBUTE6
						PP_RESUMEN.PERIODO, --Period Name
						PP_RESUMEN.STARTDATE, ----GENERICDATE1
						PP_RESUMEN.YEAR, --Year
						PP_RESUMEN.NIF, --GENERICATTRIBUTE8
						PP_RESUMEN.POSITIONSEQ_PRIN AS POSITIONSEQ
					FROM EXT.OUT_PP_RESUMEN_REP PP_RESUMEN 
					WHERE PP_RESUMEN.PERIODSEQ = :i_PeriodSeq
					
