					SELECT DISTINCT
						PP_RESUMEN.FIRSTNAME, --GENERICATTRIBUTE3
						PP_RESUMEN.LASTNAME, --GENERICATTRIBUTE2
						PP_RESUMEN.MIDDLENAME, --GENERICATTRIBUTE4
						PP_RESUMEN.N_MEDIDA, --GENERICATTRIBUTE12
						PP_RESUMEN.V_MEDIDA, --GENERICNUMBER5
						PP_RESUMEN.POS_PRIN, --GENERICATTRIBUTE1
