					GROUP BY POS_PRIN, FIRSTNAME, MIDDLENAME, LASTNAME, NIF, QO.PERIODO, STARTDATE, ID_TIPO_AGENTE, TIPO_AGENTE, POSITIONSEQ, F.ULTIMA_ACTUALIZACION
