			INSERT INTO EXT.OUT_PP_RESUMEN_FINAL_REP (TIPO_INFORME, PERIODO_FILTRO, PERIODO_FORMATO, CODIGO_AGENTE, NOMBRE_AGENTE, TIPO_AGENTE, NIF, NIF_NOMBRE, FECHA_EFECTO, PERIODO_TABLA, STARTDATE, POLIZ_CORR, EXTORNO, FEC_ACTUALIZACION, SOLO_DIFERENCIAS, POSITIONSEQ, PERIODSEQ)
