						AND PP_RESUMEN.STARTDATE >= (select max(STARTDATE) from EXT.OUT_BAL_PP_RESUMEN_REP x where x.n_medida = 'SM-O-GEN-Inspector-Meses' and x.v_medida = 1
											and x.participantseq = PP_RESUMEN.PARTICIPANTSEQ and x.positionseq_prin = PP_RESUMEN.POSITIONSEQ_PRIN
